INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/bbs', 'bbs', 'majiayu000', 'claude-skill-registry', 'community', 'bbs majiayu000 claude-skill-registry community BBS The FoldCAS BBS The FoldCAS BBS The FoldCAS BBS es un sistema de seguimiento de problemas CAS-nativo que permite crear y rastrear problemas, encontrar trabajo disponible y gestionar dependencias BBS est un système de suivi de problèmes CAS-natif qui permet de créer et de suivre des problèmes, de trouver du travail disponible et de gérer des dépendances BBS ist ein CAS-natives Issue-Tracking-System, das die Erstellung und Nachverfolgung von Problemen, die Suche nach verfügbaren Arbeiten und die Verwaltung von Abhängigkeiten ermöglicht O BBS é um sistema de gerenciamento de problemas baseado em block primitives que permite criar e rastrear problemas de forma eficaz. BBS - это система управления проблемами на основе блоков, которая позволяет создавать и отслеживать проблемы эффективно. نظام إدارة المشكلات BBS هو نظام مبني على الكتل يسمح بإنشاء وتتبع المشكلات بفعالية. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app BBS CAS Block The Fold Issue Tracker The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/gcp-architecture', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'gcp-architecture', 0, 0, 70, '2026-02-20T04:13:19.578Z', '2026-02-20T04:57:41.390Z', '837cef6e2d84dba312033d4c194ad1cac058035557ea9fcbb02c28d8274db79d', '{"id":"majiayu000/claude-skill-registry/gcp-architecture","name":"gcp-architecture","description":{"zh":"本指南提供了在Google Cloud Platform上设计安全、可扩展的基础设施的综合指南，涵盖计算、网络和IAM等核心服务","ja":"このガイドでは、Google Cloud Platform上でセキュアでスケーラブルなインフラストラクチャを設計するための包括的なガイドを提供します。コンピューティング、ネットワーク、IAMなどの主要サービスをカバーしています","ko":"이 가이드는 Google Cloud Platform에서 보안 및 확장 가능한 인프라를 디자인하는 방법에 대한 포괄적인 가이드를 제공합니다. 컴퓨팅, 네트워킹, IAM 등의 핵심 서비스를 다룹니다","es":"Guía completa para construir infraestructuras seguras y escalables en Google Cloud Platform","fr":"Guide complet pour construire des infrastructures sécurisées et évolutivité sur Google Cloud Platform","de":"Umfassender Leitfaden für den Bau von sicheren und skalierbaren Infrastrukturen auf Google Cloud Platform","pt":"Guia completo para construir infraestrutura segura e escalável na Google Cloud Platform, incluindo design de arquitetura, deploy de aplicações e configuração de IAM","ru":"Полное руководство по созданию безопасной и масштабируемой инфраструктуры на Google Cloud Platform, включая проектирование архитектуры, развертывание приложений и настройку IAM","ar":"دليل شامل لإنشاء بنية تحتية آمنة ومتوسعة على منصة جوجل كلاود، بما في ذلك تصميم الهندسة وتنفيذ التطبيقات وضبط IAM","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"GCP架构指南","ja":"GCPアーキテクチャガイド","ko":"GCP 아키텍처 가이드","es":"Arquitectura de Google Cloud Platform","fr":"Architecture Google Cloud Platform","de":"Google Cloud Platform Architektur","pt":"Arquitetura GCP: Guia Completo para Desenvolvedores","ru":"GCP Архитектура: Полное Руководство для Разработчиков","ar":"هندسة گپ: دليل شامل للمطورين","en":"gcp-architecture"},"description":{"zh":"本指南提供了在Google Cloud Platform上设计安全、可扩展的基础设施的综合指南，涵盖计算、网络和IAM等核心服务","ja":"このガイドでは、Google Cloud Platform上でセキュアでスケーラブルなインフラストラクチャを設計するための包括的なガイドを提供します。コンピューティング、ネットワーク、IAMなどの主要サービスをカバーしています","ko":"이 가이드는 Google Cloud Platform에서 보안 및 확장 가능한 인프라를 디자인하는 방법에 대한 포괄적인 가이드를 제공합니다. 컴퓨팅, 네트워킹, IAM 등의 핵심 서비스를 다룹니다","es":"Guía completa para construir infraestructuras seguras y escalables en Google Cloud Platform","fr":"Guide complet pour construire des infrastructures sécurisées et évolutivité sur Google Cloud Platform","de":"Umfassender Leitfaden für den Bau von sicheren und skalierbaren Infrastrukturen auf Google Cloud Platform","pt":"Guia completo para construir infraestrutura segura e escalável na Google Cloud Platform, incluindo design de arquitetura, deploy de aplicações e configuração...","ru":"Полное руководство по созданию безопасной и масштабируемой инфраструктуры на Google Cloud Platform, включая проектирование архитектуры, развертывание приложе...","ar":"دليل شامل لإنشاء بنية تحتية آمنة ومتوسعة على منصة جوجل كلاود، بما في ذلك تصميم الهندسة وتنفيذ التطبيقات وضبط IAM","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["计算服务（Compute Engine、App Engine）","网络服务（VPC、Firewall Rules）","IAM服务（IAM Policies、Service Accounts）","容器编排（Google Kubernetes Engine）","成本优化和性能监控"],"ja":["コンピューティングサービス（Compute Engine、App Engine）","ネットワークサービス（VPC、Firewall Rules）","IAMサービス（IAM Policies、Service Accounts）","コンテナオーケストレーション（Google Kubernetes Engine）","コスト最適化とパフォーマンスモニタリング"],"ko":["컴퓨팅 서비스（Compute Engine、App Engine）","네트워킹 서비스（VPC、Firewall Rules）","IAM 서비스（IAM Policies、Service Accounts）","컨테이너 오케스트레이션（Google Kubernetes Engine）","비용 최적화 및 성능 모니터링"],"es":["Diseño de arquitecturas de GCP para nuevos proyectos","Implementación de aplicaciones en servicios de GCP","Configuración de redes (VPC, reglas de firewall)","Configuración de políticas de IAM y cuentas de servicio","Trabajo con GKE (Google Kubernetes Engine)","Optimización de costos y rendimiento"],"fr":["Conception d''architectures GCP pour de nouveaux projets","Déploiement d''applications sur les services GCP","Configuration des réseaux (VPC, règles de pare-feu)","Configuration des politiques IAM et des comptes de service","Travail avec GKE (Google Kubernetes Engine)","Optimisation des coûts et des performances"],"de":["Entwurf von GCP-Architekturen für neue Projekte","Bereitstellung von Anwendungen in GCP-Diensten","Konfiguration von Netzwerken (VPC, Firewall-Regeln)","Konfiguration von IAM-Richtlinien und Dienstkonto","Arbeit mit GKE (Google Kubernetes Engine)","Optimierung von Kosten und Leistung"],"pt":["Design de arquitetura GCP","Deploy de aplicações em serviços GCP","Configuração de rede (VPC, regras de firewall)","Configuração de políticas IAM e contas de serviço","Trabalho com GKE (Google Kubernetes Engine)","Otimização de custos e desempenho"],"ru":["Проектирование архитектуры GCP","Развертывание приложений в сервисах GCP","Настройка сети (VPC, правила брандмауэра)","Настройка политик IAM и учетных записей сервиса","Работа с GKE (Google Kubernetes Engine)","Оптимизация затрат и производительности"],"ar":["تصميم هندسة گپ","تنفيذ التطبيقات في خدمات گپ","ضبط الشبكة (VPC، قواعد الحماية)","ضبط سياسات IAM و حسابات الخدمة","العمل مع GKE (جوجل كوبيرنيتس إنجن)","تحسين التكاليف والأداء"]},"keywords":{"zh":["GCP架构","Google Cloud Platform","云计算","安全","可扩展性","计算服务","网络服务","IAM服务","容器编排"],"ja":["GCPアーキテクチャ","Google Cloud Platform","クラウドコンピューティング","セキュリティ","スケーラビリティ","コンピューティングサービス","ネットワークサービス","IAMサービス","コンテナオーケストレーション"],"ko":["GCP 아키텍처","Google Cloud Platform","클라우드 컴퓨팅","보안","확장성","컴퓨팅 서비스","네트워킹 서비스","IAM 서비스","컨테이너 오케스트레이션"],"es":["arquitectura de google cloud platform","gcp","infraestructura en la nube","seguridad en la nube","escalabilidad en la nube","diseño de arquitecturas de gcp","implementación de aplicaciones en gcp","configuración de redes en gcp","optimización de costos en gcp"],"fr":["architecture google cloud platform","gcp","infrastructure dans le cloud","sécurité dans le cloud","évolutivité dans le cloud","conception d''architectures gcp","déploiement d''applications sur gcp","configuration des réseaux sur gcp","optimisation des coûts sur gcp"],"de":["google cloud platform architektur","gcp","infrastruktur in der cloud","sicherheit in der cloud","skalierbarkeit in der cloud","entwurf von gcp-architekturen","bereitstellung von anwendungen in gcp","konfiguration von netzwerken in gcp","optimierung von kosten in gcp"],"pt":["arquitetura gcp","google cloud platform","infraestrutura em nuvem","segurança na nuvem","escalabilidade na nuvem","desenvolvimento de aplicações em nuvem","gke","iam","vpc"],"ru":["gcp архитектура","google cloud platform","облачная инфраструктура","безопасность в облаке","масштабируемость в облаке","разработка приложений в облаке","gke","iam","vpc"],"ar":["هندسة گپ","منصة جوجل كلاود","بنية تحتية سحابية","أمان السحابة","توسعة السحابة","تنمية التطبيقات السحابية","gke","iam","vpc"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"gcp-architecture","description":"Google Cloud Platform architecture patterns and best practices. Use when designing, deploying, or reviewing GCP infrastructure including GKE, Cloud Run, Cloud Functions, BigQuery, and IAM.","bodyPreview":"# Google Cloud Platform Architecture\n\nComprehensive guide for building secure, scalable infrastructure on Google Cloud Platform.\n\n## When to Use\n\n- Designing GCP architecture for new projects\n- Deploying applications to GCP services\n- Setting up networking (VPC, firewall rules)\n- Configuring IAM policies and service accounts\n- Working with GKE (Google Kubernetes Engine)\n- Optimizing costs and performance\n\n## Core Services Overview\n\n### Compute\n\n| Service | Use Case | Key Features |\n|---------|--","body":"# Google Cloud Platform Architecture\n\nComprehensive guide for building secure, scalable infrastructure on Google Cloud Platform.\n\n## When to Use\n\n- Designing GCP architecture for new projects\n- Deploying applications to GCP services\n- Setting up networking (VPC, firewall rules)\n- Configuring IAM policies and service accounts\n- Working with GKE (Google Kubernetes Engine)\n- Optimizing costs and performance\n\n## Core Services Overview\n\n### Compute\n\n| Service | Use Case | Key Features |\n|---------|----------|--------------|\n| Compute Engine | Virtual machines | Full control, custom images |\n| GKE | Managed Kubernetes | Autopilot mode, node auto-provisioning |\n| Cloud Run | Serverless containers | Scale to zero, any container |\n| Cloud Functions | Serverless functions | Event-driven, 2nd gen |\n| App Engine | PaaS | Standard/Flexible environments |\n\n### Storage\n\n| Service | Use Case | Key Features |\n|---------|----------|--------------|\n| Cloud Storage | Object storage | Multi-regional, lifecycle |\n| Persistent Disk | Block storage (GCE) | SSD/HDD, snapshots |\n| Filestore | Managed NFS | High performance |\n| Cloud SQL | Managed SQL | MySQL, PostgreSQL, SQL Server |\n| Firestore | NoSQL document | Serverless, realtime |\n| BigQuery | Data warehouse | Serverless, petabyte-scale |\n| Cloud Spanner | Global SQL | Horizontal scaling |\n| Memorystore | Managed Redis | In-memory cache |\n\n### Networking\n\n| Service | Use Case | Key Features |\n|---------|----------|--------------|\n| VPC | Virtual network | Global, shared VPC |\n| Cloud Load Balancing | Global LB | Layer 4/7, anycast IPs |\n| Cloud CDN | Content delivery | Edge caching |\n| Cloud DNS | DNS management | 100% SLA |\n| Cloud NAT | Outbound NAT | No external IPs needed |\n\n## VPC Architecture\n\n### Shared VPC Pattern\n\n```\n┌──────────────────────────────────────────────────────────────────┐\n│ Host Project (Shared VPC)                                        │\n│                                                                  │\n│  ┌────────────────────────────────────────────────────────────┐  │\n│  │ VPC Network: shared-vpc                                    │  │\n│  │                                                            │  │\n│  │  ┌─────────────────────┐    ┌─────────────────────┐       │  │\n│  │  │ Subnet: prod-app    │    │ Subnet: prod-data   │       │  │\n│  │  │ 10.0.0.0/20         │    │ 10.0.16.0/20        │       │  │\n│  │  │ us-central1         │    │ us-central1         │       │  │\n│  │  └─────────────────────┘    └─────────────────────┘       │  │\n│  │                                                            │  │\n│  │  ┌─────────────────────┐    ┌─────────────────────┐       │  │\n│  │  │ Subnet: staging-app │    │ Subnet: staging-data│       │  │\n│  │  │ 10.1.0.0/20         │    │ 10.1.16.0/20        │       │  │\n│  │  │ us-central1         │    │ us-central1         │       │  │\n│  │  └─────────────────────┘    └─────────────────────┘       │  │\n│  └────────────────────────────────────────────────────────────┘  │\n└──────────────────────────────────────────────────────────────────┘\n         │                              │\n         ▼                              ▼\n┌─────────────────────┐      ┌─────────────────────┐\n│ Service Project A   │      │ Service Project B   │\n│ (Production)        │      │ (Staging)           │\n│                     │      │                     │\n│ GKE, Cloud Run      │      │ GKE, Cloud Run      │\n│ Cloud SQL           │      │ Cloud SQL           │\n└─────────────────────┘      └─────────────────────┘\n```\n\n### Terraform VPC\n\n```hcl\n# VPC Network\nresource \"google_compute_network\" \"main\" {\n  name                    = \"${var.project_id}-vpc\"\n  auto_create_subnetworks = false\n  routing_mode            = \"GLOBAL\"\n}\n\n# Subnets\nresource \"google_compute_subnetwork\" \"app\" {\n  name          = \"${var.project_id}-app-subnet\"\n  ip_cidr_range = \"10.0.0.0/20\"\n  region        = var.region\n  network       = google_compute_network.main.id\n\n  secondary_ip_range {\n    range_name    = \"pods\"\n    ip_cidr_range = \"10.100.0.0/16\"\n  }\n\n  secondary_ip_range {\n    range_name    = \"services\"\n    ip_cidr_range = \"10.200.0.0/20\"\n  }\n\n  private_ip_google_access = true\n\n  log_config {\n    aggregation_interval = \"INTERVAL_5_SEC\"\n    flow_sampling        = 0.5\n    metadata             = \"INCLUDE_ALL_METADATA\"\n  }\n}\n\n# Cloud NAT\nresource \"google_compute_router\" \"main\" {\n  name    = \"${var.project_id}-router\"\n  region  = var.region\n  network = google_compute_network.main.id\n}\n\nresource \"google_compute_router_nat\" \"main\" {\n  name                               = \"${var.project_id}-nat\"\n  router                             = google_compute_router.main.name\n  region                             = var.region\n  nat_ip_allocate_option             = \"AUTO_ONLY\"\n  source_subnetwork_ip_ranges_to_nat = \"ALL_SUBNETWORKS_ALL_IP_RANGES\"\n\n  log_config {\n    enable = true\n    filter = \"ERRORS_ONLY\"\n  }\n}\n\n# Firewall Rules\nresource \"google_compute_firewall\" \"allow_internal\" {\n  name    = \"${var.project_id}-allow-internal\"\n  network = google_compute_network.main.name\n\n  allow {\n    protocol = \"tcp\"\n  }\n  allow {\n    protocol = \"udp\"\n  }\n  allow {\n    protocol = \"icmp\"\n  }\n\n  source_ranges = [\"10.0.0.0/8\"]\n}\n\nresource \"google_compute_firewall\" \"allow_health_checks\" {\n  name    = \"${var.project_id}-allow-health-checks\"\n  network = google_compute_network.main.name\n\n  allow {\n    protocol = \"tcp\"\n  }\n\n  source_ranges = [\n    \"35.191.0.0/16\",   # GCP Health Checks\n    \"130.211.0.0/22\",  # GCP Health Checks\n  ]\n\n  target_tags = [\"allow-health-checks\"]\n}\n```\n\n## IAM & Service Accounts\n\n### Service Account Best Practices\n\n```hcl\n# Application Service Account\nresource \"google_service_account\" \"app\" {\n  account_id   = \"${var.project_id}-app-sa\"\n  display_name = \"Application Service Account\"\n}\n\n# Workload Identity for GKE\nresource \"google_service_account_iam_binding\" \"workload_identity\" {\n  service_account_id = google_service_account.app.name\n  role               = \"roles/iam.workloadIdentityUser\"\n  members = [\n    \"serviceAccount:${var.project_id}.svc.id.goog[${var.namespace}/${var.k8s_service_account}]\"\n  ]\n}\n\n# Grant specific permissions\nresource \"google_project_iam_member\" \"app_storage\" {\n  project = var.project_id\n  role    = \"roles/storage.objectUser\"\n  member  = \"serviceAccount:${google_service_account.app.email}\"\n\n  condition {\n    title      = \"Only app bucket\"\n    expression = \"resource.name.startsWith(''projects/_/buckets/${var.project_id}-app-data'')\"\n  }\n}\n\nresource \"google_project_iam_member\" \"app_secretmanager\" {\n  project = var.project_id\n  role    = \"roles/secretmanager.secretAccessor\"\n  member  = \"serviceAccount:${google_service_account.app.email}\"\n}\n\nresource \"google_project_iam_member\" \"app_cloudsql\" {\n  project = var.project_id\n  role    = \"roles/cloudsql.client\"\n  member  = \"serviceAccount:${google_service_account.app.email}\"\n}\n```\n\n### Custom IAM Role\n\n```hcl\nresource \"google_project_iam_custom_role\" \"app_deployer\" {\n  role_id     = \"appDeployer\"\n  title       = \"Application Deployer\"\n  description = \"Can deploy applications to Cloud Run and GKE\"\n\n  permissions = [\n    \"run.services.create\",\n    \"run.services.update\",\n    \"run.services.delete\",\n    \"run.services.get\",\n    \"container.deployments.create\",\n    \"container.deployments.update\",\n    \"container.services.create\",\n    \"container.services.update\",\n  ]\n}\n```\n\n## GKE (Google Kubernetes Engine)\n\n### GKE Autopilot Cluster\n\n```hcl\nresource \"google_container_cluster\" \"main\" {\n  name     = \"${var.project_id}-gke\"\n  location = var.region\n\n  # Autopilot mode\n  enable_autopilot = true\n\n  network    = google_compute_network.main.name\n  subnetwork = google_compute_subnetwork.app.name\n\n  ip_allocation_policy {\n    cluster_secondary_range_name  = \"pods\"\n    services_secondary_range_name = \"services\"\n  }\n\n  private_cluster_config {\n    enable_private_nodes    = true\n    enable_private_endpoint = false\n    master_ipv4_cidr_block  = \"172.16.0.0/28\"\n  }\n\n  master_authorized_networks_config {\n    cidr_blocks {\n      cidr_block   = var.authorized_network\n      display_name = \"Authorized Network\"\n    }\n  }\n\n  release_channel {\n    channel = \"REGULAR\"\n  }\n\n  workload_identity_config {\n    workload_pool = \"${var.project_id}.svc.id.goog\"\n  }\n\n  # Security\n  binary_authorization {\n    evaluation_mode = \"PROJECT_SINGLETON_POLICY_ENFORCE\"\n  }\n\n  deletion_protection = var.environment == \"prod\"\n}\n```\n\n### GKE Standard Cluster\n\n```hcl\nresource \"google_container_cluster\" \"standard\" {\n  name     = \"${var.project_id}-gke-standard\"\n  location = var.region\n\n  # Remove default node pool\n  remove_default_node_pool = true\n  initial_node_count       = 1\n\n  network    = google_compute_network.main.name\n  subnetwork = google_compute_subnetwork.app.name\n\n  ip_allocation_policy {\n    cluster_secondary_range_name  = \"pods\"\n    services_secondary_range_name = \"services\"\n  }\n\n  workload_identity_config {\n    workload_pool = \"${var.project_id}.svc.id.goog\"\n  }\n\n  addons_config {\n    http_load_balancing {\n      disabled = false\n    }\n    horizontal_pod_autoscaling {\n      disabled = false\n    }\n    gce_persistent_disk_csi_driver_config {\n      enabled = true\n    }\n  }\n}\n\nresource \"google_container_node_pool\" \"primary\" {\n  name       = \"primary-pool\"\n  cluster    = google_container_cluster.standard.name\n  location   = var.region\n\n  node_count = var.environment == \"prod\" ? 3 : 1\n\n  autoscaling {\n    min_node_count = var.environment == \"prod\" ? 3 : 1\n    max_node_count = 10\n  }\n\n  management {\n    auto_repair  = true\n    auto_upgrade = true\n  }\n\n  node_config {\n    machine_type = \"e2-standard-4\"\n    disk_size_gb = 100\n    disk_type    = \"pd-ssd\"\n\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/cloud-platform\"\n    ]\n\n    service_account = google_service_account.gke_nodes.email\n\n    workload_metadata_config {\n      mode = \"GKE_METADATA\"\n    }\n\n    shielded_instance_config {\n      enable_secure_boot          = true\n      enable_integrity_monitoring = true\n    }\n\n    labels = {\n      environment = var.environment\n    }\n\n    tags = [\"gke-node\", var.environment]\n  }\n}\n```\n\n## Cloud Run\n\n### Cloud Run Service\n\n```hcl\nresource \"google_cloud_run_v2_service\" \"app\" {\n  name     = \"${var.project_id}-app\"\n  location = var.region\n  ingress  = \"INGRESS_TRAFFIC_INTERNAL_LOAD_BALANCER\"\n\n  template {\n    service_account = google_service_account.app.email\n\n    scaling {\n      min_instance_count = var.environment == \"prod\" ? 1 : 0\n      max_instance_count = 100\n    }\n\n    containers {\n      image = \"${var.region}-docker.pkg.dev/${var.project_id}/app/myapp:${var.image_tag}\"\n\n      ports {\n        container_port = 8080\n      }\n\n      resources {\n        limits = {\n          cpu    = \"2\"\n          memory = \"1Gi\"\n        }\n        cpu_idle = true  # Scale to zero\n      }\n\n      env {\n        name  = \"PROJECT_ID\"\n        value = var.project_id\n      }\n\n      env {\n        name = \"DATABASE_URL\"\n        value_source {\n          secret_key_ref {\n            secret  = google_secret_manager_secret.db_url.secret_id\n            version = \"latest\"\n          }\n        }\n      }\n\n      startup_probe {\n        http_get {\n          path = \"/health\"\n        }\n        initial_delay_seconds = 10\n        period_seconds        = 3\n        failure_threshold     = 3\n      }\n\n      liveness_probe {\n        http_get {\n          path = \"/health\"\n        }\n        period_seconds    = 30\n        failure_threshold = 3\n      }\n    }\n\n    vpc_access {\n      network_interfaces {\n        network    = google_compute_network.main.name\n        subnetwork = google_compute_subnetwork.app.name\n      }\n      egress = \"PRIVATE_RANGES_ONLY\"\n    }\n  }\n\n  traffic {\n    type    = \"TRAFFIC_TARGET_ALLOCATION_TYPE_LATEST\"\n    percent = 100\n  }\n}\n\n# IAM - Allow unauthenticated (public API)\nresource \"google_cloud_run_v2_service_iam_member\" \"public\" {\n  count    = var.public_access ? 1 : 0\n  location = google_cloud_run_v2_service.app.location\n  name     = google_cloud_run_v2_service.app.name\n  role     = \"roles/run.invoker\"\n  member   = \"allUsers\"\n}\n\n# Custom domain\nresource \"google_cloud_run_domain_mapping\" \"app\" {\n  location = var.region\n  name     = var.domain\n\n  metadata {\n    namespace = var.project_id\n  }\n\n  spec {\n    route_name = google_cloud_run_v2_service.app.name\n  }\n}\n```\n\n## Cloud SQL\n\n### PostgreSQL Instance\n\n```hcl\nresource \"google_sql_database_instance\" \"main\" {\n  name             = \"${var.project_id}-postgres\"\n  database_version = \"POSTGRES_15\"\n  region           = var.region\n\n  settings {\n    tier              = var.environment == \"prod\" ? \"db-custom-4-16384\" : \"db-f1-micro\"\n    availability_type = var.environment == \"prod\" ? \"REGIONAL\" : \"ZONAL\"\n    disk_size         = 100\n    disk_type         = \"PD_SSD\"\n    disk_autoresize   = true\n\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = var.environment == \"prod\"\n      transaction_log_retention_days = 7\n      backup_retention_settings {\n        retained_backups = var.environment == \"prod\" ? 30 : 7\n      }\n    }\n\n    ip_configuration {\n      ipv4_enabled    = false\n      private_network = google_compute_network.main.id\n      require_ssl     = true\n    }\n\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n\n    maintenance_window {\n      day          = 7  # Sunday\n      hour         = 3\n      update_track = \"stable\"\n    }\n\n    insights_config {\n      query_insights_enabled  = true\n      query_string_length     = 1024\n      record_application_tags = true\n      record_client_address   = true\n    }\n  }\n\n  deletion_protection = var.environment == \"prod\"\n}\n\nresource \"google_sql_database\" \"main\" {\n  name     = var.database_name\n  instance = google_sql_database_instance.main.name\n}\n\nresource \"google_sql_user\" \"app\" {\n  name     = \"app\"\n  instance = google_sql_database_instance.main.name\n  password = random_password.db.result\n}\n```\n\n## Cloud Storage\n\n### Secure Bucket\n\n```hcl\nresource \"google_storage_bucket\" \"data\" {\n  name          = \"${var.project_id}-data\"\n  location      = var.region\n  force_destroy = var.environment != \"prod\"\n\n  uniform_bucket_level_access = true\n\n  versioning {\n    enabled = true\n  }\n\n  encryption {\n    default_kms_key_name = google_kms_crypto_key.storage.id\n  }\n\n  lifecycle_rule {\n    condition {\n      age = 90\n    }\n    action {\n      type          = \"SetStorageClass\"\n      storage_class = \"NEARLINE\"\n    }\n  }\n\n  lifecycle_rule {\n    condition {\n      age = 365\n    }\n    action {\n      type          = \"SetStorageClass\"\n      storage_class = \"COLDLINE\"\n    }\n  }\n\n  lifecycle_rule {\n    condition {\n      num_newer_versions = 3\n    }\n    action {\n      type = \"Delete\"\n    }\n  }\n\n  cors {\n    origin          = [\"https://${var.domain}\"]\n    method          = [\"GET\", \"PUT\", \"POST\"]\n    response_header = [\"*\"]\n    max_age_seconds = 3600\n  }\n\n  labels = local.common_labels\n}\n\n# Prevent public access\nresource \"google_storage_bucket_iam_binding\" \"prevent_public\" {\n  bucket = google_storage_bucket.data.name\n  role   = \"roles/storage.objectViewer\"\n  members = [\n    \"serviceAccount:${google_service_account.app.email}\",\n  ]\n}\n```\n\n## Cost Optimization\n\n### Committed Use Discounts\n\n| Commitment | Discount |\n|------------|----------|\n| 1-year CUD | 37% |\n| 3-year CUD | 55% |\n| Spot VMs | 60-91% |\n\n### Budget Alerts\n\n```hcl\nresource \"google_billing_budget\" \"main\" {\n  billing_account = var.billing_account_id\n  display_name    = \"${var.project_id} Budget\"\n\n  budget_filter {\n    projects = [\"projects/${var.project_id}\"]\n  }\n\n  amount {\n    specified_amount {\n      currency_code = \"USD\"\n      units         = var.monthly_budget\n    }\n  }\n\n  threshold_rules {\n    threshold_percent = 0.5\n    spend_basis       = \"CURRENT_SPEND\"\n  }\n\n  threshold_rules {\n    threshold_percent = 0.8\n    spend_basis       = \"CURRENT_SPEND\"\n  }\n\n  threshold_rules {\n    threshold_percent = 1.0\n    spend_basis       = \"FORECASTED_SPEND\"\n  }\n\n  all_updates_rule {\n    pubsub_topic = google_pubsub_topic.budget_alerts.id\n  }\n}\n```\n\n## CLI Reference\n\n```bash\n# Auth\ngcloud auth login\ngcloud auth application-default login\ngcloud config set project PROJECT_ID\n\n# Compute\ngcloud compute instances list\ngcloud compute instances start INSTANCE\ngcloud compute ssh INSTANCE --zone ZONE\n\n# GKE\ngcloud container clusters get-credentials CLUSTER --region REGION\ngcloud container clusters list\n\n# Cloud Run\ngcloud run services list\ngcloud run deploy SERVICE --image IMAGE --region REGION\ngcloud run services update-traffic SERVICE --to-latest\n\n# Cloud SQL\ngcloud sql instances list\ngcloud sql connect INSTANCE --user USER\n\n# Storage\ngsutil ls gs://BUCKET/\ngsutil cp FILE gs://BUCKET/\ngsutil rsync -r ./folder gs://BUCKET/folder\n\n# Secrets\ngcloud secrets list\ngcloud secrets versions access latest --secret SECRET_NAME\n\n# Logs\ngcloud logging read \"resource.type=cloud_run_revision\" --limit 100\n```\n\n## Security Checklist\n\n- [ ] VPC Service Controls enabled\n- [ ] Private Google Access enabled\n- [ ] Cloud NAT for outbound traffic\n- [ ] Workload Identity for GKE\n- [ ] Binary Authorization enabled\n- [ ] Cloud Armor for DDoS protection\n- [ ] Secret Manager for credentials\n- [ ] Cloud Audit Logs enabled\n- [ ] Security Command Center enabled\n\n## Integration\n\nWorks with:\n- `/terraform` - GCP provider configuration\n- `/k8s` - GKE deployments\n- `/devops` - GCP deployment pipelines\n- `/security` - GCP security review\n"},"lastSynced":"2026-02-20T04:57:41.390Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Agents needing expertise in designing secure and scalable Google Cloud Platform architectures.","zh":"非常适合需要在设计安全且可扩展的Google Cloud Platform架构方面拥有专业知识的云代理。","ja":"Google Cloud Platformアーキテクチャを設計するための専門知識が必要なクラウドエージェントに最適です。","ko":"구글 클라우드 플랫폼 아키텍처를 설계하는 데 전문 지식이 필요한 클라우드 에이전트에게 적합합니다.","es":"Perfecto para agentes de Cloud que necesitan experiencia en el diseño de arquitecturas de Google Cloud Platform seguras y escalables.","fr":"Parfait pour les agents Cloud ayant besoin d''expertise dans la conception d''architectures de plateforme Google Cloud sécurisées et évolutives.","de":"Perfekt für Cloud-Agents, die Expertenwissen im Entwurf sicherer und skalierbarer Google Cloud Platform-Architekturen benötigen.","pt":"Perfeito para Agentes de Nuvem que necessitam de especialização em projetar arquiteturas seguras e escaláveis da Plataforma Google Cloud.","ru":"Идеально подходит для облачных агентов, которым необходимы знания в области проектирования безопасных и масштабируемых архитектур платформы Google Cloud.","ar":"مثالي لعميل السحابة الذي يحتاج إلى خبرة في تصميم هياكل منصة جوجل سحابية آمنة ومقاسة"},"recommendation":{"en":"Empowers agents to deploy applications to GCP services, configure IAM policies, and optimize costs and performance using Google Kubernetes Engine (GKE) and other core services like Compute, Networking, and Storage, while ensuring compliance with VPC and firewall rules protocols.","zh":"赋予代理部署应用程序到GCP服务、配置IAM策略、使用Google Kubernetes Engine（GKE）和其他核心服务（如计算、网络和存储）优化成本和性能，同时确保遵守VPC和防火墙规则协议。","ja":"エージェントがGCPサービスにアプリケーションをデプロイし、IAMポリシーを構成し、Google Kubernetes Engine（GKE）およびCompute、Networking、Storageなどのコアサービスを使用してコストとパフォーマンスを最適化し、VPCおよびファイアウォールルールのプロトコルに準拠するようにします。","ko":"에이전트가 GCP 서비스에 애플리케이션을 배포하고, IAM 정책을 구성하고, 구글 쿠버네티스 엔진(GKE) 및 컴퓨팅, 네트워킹, 스토리지와 같은 핵심 서비스를 사용하여 비용과 성능을 최적화하고, VPC 및 방화벽 규칙 프로토콜을 준수하도록 합니다.","es":"Habilita a los agentes para implementar aplicaciones en servicios de GCP, configurar políticas de IAM, y optimizar costos y rendimiento utilizando Google Kubernetes Engine (GKE) y otros servicios básicos como Compute, Networking y Storage, garantizando el cumplimiento de protocolos de reglas de VPC y firewall.","fr":"Permet aux agents de déployer des applications sur les services GCP, de configurer des stratégies IAM, et d''optimiser les coûts et les performances en utilisant Google Kubernetes Engine (GKE) et d''autres services de base tels que Compute, Networking et Storage, tout en garantissant la conformité aux protocoles de règles de VPC et de pare-feu.","de":"Ermächtigt Agenten, Anwendungen auf GCP-Dienste zu deployen, IAM-Richtlinien zu konfigurieren und Kosten und Leistung mit Google Kubernetes Engine (GKE) und anderen Kernservices wie Compute, Networking und Storage zu optimieren, während die Einhaltung von VPC- und Firewall-Regelnprotokollen gewährleistet wird.","pt":"Habilita os agentes a implantar aplicações nos serviços do GCP, configurar políticas do IAM, otimizar custos e desempenho usando o Google Kubernetes Engine (GKE) e outros serviços principais como Computação, Rede e Armazenamento, garantindo a conformidade com os protocolos de regras de VPC e firewall.","ru":"Наделяет агентов возможностью развертывать приложения в сервисах GCP, настраивать политики IAM, оптимизировать затраты и производительность с использованием Google Kubernetes Engine (GKE) и других основных сервисов, таких как Compute, Networking и Storage, обеспечивая соблюдение протоколов правил VPC и брандмауэра.","ar":"يمنح الوكلاء القدرة على نشر التطبيقات على خدمات جوجل سحابية، وتكوين سياسات IAM، وضبط التكاليف والأداء باستخدام محرك كوبرنيتيس جوجل (GKE) وخدمات أساسية أخرى مثل الحوسبة والشبكة والتخزين، مع ضمان الامتثال لبروتوكولات قواعد VPC وجدار الحماية."},"useCases":{"en":["Designing GCP architecture for new projects","Deploying applications to GCP services with configured IAM policies","Optimizing GKE cluster performance and costs"],"zh":["为新项目设计GCP架构","将应用程序部署到GCP服务并配置IAM策略","优化GKE集群性能和成本"],"ja":["新しいプロジェクト用のGCPアーキテクチャを設計する","GCPサービスにアプリケーションをデプロイし、IAMポリシーを構成する","GKEクラスターのパフォーマンスとコストを最適化する"],"ko":["새로운 프로젝트를 위한 GCP 아키텍처 설계","GCP 서비스에 애플리케이션을 배포하고 IAM 정책을 구성","GKE 클러스터의 성능과 비용을 최적화"],"es":["Diseñar arquitectura de GCP para nuevos proyectos","Implementar aplicaciones en servicios de GCP con políticas de IAM configuradas","Optimizar el rendimiento y los costos del clúster GKE"],"fr":["Concevoir l''architecture GCP pour de nouveaux projets","Déployer des applications sur les services GCP avec des stratégies IAM configurées","Optimiser les performances et les coûts du cluster GKE"],"de":["GCP-Architektur für neue Projekte entwerfen","Anwendungen auf GCP-Dienste mit konfigurierten IAM-Richtlinien deployen","Leistung und Kosten des GKE-Clusters optimieren"],"pt":["Projetar arquitetura do GCP para novos projetos","Implantar aplicações nos serviços do GCP com políticas do IAM configuradas","Otimizar o desempenho e os custos do cluster GKE"],"ru":["Проектирование архитектуры GCP для новых проектов","Развертывание приложений в сервисах GCP с настроенными политиками IAM","Оптимизация производительности и затрат кластера GKE"],"ar":["تصميم هيكل جوجل سحابي لمشاريع جديدة","نشر تطبيقات على خدمات جوجل سحابية مع سياسات IAM تم تكوينها","تحسين أداء وتكلفة كلاستر GKE"]},"limitations":{"en":["Requires Google Cloud Platform account and credentials","GCP services and features may change over time"],"zh":["需要Google Cloud Platform账号和凭据","GCP服务和功能可能会随时间而改变"],"ja":["Google Cloud Platformアカウントと資格情報が必要","GCPサービスおよび機能は時間の経過とともに変更される場合がある"],"ko":["구글 클라우드 플랫폼 계정 및 자격 증명이 필요","GCP 서비스 및 기능은 시간이 지남에 따라 변경될 수 있음"],"es":["Requiere cuenta y credenciales de Google Cloud Platform","Los servicios y características de GCP pueden cambiar con el tiempo"],"fr":["Nécessite un compte et des informations d''identification de la plateforme Google Cloud","Les services et fonctionnalités de GCP peuvent changer avec le temps"],"de":["Benötigt Google Cloud Platform-Konto und -Anmeldeinformationen","GCP-Dienste und -Funktionen können sich im Laufe der Zeit ändern"],"pt":["Exige conta e credenciais da Plataforma Google Cloud","Serviços e recursos do GCP podem mudar ao longo do tempo"],"ru":["Требуется учетная запись и учетные данные платформы Google Cloud","Сервисы и функции GCP могут меняться со временем"],"ar":["يتطلب حسابًا وأرصدة منصة جوجل سحابية","يمكن أن تتغير خدمات وسمات جوجل سحابية مع مرور الوقت"]},"version":3},"contentHash":"837cef6e2d84dba312033d4c194ad1cac058035557ea9fcbb02c28d8274db79d","qualityScore":70}');
