INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/gcp-architecture', 'gcp-architecture', 'majiayu000', 'claude-skill-registry', 'community', 'gcp-architecture majiayu000 claude-skill-registry community 本指南提供了在Google Cloud Platform上设计安全、可扩展的基础设施的综合指南，涵盖计算、网络和IAM等核心服务 このガイドでは、Google Cloud Platform上でセキュアでスケーラブルなインフラストラクチャを設計するための包括的なガイドを提供します。コンピューティング、ネットワーク、IAMなどの主要サービスをカバーしています 이 가이드는 Google Cloud Platform에서 보안 및 확장 가능한 인프라를 디자인하는 방법에 대한 포괄적인 가이드를 제공합니다. 컴퓨팅, 네트워킹, IAM 등의 핵심 서비스를 다룹니다 Guía completa para construir infraestructuras seguras y escalables en Google Cloud Platform Guide complet pour construire des infrastructures sécurisées et évolutivité sur Google Cloud Platform Umfassender Leitfaden für den Bau von sicheren und skalierbaren Infrastrukturen auf Google Cloud Platform Guia completo para construir infraestrutura segura e escalável na Google Cloud Platform, incluindo design de arquitetura, deploy de aplicações e configuração de IAM Полное руководство по созданию безопасной и масштабируемой инфраструктуры на Google Cloud Platform, включая проектирование архитектуры, развертывание приложений и настройку IAM دليل شامل لإنشاء بنية تحتية آمنة ومتوسعة على منصة جوجل كلاود، بما في ذلك تصميم الهندسة وتنفيذ التطبيقات وضبط IAM The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app GCP架构 Google Cloud Platform 云计算 安全 可扩展性 计算服务 网络服务 IAM服务 容器编排 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/boq', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'boq', 0, 0, 70, '2026-02-20T04:13:19.578Z', '2026-02-20T04:57:56.766Z', '91bd4239e38bc74f5eb2d2954d0d62ad7b8ca906965ec7e3b96ff8122b0621d5', '{"id":"majiayu000/claude-skill-registry/boq","name":"boq","description":{"zh":"BOQ 技能是用于创建和管理建筑成本估算的综合技能，支持 Excel 格式","ja":"BOQ スキルは、建設費用見積もりを作成して管理するための包括的なスキルです。Excel 形式をサポートしています","ko":"BOQ 스킬은 건설 비용 추정을 생성하고 관리하기 위한 포괄적인 스킬으로 엑셀 형식을 지원합니다","es":"La habilidad BOQ es una herramienta para la gestión de cantidades y precios de construcción, que ayuda a los desarrolladores a crear y administrar documentos de BOQ con Excel","fr":"La compétence BOQ est un outil pour la gestion des quantités et des prix de construction, qui aide les développeurs à créer et gérer des documents de BOQ avec Excel","de":"Die Fähigkeit BOQ ist ein Werkzeug für die Verwaltung von Mengen und Preisen im Bauwesen, das Entwicklern hilft, BOQ-Dokumente mit Excel zu erstellen und zu verwalten","pt":"A ferramenta BOQ é uma solução para gerenciar obras de construção, permitindo criar e gerenciar folhas de quantidades com o Excel.","ru":"Инструмент BOQ - это решение для управления строительством, позволяющее создавать и управлять таблицами количеств с помощью Excel.","ar":"أداة BOQ هي حل لإدارة المشاريع الإنشائية، تمكن من إنشاء و إدارة جداول الكميات باستخدام برنامج إكسل.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"BOQ 技能：使用 Excel 管理建筑成本估算","ja":"BOQ スキル：Excel を使用した建設費用見積もり管理","ko":"BOQ 스킬: 엑셀을 사용한 건설 비용 추정 관리","es":"BOQ: Gestión de Cantidades y Precios de Construcción","fr":"BOQ: Gestion des Quantités et des Prix de Construction","de":"BOQ: Verwaltung von Mengen und Preisen im Bauwesen","pt":"BOQ: Ferramenta de Gerenciamento de Obras","ru":"BOQ: Инструмент управления строительством","ar":"BOQ: أداة إدارة المشاريع الإنشائية","en":"boq"},"description":{"zh":"BOQ 技能是用于创建和管理建筑成本估算的综合技能，支持 Excel 格式","ja":"BOQ スキルは、建設費用見積もりを作成して管理するための包括的なスキルです。Excel 形式をサポートしています","ko":"BOQ 스킬은 건설 비용 추정을 생성하고 관리하기 위한 포괄적인 스킬으로 엑셀 형식을 지원합니다","es":"La habilidad BOQ es una herramienta para la gestión de cantidades y precios de construcción, que ayuda a los desarrolladores a crear y administrar documentos...","fr":"La compétence BOQ est un outil pour la gestion des quantités et des prix de construction, qui aide les développeurs à créer et gérer des documents de BOQ ave...","de":"Die Fähigkeit BOQ ist ein Werkzeug für die Verwaltung von Mengen und Preisen im Bauwesen, das Entwicklern hilft, BOQ-Dokumente mit Excel zu erstellen und zu ...","pt":"A ferramenta BOQ é uma solução para gerenciar obras de construção, permitindo criar e gerenciar folhas de quantidades com o Excel.","ru":"Инструмент BOQ - это решение для управления строительством, позволяющее создавать и управлять таблицами количеств с помощью Excel.","ar":"أداة BOQ هي حل لإدارة المشاريع الإنشائية، تمكن من إنشاء و إدارة جداول الكميات باستخدام برنامج إكسل.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["创建和管理建筑成本估算","支持 Excel 格式","包含 5 个主要工作类别","生成详细的成本报告","提高工作效率和准确性"],"ja":["建設費用見積もりを作成して管理","Excel 形式をサポート","5 つの主要な作業カテゴリを含む","詳細なコストレポートを生成","作業効率と精度を向上させる"],"ko":["건설 비용 추정을 생성하고 관리","엑셀 형식을 지원","5개의 주요 작업 분류를 포함","상세한 비용 보고서를 생성","작업 효율과 정확도를 향상시키는"],"es":["Gestión de cantidades y precios de construcción","Creación de documentos de BOQ con Excel","Organización de los documentos en carpetas","Seguimiento de los costos y presupuestos","Análisis de los datos de construcción"],"fr":["Gestion des quantités et des prix de construction","Création de documents de BOQ avec Excel","Organisation des documents dans des dossiers","Suivi des coûts et des budgets","Analyse des données de construction"],"de":["Verwaltung von Mengen und Preisen im Bauwesen","Erstellung von BOQ-Dokumenten mit Excel","Organisation der Dokumente in Ordnern","Verfolgung der Kosten und Budgets","Analyse der Baudaten"],"pt":["Criação de folhas de quantidades personalizadas","Gerenciamento de obras de construção com o Excel","Organização de trabalhos em 5 categorias principais","Padrões de melhores práticas para criação de BOQ","Armazenamento de arquivos em pasta separada"],"ru":["Создание индивидуальных таблиц количеств","Управление строительными проектами с помощью Excel","Организация работ в 5 основных категориях","Стандарты лучших практик для создания BOQ","Хранение файлов в отдельной папке"],"ar":["إنشاء جداول كميات مخصصة","إدارة المشاريع الإنشائية باستخدام برنامج إكسل","تنظيم الأعمال في 5 فئات رئيسية","معايير أفضل الممارسات لإنشاء قائمة الكميات","تخزين الملفات في مجلد منفصل"]},"keywords":{"zh":["BOQ","建筑成本估算","Excel","建设项目管理","成本管理","建筑工程"],"ja":["BOQ","建設費用見積もり","Excel","建設プロジェクト管理","コスト管理","建築エンジニアリング"],"ko":["BOQ","건설 비용 추정","엑셀","건설 프로젝트 관리","비용 관리","건축 공학"],"es":["BOQ","gestión de cantidades","precios de construcción","Excel","documentos de BOQ","construcción","presupuestos","costos","análisis de datos"],"fr":["BOQ","gestion des quantités","prix de construction","Excel","documents de BOQ","construction","budgets","coûts","analyse de données"],"de":["BOQ","Verwaltung von Mengen","Preise im Bauwesen","Excel","BOQ-Dokumente","Bauwesen","Budgets","Kosten","Datenanalyse"],"pt":["BOQ","gerenciamento de obras","folhas de quantidades","Excel","construção civil","gestão de projetos","engenharia","arquitetura"],"ru":["BOQ","управление строительством","таблицы количеств","Excel","строительство","управление проектами","инженерия","архитектура"],"ar":["BOQ","إدارة المشاريع الإنشائية","جداول الكميات","إكسل","الإنشاءات المدنية","إدارة المشاريع","الهندسة","العمارة"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"boq","description":"Comprehensive BOQ (Bill of Quantities) creation and management for construction projects. This skill should be used when Claude needs to: (1) Create new BOQ files with standard work categories, (2) Add items to existing BOQ, (3) Manage construction cost estimates with material and labor breakdowns, (4) Generate Thai construction project cost sheets with proper formatting","bodyPreview":"# BOQ (Bill of Quantities) Skill\n\nทักษะสำหรับจัดทำและจัดการใบประมาณราคาค่าก่อสร้าง (BOQ) ด้วย Excel\n\n**📁 Output Location:** ไฟล์ BOQ ที่สร้างจะถูกบันทึกไปที่ `workspace/boq_examples/` เพื่อแยกออกจาก skill folder\n\n**📚 Best Practices:** อ่านแนวทางการจัดทำ BOQ ที่ถูกต้องได้ที่ `BEST_PRACTICES.md`\n\n## หมวดงานมาตรฐาน\n\nBOQ ทุกไฟล์จะมี 5 หมวดงานหลัก:\n1. **งานเตรียมการ** - งานรื้อถอน, ปรับพื้นที่, ขนขยะ\n2. **งานโครงสร้าง** - งานเทคอนกรีต, เหล็กเสริม, โครงสร้างหลัก\n3. **งานสถาปัตยกรรม** - งานผนัง, งานฝ","body":"# BOQ (Bill of Quantities) Skill\n\nทักษะสำหรับจัดทำและจัดการใบประมาณราคาค่าก่อสร้าง (BOQ) ด้วย Excel\n\n**📁 Output Location:** ไฟล์ BOQ ที่สร้างจะถูกบันทึกไปที่ `workspace/boq_examples/` เพื่อแยกออกจาก skill folder\n\n**📚 Best Practices:** อ่านแนวทางการจัดทำ BOQ ที่ถูกต้องได้ที่ `BEST_PRACTICES.md`\n\n## หมวดงานมาตรฐาน\n\nBOQ ทุกไฟล์จะมี 5 หมวดงานหลัก:\n1. **งานเตรียมการ** - งานรื้อถอน, ปรับพื้นที่, ขนขยะ\n2. **งานโครงสร้าง** - งานเทคอนกรีต, เหล็กเสริม, โครงสร้างหลัก\n3. **งานสถาปัตยกรรม** - งานผนัง, งานฝ้า, งานสี, งานพื้น\n4. **งานระบบไฟฟ้า** - ระบบไฟฟ้า, ระบบแสงสว่าง, เต้ารับ\n5. **งานระบบสุขาภิบาล** - งานประปา, งานท่อ, สุขภัณฑ์\n\n## โครงสร้างตาราง BOQ\n\nแต่ละ BOQ จะมีคอลัมน์:\n- **ลำดับ** - เลขที่รายการ\n- **รายการ** - รายละเอียดงาน\n- **ปริมาณ** - จำนวน\n- **หน่วย** - หน่วยนับ (ตร.ม., ตร.วา, จุด, ชุด, etc.)\n- **ค่าวัสดุต่อหน่วย** - ราคาวัสดุต่อหน่วย\n- **ราคารวมวัสดุ** - คำนวณอัตโนมัติ: ปริมาณ × ค่าวัสดุต่อหน่วย\n- **ค่าแรงต่อหน่วย** - ค่าแรงต่อหน่วย\n- **ค่าแรงรวม** - คำนวณอัตโนมัติ: ปริมาณ × ค่าแรงต่อหน่วย\n- **รวมราคา** - คำนวณอัตโนมัติ: ราคารวมวัสดุ + ค่าแรงรวม\n- **หมายเหตุ** - หมายเหตุเพิ่มเติม\n\n## การใช้งาน\n\n### 1. สร้าง BOQ ใหม่\n\nUse the `boq_helper.py` script to create a new BOQ:\n\n```bash\npython boq_helper.py create <filename> [project_name] [location] [customer]\n```\n\n**Examples:**\n\n```bash\n# สร้าง BOQ พื้นฐาน\npython boq_helper.py create project_boq.xlsx\n\n# สร้าง BOQ พร้อมข้อมูลโครงการ\npython boq_helper.py create office_renovation.xlsx \"โครงการปรับปรุงสำนักงาน\" \"กรุงเทพมหานคร\" \"บริษัท ABC จำกัด\"\n```\n\nThe script creates a formatted Excel file with:\n- Project information header (ข้อมูลโครงการ, สถานที่, ลูกค้า)\n- All 5 standard work categories with space for 3 items each\n- Automatic calculation formulas for costs\n- Summary rows for each category\n- Grand total at the bottom\n- Professional formatting with colors and borders\n\n### 2. เพิ่มรายการใน BOQ\n\nAdd items to specific categories:\n\n```bash\npython boq_helper.py add <filename> <category> <item_no> <description> <quantity> <unit> [material_cost] [labor_cost] [note]\n```\n\n**Parameters:**\n- `filename`: BOQ file path\n- `category`: One of the 5 standard categories (exact match required)\n- `item_no`: Item number (e.g., \"1.1\", \"2.1\")\n- `description`: Item description\n- `quantity`: Quantity (number)\n- `unit`: Unit (e.g., \"ตร.ม.\", \"ตร.วา\", \"จุด\", \"ชุด\")\n- `material_cost`: Material cost per unit (optional, default: 0)\n- `labor_cost`: Labor cost per unit (optional, default: 0)\n- `note`: Additional notes (optional)\n\n**Example:**\n\n```bash\npython boq_helper.py add office_renovation.xlsx \"งานเตรียมการ\" \"1.1\" \"รื้อถอนผนังเก่า\" 25.5 \"ตร.ม.\" 50 150 \"รวมขนย้ายเศษวัสดุ\"\n```\n\n### 3. คำนวณ Formula ใหม่\n\nAfter adding items, recalculate all formulas:\n\n```bash\npython recalc.py <filename>\n```\n\n**Example:**\n```bash\npython recalc.py office_renovation.xlsx\n```\n\nThe recalc script:\n- Recalculates all formulas (ราคารวมวัสดุ, ค่าแรงรวม, รวมราคา, etc.)\n- Updates summary rows for each category\n- Updates grand total\n- Checks for Excel errors (#REF!, #DIV/0!, etc.)\n- Returns JSON with status and any errors found\n\n## Workflow Example\n\nComplete workflow for creating a BOQ:\n\n```python\nimport subprocess\nimport json\n\n# 1. Create new BOQ\nresult = subprocess.run([\n    ''python'', ''boq_helper.py'', ''create'',\n    ''renovation.xlsx'',\n    ''โครงการปรับปรุงอาคาร'',\n    ''กรุงเทพฯ'',\n    ''บริษัท XYZ''\n], capture_output=True, text=True)\nprint(json.loads(result.stdout))\n\n# 2. Add items to different categories\nitems = [\n    (''งานเตรียมการ'', ''1.1'', ''รื้อถอนผนัง'', 30, ''ตร.ม.'', 50, 150),\n    (''งานโครงสร้าง'', ''2.1'', ''เทพื้นคอนกรีต'', 50, ''ตร.ม.'', 800, 400),\n    (''งานสถาปัตยกรรม'', ''3.1'', ''ทาสีภายใน'', 100, ''ตร.ม.'', 80, 120),\n]\n\nfor category, no, desc, qty, unit, mat, lab in items:\n    subprocess.run([\n        ''python'', ''boq_helper.py'', ''add'',\n        ''renovation.xlsx'', category, no, desc,\n        str(qty), unit, str(mat), str(lab)\n    ], capture_output=True, text=True)\n\n# 3. Recalculate formulas\nresult = subprocess.run([\n    ''python'', ''recalc.py'', ''renovation.xlsx''\n], capture_output=True, text=True)\nprint(json.loads(result.stdout))\n```\n\n## Using Python Directly (Alternative Method)\n\nFor more flexibility, directly use openpyxl with the xlsx skill patterns:\n\n```python\nfrom openpyxl import load_workbook\n\nwb = load_workbook(''renovation.xlsx'')\nws = wb.active\n\n# Add custom item to specific row\nrow = 8  # Example row number\nws[f''A{row}''] = ''1.2''\nws[f''B{row}''] = ''งานขุดดิน''\nws[f''C{row}''] = 15.5\nws[f''D{row}''] = ''ลบ.ม.''\nws[f''E{row}''] = 200\nws[f''F{row}''] = f''=C{row}*E{row}''  # Auto-calculate\nws[f''G{row}''] = 300\nws[f''H{row}''] = f''=C{row}*G{row}''  # Auto-calculate\nws[f''I{row}''] = f''=F{row}+H{row}''  # Total\nws[f''J{row}''] = ''รวมค่าขนย้ายดิน''\n\nwb.save(''renovation.xlsx'')\n```\n\nThen recalculate:\n```bash\npython recalc.py renovation.xlsx\n```\n\n## Important Notes\n\n### Formula Usage\n- **ALWAYS use Excel formulas** instead of calculating in Python\n- Formulas ensure the BOQ remains dynamic and updateable\n- Let Excel calculate: ราคารวมวัสดุ, ค่าแรงรวม, รวมราคา\n\n### Category Limits\n- Each category can hold up to 3 items by default\n- To add more items, modify the BOQ structure or use Python directly\n\n### Recalculation\n- **MANDATORY**: Always run `recalc.py` after creating or modifying BOQ\n- This ensures all formulas are calculated correctly\n- Check the JSON output for any errors\n\n### Thai Language Support\n- All output uses Thai language\n- File names can be in Thai or English\n- Category names must match exactly (including Thai characters)\n\n### Error Handling\n- Scripts return JSON output for easy parsing\n- Check `status` field: \"success\" or \"error\"\n- Error messages are in Thai for clarity\n\n## Bundled Scripts\n\n- `boq_helper.py` - Main BOQ creation and management script\n- `recalc.py` - Formula recalculation script\n- `validate_boq.py` - Validation script for checking budget proportions\n- `BEST_PRACTICES.md` - Guidelines for creating proper BOQ\n\n## Best Practices\n\nสัดส่วนงบประมาณมาตรฐาน (สำหรับบ้านพักอาศัย):\n- **งานเตรียมการ:** ≤ 5%\n- **งานโครงสร้าง:** 28-32% (เป้าหมาย 30%)\n- **งานสถาปัตยกรรม:** 38-42% (เป้าหมาย 40%)\n- **งานระบบไฟฟ้า:** 10-14% (เป้าหมาย 12%)\n- **งานระบบสุขาภิบาล:** 12-16% (เป้าหมาย 13%)\n\nอ่านรายละเอียดเพิ่มเติมใน `BEST_PRACTICES.md`\n\n## Examples\n\nตัวอย่างการใช้งานอยู่ที่ `examples/` folder:\n\n```bash\n# สร้าง BOQ บ้านพักอาศัย 2 ชั้น (ตาม Best Practices)\npython examples/create_house_boq.py\n```\n\nไฟล์ที่สร้างจะอยู่ที่: `workspace/boq_examples/`\n\n## Validation\n\nตรวจสอบสัดส่วนงบประมาณ:\n\n```python\nfrom validate_boq import validate_from_data\n\nboq_totals = {\n    \"งานเตรียมการ\": 186916,\n    \"งานโครงสร้าง\": 1122092,\n    \"งานสถาปัตยกรรม\": 1495327,\n    \"งานระบบไฟฟ้า\": 448598,\n    \"งานระบบสุขาภิบาล\": 485981\n}\n\nvalidate_from_data(boq_totals)\n```\n"},"lastSynced":"2026-02-20T04:57:56.766Z","agentAnalysis":{"suitability":{"en":"Ideal for Construction Agents requiring precise Bill of Quantities management and Excel integration.","zh":"适用于需要精确的工程量清单管理和 Excel 集成的建筑代理","ja":"建設エージェントが正確な工事数量書の管理と Excel 統合を必要とする場合に最適","ko":"정확한 공사량 관리와 Excel 통합이 필요한 건설 에이전트에게 적합","es":"Ideal para agentes de construcción que requieren una gestión precisa de la lista de cantidades y la integración con Excel.","fr":"Idéal pour les agents de construction nécessitant une gestion précise de la liste des quantités et une intégration avec Excel.","de":"Ideal für Baubetreuer, die eine präzise Verwaltung der Leistungsbeschreibung und eine Excel-Integration erfordern.","pt":"Ideal para Agentes de Construção que requerem um gerenciamento preciso de Lista de Quantidades e integração com o Excel.","ru":"Идеально для агентов по строительству, требующих точного управления перечнем количеств и интеграции с Excel.","ar":"مثالي لعمليات وكالات البناء التي تتطلب إدارة دقيقة للكميات ودمج مع برنامج إكسل."},"recommendation":{"en":"Empowers agents to generate and manage comprehensive BOQ files with standardized work categories, including งานเตรียมการ, งานโครงสร้าง, and งานสถาปัตยกรรม, utilizing Excel for data manipulation and storage in the workspace/boq_examples/ directory.","zh":"赋予代理生成和管理全面的工事数量书文件，具有标准化的工作类别，包括 工作准备、结构工作 和 建筑工作，利用 Excel 进行数据操作和存储在 workspace/boq_examples/ 目录中","ja":"エージェントが標準化された作業カテゴリを含む包括的な工事数量書ファイルを生成、管理できるようにし、作業準備、構造作業、建築作業などのカテゴリを使用し、Excel を使用してデータ操作、workspace/boq_examples/ ディレクトリへのデータ保存を行う","ko":"에이전트가 표준화된 작업 카테고리를 포함한 포괄적인 공사량 파일을 생성 및 관리할 수 있도록 하며, 준비작업, 구조작업, 건축작업 등의 카테고리를 사용하여 Excel을 통해 데이터 조작 및 workspace/boq_examples/ 디렉토리에 데이터 저장","es":"Permite a lo