INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/enhance-prompt', 'enhance-prompt', 'majiayu000', 'claude-skill-registry', 'community', 'enhance-prompt majiayu000 claude-skill-registry community 增强提示是 Stitch 提示工程师用来优化 UI 生成结果的技术，通过最佳实践和指导来提高结果质量 Enhance Prompt は、Stitch のプロンプトエンジニアが UI 生成結果を最適化するために使用するテクニックです。ベストプラクティスとガイドを通じて結果の品質を向上させます 강화 프롬프트는 스티치 프롬프트 엔지니어가 UI 생성 결과를 최적화하기 위해 사용하는 기술입니다. 모범 사례와 지침을 통해 결과의 품질을 향상시킵니다 El ingeniero de prompts de Stitch transforma ideas de generación de UI en prompts optimizados L''ingénieur de prompts de Stitch transforme les idées de génération d''UI en prompts optimisés Der Stitch-Prompt-Ingenieur wandelt UI-Generierungs-Ideen in optimierte Prompts um O enhance-prompt é uma habilidade que ajuda a transformar ideias vagas de geração de UI em prompts polidos e otimizados para Stitch Улучшение промптов - это навык, который помогает превратить расплывчатые идеи генерации UI в отполированные и оптимизированные промпты для Stitch تحسين البرومبتات هو مهارة تساعد على تحويل الأفكار الغامضة لتوليد واجهة المستخدم إلى برومبتات منقحة ومحسنة لستيتش The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app 增强提示 Stitch 提示工程师 UI 生成结果优化 最佳实践 指导 结果质量 技术 开发 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
