INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/motion', 'motion', 'majiayu000', 'claude-skill-registry', 'community', 'motion majiayu000 claude-skill-registry community Motion Vue是一个用于Vue 3和Nuxt的动画库，提供简单的声明式动画和手势交互 Motion VueはVue 3とNuxtのためのアニメーションライブラリで、シンプルな宣言的アニメーションとジェスチャーインタラクションを提供します 모션 뷰는 Vue 3와 Nuxt를 위한 애니메이션 라이브러리로서 간단한 선언적 애니메이션과 제스처 상호작용을 제공합니다 Motion Vue es una biblioteca de animaciones para Vue 3 y Nuxt que ofrece animaciones declarativas y gestos con un tamaño de paquete mínimo Motion Vue est une bibliothèque d''animations pour Vue 3 et Nuxt qui offre des animations déclaratives et des gestes avec une taille de paquet minimale Motion Vue ist eine Animationsbibliothek für Vue 3 und Nuxt, die deklarative Animationen und Gesten mit minimalem Paketgröße bietet Motion Vue é uma biblioteca de animação para Vue 3 e Nuxt, oferecendo animações aceleradas por hardware e tamanho de bundle mínimo. Motion Vue - библиотека анимации для Vue 3 и Nuxt, предлагающая hardware-ускоренные анимации и минимальный размер бандла. موشن فيو هي مكتبة الرسوم المتحركة لفيو 3 ونيكست، توفر رسوم متحركة معززة بأجهزة و حجم حزمة صغير The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Vue 3动画 Nuxt动画 JavaScript动画库 声明式动画 手势交互 生产就绪 硬件加速 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
