INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/nuxt-seo', 'nuxt-seo', 'majiayu000', 'claude-skill-registry', 'community', 'nuxt-seo majiayu000 claude-skill-registry community Nuxt SEO是用于提升Nuxt.js应用SEO排名的工具，提供SEO配置、robots.txt和sitemap.xml生成等功能 Nuxt SEOはNuxt.jsアプリのSEOランキングを上げるためのツールです。SEO設定、robots.txt、sitemap.xmlの生成などの機能を提供します 누트 SEO는 누트js 애플리케이션의 SEO 순위를 높이기 위한 도구로, SEO 설정, robots.txt 및 sitemap.xml 생성 등의 기능을 제공합니다 Nuxt SEO es un módulo que ayuda a mejorar la optimización de sitios web, ofrece funcionalidades como configuración de SEO, generación de robots.txt y sitemap.xml, y más Nuxt SEO est un module qui aide à améliorer l''optimisation des sites web, il offre des fonctionnalités telles que la configuration de SEO, la génération de robots.txt et sitemap.xml, et plus encore Nuxt SEO ist ein Modul, das bei der Optimierung von Websites hilft, es bietet Funktionen wie SEO-Konfiguration, Generierung von robots.txt und sitemap.xml und mehr O módulo Nuxt SEO fornece recursos avançados para melhorar o SEO do seu site, incluindo configuração de site, geração de robots.txt e sitemap.xml Модуль Nuxt SEO предоставляет продвинутые функции для улучшения SEO вашего сайта, включая настройку сайта, генерацию robots.txt и sitemap.xml يوفر وحدة Nuxt SEO ميزات متقدمة لتحسين محركات البحث لsite الخاص بك، بما في ذلك إعدادات الموقع وتوليد ملفات robots.txt و sitemap.xml The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Nuxt SEO Nuxt.js SEO优化 搜索引擎优化 robots.txt sitemap.xml OG图像 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
