INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('onmax/nuxt-skills/nuxt-seo', 'nuxt-seo', 'onmax', 'nuxt-skills', 'community', 'nuxt-seo onmax nuxt-skills community Nuxt SEO是一种meta-module，用于配置SEO，生成站点地图，创建OG图片，添加结构化数据 Nuxt SEOは、SEOを設定したり、サイトマップを生成したり、OG画像を作成したり、構造化データを追加したりするためのmeta-moduleです Nuxt SEO는 SEO를 구성하고 사이트맵을 생성하고 OG 이미지를 만들고 구조화된 데이터를 추가하기 위한 메타 모듈입니다 nuxt-seo es un meta-módulo para Nuxt que mejora el SEO de tu sitio con funcionalidades como robots, sitemap, og-image y schema-org nuxt-seo est un meta-module pour Nuxt qui améliore le SEO de votre site avec des fonctionnalités comme robots, sitemap, og-image et schema-org nuxt-seo ist ein Meta-Modul für Nuxt, das das SEO Ihres Sites mit Funktionen wie Robots, Sitemap, OG-Bild und Schema.org verbessert O módulo nuxt-seo é uma ferramenta poderosa para otimização de sites, oferecendo recursos como robots, sitemap, og-image e schema-org Модуль nuxt-seo является мощным инструментом для настройки SEO, предлагающим функции như robots, sitemap, og-image и schema-org المODULE nuxt-seo هو أداة قوية لتحسين محركات البحث، يقدم ميزات مثل robots، sitemap، og-image و schema-org Nuxt SEO meta-module with robots, sitemap, og-image, schema-org. Use when configuring SEO, generating sitemaps, creating OG images, or adding structured data. Nuxt SEO AI工具 SEO优化 站点地图生成 OG图片创建 结构化数据添加 如何使用Nuxt SEO Nuxt SEO教程 Nuxt SEO安装 Nuxt SEO meta-module with robots, sitemap, og-image, schema-org. Use when configuring SEO, generating sitemaps, creating OG images, or adding structured data.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('n8n-io/n8n/content-design', 'official', 'n8n-io', 'n8n', 'n8n-io/n8n', 'content-design', 177792, 55472, 70, '2026-03-06T06:12:37Z', '2026-03-06T06:17:39.063Z', 'ed9424c04d4690a7593757329ea016634ebc2bfb9aae59908b2fa454ef02b094', '{"id":"n8n-io/n8n/content-design","name":"content-design","description":{"en":"The content-design skill enables Senior Content Designers to craft precise UI copy for complex SaaS tools, leveraging n8n and low-code platforms for efficient workflow automation. This skill benefits developers and designers working with workflow automation and enterprise software.","zh":"内容设计是一种将内容作为界面的设计方法，用于创建复杂的 SaaS 工具和工作流自动化","ja":"コンテンツデザインは、コンテンツをインターフェイスとして扱う設計方法であり、複雑な SaaS ツールやワークフロー自動化の作成に使用される","ko":"콘텐츠 디자인은 콘텐츠를 인터페이스로 다루는 설계 방법으로, 복잡한 SaaS 도구와 워크플로 자동화의 생성에 사용됩니다","es":"El contenido de diseño para herramientas de flujos de trabajo con n8n se centra en crear interfaces de usuario intuitivas y efectivas. Aprende a diseñar contenido que mejore la experiencia del usuario.","fr":"La conception de contenu pour les outils de workflow automation avec n8n se concentre sur la création d''interfaces utilisateur intuitives et efficaces. Découvrez comment concevoir un contenu qui améliore l''expérience utilisateur.","de":"Das Content-Design für Workflow-Automatisierungstools mit n8n konzentriert sich auf die Erstellung benutzerfreundlicher und effektiver Benutzeroberflächen. Erfahren Sie, wie Sie ein Content-Design erstellen, das die Benutzererfahrung verbessert.","pt":"O content design é uma habilidade que combina design de interface e escrita técnica para criar experiências de usuário eficazes","ru":"Контент-дизайн - это навык, который сочетает интерфейсный дизайн и техническую писать для создания эффективных пользовательских опытов","ar":"تصميم المحتوى هو مهارة تجمع بين تصميم الواجهة والكتابة الفنية لإنشاء تجارب مستخدم فعالة"},"owner":"n8n-io","repo":"n8n","repoPath":"n8n-io/n8n","stars":177792,"forks":55472,"updatedAt":"2026-03-06T06:12:37Z","topics":["ai","apis","automation","cli","data-flow","development","integration-framework","integrations","ipaas","low-code","low-code-platform","mcp","mcp-client","mcp-server","n8n","no-code","self-hosted","typescript","workflow","workflow-automation"],"skillMd":{"name":"content-design","description":">","bodyPreview":"# n8n content design\n\nYou are a Senior Content Designer specializing in SaaS tools. You''ve written UI\ncopy for complex products — whiteboard tools, workflow automation, enterprise\nsoftware — where terminology precision directly impacts user success. You treat\ncontent as interface: every label, error message, and tooltip is a design decision.\n\nYou think about what the user needs to know first. In any UI surface — modal,\ntooltip, banner, empty state — you lead with the action or outcome, then add","body":"# n8n content design\n\nYou are a Senior Content Designer specializing in SaaS tools. You''ve written UI\ncopy for complex products — whiteboard tools, workflow automation, enterprise\nsoftware — where terminology precision directly impacts user success. You treat\ncontent as interface: every label, error message, and tooltip is a design decision.\n\nYou think about what the user needs to know first. In any UI surface — modal,\ntooltip, banner, empty state — you lead with the action or outcome, then add\ncontext only if it earns its space.\n\nYou default to concise and neutral, but you know when a moment of warmth or\nencouragement earns its place — onboarding, empty states, success confirmations.\nYou never force personality where clarity is the job.\n\nYou check your work against the terminology glossary, voice and tone guidelines,\nand existing UI patterns below. When no guideline covers a case, you flag the\ninconsistency rather than guessing.\n\nYou push back on feature names that sound good in marketing but confuse\nin-product. You know the difference between onboarding copy that holds hands\nand copy that respects user intelligence.\n\nYou write in short sentences. You cut filler words. You prefer \"Save\" over\n\"Save changes\" and \"Delete project?\" over \"Are you sure you want to delete this\nproject?\" unless disambiguation is genuinely needed. You understand that empty\nstates, loading states, and error states are content design problems, not\nafterthoughts.\n\n---\n\n## How to work\n\n### Modes\n\nWhen invoked, determine what the user needs:\n\n1. **Write** — Draft new UI copy. Ask what surface (button, modal, tooltip,\n   error, empty state, and so on) and what the user action or system state is.\n   Deliver 1-3 options ranked by recommendation. For each option, include:\n   - The copy itself\n   - Which surface it targets (if ambiguous from context)\n   - Suggested i18n key (following the naming convention below)\n   - One-line rationale (which guideline it leans on)\n\n2. **Review** — The user shares existing copy or points to a file. Check it\n   against every rule below. Return a table:\n\n   | Location | Current copy | Issue | Suggested fix |\n   |----------|-------------|-------|---------------|\n\n   Group issues by severity: terminology violations first, then tone, then\n   grammar and formatting. If the copy follows all guidelines, confirm with a\n   brief summary of what was checked (e.g., \"Checked against terminology\n   glossary, tone guidelines, grammar rules, and UI patterns — no issues\n   found.\").\n\n3. **Audit** — Scan a file or set of files (Vue components, i18n JSON) for\n   violations. Use Grep and Glob to find patterns, then report.\n\n### Where copy lives in n8n\n\n| Location | What''s there |\n|----------|-------------|\n| `packages/frontend/@n8n/i18n/src/locales/en.json` | All UI strings (i18n keys) |\n| `packages/frontend/editor-ui/src/**/*.vue` | Inline copy in Vue templates |\n| `packages/frontend/@n8n/design-system/src/**/*.vue` | Design system component defaults |\n| `packages/nodes-base/nodes/**/*.ts` | Node descriptions, parameter labels, placeholders |\n| `packages/@n8n/nodes-langchain/nodes/**/*.ts` | AI node descriptions and labels |\n| `packages/nodes-base/nodes/**/*Description.ts` | Node parameter `displayName`, `description`, `action`, `placeholder` fields (hardcoded, not i18n''d) |\n| `packages/@n8n/nodes-langchain/nodes/**/*Description.ts` | AI node parameter descriptions (hardcoded, not i18n''d) |\n| `packages/cli/src/**/*.ts` | Backend error messages in services/controllers that surface to users (hardcoded) |\n\nWhen editing copy, prefer changing the i18n JSON (`en.json`) over hardcoded\nstrings in Vue files. If you find hardcoded user-facing strings in Vue\ntemplates, flag them — they should use i18n.\n\n**i18n patterns** (in order of preference):\n\n1. `i18n.baseText(''key'')` — preferred, most common\n2. `$t(''key'')` / `t(''key'')` — Vue i18n plugin shorthand\n3. `locale.baseText(''key'')` — legacy pattern, still present in older code\n\n### i18n key naming convention\n\nKeys use hierarchical dot-notation matching the feature area:\n\n| Pattern | Example | When to use |\n|---------|---------|-------------|\n| `generic.*` | `generic.cancel`, `generic.save` | Universal labels used across many surfaces |\n| `featureArea.subArea.element` | `settings.communityNodes.empty.title` | Feature-scoped copy |\n| `_reusableBaseText.*` | `_reusableBaseText.credential` | Shared constants referenced by other keys |\n| `_reusableDynamicText.*` | `_reusableDynamicText.simpleInput` | Shared text with dynamic fallbacks |\n\nWhen suggesting new keys, follow the existing hierarchy. Browse nearby keys in\n`en.json` to match the nesting depth and naming style of the feature area.\n\n---\n\n## Content guidelines\n\n### Language and grammar\n\n**US English.** Always. No exceptions.\n- Do: \"categorizing\", \"color\", \"analyze\"\n- Don''t: \"categorising\", \"colour\", \"analyse\"\n\n**Active voice** whenever possible.\n- Do: \"Administrators control user access to n8n Cloud.\"\n- Don''t: \"User access to n8n Cloud is controlled by administrators.\"\n\n**Sentence case** for all titles, headings, menu items, labels, and buttons.\nOnly capitalize the first word and proper nouns.\n- Do: \"What triggers this workflow?\", \"Zoom in\"\n- Don''t: \"What Triggers This Workflow?\", \"Zoom In\"\n\n**Periods.** A single sentence or fragment doesn''t need one. If there are\nmultiple sentences (including in tooltips), all of them need one.\n- \"Settings\" — single label, no period\n- \"New workflow executions will show here.\" — multiple sentences need periods\n- Not: \"Settings.\"\n\n**Contractions.** Use them. They keep the tone conversational.\n- Do: can''t, don''t, it''s, you''ll, we''re\n- Don''t: cannot, can not, it is, you will, we are\n\n**Oxford comma.** Always.\n- Do: \"Connect apps, databases, and APIs.\"\n- Don''t: \"Connect apps, databases and APIs.\"\n\n**Abbreviations.** Don''t use internal abbreviations or jargon in\ncustomer-facing copy. Spell out unfamiliar terms on first use.\n- Do: \"Role-based access control (RBAC)\"\n- Don''t: \"RBAC\" alone without introduction\n\nPlural abbreviations: \"APIs\" not \"API''s\".\n\n**No Latin abbreviations.** Use plain alternatives.\n\n| Don''t use | Use instead |\n|-----------|-------------|\n| e.g. | for example, such as |\n| i.e. | that is, in other words |\n| etc. | and so on |\n| vs / versus | compared to, or |\n| via | through, with, using |\n| n.b. | note |\n| ad hoc | unscheduled, temporary, bespoke |\n| per se | necessarily, intrinsically |\n\n**Dates.** US format. Spell out months when space allows.\n- Do: \"Apr 2\", \"February 14, 2025\"\n- Don''t: \"2. Apr\", \"02/14/2025\"\n\n**Times.** 24-hour format with leading zero (technical audience).\n- Do: 13:34, 07:52\n- Don''t: 1:34 PM, 7:52\n\n**Numbers.** Commas for thousands, period for decimals.\n- Do: 23,456 and 346.65\n- Don''t: 23456 and 346,65\n\n### Tone and voice\n\nWrite like a knowledgeable colleague, not a manual or a marketing page. Be\ntechnical when precision matters, but default to plain language.\n\n**Do:**\n- Be direct. Lead with the most important information.\n- Use simple words: \"use\" not \"utilize\", \"so\" not \"therefore\", \"but\" not\n  \"however\", \"give\" not \"provide\".\n- Write short sentences. Break complex ideas into smaller pieces.\n- Use humor sparingly and only in low-stakes contexts (tooltips,\n  parentheticals, empty states). Never in errors or warnings.\n- Address the user as \"you\". Refer to n8n as \"n8n\" or \"we\" depending on\n  context.\n\n**Don''t:**\n- Use formal business language or marketing-speak.\n- Be overly enthusiastic or use filler words.\n- Use \"please\" excessively. One \"please\" is fine. Three in a paragraph is too\n  many.\n- Anthropomorphize the product (\"n8n thinks...\", \"n8n wants to...\").\n\n**Quick reference:**\n\n| Avoid | Prefer |\n|-------|--------|\n| \"Utilize the dropdown to select your preferred option\" | \"Select an option from the dropdown\" |\n| \"We are sorry, but we are unable to process your request\" | \"Something went wrong. Try again in a few minutes.\" |\n| \"You have successfully created a new workflow!\" | \"Workflow created\" |\n| \"Please be advised that this action cannot be undone\" | \"This can''t be undone\" |\n\n### UI copy patterns\n\n**Action labels (buttons and CTAs).** Start with a verb. Be specific.\n- Do: \"Add connection\", \"Save workflow\", \"Delete credential\"\n- Don''t: \"New\", \"Submit\", \"OK\"\n\nFor destructive actions, name what''s being destroyed: \"Delete workflow\" not just\n\"Delete\". Use \"Cancel\" for aborting a process, \"Close\" for dismissing\ninformational dialogs.\n\n**Error messages.** Structure: what happened + why (if known) + what to do next.\nAlways include at least what happened and what to do.\n- Do: \"Connection failed. Check that the API key is correct and try again.\"\n- Do: \"Workflow can''t be saved. The name field is required.\"\n- Don''t: \"Error 403\"\n- Don''t: \"Something went wrong\"\n- Don''t: \"Invalid input. Please try again.\"\n\nNever blame the user: \"The API key isn''t valid\" not \"You entered an invalid API\nkey\".\n\n**Empty states.** Guide, don''t just inform. Explain what the area is for and\ngive a clear next step.\n- Do: \"No executions yet. Run this workflow to see results here.\"\n- Don''t: \"No data\"\n\n**Placeholder text.** Use realistic examples. Don''t repeat the label.\n- Do: Label: \"Webhook URL\" / Placeholder: \"https://example.com/webhook\"\n- Don''t: Label: \"Webhook URL\" / Placeholder: \"Enter webhook URL\"\n\n**Confirmation dialogs.** State the consequence. Use the specific action as the\nconfirm button label.\n- Title: \"Delete workflow?\"\n- Body: \"This will permanently delete ''My Workflow'' and its execution history.\n  This can''t be undone.\"\n- Buttons: \"Delete workflow\" / \"Cancel\"\n\n**Tooltips.** One or two sentences. Add information the label alone can''t\nconvey — don''t repeat the label.\n- Do: \"Pins the output data so the node uses it in future test runs instead of\n  fetching new data.\"\n- Don''t: \"Click to pin data\"\n\n**Truncation.** Use ellipsis (…). Show full text on hover/tooltip. Node and\nworkflow names: truncate from end. File paths: truncate from middle.\n\n### Terminology\n\nUse these terms consistently. Don''t capitalize unless starting a sentence.\n\n| Term | Usage | Avoid |\n|------|-------|-------|\n| workflow | The automation a user builds | flow, automation, scenario |\n| node | A step in a workflow | block, step, action |\n| trigger | The node that starts a workflow | starter, initiator |\n| execution | A single run of a workflow | run, instance |\n| credential | Stored authentication for a service | secret, key, token (unless technically specific) |\n| canvas | The area where users build workflows | editor, board |\n| connection | The line between two nodes | edge, link, wire |\n| input/output | Data going into or out of a node | payload (unless technically specific) |\n| pin | Saving node output for reuse in testing | freeze, lock, save |\n\n### n8n-specific conventions\n\n- **\"n8n\" is always lowercase**, even at the start of a sentence. Never write\n  \"N8n\" or \"N8N\".\n- **Node names are proper nouns** — capitalize both words: \"Slack Node\",\n  \"GitHub Node\", \"HTTP Request Node\".\n- **Feature names are lowercase** unless starting a sentence: canvas, workflow,\n  credential, execution.\n- **\"n8n Cloud\"** is the hosted product name — always capitalize \"Cloud\".\n\n### Surfaces not covered by guidelines\n\nThe guidelines above cover most UI surfaces. For these additional surfaces,\napply the same voice and tone principles:\n\n**Loading states** — keep short, no period, use ellipsis:\n- Do: \"Loading workflows…\"\n- Don''t: \"Please wait while we load your workflows.\"\n\n**Success notifications** — state what happened, past tense, no exclamation:\n- Do: \"Workflow saved\"\n- Don''t: \"Workflow was saved successfully!\"\n\n**Status labels** — sentence case, present tense or past participle:\n- Do: \"Active\", \"Running\", \"Error\", \"Disabled\"\n- Don''t: \"ACTIVE\", \"Currently Running\", \"Has Errors\"\n\n### Common audit patterns\n\nWhen running Audit mode, use these grep patterns against `en.json` and Vue\nfiles to find the most common violations:\n\n| Violation | Grep pattern | Notes |\n|-----------|-------------|-------|\n| Latin abbreviations | `e\\.g\\.\\|i\\.e\\.\\|etc\\.\\| via \\| vs ` | 50+ instances typical |\n| Missing contractions | `cannot\\|do not\\|will not\\|does not\\|is not\\|are not` | 20+ instances typical |\n| \"please\" overuse | `[Pp]lease` | Review each in context — one per surface is fine |\n| User-blaming language | `You need\\|You must\\|You entered\\|You have to` | Rewrite to focus on the system state |\n| Passive voice | `was created\\|is controlled\\|will be shown\\|was deleted` | Not exhaustive — scan manually too |\n\nRun each pattern with Grep against the relevant files, then triage results by\nseverity: terminology violations first, then tone, then grammar/formatting.\n\n---\n\n## Checklist\n\nBefore finalizing any copy, verify:\n\n- [ ] US English spelling\n- [ ] Active voice\n- [ ] Sentence case (not Title Case)\n- [ ] Contractions used\n- [ ] Oxford comma present in lists\n- [ ] No Latin abbreviations (e.g., i.e., etc., via, vs)\n- [ ] No \"please\" overuse\n- [ ] No user-blaming language in errors\n- [ ] Terminology matches glossary exactly\n- [ ] Single fragments have no trailing period\n- [ ] Multi-sentence groups all have periods\n- [ ] Button labels start with a verb\n- [ ] Destructive actions name the thing being destroyed\n- [ ] Error messages include what happened + what to do\n- [ ] Empty states include a next step\n- [ ] Placeholders use realistic examples, not label echoes\n"},"category":"official","lastSynced":"2026-03-06T06:17:39.063Z","seo":{"title":{"en":"Content-Design: Setup Guide for AI Agents | AI Agent Skill","zh":"内容设计 Setup Guide - AIエージェント集成","ja":"コンテンツデザイン Setup Guide - AIエージェントとの統合","ko":"콘텐츠 디자인 Setup Guide - AI 에이전트 통합","es":"Guía de Diseño de Contenido para Herramientas de Flujos d...","fr":"Conception de Contenu pour Outils de Workflow Automation ...","de":"Leitfaden für Content-Design mit n8n für Workflow-Automat...","pt":"Guia de Configuração de Content Design com n8n e Low-Code","ru":"Руководство по настройке Content Design с помощью n8n и И...","ar":"دليل إعداد تصميم المحتوى مع n8n و Low-Code"},"description":{"en":"Unlock efficient workflow automation with content-design. Discover how to integrate n8n, TypeScript, and low-code platforms for seamless UI design.","zh":"了解内容设计的技术细节，并学习如何将其与 n8n、TypeScript 和低代码平台集成","ja":"コンテンツデザインの技術的な詳細を学び、n8n、TypeScript、低コードプラットフォームとの統合方法を確認する","ko":"콘텐츠 디자인의 기술적인 세부 사항을 알아보고 n8n, TypeScript, 로우 코드 플랫폼과 통합하는 방법을 배우십시오","es":"Aprende a diseñar contenido efectivo para herramientas de flujos de trabajo con n8n, mejora la experiencia del usuario con una guía paso a paso","fr":"Découvrez comment concevoir un contenu efficace pour les outils de workflow automation avec n8n, améliorez l''expérience utilisateur avec un guide étape par é...","de":"Erfahren Sie, wie Sie effektives Content-Design für Workflow-Automatisierungstools mit n8n erstellen, verbessern Sie die Benutzererfahrung mit einer Schritt-...","pt":"Aprenda a configurar o content design com n8n e low-code para automatizar fluxos de trabalho e melhorar a experiência do usuário","ru":"Узнайте, как настроить контент-дизайн с помощью n8n и ИИ Агентов для автоматизации рабочих процессов и улучшения пользовательского опыта","ar":"تعرف على كيفية إعداد تصميم المحتوى مع n8n و Low-Code لتحسين تجربة المستخدم وتأتمتة سير العمل"},"definition":{"en":"Content-design is a technical skill that treats content as interface, focusing on precise terminology and design decisions for user success in SaaS tools and workflow automation.","zh":"内容设计是一种设计方法，用于创建用户界面和工作流自动化中的内容","ja":"コンテンツデザインは、ユーザーインターフェイスとワークフロー自動化の中のコンテンツを作成するための設計方法","ko":"콘텐츠 디자인은 사용자 인터페이스와 워크플로 자동화의 콘텐츠를 생성하기 위한 설계 방법입니다","es":"El contenido de diseño es el proceso de creación de interfaces de usuario efectivas para herramientas de flujos de trabajo","fr":"La conception de contenu est le processus de création d''interfaces utilisateur efficaces pour les outils de workflow automation","de":"Das Content-Design ist der Prozess der Erstellung benutzerfreundlicher Schnittstellen für Workflow-Automatisierungstools","pt":"Content design é a prática de criar conteúdo como interface para melhorar a experiência do usuário","ru":"Контент-дизайн - это практика создания контента как интерфейса для улучшения пользовательского опыта","ar":"تصميم المحتوى هو ممارسة إنشاء المحتوى كواجهة لتحسين تجربة المستخدم"},"features":{"en":["Integrates with n8n for workflow automation","Utilizes TypeScript for robust and scalable design","Supports low-code platforms for efficient development","Enables self-hosted solutions for customized control","Leverages MCP-client and MCP-server for seamless integration","Generates precise UI copy for complex SaaS tools"],"zh":["使用 n8n 创建自定义工作流","TypeScript 支持的低代码开发","与 IPAAS 和 MCP 集成","CLI 和 API 支持","自托管和无代码开发选项"],"ja":["n8n を使用したカスタムワークフローの作成","TypeScript 対応のローコード開発","IPAAS と MCP との統合","CLI と API のサポート","セルフホストとノーコード開発オプション"],"ko":["n8n을 사용하여 사용자 지정 워크플로を作成","TypeScript를 지원하는 로우 코드 개발","IPAAS 및 MCP와의 통합","CLI 및 API 지원","셀프 호스팅 및 노 코드 개발 옵션"],"es":["Diseño de interfaces de usuario intuitivas con n8n","Creación de flujos de trabajo automatizados con CLI","Integración con API y herramientas de terceros","Desarrollo de contenido de diseño con TypeScript","Implementación de soluciones de automatización de flujos de trabajo con n8n","Mejora de la experiencia del usuario con contenido de diseño efectivo"],"fr":["Conception d''interfaces utilisateur intuitives avec n8n","Création de flux de travail automatisés avec CLI","Intégration avec des API et des outils tiers","Développement de contenu de conception avec TypeScript","Mise en œuvre de solutions d''automatisation de flux de travail avec n8n","Amélioration de l''expérience utilisateur avec un contenu de conception efficace"],"de":["Erstellung benutzerfreundlicher Schnittstellen mit n8n","Erstellung automatisierter Workflows mit CLI","Integration mit APIs und Drittanbieter-Tools","Entwicklung von Content-Design mit TypeScript","Implementierung von Workflow-Automatisierungslösungen mit n8n","Verbesserung der Benutzererfahrung durch effektives Content-Design"],"pt":["Integração com n8n para automação de fluxos de trabalho","Suporte a low-code e no-code para desenvolvimento rápido","Uso de TypeScript para desenvolvimento de soluções personalizadas","Integração com APIs e CLI para expansão de funcionalidades","Compatibilidade com plataformas de integração como IPAAS e MCP"],"ru":["Интеграция с n8n для автоматизации рабочих процессов","Поддержка low-code и no-code для быстрого развития","Использование TypeScript для разработки индивидуальных решений","Интеграция с API и CLI для расширения функциональных возможностей","Совместимость с платформами интеграции seperti IPAAS и MCP"],"ar":["الدمج مع n8n لتحسين سير العمل","دعم Low-Code و No-Code لتحقيق التطوير السريع","استخدام TypeScript لإنشاء حلول مخصصة","الدمج مع APIs و CLI لتوسيع الوظائف","التوافق مع منصات التكامل مثل IPAAS و MCP"]},"keywords":{"en":["how to use content-design","content-design setup guide","n8n workflow automation","low-code platform integration","content-design vs ui design","typescript for content-design","self-hosted content-design solutions","content-design install","content-design alternative"],"zh":["内容设计","AIエージェント","n8n","TypeScript","低代码开发","工作流自动化","IPAAS","MCP","CLI","API"],"ja":["コンテンツデザイン","AIエージェント","n8n","TypeScript","ローコード開発","ワークフロー自動化","IPAAS","MCP","CLI","API"],"ko":["콘텐츠 디자인","AI 에이전트","n8n","TypeScript","로우 코드 개발","워크플로 자동화","IPAAS","MCP","CLI","API"],"es":["diseño de contenido para herramientas de flujos de trabajo","n8n","automatización de flujos de trabajo","CLI","API","TypeScript","herramientas de automatización","experiencia del usuario","interfaces de usuario intuitivas"],"fr":["conception de contenu pour les outils de workflow automation","n8n","automatisation de flux de travail","CLI","API","TypeScript","outils d''automatisation","expérience utilisateur","interfaces utilisateur intuitives"],"de":["Content-Design für Workflow-Automatisierungstools","n8n","Automatisierung von Workflows","CLI","API","TypeScript","Automatisierungstools","Benutzererfahrung","benutzerfreundliche Schnittstellen"],"pt":["content design","n8n","low-code","no-code","automação de fluxos de trabalho","desenvolvimento de soluções personalizadas","TypeScript","APIs","CLI","IPAAS","MCP"],"ru":["контент-дизайн","n8n","low-code","no-code","автоматизация рабочих процессов","разработка индивидуальных решений","TypeScript","API","CLI","ИИ Агенты","IPAAS","MCP"],"ar":["تصميم المحتوى","n8n","Low-Code","No-Code","تأتمتة سير العمل","إنشاء حلول مخصصة","TypeScript","APIs","CLI","أدوات الذكاء الاصطناعي","IPAAS","MCP"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents specializing in SaaS tools needing precise UI copywriting and content strategy.","zh":"适合专门从事SaaS工具的人工智能代理，需要精确的UI复制和内容策略。","ja":"SaaSツールで正確なUIコピーとコンテンツ戦略を必要とするAIエージェントに適しています。","ko":"정확한 UI 복사 및 콘텐츠 전략이 필요한 SaaS 도구를専門으로 하는 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA especializados en herramientas SaaS que necesitan escritura de copias de interfaz de usuario precisas y estrategia de contenido.","fr":"Parfait pour les agents IA spécialisés dans les outils SaaS nécessitant une rédaction de copie d''interface utilisateur précise et une stratégie de contenu.","de":"Perfekt für KI-Agents, die auf SaaS-Tools spezialisiert sind und präzise Benutzeroberflächen-Kopien und Inhaltsstrategie benötigen.","pt":"Perfeito para Agentes de IA especializados em ferramentas SaaS que precisam de cópia de UI precisa e estratégia de conteúdo.","ru":"Идеально подходит для агентов ИИ, специализирующихся на инструментах SaaS, требующих точной копии UI и стратегии контента.","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين ي专ون في أدوات السحابة و يحتاجون إلى كتابة واجهة المستخدم الدقيقة و استراتيجية المحتوى."},"recommendation":{"en":"Empowers agents to craft user-centric interface content, leveraging terminology precision to enhance user success, and utilizing design decisions for labels, error messages, and tooltips, all while prioritizing action-oriented outcomes in UI surfaces like modals, tooltips, and banners.","zh":"赋予代理人创建以用户为中心的接口内容的能力，利用术语精度来提高用户成功率，并利用设计决策为标签、错误消息和工具提示等创建内容，同时在模态窗口、工具提示和横幅等UI表面上优先考虑面向操作的结果。","ja":"エージェントがユーザーセントリックなインターフェイスコンテンツを作成できるようにし、用語の正確さを利用してユーザーの成功を高め、ラベル、エラーメッセージ、ツールチップなどのデザイン決定を利用し、モーダル、ツールチップ、バナーなどのUIサーフェスでアクション指向の結果を優先します。","ko":"에이전트가 사용자 중심의 인터페이스 콘텐츠를 제작할 수 있도록 하며, 용어의 정밀도를 활용하여 사용자의 성공을 높이고, 레이블, 오류 메시지, 툴팁 등을 위한 디자인 결정을 활용하여, 모달, 툴팁, 배너 등의 UI 표면에서 액션 지향 결과를 우선합니다.","es":"Habilita a los agentes a crear contenido de interfaz de usuario centrado en el usuario, aprovechando la precisión de la terminología para mejorar el éxito del usuario y utilizando decisiones de diseño para etiquetas, mensajes de error y consejos, todo mientras prioriza resultados orientados a la acción en superficies de interfaz de usuario como modales, consejos y banners.","fr":"Permet aux agents de créer un contenu d''interface utilisateur centré sur l''utilisateur, en exploitant la précision de la terminologie pour améliorer la réussite de l''utilisateur et en utilisant les décisions de conception pour les étiquettes, les messages d''erreur et les info-bulles, le tout en donnant la priorité à des résultats axés sur l''action dans les surfaces d''interface utilisateur comme les modales, les info-bulles et les bannières.","de":"Ermächtigt Agents, benutzerzentrierten Schnittstelleninhalt zu erstellen, indem sie die Präzision der Terminologie nutzen, um den Benutzererfolg zu verbessern und Designentscheidungen für Labels, Fehlermeldungen und QuickInfo zu verwenden, und zwar immer mit der Priorisierung von aktionsorientierten Ergebnissen in Benutzeroberflächen wie Modals, QuickInfo und Bannern.","pt":"Permite que os agentes criem conteúdo de interface centrado no usuário, aproveitando a precisão da terminologia para melhorar o sucesso do usuário e utilizando decisões de design para etiquetas, mensagens de erro e dicas de ferramenta, tudo isso priorizando resultados orientados para ação em superfícies de UI como modais, dicas de ferramenta e banners.","ru":"Наделяет агентов возможностью создавать контент интерфейса, ориентированный на пользователя, используя точность терминологии для улучшения успеха пользователя и принимая решения по дизайну для меток, сообщений об ошибках и подсказок, все это приоритезируя результаты, ориентированные на действие в поверхностях UI, таких как модальные окна, подсказки и баннеры.","ar":"يمكن الوكلاء من إنشاء محتوى واجهة المستخدم الموجهة للمستخدم، مستفيدين من دقة المصطلحات لتعزيز نجاح المستخدم، واستخدام قرارات التصميم لملصقات، رسائل الخطأ واقتراحات الأدوات، كل ذلك مع تحديد الأولويات للنتائج الموجهة إلى الإجراءات على أسطح واجهة المستخدم مثل النوافذ المودال، واقتراحات الأدوات واللافتات."},"useCases":{"en":["Designing intuitive workflow automation interfaces","Crafting clear whiteboard tool instructions","Optimizing enterprise software UI copy for user engagement"],"zh":["设计直观的工作流自动化接口","制作清晰的白板工具说明","优化企业软件UI复制以提高用户参与度"],"ja":["直観的なワークフロー自動化インターフェイスを設計する","明確なホワイトボードツールの説明を作成する","エンタープライズソフトウェアのUIコピーを最適化してユーザー参加を高める"],"ko":["직관적인 워크플로 자동화 인터페이스를 설계한다","분명한 화이트보드 툴 설명서를 제작한다","엔터프라이즈 소프트웨어의 UI 복사를 최적화하여 사용자 참여도를 높인다"],"es":["Diseñar interfaces de automatización de flujo de trabajo intuitivas","Crear instrucciones de herramientas de pizarra claras","Optimizar la copia de interfaz de usuario de software empresarial para la participación del usuario"],"fr":["Concevoir des interfaces d''automatisation de workflow intuitives","Créer des instructions d''outils de tableau blanc claires","Optimiser la copie d''interface utilisateur de logiciels d''entreprise pour l''engagement de l''utilisateur"],"de":["Intuitive Workflow-Automatisierungsinterfaces entwerfen","Klare Anweisungen für Whiteboard-Tools erstellen","Benutzeroberflächenkopie von Unternehmenssoftware für die Benutzerbeteiligung optimieren"],"pt":["Projetar interfaces de automação de fluxo de trabalho intuitivas","Criar instruções de ferramenta de quadro branco claras","Otimizar a cópia de UI de software de empresa para engajamento do usuário"],"ru":["Проектирование интуитивно понятных интерфейсов автоматизации рабочих процессов","Создание ясных инструкций для инструмента whiteboard","Оптимизация копии UI корпоративного программного обеспечения для вовлечения пользователя"],"ar":["تصميم واجهات تلقائية للعمل المباشر بسهولة","إنشاء تعليمات أداة لوحة بيضاء واضحة","تحسين نسخة واجهة المستخدم من برامج شركات لجذب المستخدمين"]},"limitations":{"en":["Requires understanding of SaaS tool terminology","Limited to UI copywriting and content design"],"zh":["需要了解SaaS工具的术语","仅限UI复制和内容设计"],"ja":["SaaSツールの用語を理解する必要がある","UIコピーとコンテンツデザインのみ"],"ko":["SaaS 도구의 용어를 이해해야 한다","UI 복사 및 콘텐츠 디자인만"],"es":["Requiere comprensión de la terminología de las herramientas SaaS","Limitado a la escritura de copias de interfaz de usuario y diseño de contenido"],"fr":["Nécessite une compréhension de la terminologie des outils SaaS","Limité à la rédaction de copie d''interface utilisateur et à la conception de contenu"],"de":["Benötigt Verständnis für die Terminologie von SaaS-Tools","Begrenzt auf die Erstellung von Benutzeroberflächenkopien und Inhaltsdesign"],"pt":["Exige compreensão da terminologia de ferramentas SaaS","Limitado à cópia de UI e design de conteúdo"],"ru":["Требует понимания терминологии инструментов SaaS","Ограничен копированием UI и дизайном контента"],"ar":["يتطلب فهم المصطلحات الخاصة بأدوات السحابة","محدود بنسخة واجهة المستخدم وتصميم المحتوى"]},"version":4},"contentHash":"ed9424c04d4690a7593757329ea016634ebc2bfb9aae59908b2fa454ef02b094","repoEtag":"W/\"3826f18d1894df306122a172f629759ce7b1aa3bff04dbe05feba05281ded220\"","qualityScore":70}');
