INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('n8n-io/n8n/content-design', 'content-design', 'n8n-io', 'n8n', 'official', 'content-design n8n-io n8n official ai apis automation cli data-flow development integration-framework integrations ipaas low-code low-code-platform mcp mcp-client mcp-server n8n no-code self-hosted typescript workflow workflow-automation The content-design skill enables Senior Content Designers to craft precise UI copy for complex SaaS tools, leveraging n8n and low-code platforms for efficient workflow automation. This skill benefits developers and designers working with workflow automation and enterprise software. 内容设计是一种将内容作为界面的设计方法，用于创建复杂的 SaaS 工具和工作流自动化 コンテンツデザインは、コンテンツをインターフェイスとして扱う設計方法であり、複雑な SaaS ツールやワークフロー自動化の作成に使用される 콘텐츠 디자인은 콘텐츠를 인터페이스로 다루는 설계 방법으로, 복잡한 SaaS 도구와 워크플로 자동화의 생성에 사용됩니다 El contenido de diseño para herramientas de flujos de trabajo con n8n se centra en crear interfaces de usuario intuitivas y efectivas. Aprende a diseñar contenido que mejore la experiencia del usuario. La conception de contenu pour les outils de workflow automation avec n8n se concentre sur la création d''interfaces utilisateur intuitives et efficaces. Découvrez comment concevoir un contenu qui améliore l''expérience utilisateur. Das Content-Design für Workflow-Automatisierungstools mit n8n konzentriert sich auf die Erstellung benutzerfreundlicher und effektiver Benutzeroberflächen. Erfahren Sie, wie Sie ein Content-Design erstellen, das die Benutzererfahrung verbessert. O content design é uma habilidade que combina design de interface e escrita técnica para criar experiências de usuário eficazes Контент-дизайн - это навык, который сочетает интерфейсный дизайн и техническую писать для создания эффективных пользовательских опытов تصميم المحتوى هو مهارة تجمع بين تصميم الواجهة والكتابة الفنية لإنشاء تجارب مستخدم فعالة how to use content-design content-design setup guide n8n workflow automation low-code platform integration content-design vs ui design typescript for content-design self-hosted content-design solutions content-design install content-design alternative 内容设计 AIエージェント n8n TypeScript 低代码开发 工作流自动化 IPAAS MCP CLI API Integrates with n8n for workflow automation Utilizes TypeScript for robust and scalable design Supports low-code platforms for efficient development Enables self-hosted solutions for customized control Leverages MCP-client and MCP-server for seamless integration Generates precise UI copy for complex SaaS tools Content-design is a technical skill that treats content as interface, focusing on precise terminology and design decisions for user success in SaaS tools and workflow automation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/agent-harness-construction', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'agent-harness-construction', 61988, 7678, 70, '2026-03-06T03:39:20Z', '2026-03-06T03:40:46.529Z', '8da8d0cd5ab9bcdfc3885818de04fbb7de18446b282138bb1b39b6863f335020', '{"id":"affaan-m/everything-claude-code/agent-harness-construction","name":"agent-harness-construction","description":{"en":"This skill helps developers design and optimize the core components of AI agents, including action spaces, tool definitions, and observation formatting. It is specifically aimed at improving agent performance on platforms like Anthropic''s Claude through MCP.","zh":"设计和优化AI代理的动作空间、工具定义和观察格式，以提高完成率","ja":"AIエージェントのアクションスペース、ツール定義、観測フォーマットを設計および最適化して完了率を向上させる","ko":"AI 에이전트의 액션 공간, 도구 정의, 관찰 형식을 설계 및 최적화하여 완료率를 향상시킵니다","es":"Agent Harness Construction es una habilidad para diseñar y optimizar AI agent action spaces, tool definitions y observation formatting para una mayor tasa de finalización.","fr":"Agent Harness Construction est une compétence qui permet de concevoir et d''optimiser les espaces d''action, les définitions d''outils et la mise en forme des observations pour les agents IA pour une meilleure completion.","de":"Agent Harness Construction ist eine Fähigkeit zum Entwerfen und Optimieren von AI-Agenten-Aktionsräumen, Werkzeugdefinitionen und Beobachtungsformatierungen für eine höhere Fertigstellungsrate.","pt":"Otimizar agentes de IA para alta taxa de conclusão envolve projetar espaços de ação de alta qualidade, definições de ferramentas explícitas e formatação de observações eficazes.","ru":"Оптимизация ИИ агентов для повышения процентного коэффициента завершения включает в себя проектирование высококачественных пространств действий, явных определений инструментов и эффективного форматирования наблюдений.","ar":"تحسين وحدات الإيضاح الذكية لتحقيق أعلى معدلات الإنجاز يتطلب تصميم مساحات العمل عالية الجودة وتحديد أدوات واضحة وتنسيق ملاحظات فعال"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"agent-harness-construction","description":"Design and optimize AI agent action spaces, tool definitions, and observation formatting for higher completion rates.","bodyPreview":"# Agent Harness Construction\n\nUse this skill when you are improving how an agent plans, calls tools, recovers from errors, and converges on completion.\n\n## Core Model\n\nAgent output quality is constrained by:\n1. Action space quality\n2. Observation quality\n3. Recovery quality\n4. Context budget quality\n\n## Action Space Design\n\n1. Use stable, explicit tool names.\n2. Keep inputs schema-first and narrow.\n3. Return deterministic output shapes.\n4. Avoid catch-all tools unless isolation is impossible.\n\n#","body":"# Agent Harness Construction\n\nUse this skill when you are improving how an agent plans, calls tools, recovers from errors, and converges on completion.\n\n## Core Model\n\nAgent output quality is constrained by:\n1. Action space quality\n2. Observation quality\n3. Recovery quality\n4. Context budget quality\n\n## Action Space Design\n\n1. Use stable, explicit tool names.\n2. Keep inputs schema-first and narrow.\n3. Return deterministic output shapes.\n4. Avoid catch-all tools unless isolation is impossible.\n\n## Granularity Rules\n\n- Use micro-tools for high-risk operations (deploy, migration, permissions).\n- Use medium tools for common edit/read/search loops.\n- Use macro-tools only when round-trip overhead is the dominant cost.\n\n## Observation Design\n\nEvery tool response should include:\n- `status`: success|warning|error\n- `summary`: one-line result\n- `next_actions`: actionable follow-ups\n- `artifacts`: file paths / IDs\n\n## Error Recovery Contract\n\nFor every error path, include:\n- root cause hint\n- safe retry instruction\n- explicit stop condition\n\n## Context Budgeting\n\n1. Keep system prompt minimal and invariant.\n2. Move large guidance into skills loaded on demand.\n3. Prefer references to files over inlining long documents.\n4. Compact at phase boundaries, not arbitrary token thresholds.\n\n## Architecture Pattern Guidance\n\n- ReAct: best for exploratory tasks with uncertain path.\n- Function-calling: best for structured deterministic flows.\n- Hybrid (recommended): ReAct planning + typed tool execution.\n\n## Benchmarking\n\nTrack:\n- completion rate\n- retries per task\n- pass@1 and pass@3\n- cost per successful task\n\n## Anti-Patterns\n\n- Too many tools with overlapping semantics.\n- Opaque tool output with no recovery hints.\n- Error-only output without next steps.\n- Context overloading with irrelevant references.\n"},"category":"official","lastSynced":"2026-03-06T03:40:46.529Z","seo":{"title":{"en":"Agent Harness Construction: Optimize AI Agent Action Spac...","zh":"AI代理工具构建最佳实践","ja":"AIエージェントのハーネス構築ガイド","ko":"AI 에이전트 하네스 구축 설정 가이드","es":"Guía de configuración de Agentes de Inteligencia Artifici...","fr":"Construire des agents IA efficaces avec Agent Harness Con...","de":"Agent Harness Construction-Setup Guide für künstliche Int...","pt":"Guia de Configuração de Agentes de Inteligência Artificia...","ru":"Настройка ИИ Агентов для Повышения Процентного Коэффициен...","ar":"دليل إعداد وحدات الإيضاح الذكية لتحقيق أعلى معدلات الإنجاز"},"description":{"en":"Learn to design stable tool names, schema-first inputs, and deterministic outputs for Claude & MCP agents. Boost your AI agent''s completion rate and error re...","zh":"提高AI代理的完成率，优化动作空间、工具定义和观察格式","ja":"AIエージェントの完了率を向上させるためのアクションスペース、ツール定義、観測フォーマットの最適化","ko":"AI 에이전트의 완료率를 높이는ための 액션 공간, 도구 정의, 관찰 형식 최적화","es":"Mejora la calidad de tus agentes de inteligencia artificial con Agent Harness Construction. Aprende a diseñar y optimizar espacios de acción y herramientas p...","fr":"Améliorez la qualité de vos agents IA avec Agent Harness Construction. Découvrez comment concevoir et optimiser les espaces d''action et les outils pour une m...","de":"Verbessern Sie die Qualität Ihrer künstlichen Intelligenz-Agenten mit Agent Harness Construction. Erfahren Sie, wie Sie Aktionsräume und Werkzeuge optimieren...","pt":"Aprenda a projetar e otimizar espaços de ação de agentes de IA, definições de ferramentas e formatação de observações para melhorar as taxas de conclusão","ru":"Узнайте, как спроектировать и оптимизировать пространства действий ИИ агентов, определения инструментов и форматирование наблюдений для повышения показателей...","ar":"تعرف على كيفية تصميم وحدات الإيضاح الذكية وتحسين مساحات العمل والأدوات والتنسيق لتحقيق أعلى معدلات الإنجاز"},"definition":{"en":"agent-harness-construction is a developer skill for designing and optimizing AI agent action spaces, tool definitions, and observation formatting. It focuses on core constraints like action space quality and recovery quality to achieve higher completion rates for agents like Claude.","zh":"AI代理工具构建是指设计和优化AI代理的动作空间、工具定义和观察格式","ja":"AIエージェントのハーネス構築とは、AIエージェントのアクションスペース、ツール定義、観測フォーマットを設計および最適化すること","ko":"AI 에이전트 하네스 구축은 AI 에이전트의 액션 공간, 도구 정의, 관찰 형식을 설계 및 최적화하는 것을 말합니다","es":"Agent Harness Construction es una técnica para mejorar la calidad de los agentes de inteligencia artificial mediante la optimización de espacios de acción y herramientas.","fr":"Agent Harness Construction est une technique d''amélioration de la qualité des agents IA via l''optimisation des espaces d''action et des outils.","de":"Agent Harness Construction ist eine Technik zur Verbesserung der Qualität künstlicher Intelligenz-Agenten durch die Optimierung von Aktionsräumen und Werkzeugen.","pt":"Construção de harness de agentes é a prática de projetar e otimizar a infraestrutura de agentes de IA para melhorar a taxa de conclusão","ru":"Конструкция харнесса агентов - это практика проектирования и оптимизации инфраструктуры ИИ агентов для повышения показателей завершения","ar":"بناء حزام الوحدات هو ممارسة تصميم وتحسين بنية وحدات الإيضاح الذكية لتحقيق أعلى معدلات الإنجاز"},"features":{"en":["Designs stable, explicit tool names for agent action spaces","Implements schema-first and narrow input definitions for tools","Ensures deterministic output shapes from agent tools","Optimizes agent context budget quality for efficient operation","Improves agent recovery quality from errors during execution","Avoids catch-all tools to maintain clear tool isolation"],"zh":["稳定的显式工具名称","输入模式优先和狭窄的输入","确定的输出形状","避免catch-all工具"],"ja":["安定した明示的なツール名","入力スキーマ優先と狭い入力","決定的な出力形状","キャッチオールツールの回避"],"ko":["안정적인 명시적인 도구 이름","입력 스키마 우선 및 狭い 입력","결정적인 출력 형태","캐치 올 도구 회피"],"es":["Diseño de espacios de acción estables y explícitos","Definición de herramientas con nombres claros y deterministas","Optimización de la calidad de las observaciones","Mejora de la recuperación de errores y la convergencia hacia la finalización","Uso de esquemas de entrada y salida claros y concisos","Evitación de herramientas generales a menos que sea imposible aislarlas"],"fr":["Conception d''espaces d''action stables et explicites","Définition d''outils avec des noms clairs et déterministes","Optimisation de la qualité des observations","Amélioration de la récupération des erreurs et de la convergence vers l''achèvement","Utilisation de schémas d''entrée et de sortie clairs et concis","Évitement des outils généraux sauf si l''isolement est impossible"],"de":["Entwurf von stabilen und expliziten Aktionsräumen","Definition von Werkzeugen mit klaren und deterministischen Namen","Optimierung der Qualität der Beobachtungen","Verbesserung der Fehlerbehebung und der Konvergenz zur Fertigstellung","Verwendung von klaren und knappen Eingabe- und Ausgabeschemata","Ve