INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('benfwalla/things-to-be-happy-about/convex-component-authoring', 'convex-component-authoring', 'benfwalla', 'things-to-be-happy-about', 'community', 'convex-component-authoring benfwalla things-to-be-happy-about community Convex-component-authoring enables developers to create reusable Convex components for sharing across projects, with features like proper isolation and exports. This skill benefits developers working with Convex. Convex 组件编写允许开发者创建自包含、可重用的组件，具有依赖管理和导出功能 Convex コンポーネント著作は、依存関係管理とエクスポート機能を備えた、自己完結型のコンポーネントを作成することを可能にします Convex 컴포넌트 작성은 의존성 관리와导出機能을 갖춘 재사용 가능한 컴포넌트를 생성할 수 있습니다 Convex componente authoring permite crear componentes reutilizables con aislamiento y gestión de dependencias L''authoring de composants Convex permet de créer des composants réutilisables avec isolation et gestion de dépendances Convex-Komponentenauthoring ermöglicht die Erstellung von wiederverwendbaren Komponenten mit Isolation und Abhängigkeitsverwaltung Convex component authoring permite criar componentes reutilizáveis com isolamento, exportação e gerenciamento de dependências Компоненты Convex позволяют создавать самодостаточные компоненты с правильной изоляцией, экспортом и управлением зависимостями مكونات Convex تسمح بإنشاء مكونات قابلة لإعادة الاستخدام مع العزل والتصدير وإدارة التبعيات how to use convex-component-authoring convex-component-authoring setup guide convex-component-authoring vs component-based architecture convex-component-authoring install what is convex-component-authoring convex-component-authoring alternative convex-component-authoring documentation convex-component-authoring tutorial convex-component-authoring best practices Convex 组件编写 AIエージェント开发 Convex CLI JavaScript Python 组件管理 依赖管理 导出功能 Creates self-contained Convex components with proper isolation Supports exports and dependency management for sharing across projects Follows documentation guidelines from https://docs.convex.dev/components Utilizes component authoring guidelines from https://docs.convex.dev/components/authoring Integrates with broader context from https://docs.convex.dev/llms.txt convex-component-authoring is a technique for creating self-contained, reusable Convex components with proper isolation, exports, and dependency management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Pratikkadam254/LinkedinLeadGen/convex-component-authoring', 'community', 'Pratikkadam254', 'LinkedinLeadGen', 'Pratikkadam254/LinkedinLeadGen', 'convex-component-authoring', 0, 0, 70, '2026-03-07T01:49:01.489Z', '2026-03-07T01:58:32.367Z', '561346aded0969635fc3f32ae6d465f882266b6be20b4038c7a55645ff6db7c2', '{"id":"Pratikkadam254/LinkedinLeadGen/convex-component-authoring","name":"convex-component-authoring","description":{"en":"Convex-component-authoring enables developers to create reusable Convex components for sharing across projects. It provides proper isolation, exports, and dependency management.","zh":"Convex 组件是自包含、可重用的单元，具有适当的隔离、导出和依赖管理","ja":"Convex コンポーネントは、適切な隔離、エクスポート、依存関係管理を備えた自己完結型の再利用可能な単位です","ko":"Convex 컴포넌트는 적절한 격리, 내보내기, 의존성 관리를 갖춘 자체 포함형 재사용 가능한 단위입니다","es":"Crea componentes Convex autocontenidos y reutilizables con documentación y recursos adecuados","fr":"Créez des composants Convex autonomes et réutilisables avec documentation et ressources appropriées","de":"Erstellen Sie selbstenthaltene und wiederverwendbare Convex-Komponenten mit Dokumentation und Ressourcen","pt":"Convex component authoring permite criar componentes reutilizáveis com isolamento, exportação e gerenciamento de dependências","ru":"Convex компоненты позволяют создавать автономные, повторно используемые компоненты с правильной изоляцией и управлением зависимостями","ar":"إنشاء مكونات Convex قابلة لإعادة الاستخدام مع العزل والتصدير وإدارة التبعيات"},"seo":{"title":{"en":"Convex-Component-Authoring: Setup Guide for AI Agents | A...","zh":"Convex 组件创建最佳实践","ja":"Convex コンポーネント作成ガイド - AIエージェント","ko":"Convex 컴포넌트 작성 Setup Guide - AI 툴","es":"Guía de Configuración de Componentes Convex","fr":"Guide de Mise en Place des Composants Convex","de":"Einrichtungsleitfaden für Convex-Komponenten","pt":"Guia de Configuração de Convex Component Authoring","ru":"Настройка Convex Компонентов: Лучшие Практики","ar":"دليل إنشاء Convex Component Authoring"},"description":{"en":"Learn how to create self-contained Convex components with proper isolation and dependency management. Get started with Convex component authoring today!","zh":"学习 Convex 组件的创建、重用和管理，实现项目间的高效共享","ja":"Convex コンポーネントの作成、再利用、管理について学び、プロジェクト間の効率的な共有を実現する - AIエージェント","ko":"Convex 컴포넌트의 작성, 재사용, 관리에 대해 알아보고 프로젝트 간의 효율적인 공유를 실현하세요 - AI 툴","es":"Aprende a crear componentes Convex reutilizables con aislamiento, exportaciones y gestión de dependencias adecuados","fr":"Découvrez comment créer des composants Convex réutilisables avec isolation, exportations et gestion de dépendances appropriées","de":"Erfahren Sie, wie Sie wiederverwendbare Convex-Komponenten mit ordnungsgemäßer Isolation, Exporten und Abhängigkeitsverwaltung erstellen","pt":"Aprenda a criar componentes Convex reutilizáveis com isolamento, exportação e gerenciamento de dependências adequados","ru":"Исследуйте возможности Convex компонентов с правильной изоляцией, экспортом и управлением зависимостями","ar":"تعرف على كيفية إنشاء مكونات Convex قابلة لإعادة الاستخدام مع العزل والتصدير وإدارة التبعيات"},"definition":{"en":"Convex-component-authoring is a technique for creating self-contained, reusable Convex components with proper isolation, exports, and dependency management.","zh":"Convex 组件是用于构建和共享 Convex 应用的基本单元","ja":"Convex コンポーネントは、Convex アプリケーションの構築と共有の基本単位です","ko":"Convex 컴포넌트는 Convex 애플리케이션을 구축하고 공유하는 기본 단위입니다","es":"Componentes Convex son elementos reutilizables con aislamiento y gestión de dependencias","fr":"Les composants Convex sont des éléments réutilisables avec isolation et gestion de dépendances","de":"Convex-Komponenten sind wiederverwendbare Elemente mit Isolation und Abhängigkeitsverwaltung","pt":"Convex component authoring é uma técnica para criar componentes reutilizáveis","ru":"Convex компоненты - это метод создания автономных, повторно используемых компонентов","ar":"Convex component authoring هو تقنية لإنشاء مكونات قابلة لإعادة الاستخدام"},"features":{"en":["Creates self-contained Convex components with proper isolation","Provides exports and dependency management for sharing across projects","Follows documentation from https://docs.convex.dev/components","Supports component authoring as described in https://docs.convex.dev/components/authoring","Allows for broader context understanding with https://docs.convex.dev/llms.txt","Enables fetching of the latest documentation for implementation"],"zh":["创建自包含的 Convex 组件","实现组件间的适当隔离","管理组件的导出和依赖","共享组件跨多个项目","使用 Convex 文档进行组件作者化","遵循 Convex 组件作者化指南"],"ja":["自己完結型の Convex コンポーネントを作成する","コンポーネント間の適切な隔離を実現する","コンポーネントのエクスポートと依存関係を管理する","コンポーネントを複数のプロジェクト間で共有する","Convex ドキュメントを使用してコンポーネントを著者化する","Convex コンポーネント著者化ガイドに従う"],"ko":["자체 포함형 Convex 컴포넌트를 작성한다","컴포넌트 간의 적절한 격리를 구현한다","컴포넌트의 내보내기와 의존성을 관리한다","컴포넌트를 여러 프로젝트 간에 공유한다","Convex 문서를 사용하여 컴포넌트를 작성한다","Convex 컴포넌트 작성 가이드를 따름"],"es":["Creación de componentes autocontenidos","Gestión de dependencias y exportaciones","Aislamiento adecuado para proyectos","Documentación y recursos para el desarrollo","Compatibilidad con tecnologías como CLI"],"fr":["Création de composants autonomes","Gestion de dépendances et d''exportations","Isolation appropriée pour les projets","Documentation et ressources pour le développement","Compatibilité avec des technologies comme CLI"],"de":["Erstellung von selbstenthaltenden Komponenten","Verwaltung von Abhängigkeiten und Exporten","Ordentliche Isolation für Projekte","Dokumentation und Ressourcen für die Entwicklung","Kompatibilität mit Technologien wie CLI"],"pt":["Criação de componentes Convex reutilizáveis","Isolamento e exportação de componentes","Gerenciamento de dependências","Integração com https://docs.convex.dev/components","Suporte a documentação em https://docs.convex.dev/components/authoring","Compatibilidade com https://docs.convex.dev/llms.txt"],"ru":["Создание автономных Convex компонентов","Изоляция и экспорт компонентов","Управление зависимостями","Интеграция с https://docs.convex.dev/components","Поддержка документации в https://docs.convex.dev/components/authoring","Совместимость с https://docs.convex.dev/llms.txt"],"ar":["إنشاء مكونات Convex قابلة لإعادة الاستخدام","العزل والتصدير للمكونات","إدارة التبعيات","التكامل مع https://docs.convex.dev/components","دعم الوثائق في https://docs.convex.dev/components/authoring","التوافق مع https://docs.convex.dev/llms.txt"]},"keywords":{"en":["how to use convex-component-authoring","convex-component-authoring setup guide","convex-component-authoring documentation","what is convex-component-authoring","convex-component-authoring vs other component authoring techniques","convex-component-authoring install","convex-component-authoring tutorial","convex-component-authoring best practices","convex-component-authoring for AI agents"],"zh":["Convex 组件","Convex 组件创建","Convex 组件作者化","Convex 依赖管理","Convex 文档","Convex 开发","Convex 应用构建","Convex 项目共享","AI 工具","Convex 技术"],"ja":["Convex コンポーネント","Convex コンポーネント作成","Convex コンポーネント著者化","Convex 依存関係管理","Convex ドキュメント","Convex 開発","Convex アプリケーションの構築","Convex プロジェクト共有","AI エージェント","Convex 技術"],"ko":["Convex 컴포넌트","Convex 컴포넌트 작성","Convex 컴포넌트 작성 가이드","Convex 의존성 관리","Convex 문서","Convex 개발","Convex 애플리케이션 구축","Convex 프로젝트 공유","AI 툴","Convex 기술"],"es":["componentes Convex","desarrollo de componentes","Herramientas de AI","Agentes de inteligencia artificial","Guías de configuración","Tecnologías de desarrollo","CLI","Gestión de dependencias"],"fr":["composants Convex","développement de composants","Outils d''IA","Agents d''intelligence artificielle","Guides de mise en place","Technologies de développement","CLI","Gestion de dépendances"],"de":["Convex-Komponenten","Entwicklung von Komponenten","AI-Tools","Künstliche Intelligenz Agenten","Einrichtungsleitfäden","Entwicklungstechnologien","CLI","Abhängigkeitsverwaltung"],"pt":["convex component authoring","componentes reutilizáveis","isolamento de componentes","gerenciamento de dependências","documentação convex","guias de configuração convex","ferramentas de desenvolvimento convex","convex para desenvolvedores","componentes convex"],"ru":["Convex компоненты","ИИ Агенты","автономные компоненты","изоляция компонентов","управление зависимостями","документация Convex","руководства по настройке Convex","инструменты разработки Convex","Convex для разработчиков","компоненты Convex"],"ar":["إنشاء مكونات Convex","أدوات الذكاء الاصطناعي","مكونات قابلة لإعادة الاستخدام","عزل المكونات","إدارة التبعيات","توثيق Convex","دلائل إعداد Convex","أدوات تطوير Convex","Convex للمطورين","مكونات Convex"]}},"owner":"Pratikkadam254","repo":"LinkedinLeadGen","repoPath":"Pratikkadam254/LinkedinLeadGen","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.489Z","topics":[],"category":"community","skillMd":{"name":"convex-component-authoring","description":"How to create, structure, and publish self-contained Convex components with proper isolation, exports, and dependency management","version":"1.0.0","tags":["convex","components","reusable","packages","npm"],"bodyPreview":"# Convex Component Authoring\n\nCreate self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n### What Are Convex Components?\n\nConvex component","body":"# Convex Component Authoring\n\nCreate self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n### What Are Convex Components?\n\nConvex components are self-contained packages that include:\n- Database tables (isolated from the main app)\n- Functions (queries, mutations, actions)\n- TypeScript types and validators\n- Optional frontend hooks\n\n### Component Structure\n\n```\nmy-convex-component/\n├── package.json\n├── tsconfig.json\n├── README.md\n├── src/\n│   ├── index.ts           # Main exports\n│   ├── component.ts       # Component definition\n│   ├── schema.ts          # Component schema\n│   └── functions/\n│       ├── queries.ts\n│       ├── mutations.ts\n│       └── actions.ts\n└── convex.config.ts       # Component configuration\n```\n\n### Creating a Component\n\n#### 1. Component Configuration\n\n```typescript\n// convex.config.ts\nimport { defineComponent } from \"convex/server\";\n\nexport default defineComponent(\"myComponent\");\n```\n\n#### 2. Component Schema\n\n```typescript\n// src/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  // Tables are isolated to this component\n  items: defineTable({\n    name: v.string(),\n    data: v.any(),\n    createdAt: v.number(),\n  }).index(\"by_name\", [\"name\"]),\n  \n  config: defineTable({\n    key: v.string(),\n    value: v.any(),\n  }).index(\"by_key\", [\"key\"]),\n});\n```\n\n#### 3. Component Definition\n\n```typescript\n// src/component.ts\nimport { defineComponent, ComponentDefinition } from \"convex/server\";\nimport schema from \"./schema\";\nimport * as queries from \"./functions/queries\";\nimport * as mutations from \"./functions/mutations\";\n\nconst component = defineComponent(\"myComponent\", {\n  schema,\n  functions: {\n    ...queries,\n    ...mutations,\n  },\n});\n\nexport default component;\n```\n\n#### 4. Component Functions\n\n```typescript\n// src/functions/queries.ts\nimport { query } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const list = query({\n  args: {\n    limit: v.optional(v.number()),\n  },\n  returns: v.array(v.object({\n    _id: v.id(\"items\"),\n    name: v.string(),\n    data: v.any(),\n    createdAt: v.number(),\n  })),\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"items\")\n      .order(\"desc\")\n      .take(args.limit ?? 10);\n  },\n});\n\nexport const get = query({\n  args: { name: v.string() },\n  returns: v.union(v.object({\n    _id: v.id(\"items\"),\n    name: v.string(),\n    data: v.any(),\n  }), v.null()),\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"items\")\n      .withIndex(\"by_name\", (q) => q.eq(\"name\", args.name))\n      .unique();\n  },\n});\n```\n\n```typescript\n// src/functions/mutations.ts\nimport { mutation } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const create = mutation({\n  args: {\n    name: v.string(),\n    data: v.any(),\n  },\n  returns: v.id(\"items\"),\n  handler: async (ctx, args) => {\n    return await ctx.db.insert(\"items\", {\n      name: args.name,\n      data: args.data,\n      createdAt: Date.now(),\n    });\n  },\n});\n\nexport const update = mutation({\n  args: {\n    id: v.id(\"items\"),\n    data: v.any(),\n  },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    await ctx.db.patch(args.id, { data: args.data });\n    return null;\n  },\n});\n\nexport const remove = mutation({\n  args: { id: v.id(\"items\") },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    await ctx.db.delete(args.id);\n    return null;\n  },\n});\n```\n\n#### 5. Main Exports\n\n```typescript\n// src/index.ts\nexport { default as component } from \"./component\";\nexport * from \"./functions/queries\";\nexport * from \"./functions/mutations\";\n\n// Export types for consumers\nexport type { Id } from \"./_generated/dataModel\";\n```\n\n### Using a Component\n\n```typescript\n// In the consuming app''s convex/convex.config.ts\nimport { defineApp } from \"convex/server\";\nimport myComponent from \"my-convex-component\";\n\nconst app = defineApp();\n\napp.use(myComponent, { name: \"myComponent\" });\n\nexport default app;\n```\n\n```typescript\n// In the consuming app''s code\nimport { useQuery, useMutation } from \"convex/react\";\nimport { api } from \"../convex/_generated/api\";\n\nfunction MyApp() {\n  // Access component functions through the app''s API\n  const items = useQuery(api.myComponent.list, { limit: 10 });\n  const createItem = useMutation(api.myComponent.create);\n  \n  return (\n    <div>\n      {items?.map((item) => (\n        <div key={item._id}>{item.name}</div>\n      ))}\n      <button onClick={() => createItem({ name: \"New\", data: {} })}>\n        Add Item\n      </button>\n    </div>\n  );\n}\n```\n\n### Component Configuration Options\n\n```typescript\n// convex/convex.config.ts\nimport { defineApp } from \"convex/server\";\nimport myComponent from \"my-convex-component\";\n\nconst app = defineApp();\n\n// Basic usage\napp.use(myComponent);\n\n// With custom name\napp.use(myComponent, { name: \"customName\" });\n\n// Multiple instances\napp.use(myComponent, { name: \"instance1\" });\napp.use(myComponent, { name: \"instance2\" });\n\nexport default app;\n```\n\n### Providing Component Hooks\n\n```typescript\n// src/hooks.ts\nimport { useQuery, useMutation } from \"convex/react\";\nimport { FunctionReference } from \"convex/server\";\n\n// Type-safe hooks for component consumers\nexport function useMyComponent(api: {\n  list: FunctionReference<\"query\">;\n  create: FunctionReference<\"mutation\">;\n}) {\n  const items = useQuery(api.list, {});\n  const createItem = useMutation(api.create);\n  \n  return {\n    items,\n    createItem,\n    isLoading: items === undefined,\n  };\n}\n```\n\n### Publishing a Component\n\n#### package.json\n\n```json\n{\n  \"name\": \"my-convex-component\",\n  \"version\": \"1.0.0\",\n  \"description\": \"A reusable Convex component\",\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"files\": [\n    \"dist\",\n    \"convex.config.ts\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc\",\n    \"prepublishOnly\": \"npm run build\"\n  },\n  \"peerDependencies\": {\n    \"convex\": \"^1.0.0\"\n  },\n  \"devDependencies\": {\n    \"convex\": \"^1.17.0\",\n    \"typescript\": \"^5.0.0\"\n  },\n  \"keywords\": [\n    \"convex\",\n    \"component\"\n  ]\n}\n```\n\n#### tsconfig.json\n\n```json\n{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"declaration\": true,\n    \"outDir\": \"dist\",\n    \"strict\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true\n  },\n  \"include\": [\"src/**/*\"],\n  \"exclude\": [\"node_modules\", \"dist\"]\n}\n```\n\n## Examples\n\n### Rate Limiter Component\n\n```typescript\n// rate-limiter/src/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  requests: defineTable({\n    key: v.string(),\n    timestamp: v.number(),\n  })\n    .index(\"by_key\", [\"key\"])\n    .index(\"by_key_and_time\", [\"key\", \"timestamp\"]),\n});\n```\n\n```typescript\n// rate-limiter/src/functions/mutations.ts\nimport { mutation } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const checkLimit = mutation({\n  args: {\n    key: v.string(),\n    limit: v.number(),\n    windowMs: v.number(),\n  },\n  returns: v.object({\n    allowed: v.boolean(),\n    remaining: v.number(),\n    resetAt: v.number(),\n  }),\n  handler: async (ctx, args) => {\n    const now = Date.now();\n    const windowStart = now - args.windowMs;\n    \n    // Clean old entries\n    const oldEntries = await ctx.db\n      .query(\"requests\")\n      .withIndex(\"by_key_and_time\", (q) => \n        q.eq(\"key\", args.key).lt(\"timestamp\", windowStart)\n      )\n      .collect();\n    \n    for (const entry of oldEntries) {\n      await ctx.db.delete(entry._id);\n    }\n    \n    // Count current window\n    const currentRequests = await ctx.db\n      .query(\"requests\")\n      .withIndex(\"by_key\", (q) => q.eq(\"key\", args.key))\n      .collect();\n    \n    const remaining = Math.max(0, args.limit - currentRequests.length);\n    const allowed = remaining > 0;\n    \n    if (allowed) {\n      await ctx.db.insert(\"requests\", {\n        key: args.key,\n        timestamp: now,\n      });\n    }\n    \n    const oldestRequest = currentRequests[0];\n    const resetAt = oldestRequest \n      ? oldestRequest.timestamp + args.windowMs \n      : now + args.windowMs;\n    \n    return { allowed, remaining: remaining - (allowed ? 1 : 0), resetAt };\n  },\n});\n```\n\n```typescript\n// Usage in consuming app\nimport { useMutation } from \"convex/react\";\nimport { api } from \"../convex/_generated/api\";\n\nfunction useRateLimitedAction() {\n  const checkLimit = useMutation(api.rateLimiter.checkLimit);\n  \n  return async (action: () => Promise<void>) => {\n    const result = await checkLimit({\n      key: \"user-action\",\n      limit: 10,\n      windowMs: 60000,\n    });\n    \n    if (!result.allowed) {\n      throw new Error(`Rate limited. Try again at ${new Date(result.resetAt)}`);\n    }\n    \n    await action();\n  };\n}\n```\n\n## Best Practices\n\n- Never run `npx convex deploy` unless explicitly instructed\n- Never run any git commands unless explicitly instructed\n- Keep component tables isolated (don''t reference main app tables)\n- Export clear TypeScript types for consumers\n- Document all public functions and their arguments\n- Use semantic versioning for component releases\n- Include comprehensive README with examples\n- Test components in isolation before publishing\n\n## Common Pitfalls\n\n1. **Cross-referencing tables** - Component tables should be self-contained\n2. **Missing type exports** - Export all necessary types\n3. **Hardcoded configuration** - Use component options for customization\n4. **No versioning** - Follow semantic versioning\n5. **Poor documentation** - Document all public APIs\n\n## References\n\n- Convex Documentation: https://docs.convex.dev/\n- Convex LLMs.txt: https://docs.convex.dev/llms.txt\n- Components: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n"},"lastSynced":"2026-03-07T01:58:32.367Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing reusable and modular Convex components with proper isolation and dependency management.","zh":"非常适合需要可重用和模块化Convex组件的全栈代理，具有适当的隔离和依赖管理。","ja":"フルスタックエージェントが再利用可能なモジュラ化されたConvexコンポーネントを必要とする場合に最適です。適切な分離と依存関係の管理が可能です。","ko":"재사용 가능한 모듈화 된 Convex 구성 요소를 필요로하는 풀 스택 에이전트에게 적합합니다. 적절한 격리 및 종속성 관리를 제공합니다.","es":"Perfecto para Agentes de Full Stack que necesitan componentes Convex reutilizables y modulares con aislamiento y gestión de dependencias adecuados.","fr":"Parfait pour les agents Full Stack ayant besoin de composants Convex réutilisables et modulaires avec une isolation et une gestion des dépendances appropriées.","de":"Perfekt für Full-Stack-Agents, die wiederverwendbare und modulare Convex-Komponenten mit ordnungsgemäßer Isolation und Abhängigkeitsverwaltung benötigen.","pt":"Perfeito para Agentes Full Stack que precisam de componentes Convex reutilizáveis e modulares com isolamento e gerenciamento de dependências adequados.","ru":"Идеально для агентов Full Stack, которым нужны многократно используемые и модульные компоненты Convex с правильной изоляцией и управлением зависимостями.","ar":"مثالي لموكلات الويب الكاملة التي تحتاج إلى مكونات Convex قابلة لإعادة الاستخدام ومتوافرة مع عزل وإدارة التبعيات المناسبة."},"recommendation":{"en":"Empowers agents to create self-contained Convex components with exports and dependency management, enabling seamless sharing across projects using Convex components and following the documentation from https://docs.convex.dev/components.","zh":"赋予代理创建自包含的Convex组件的能力，具有导出和依赖管理功能，实现跨项目共享Convex组件和遵循https://docs.convex.dev/components的文档。","ja":"エージェントがConvexコンポーネントを自己完結型でエクスポートおよび依存関係管理を実現することで、プロジェクト間でConvexコンポーネントをシームレスに共有し、https://docs.convex.dev/componentsのドキュメントに従うことができます。","ko":"에이전트가Convex 구성 요소를 자체적으로 포함 시키고 종속성 관리를 통해 내보낼 수있는 능력을 부여하여 프로젝트 간에Convex 구성 요소를无缝로 공유하고 https://docs.convex.dev/components의 설명서를 따를 수 있습니다.","es":"Habilita a los agentes a crear componentes Convex autocontenidos con exportaciones y gestión de dependencias, lo que permite una compartición fluida entre proyectos que utilizan componentes Convex y siguiendo la documentación de https://docs.convex.dev/components.","fr":"Permet aux agents de créer des composants Convex autocontenus avec des exportations et une gestion des dépendances, ce qui permet un partage fluide entre les projets utilisant des composants Convex et en suivant la documentation de https://docs.convex.dev/components.","de":"Ermächtigt Agents, selbstenthaltene Convex-Komponenten mit Exporten und Abhängigkeitsverwaltung zu erstellen, was ein nahtloses Teilen zwischen Projekten ermöglicht, die Convex-Komponenten verwenden und der Dokumentation von https://docs.convex.dev/components folgen.","pt":"Habilita os agentes a criar componentes Convex autocontidos com exports e gerenciamento de dependências, permitindo compartilhamento sem problemas em projetos que usam componentes Convex e seguindo a documentação de https://docs.convex.dev/components.","ru":"Наделяет агентов возможностью создавать самодостаточные компоненты Convex с экспортами и управлением зависимостями, что позволяет легко делиться ими между проектами, использующими компоненты Convex, и следуя документации на https://docs.convex.dev/components.","ar":"يمنح الموكلات القدرة على إنشاء مكونات Convex متكاملة مع تصدير وإدارة التبعيات، وتمكين المشاركة السهلة عبر المشاريع التي تستخدم مكونات Convex واتباع التوثيق من https://docs.convex.dev/components."},"useCases":{"en":["Authoring reusable Convex components for multiple projects","Implementing proper isolation and exports for Convex components","Managing dependencies across shared Convex components"],"zh":["为多个项目创建可重用Convex组件","为Convex组件实现适当的隔离和导出","管理共享Convex组件的依赖"],"ja":["複数のプロジェクト用に再利用可能なConvexコンポーネントを作成する","Convexコンポーネントの適切な分離とエクスポートを実装する","共有Convexコンポーネントの依存関係を管理する"],"ko":["여러 프로젝트 용으로 재사용 가능한 Convex 구성 요소를 작성하는 것","Convex 구성 요소에 대한 적절한 격리 및 내보내기 구현","공유 Convex 구성 요소의 종속성 관리"],"es":["Creación de componentes Convex reutilizables para múltiples proyectos","Implementación de un aislamiento y exportaciones adecuados para componentes Convex","Gestión de dependencias entre componentes Convex compartidos"],"fr":["Création de composants Convex réutilisables pour plusieurs projets","Mise en œuvre d''une isolation et d''exportations appropriées pour les composants Convex","Gestion des dépendances entre les composants Convex partagés"],"de":["Erstellung wiederverwendbarer Convex-Komponenten für mehrere Projekte","Implementierung einer ordnungsgemäßen Isolation und Exporte für Convex-Komponenten","Verwaltung von Abhängigkeiten zwischen geteilten Convex-Komponenten"],"pt":["Criação de componentes Convex reutilizáveis para vários projetos","Implementação de isolamento e exports adequados para componentes Convex","Gerenciamento de dependências entre componentes Convex compartilhados"],"ru":["Создание многократно используемых компонентов Convex для нескольких проектов","Реализация правильной изоляции и экспортов для компонентов Convex","Управление зависимостями между общими компонентами Convex"],"ar":["إنشاء مكونات Convex قابلة لإعادة الاستخدام لمشاريع متعددة","تطبيق عزل وتصدير مناسبين لمكونات Convex","إدارة التبعيات بين مكونات Convex المشتركة"]},"limitations":{"en":["Requires knowledge of Convex component authoring","Dependent on documentation from https://docs.convex.dev/components for implementation"],"zh":["需要Convex组件编写知识","依赖https://docs.convex.dev/components的文档进行实现"],"ja":["Convexコンポーネントの作成に関する知識が必要","実装にはhttps://docs.convex.dev/componentsのドキュメントに依存"],"ko":["Convex 구성 요소 작성 지식이 필요","구현에는 https://docs.convex.dev/components의 설명서가 필요"],"es":["Requiere conocimiento de la creación de componentes Convex","Depende de la documentación de https://docs.convex.dev/components para la implementación"],"fr":["Nécessite des connaissances en matière de création de composants Convex","Dépend de la documentation de https://docs.convex.dev/components pour la mise en œuvre"],"de":["Erfordert Kenntnisse über die Erstellung von Convex-Komponenten","Hängt von der Dokumentation von https://docs.convex.dev/components für die Implementierung ab"],"pt":["Requer conhecimento de criação de componentes Convex","Depende da documentação de https://docs.convex.dev/components para implementação"],"ru":["Требует знания создания компонентов Convex","Зависит от документации на https://docs.convex.dev/components для реализации"],"ar":["يتطلب معرفة بإنشاء مكونات Convex","يعتمد على التوثيق من https://docs.convex.dev/components للتطبيق"]},"version":4},"contentHash":"561346aded0969635fc3f32ae6d465f882266b6be20b4038c7a55645ff6db7c2","qualityScore":70}');
