INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Pratikkadam254/LinkedinLeadGen/convex-component-authoring', 'convex-component-authoring', 'Pratikkadam254', 'LinkedinLeadGen', 'community', 'convex-component-authoring Pratikkadam254 LinkedinLeadGen community Convex-component-authoring enables developers to create reusable Convex components for sharing across projects. It provides proper isolation, exports, and dependency management. Convex 组件是自包含、可重用的单元，具有适当的隔离、导出和依赖管理 Convex コンポーネントは、適切な隔離、エクスポート、依存関係管理を備えた自己完結型の再利用可能な単位です Convex 컴포넌트는 적절한 격리, 내보내기, 의존성 관리를 갖춘 자체 포함형 재사용 가능한 단위입니다 Crea componentes Convex autocontenidos y reutilizables con documentación y recursos adecuados Créez des composants Convex autonomes et réutilisables avec documentation et ressources appropriées Erstellen Sie selbstenthaltene und wiederverwendbare Convex-Komponenten mit Dokumentation und Ressourcen Convex component authoring permite criar componentes reutilizáveis com isolamento, exportação e gerenciamento de dependências Convex компоненты позволяют создавать автономные, повторно используемые компоненты с правильной изоляцией и управлением зависимостями إنشاء مكونات Convex قابلة لإعادة الاستخدام مع العزل والتصدير وإدارة التبعيات how to use convex-component-authoring convex-component-authoring setup guide convex-component-authoring documentation what is convex-component-authoring convex-component-authoring vs other component authoring techniques convex-component-authoring install convex-component-authoring tutorial convex-component-authoring best practices convex-component-authoring for AI agents Convex 组件 Convex 组件创建 Convex 组件作者化 Convex 依赖管理 Convex 文档 Convex 开发 Convex 应用构建 Convex 项目共享 AI 工具 Convex 技术 Creates self-contained Convex components with proper isolation Provides exports and dependency management for sharing across projects Follows documentation from https://docs.convex.dev/components Supports component authoring as described in https://docs.convex.dev/components/authoring Allows for broader context understanding with https://docs.convex.dev/llms.txt Enables fetching of the latest documentation for implementation Convex-component-authoring is a technique for creating self-contained, reusable Convex components with proper isolation, exports, and dependency management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('callstackincubator/agent-skills/react-native-brownfield-migration', 'official', 'callstackincubator', 'agent-skills', 'callstackincubator/agent-skills', 'react-native-brownfield-migration', 969, 57, 69, '2026-03-06T00:34:35Z', '2026-03-06T04:53:11.946Z', '406ee99d6da778962458ed7d26804ef276c96ea52575a8a2d744867be04a56fd', '{"id":"callstackincubator/agent-skills/react-native-brownfield-migration","name":"react-native-brownfield-migration","description":{"zh":"提供 React Native 渐进迁移策略，使用 @callstack/react-native-brownfield 进行初始设置，并将 XCFramework/AAR 构件集成到宿主应用中","ja":"React Native ブラウNFィールド マイグレーションを使用して、ネイティブ iOS と Android アプリを React Native または Expo に移行します","ko":"React Native 브라운 필드 마이그레이션을 사용하여 네이티브 iOS와 Android 애플리케이션을 React Native 또는 Expo로 마이그레이션합니다","pt":"A @callstack/react-native-brownfield fornece uma estratégia de adoção incremental para migrar aplicativos nativos para React Native ou Expo. Ela ajuda a planejar etapas de migração e integrar artefatos XCFramework/AAR","ru":"ИИ Агент @callstack/react-native-brownfield предоставляет пошаговую стратегию миграции нативных приложений в React Native или Expo. Она помогает планировать шаги миграции и интегрировать артефакты XCFramework/AAR","ar":"توفر @callstack/react-native-brownfield استراتيجية لتبني متدرج لنقل التطبيقات الأصلية إلى React Native أو Expo. تساعد في تخطيط خطوات النقل وتегра المكونات الإضافية XCFramework/AAR","en":"Provides an incremental adoption strategy to migrate native iOS or Android apps to React Native or Expo using @callstack/react-native-brownfield for initial setup. Use when planning migration steps, packaging XCFramework/AAR artifacts, and integrating them into host apps."},"owner":"callstackincubator","repo":"agent-skills","repoPath":"callstackincubator/agent-skills","stars":969,"forks":57,"updatedAt":"2026-03-06T00:34:35Z","topics":[],"skillMd":{"name":"react-native-brownfield-migration","description":"Provides an incremental adoption strategy to migrate native iOS or Android apps to React Native or Expo using @callstack/react-native-brownfield for initial setup. Use when planning migration steps, packaging XCFramework/AAR artifacts, and integrating them into host apps.","tags":"react-native, brownfield, expo, bare, ios, android, xcframework, aar, native-integration","bodyPreview":"# Migrating to React Native\n\n## Overview\n\nPrescriptive workflow for incremental adoption of React Native in existing native apps using `@callstack/react-native-brownfield`, from initial setup through phased host integration.\n\n- Expo track\n- Bare React Native track\n\nUse one track per task unless the user explicitly asks for migration or comparison.\n\n## Migration Strategy\n\nUse this strategy for brownfield migration planning and execution:\n\n1. Assess app state and select Expo or bare path.\n2. Perfo","body":"# Migrating to React Native\n\n## Overview\n\nPrescriptive workflow for incremental adoption of React Native in existing native apps using `@callstack/react-native-brownfield`, from initial setup through phased host integration.\n\n- Expo track\n- Bare React Native track\n\nUse one track per task unless the user explicitly asks for migration or comparison.\n\n## Migration Strategy\n\nUse this strategy for brownfield migration planning and execution:\n\n1. Assess app state and select Expo or bare path.\n2. Perform initial setup with `@callstack/react-native-brownfield`.\n3. Package RN artifacts (`XCFramework`/`AAR`) from the RN source app.\n4. Integrate one RN surface into the host app and validate startup/runtime.\n5. Repeat integration by feature/screen for incremental rollout.\n\n## Agent Guardrails (Global)\n\nApply these rules across all reference files:\n\n1. Select one path first (Expo or bare) and do not mix steps.\n2. Use placeholders from the docs (`<framework_target_name>`, `<android_module_name>`, `<registered_module_name>`) and resolve from project files.\n3. Validate each packaging command before moving to host integration.\n4. Prefer official docs for long platform snippets and CLI option details.\n5. Keep host apps isolated from direct React Native APIs when possible (facade approach).\n\n## Canonical Docs\n\n- [Quick Start](https://oss.callstack.com/react-native-brownfield/docs/getting-started/quick-start.md)\n- [Expo Integration](https://oss.callstack.com/react-native-brownfield/docs/getting-started/expo.md)\n- [iOS Integration](https://oss.callstack.com/react-native-brownfield/docs/getting-started/ios.md)\n- [Android Integration](https://oss.callstack.com/react-native-brownfield/docs/getting-started/android.md)\n- [Brownfield CLI](https://oss.callstack.com/react-native-brownfield/docs/cli/brownfield.md)\n- [Guidelines](https://oss.callstack.com/react-native-brownfield/docs/guides/guidelines.md)\n- [Troubleshooting](https://oss.callstack.com/react-native-brownfield/docs/guides/troubleshooting.md)\n\n## Path Selection Gate (Must Run First)\n\nBefore selecting any reference file, classify the project:\n\n1. If no React Native app exists yet, use Expo creation path:\n   - [expo-create-app.md][expo-create-app] -> [expo-quick-start.md][expo-quick-start]\n2. If React Native app exists, inspect `package.json` and `app.json`:\n   - Expo if `expo` is present or Expo plugin workflow is requested.\n   - Bare RN if native folders and direct RN CLI workflow are used without Expo path requirements.\n3. If still unclear, ask one disambiguation question.\n4. Continue with exactly one path.\n\n## When to Apply\n\nReference this package when:\n\n- Planning incremental migration from native-only apps to React Native or Expo\n- Creating brownfield integration flows for Expo or bare React Native projects\n- Performing initial setup with `@callstack/react-native-brownfield`\n- Generating iOS XCFramework artifacts from a React Native app\n- Generating and publishing Android AAR artifacts from a React Native app\n- Integrating generated artifacts into host iOS/Android apps\n\n## Quick Reference\n\n| File | Description |\n|------|-------------|\n| [quick-start.md][quick-start] | Shared preflight and mandatory path-selection gate |\n| [expo-create-app.md][expo-create-app] | Scaffold a new Expo app before Expo brownfield setup |\n| [expo-quick-start.md][expo-quick-start] | Expo plugin setup and packaging readiness |\n| [expo-ios-integration.md][expo-ios-integration] | Expo iOS packaging and host startup integration |\n| [expo-android-integration.md][expo-android-integration] | Expo Android packaging, publish, and host integration |\n| [bare-quick-start.md][bare-quick-start] | Bare React Native baseline setup |\n| [bare-ios-xcframework-generation.md][bare-ios-xcframework-generation] | Bare iOS XCFramework generation |\n| [bare-android-aar-generation.md][bare-android-aar-generation] | Bare Android AAR generation and publish |\n| [bare-ios-native-integration.md][bare-ios-native-integration] | Bare iOS host integration |\n| [bare-android-native-integration.md][bare-android-native-integration] | Bare Android host integration |\n\n## Problem -> Skill Mapping\n\n| Problem | Start With |\n|---------|------------|\n| Need path decision first | [quick-start.md][quick-start] |\n| Need to create a new Expo app for brownfield | [expo-create-app.md][expo-create-app] |\n| Need Expo brownfield setup and plugin wiring | [expo-quick-start.md][expo-quick-start] |\n| Need Expo iOS brownfield integration | [expo-ios-integration.md][expo-ios-integration] |\n| Need Expo Android brownfield integration | [expo-android-integration.md][expo-android-integration] |\n| Need bare RN baseline setup | [bare-quick-start.md][bare-quick-start] |\n| Need bare RN iOS XCFramework generation | [bare-ios-xcframework-generation.md][bare-ios-xcframework-generation] |\n| Need bare RN Android AAR generation/publish | [bare-android-aar-generation.md][bare-android-aar-generation] |\n| Need bare RN iOS host integration | [bare-ios-native-integration.md][bare-ios-native-integration] |\n| Need bare RN Android host integration | [bare-android-native-integration.md][bare-android-native-integration] |\n\n[quick-start]: references/quick-start.md\n[expo-create-app]: references/expo-create-app.md\n[expo-quick-start]: references/expo-quick-start.md\n[expo-ios-integration]: references/expo-ios-integration.md\n[expo-android-integration]: references/expo-android-integration.md\n[bare-quick-start]: references/bare-quick-start.md\n[bare-ios-xcframework-generation]: references/bare-ios-xcframework-generation.md\n[bare-android-aar-generation]: references/bare-android-aar-generation.md\n[bare-ios-native-integration]: references/bare-ios-native-integration.md\n[bare-android-native-integration]: references/bare-android-native-integration.md\n"},"category":"official","lastSynced":"2026-03-06T04:53:11.946Z","seo":{"title":{"zh":"React Native渐进迁移 Setup Guide - AIエージェント","ja":"React Native ブラウNFィールド マイグレーション Best Practices - AIエージェント","ko":"React Native 브라운 필드 마이그레이션 가이드 - AI 에이전트","pt":"Guia de Configuração para Migração de Aplicativos Nativos...","ru":"ИИ Агент для Миграции Нативных Приложений в React Native:...","ar":"دليل إعداد لمهاجرة التطبيقات الأصلية إلى React Native باس...","en":"react-native-brownfield-migration"},"description":{"zh":"提供 React Native 渐进迁移策略，使用 @callstack/react-native-brownfield 进行初始设置，并将 XCFramework/AAR 构件集成到宿主应用中","ja":"React Native ブラウNFィールド マイグレーションを使用して、ネイティブ iOS と Android アプリを React Native または Expo に移行します","ko":"React Native 브라운 필드 마이그레이션을 사용하여 네이티브 iOS와 Android 애플리케이션을 React Native 또는 Expo로 마이그레이션합니다","pt":"A @callstack/react-native-brownfield fornece uma estratégia de adoção incremental para migrar aplicativos nativos para React Native ou Expo. Ela ajuda a plan...","ru":"ИИ Агент @callstack/react-native-brownfield предоставляет пошаговую стратегию миграции нативных приложений в React Native или Expo. Она помогает планировать ...","ar":"توفر @callstack/react-native-brownfield استراتيجية لتبني متدرج لنقل التطبيقات الأصلية إلى React Native أو Expo. تساعد في تخطيط خطوات النقل وتегра المكونات ال...","en":"Provides an incremental adoption strategy to migrate native iOS or Android apps to React Native or Expo using @callstack/react-native-brownfield for initial ..."},"definition":{"en":"Provides an incremental adoption strategy to migrate native iOS or Android apps to React Native or Expo using @callstack/react-native-brownfield for initial setup. Use when planning migration steps, packaging XCFramework/AAR artifacts, and integrating them into host apps."},"features":{"zh":["使用 @callstack/react-native-brownfield 进行初始设置","支持 Expo 和 Bare React Native 两种路径","将 XCFramework/AAR 构件集成到宿主应用中","提供渐进迁移策略","支持原生 iOS 和 Android 应用的迁移"],"ja":["初期設定に @callstack/react-native-brownfield を使用","Expo と Bare React Native の 2 つのパスをサポート","XCFramework/AAR アーティファクトをホストアプリに統合","段階的なマイグレーション戦略を提供","ネイティブ iOS と Android アプリのマイグレーションをサポート"],"ko":["초기 설정에 @callstack/react-native-brownfield 사용","Expo와 Bare React Native의 2가지 경로를 지원","XCFramework/AAR 아티팩트를 호스트 애플리케이션에 통합","渐进 마이그레이션 전략을 제공","네이티브 iOS와 Android 애플리케이션의 마이그레이션을 지원"],"pt":["Estratégia de adoção incremental para migração de aplicativos nativos","Suporte para React Native e Expo","Integração de artefatos XCFramework/AAR","Planejamento de etapas de migração","Uso de @callstack/react-native-brownfield para configuração inicial"],"ru":["Пошаговая стратегия миграции нативных приложений","Поддержка React Native и Expo","Интеграция артефактов XCFramework/AAR","Планирование шагов миграции","Использование @callstack/react-native-brownfield для первоначальной настройки"],"ar":["استراتيجية لتبني متدرج لنقل التطبيقات الأصلية","دعم React Native و Expo","تегра المكونات الإضافية XCFramework/AAR","تخطيط خطوات النقل","استخدام @callstack/react-native-brownfield لضبط أولي"]},"keywords":{"zh":["React Native 渐进迁移","原生应用迁移","AIエージェント","@callstack/react-native-brownfield","Expo","Bare React Native","XCFramework","AAR"],"ja":["React Native ブラウNFィールド マイグレーション","ネイティブ アプリ マイグレーション","AIエージェント","@callstack/react-native-brownfield","Expo","Bare React Native","XCFramework","AAR"],"ko":["React Native 브라운 필드 마이그레이션","네이티브 애플리케이션 마이그레이션","AI 에이전트","@callstack/react-native-brownfield","Expo","Bare React Native","XCFramework","AAR"],"pt":["react native brownfield migration","migração de aplicativos nativos","adoção incremental","react native","expo","xcframework","aar","migração de aplicativos"],"ru":["react native brownfield migration","миграция нативных приложений","поэтапное внедрение","react native","expo","xcframework","aar","миграция приложений"],"ar":["react native brownfield migration","نقل التطبيقات الأصلية","تبني متدرج","react native","expo","xcframework","aar","نقل التطبيقات"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Mobile Agents needing incremental React Native adoption strategies for existing native iOS or Android apps","zh":"适用于需要逐步采用 React Native 的移动代理，用于现有的原生 iOS 或 Android 应用","ja":"React Native を段階的に採用する必要があるモバイルエージェントに適しています。既存のネイティブ iOS または Android アプリ用","ko":"기존의 네이티브 iOS 또는 Android 앱에 대해 점진적인 React Native 채택이 필요한 모바일 에이전트에 적합합니다","es":"Perfecto para Agentes Móviles que necesitan estrategias de adopción incremental de React Native para aplicaciones nativas de iOS o Android existentes","fr":"Parfait pour les agents mobiles ayant besoin de stratégies d''adoption incrémentale de React Native pour les applications natives iOS ou Android existantes","de":"Perfekt für Mobile Agents, die inkrementelle React Native-Adoptionsstrategien für bestehende native iOS- oder Android-Apps benötigen","pt":"Perfeito para Agentes Móveis que necessitam de estratégias de adoção incremental do React Native para aplicativos nativos iOS ou Android existentes","ru":"Идеально подходит для мобильных агентов, которым необходимы инкрементные стратегии внедрения React Native для существующих родных приложений iOS или Android","ar":"مثالي لعميل المحمول الذين يحتاجون إلى استراتيجيات تبني تدريجي ل React Native لتطبيقات iOS أو Android الأصلية الحالية"},"recommendation":{"en":"Empowers agents to migrate native apps to React Native or Expo using @callstack/react-native-brownfield, streamlining the process with phased host integration and packaging XCFramework/AAR artifacts","zh":"赋予代理将原生应用迁移到 React Native 或 Expo 的能力，使用 @callstack/react-native-brownfield，通过分阶段的主机集成和打包 XCFramework/AAR 工件来简化流程","ja":"@callstack/react-native-brownfield を使用して、エージェントがネイティブ アプリを React Native または Expo に移行できるようにし、段階的なホスト統合と XCFramework/AAR アーティファクトのパッケージ化によってプロセスを合理化する","ko":"@callstack/react-native-brownfield를 사용하여 에이전트가 네이티브 앱을 React Native 또는 Expo로 마이그레이션할 수 있도록 하며, 호스트 통합과 XCFramework/AAR 아티팩트의 패키징을 통해 프로세스를 간소화합니다","es":"Habilita a los agentes a migrar aplicaciones nativas a React Native o Expo utilizando @callstack/react-native-brownfield, simplificando el proceso con una integración de host por fases y empaquetando artefactos XCFramework/AAR","fr":"Permet aux agents de migrer des applications natives vers React Native ou Expo en utilisant @callstack/react-native-brownfield, en simplifiant le processus avec une intégration de l''hôte par phases et en empaquetant les artefacts XCFramework/AAR","de":"Ermächtigt die Agenten, native Apps zu React Native oder Expo zu migrieren, indem sie @callstack/react-native-brownfield verwenden, wodurch der Prozess durch eine phasenweise Host-Integration und Verpackung von XCFramework/AAR-Artefakten vereinfacht wird","pt":"Habilita os agentes a migrar aplicativos nativos para React Native ou Expo usando @callstack/react-native-brownfield, simplificando o processo com integração hospedeira faseada e embalagem de artefatos XCFramework/AAR","ru":"Позволяет агентам переносить родные приложения в React Native или Expo, используя @callstack/react-native-brownfield, упрощая процесс с помощью фазовой интеграции хоста и упаковки артефактов XCFramework/AAR","ar":"تمكين العميل من перенقل التطبيقات الأصلية إلى React Native أو Expo باستخدام @callstack/react-native-brownfield، وبذلك يُبسط العملية من خلال دمج الطرف المضيف المرحلي وتغليف مكونات XCFramework/AAR"},"useCases":{"en":["Planning brownfield migration steps for native iOS or Android apps","Packaging XCFramework/AAR artifacts for integration into host apps","Executing incremental adoption of React Native in existing native apps using Expo or bare React Native tracks"],"zh":["为原生 iOS 或 Android 应用规划棕地迁移步骤","为集成到宿主应用程序而打包 XCFramework/AAR 工件","使用 Expo 或裸 React Native 跟踪在现有原生应用中执行 React Native 的增量采用"],"ja":["ネイティブ iOS または Android アプリのブラウNFIELD 移行ステップを計画する","ホスト アプリに統合するための XCFramework/AAR アーティファクトをパッケージ化する","Expo またはバレ React Native トラックを使用して既存のネイティブ アプリで React Native のインクリメンタル アドプションを実行する"],"ko":["기존 네이티브 iOS 또는 Android 앱의 브라운필드 마이그레이션 단계 계획","호스트 앱에 통합하기 위한 XCFramework/AAR 아티팩트의 패키징","Expo 또는 베어 React Native 트랙을 사용하여 기존 네이티브 앱에서 React Native의 증분 채택을 실행"],"es":["Planificación de los pasos de migración brownfield para aplicaciones nativas de iOS o Android","Empaquetado de artefactos XCFramework/AAR para integración en aplicaciones de host","Ejecución de la adopción incremental de React Native en aplicaciones nativas existentes utilizando Expo o pistas de React Native bare"],"fr":["Planification des étapes de migration brownfield pour les applications natives iOS ou Android","Empaquetage des artefacts XCFramework/AAR pour intégration dans les applications hôtes","Exécution de l''adoption incrémentale de React Native dans les applications natives existantes en utilisant Expo ou des pistes React Native bare"],"de":["Planung der Brownfield-Migrationschritte für native iOS- oder Android-Apps","Verpacken von XCFramework/AAR-Artefakten für die Integration in Host-Apps","Durchführung der inkrementellen Adoption von React Native in bestehenden nativen Apps mit Expo oder unbaren React Native-Tracks"],"pt":["Planejamento de etapas de migração brownfield para aplicativos nativos iOS ou Android","Embalagem de artefatos XCFramework/AAR para integração em aplicativos hospedeiros","Execução de adoção incremental do React Native em aplicativos nativos existentes usando Expo ou faixas React Native nuas"],"ru":["Планирование шагов миграции brownfield для родных приложений iOS или Android","Упаковка артефактов XCFramework/AAR для интеграции в хост-приложения","Выполнение инкрементного внедрения React Native в существующие родные приложения с помощью Expo или голых треков React Native"],"ar":["تخطيط خطوات هجرة براونفيلد لتطبيقات iOS أو Android الأصلية","تغليف مكونات XCFramework/AAR لدمجها في تطبيقات الطرف المضيف","تنفيذ التبني التدريجي ل React Native في التطبيقات الأصلية الحالية باستخدام Expo أو المسارات النقية من React Native"]},"limitations":{"en":["Requires @callstack/react-native-brownfield for initial setup","Limited to React Native or Expo migration"],"zh":["需要 @callstack/react-native-brownfield 进行初始设置","仅限 React Native 或 Expo 迁移"],"ja":["初期設定には @callstack/react-native-brownfield が必要","React Native または Expo への移行のみ"],"ko":["초기 설정에는 @callstack/react-native-brownfield가 필요","React Native 또는 Expo 마이그레이션만"],"es":["Requiere @callstack/react-native-brownfield para la configuración inicial","Limitado a la migración de React Native o Expo"],"fr":["Nécessite @callstack/react-native-brownfield pour la configuration initiale","Limité à la migration de React Native ou Expo"],"de":["Benötigt @callstack/react-native-brownfield für die anfängliche Einrichtung","Begrenzt auf die Migration von React Native oder Expo"],"pt":["Requer @callstack/react-native-brownfield para configuração inicial","Limitado à migração do React Native ou Expo"],"ru":["Требуется @callstack/react-native-brownfield для начальной настройки","Ограничен миграцией React Native или Expo"],"ar":["يتطلب @callstack/react-native-brownfield لإعداد أولي","محدود بتبني React Native أو Expo"]},"version":4},"contentHash":"406ee99d6da778962458ed7d26804ef276c96ea52575a8a2d744867be04a56fd","repoEtag":"W/\"cde3f79b6c913438993afe18fdb53c1f5dcf7c814f31b8ef5104f2d45f6ca3dc\"","qualityScore":69}');
