INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('callstackincubator/agent-skills/react-native-brownfield-migration', 'react-native-brownfield-migration', 'callstackincubator', 'agent-skills', 'official', 'react-native-brownfield-migration callstackincubator agent-skills official 提供 React Native 渐进迁移策略，使用 @callstack/react-native-brownfield 进行初始设置，并将 XCFramework/AAR 构件集成到宿主应用中 React Native ブラウNFィールド マイグレーションを使用して、ネイティブ iOS と Android アプリを React Native または Expo に移行します React Native 브라운 필드 마이그레이션을 사용하여 네이티브 iOS와 Android 애플리케이션을 React Native 또는 Expo로 마이그레이션합니다 A @callstack/react-native-brownfield fornece uma estratégia de adoção incremental para migrar aplicativos nativos para React Native ou Expo. Ela ajuda a planejar etapas de migração e integrar artefatos XCFramework/AAR ИИ Агент @callstack/react-native-brownfield предоставляет пошаговую стратегию миграции нативных приложений в React Native или Expo. Она помогает планировать шаги миграции и интегрировать артефакты XCFramework/AAR توفر @callstack/react-native-brownfield استراتيجية لتبني متدرج لنقل التطبيقات الأصلية إلى React Native أو Expo. تساعد في تخطيط خطوات النقل وتегра المكونات الإضافية XCFramework/AAR Provides an incremental adoption strategy to migrate native iOS or Android apps to React Native or Expo using @callstack/react-native-brownfield for initial setup. Use when planning migration steps, packaging XCFramework/AAR artifacts, and integrating them into host apps. React Native 渐进迁移 原生应用迁移 AIエージェント @callstack/react-native-brownfield Expo Bare React Native XCFramework AAR Provides an incremental adoption strategy to migrate native iOS or Android apps to React Native or Expo using @callstack/react-native-brownfield for initial setup. Use when planning migration steps, packaging XCFramework/AAR artifacts, and integrating them into host apps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/brainstorming', 'official', 'obra', 'superpowers', 'obra/superpowers', 'brainstorming', 71924, 5546, 68, '2026-03-06T03:26:30Z', '2026-03-06T03:28:13.897Z', '7a238df1ebf0656c1da199aafafcc78c42f47bf4e56dd4e007a67afbb10af455', '{"id":"obra/superpowers/brainstorming","name":"brainstorming","description":{"en":"The Brainstorming Skill transforms initial ideas into fully formed technical designs and specifications through natural language dialogue. It is a mandatory pre-implementation gate for developers and product managers to clarify requirements and user intent.","zh":"AI代理头脑风暴技能通过协作对话将创意转化为完整设计和规范。它在理解项目上下文后逐步细化需求，在呈现设计并获得批准前禁止任何实现操作。","ja":"AIエージェントのブレインストーミングスキルは、協調的对話を通じてアイデアを設計と仕様に変換します。プロジェクトコンテキストを理解した後、要件を段階的に精緻化し、設計承認まで実装行動を禁止します。","ko":"AI 에이전트 브레인스토밍 기술은 협력적 대화를 통해 아이디어를 설계와 사양으로 전환합니다. 프로젝트 컨텍스트 이해 후 요구사항을 단계적으로 정제하며, 설계 승인 전까지 구현 행동을 금지합니다.","es":"El brainstorming es una etapa crucial antes de cualquier trabajo creativo, ayuda a explorar la intención del usuario y los requisitos de diseño","fr":"Le brainstorming est une étape cruciale avant tout travail créatif, il aide à explorer l''intention de l''utilisateur et les exigences de conception","de":"Das Brainstorming ist ein entscheidender Schritt vor jeder kreativen Arbeit, es hilft dabei, die Benutzerabsicht und die Designanforderungen zu erkunden","pt":"Um agente de IA especializado em brainstorming técnico que transforma ideias em designs e especificações completas através de diálogo colaborativo. É um hard-gate obrigatório antes de qualquer implementação de código.","ru":"Специализированный ИИ агент для технического brainstorming, превращающий идеи в готовые дизайны и спецификации через collaborative dialogue. Обязательный hard-gate перед любым кодированием.","ar":"وكيل ذكاء اصطناعي متخصص في العصف الذهني التقني لتحويل الأفكار إلى تصاميم ومواصفات كاملة عبر الحوار التعاوني. بوابة إلزامية قبل أي تنفيذ للكود."},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"brainstorming","description":"You MUST use this before any creative work - creating features, building components, adding functionality, or modifying behavior. Explores user intent, requirements and design before implementation.","bodyPreview":"# Brainstorming Ideas Into Designs\n\n## Overview\n\nHelp turn ideas into fully formed designs and specs through natural collaborative dialogue.\n\nStart by understanding the current project context, then ask questions one at a time to refine the idea. Once you understand what you''re building, present the design and get user approval.\n\n<HARD-GATE>\nDo NOT invoke any implementation skill, write any code, scaffold any project, or take any implementation action until you have presented a design and the us","body":"# Brainstorming Ideas Into Designs\n\n## Overview\n\nHelp turn ideas into fully formed designs and specs through natural collaborative dialogue.\n\nStart by understanding the current project context, then ask questions one at a time to refine the idea. Once you understand what you''re building, present the design and get user approval.\n\n<HARD-GATE>\nDo NOT invoke any implementation skill, write any code, scaffold any project, or take any implementation action until you have presented a design and the user has approved it. This applies to EVERY project regardless of perceived simplicity.\n</HARD-GATE>\n\n## Anti-Pattern: \"This Is Too Simple To Need A Design\"\n\nEvery project goes through this process. A todo list, a single-function utility, a config change — all of them. \"Simple\" projects are where unexamined assumptions cause the most wasted work. The design can be short (a few sentences for truly simple projects), but you MUST present it and get approval.\n\n## Checklist\n\nYou MUST create a task for each of these items and complete them in order:\n\n1. **Explore project context** — check files, docs, recent commits\n2. **Ask clarifying questions** — one at a time, understand purpose/constraints/success criteria\n3. **Propose 2-3 approaches** — with trade-offs and your recommendation\n4. **Present design** — in sections scaled to their complexity, get user approval after each section\n5. **Write design doc** — save to `docs/plans/YYYY-MM-DD-<topic>-design.md` and commit\n6. **Transition to implementation** — invoke writing-plans skill to create implementation plan\n\n## Process Flow\n\n```dot\ndigraph brainstorming {\n    \"Explore project context\" [shape=box];\n    \"Ask clarifying questions\" [shape=box];\n    \"Propose 2-3 approaches\" [shape=box];\n    \"Present design sections\" [shape=box];\n    \"User approves design?\" [shape=diamond];\n    \"Write design doc\" [shape=box];\n    \"Invoke writing-plans skill\" [shape=doublecircle];\n\n    \"Explore project context\" -> \"Ask clarifying questions\";\n    \"Ask clarifying questions\" -> \"Propose 2-3 approaches\";\n    \"Propose 2-3 approaches\" -> \"Present design sections\";\n    \"Present design sections\" -> \"User approves design?\";\n    \"User approves design?\" -> \"Present design sections\" [label=\"no, revise\"];\n    \"User approves design?\" -> \"Write design doc\" [label=\"yes\"];\n    \"Write design doc\" -> \"Invoke writing-plans skill\";\n}\n```\n\n**The terminal state is invoking writing-plans.** Do NOT invoke frontend-design, mcp-builder, or any other implementation skill. The ONLY skill you invoke after brainstorming is writing-plans.\n\n## The Process\n\n**Understanding the idea:**\n- Check out the current project state first (files, docs, recent commits)\n- Ask questions one at a time to refine the idea\n- Prefer multiple choice questions when possible, but open-ended is fine too\n- Only one question per message - if a topic needs more exploration, break it into multiple questions\n- Focus on understanding: purpose, constraints, success criteria\n\n**Exploring approaches:**\n- Propose 2-3 different approaches with trade-offs\n- Present options conversationally with your recommendation and reasoning\n- Lead with your recommended option and explain why\n\n**Presenting the design:**\n- Once you believe you understand what you''re building, present the design\n- Scale each section to its complexity: a few sentences if straightforward, up to 200-300 words if nuanced\n- Ask after each section whether it looks right so far\n- Cover: architecture, components, data flow, error handling, testing\n- Be ready to go back and clarify if something doesn''t make sense\n\n## After the Design\n\n**Documentation:**\n- Write the validated design to `docs/plans/YYYY-MM-DD-<topic>-design.md`\n- Use elements-of-style:writing-clearly-and-concisely skill if available\n- Commit the design document to git\n\n**Implementation:**\n- Invoke the writing-plans skill to create a detailed implementation plan\n- Do NOT invoke any other skill. writing-plans is the next step.\n\n## Key Principles\n\n- **One question at a time** - Don''t overwhelm with multiple questions\n- **Multiple choice preferred** - Easier to answer than open-ended when possible\n- **YAGNI ruthlessly** - Remove unnecessary features from all designs\n- **Explore alternatives** - Always propose 2-3 approaches before settling\n- **Incremental validation** - Present design, get approval before moving on\n- **Be flexible** - Go back and clarify when something doesn''t make sense\n"},"category":"official","lastSynced":"2026-03-06T03:28:13.897Z","seo":{"title":{"en":"Brainstorming: Collaborative Design & Spec Generation | A...","zh":"AI代理头脑风暴最佳实践：设计前需求分析指南","ja":"AIエージェントを使ったブレインストーミング：設計前の要件定義ガイド","ko":"AI 에이전트 브레인스토밍 최적화: 구현 전 설계 검토 가이드","es":"Guía de Configuración para Brainstorming con Herramientas...","fr":"Guide de Mise en Place pour le Brainstorming avec des Out...","de":"Einrichtungsleitfaden für Brainstorming mit KI-Tools","pt":"Brainstorming AI Agent: Guia de Melhores Práticas para De...","ru":"Brainstorming ИИ Агент: Лучшие практики для проектировани...","ar":"وكيل الذكاء الاصطناعي Brainstorming: دليل أفضل الممارسات ..."},"description":{"en":"Stop coding blind. This AI Agent Skill acts as a hard-gate, forcing collaborative dialogue to refine user intent & generate approved designs before any imple...","zh":"AI代理头脑风暴技能：通过自然对话将创意转化为完整设计规范。在实现前分析用户意图和需求，避免过早编码，确保项目方向正确。","ja":"AIエージェントのブレインストーミングスキル：自然な対話でアイデアを設計仕様に変換。実装前にユーザー意図と要件を分析し、早期コーディングを防止。","ko":"AI 에이전트 브레인스토밍 기술: 자연스러운 대화로 아이디어를 설계 사양으로 전환. 구현 전 사용자 의도와 요구사항을 분석하여 조기 코딩 방지.","es":"Aprende a utilizar el brainstorming antes de cualquier trabajo creativo con herramientas de AI para desarrolladores","fr":"Découvrez comment utiliser le brainstorming avant tout travail créatif avec des outils d''IA pour les développeurs","de":"Erfahren Sie, wie Sie das Brainstorming vor jeder kreativen Arbeit mit KI-Tools für Entwickler nutzen können","pt":"Use este agente de IA antes de codificar para explorar a intenção do usuário e requisitos técnicos. Colabora no diálogo para refinar ideias e gerar designs a...","ru":"Используйте этого ИИ агента перед кодированием для изучения пользовательского intent и технических требований. Совместный диалог для уточнения идей и генерац...","ar":"استخدم هذا الوكيل قبل البرمجة لاستكشاف نية المستخدم والمتطلبات الفنية. حوار تعاوني لصقل الأفكار وإنشاء تصاميم معتمدة لتجنب إعادة العمل."},"definition":{"en":"Brainstorming is an AI Agent Skill that facilitates a structured, collaborative dialogue to explore user intent and project requirements. It acts as a mandatory hard-gate to generate and get approval on a complete design specification before any code is written or implementation actions are taken.","zh":"AI代理头脑风暴是一种在创造性工作前使用的技能，通过自然对话探索用户意图、需求和设计。它在呈现设计方案并获得用户批准前，严格禁止任何实现操作，确保项目方向正确。","ja":"AIエージェントのブレインストーミングは、創造的作業前に使用するスキルで、自然な対話を通じてユーザー意図、要件、設計を探求します。設計案を提示しユーザー承認を得るまで、実装行動を厳格に禁止します。","ko":"AI 에이전트 브레인스토밍은 창의적 작업 전에 사용되는 기술로, 자연스러운 대화를 통해 사용자 의도, 요구사항, 설계를 탐구합니다. 설계안을 제시하고 사용자 승인을 얻을 때까지 구현 행동을 엄격히 금지합니다.","es":"El brainstorming es un proceso de colaboración que ayuda a convertir ideas en diseños y especificaciones completas","fr":"Le brainstorming est un processus de collaboration qui aide à convertir des idées en conceptions et spécifications complètes","de":"Das Brainstorming ist ein Kollaborationsprozess, der dabei hilft, Ideen in vollständige Designs und Spezifikationen umzusetzen","pt":"Brainstorming é uma skill de IA que atua como um gate obrigatório para explorar a intenção do usuário, requisitos e design antes da implementação. Transforma ideias em designs completos através de diálogo colaborativo e questionamento sequencial.","ru":"Brainstorming — это навык ИИ, действующий как обязательный hard-gate для исследования пользовательского intent, требований и дизайна перед implementation. Превращает идеи в готовые designs через collaborative dialogue.","ar":"Brainstorming هي مهارة ذكاء اصطناعي تعمل كبوابة إلزامية لاستكشاف نية المستخدم والمتطلبات والتصميم قبل التنفيذ. تحول الأفكار إلى تصاميم كاملة عبر الحوار التعاوني والأسئلة المتسلسلة."},"features":{"en":["Enforces a mandatory pre-implementation hard-gate to prevent premature coding","Refines ideas through iterative, natural collaborative dialogue","Generates complete technical designs and specifications from initial concepts","Explicitly withholds all implementation skills (e.g., coding, scaffolding) until design approval"],"zh":["通过自然协作对话将创意转化为完整设计规范","基于当前项目上下文逐步提问细化需求","在呈现设计并获得批准前禁止任何实现操作","严格防止过早编写代码或搭建项目","专注于用户意图和需求探索而非立即实现","确保功能创建前的完整设计验证流程"],"ja":["自然な協調的对話でアイデアを設計仕様に変換","現在のプロジェクトコンテキストに基づく段階的質問","設計承認まで実装スキルの起動を禁止","早期コーディングやプロジェクト構築を防止","ユーザー意図と要件探索に集中","機能作成前の完全な設計検証プロセスを確保"],"ko":["자연스러운 협력적 대화로 아이디어를 설계 사양으로 전환","현재 프로젝트 컨텍스트 기반의 단계적 질문","설계 승인 전까지 구현 기술 실행 금지","조기 코딩이나 프로젝트 스캐폴딩 방지","사용자 의도와 요구사항 탐구에 집중","기능 생성 전 완전한 설계 검증 프로세스 보장"],"es":["Exploración de la intención del usuario y los requisitos de diseño","Colaboración natural a través del diálogo","Presentación de diseños y especificaciones completas","Aprobación del usuario antes de la implementación","Integración con herramientas de AI para desarrolladores"],"fr":["Exploration de l''intention de l''utilisateur et des exigences de conception","Collaboration naturelle à travers le dialogue","Présentation de conceptions et spécifications complètes","Approbation de l''utilisateur avant la mise en œuvre","Intégration avec des outils d''IA pour les développeurs"],"de":["Erforschung der Benutzerabsicht und der Designanforderungen","Natürliche Kollaboration durch den Dialog","Präsentation von vollständigen Designs und Spezifikationen","Benutzerzustimmung vor der Implementierung","Integration mit KI-Tools für Entwickler"],"pt":["Hard-gate obrigatório que bloqueia implementação até aprovação do design","Diálogo colaborativo natural para refinamento progressivo de ideias","Exploração técnica de intenção do usuário e requisitos de projeto","Questionamento sequencial focado em contexto de projeto atual","Geração de especificações completas para features e componentes","Prevenção de retrabalho através de validação pré-implementação"],"ru":["Обязательный hard-gate, блокирующий implementation до approval дизайна","Естественный collaborative dialogue для progressive refinement идей","Техническое исследование user intent и project requirements","Sequential questioning с фокусом на current project context","Генерация полных specifications для features и components","Предотвращение rework через pre-implementation validation"],"ar":["بوابة إلزامية تمنع التنفيذ حتى الموافقة على التصميم","حوار تعاوني طبيعي لصقل الأفكار بشكل تدريجي","استكشاف تقني لنية المستخدم ومتطلبات المشروع","أسئلة متسلسلة تركز على سياق المشروع الحالي","إنشاء مواصفات كاملة للميزات والمكونات","منع إعادة العمل من خلال التحقق قبل التنفيذ"]},"keywords":{"en":["brainstorming AI agent skill","how to use brainstorming for design","brainstorming vs direct implementation","pre development requirements gathering","brainstorming skill setup guide","what is brainstorming in AI agents","collaborative design specification generator","AI agent hard-gate skill"],"zh":["AI代理头脑风暴","需求分析技能","设计前验证","用户意图探索","自然对话设计","实现前规范","AI协作工具","功能设计最佳实践"],"ja":["AIエージェントブレインストーミング","要件定義スキル","設計前検証","ユーザー意図探求","自然対話設計","実装前仕様","AI協調ツール","機能設計ベストプラクティス"],"ko":["AI 에이전트 브레인스토밍","요구사항 분석 기술","설계 전 검증","사용자 의도 탐구","자연스러운 대화 설계","구현 전 사양","AI 협업 도구","기능 설계 최적 방법"],"es":["brainstorming para desarrolladores","herramientas de AI para desarrolladores","diseño de software","desarrollo de aplicaciones","colaboración en equipo","intención del usuario","requisitos de diseño","especificaciones completas"],"fr":["brainstorming pour les développeurs","outils d''IA pour les développeurs","conception de logiciels","développement d''applications","collaboration d''équipe","intention de l''utilisateur","exigences de conception","spécifications complètes"],"de":["Brainstorming für Entwickler","KI-Tools für Entwickler","Software-Design","Anwendungs-Entwicklung","Team-Kollaboration","Benutzerabsicht","Designanforderungen","vollständige Spezifikationen"],"pt":["brainstorming agente ia","design colaborativo ia","pré-implementação features","hard-gate desenvolvimento","explorar intenção usuário","refinar ideias técnicas","especificações componentes react","validação pré-codificação"],"ru":["brainstorming ИИ агент","collaborative dialogue дизайн","pre-implementation проектирование","hard-gate разработка","user intent исследование","technical refinement идей","specifications components react","pre-coding validation"],"ar":["عصف ذهني وكيل ذكاء اصطناعي","حوار تعاوني للتصميم","ما قبل التنفيذ الميزات","بوابة إلزامية للتطوير","استكشاف نية المستخدم","صقل الأفكار التقنية","مواصفات مكونات React","تحقق قبل البرمجة"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Design-First Agents requiring comprehensive requirement analysis before implementation.","zh":"Perfect for Design-First Agents requiring comprehensive requirement analysis before implementation.","ja":"Perfect for Design-First Agents requiring comprehensive requirement analysis before implementation.","ko":"Perfect for Design-First Agents requiring comprehensive requirement analysis before implementation.","es":"Perfecto para agentes de diseño primero que requieren un análisis exhaustivo de requisitos antes de la implementación.","fr":"Parfait pour les agents axés sur la conception nécessitant une analyse complète des exigences avant la mise en œuvre.","de":"Ideal für Design-First-Agenten, die eine umfassende Anforderungsanalyse vor der Implementierung benötigen.","pt":"Perfeito para Agentes Design-First que exigem análise abrangente de requisitos antes da implementação.","ru":"Идеально подходит для агентов Design-First, требующих всестороннего анализа требований перед внедрением.","ar":"مثالي لوكلاء Design-First الذين يتطلبون تحليلاً شاملاً للمتطلبات قبل التنفيذ."},"recommendation":{"en":"Enforces a hard-gated design process that prevents premature implementation by systematically exploring user intent, requirements, and design specifications through natural collaborative dialogue. Ensures full design approval before any code generation or project scaffolding occurs.","zh":"Enforces a hard-gated design process that prevents premature implementation by systematically exploring user intent, requirements, and design specifications through natural collaborative dialogue. Ensures full design approval before any code generation or project scaffolding occurs.","ja":"Enforces a hard-gated design process that prevents premature implementation by systematically exploring user intent, requirements, and design specifications through natural collaborative dialogue. Ensures full design approval before any code generation or project scaffolding occurs.","ko":"Enforces a hard-gated design process that prevents premature implementation by systematically exploring user intent, requirements, and design specifications through natural collaborative dialogue. Ensures full design approval before any code generation or project scaffolding occurs.","es":"Impone un proceso de diseño estricto que evita la implementación prematura mediante la exploración sistemática de la intención del usuario, los requisitos y las especificaciones de diseño a través de un diálogo colaborativo natural. Garantiza la aprobación completa del diseño antes de que se genere cualquier código o se cree la estructura del proyecto.","fr":"Applique un processus de conception rigoureux qui empêche une mise en œuvre prématurée en explorant systématiquement l''intention de l''utilisateur, les exigences et les spécifications de conception grâce à un dialogue collaboratif naturel. Garantit une approbation complète de la conception avant toute génération de code ou échafaudage de projet.","de":"Erzwingt einen streng abgesicherten Designprozess, der eine vorzeitige Implementierung verhindert, indem systematisch die Benutzerabsicht, Anforderungen und Designspezifikationen durch natürlichen kollaborativen Dialog untersucht werden. Stellt sicher, dass das Design vollständig genehmigt ist, bevor Codegenerierung oder Projektgerüstbau erfolgt.","pt":"Impõe um processo de design rigoroso que evita implementação prematura, explorando sistematicamente a intenção do usuário, requisitos e especificações de design por meio de diálogo colaborativo natural. Garante aprovação total do design antes de qualquer geração de código ou criação de estrutura de projeto.","ru":"Обеспечивает строгий поэтапный процесс проектирования, предотвращающий преждевременную реализацию путем систематического изучения намерений пользователя, требований и спецификаций проектирования через естественный совместный диалог. Гарантирует полное утверждение дизайна перед любым генерацией кода или созданием каркаса проекта.","ar":"يفرض عملية تصميم صارمة تمنع التنفيذ المبكر من خلال استكشاف منهجي لنية المستخدم والمتطلبات ومواصفات التصميم من خلال حوار تعاوني طبيعي. يضمن الموافقة الكاملة على التصميم قبل أي توليد للكود أو إنشاء هيكل المشروع."},"useCases":{"en":["Refining vague concepts into detailed specifications","Conducting comprehensive requirement analysis","Creating implementation-ready design documents","Validating user intent before development"],"zh":["Refining vague concepts into detailed specifications","Conducting comprehensive requirement analysis","Creating implementation-ready design documents","Validating user intent before development"],"ja":["Refining vague concepts into detailed specifications","Conducting comprehensive requirement analysis","Creating implementation-ready design documents","Validating user intent before development"],"ko":["Refining vague concepts into detailed specifications","Conducting comprehensive requirement analysis","Creating implementation-ready design documents","Validating user intent before development"],"es":["Refinar conceptos vagos en especificaciones detalladas","Realizar un análisis exhaustivo de requisitos","Crear documentos de diseño listos para implementación","Validar la intención del usuario antes del desarrollo"],"fr":["Affiner des concepts vagues en spécifications détaillées","Mener une analyse complète des exigences","Créer des documents de conception prêts pour l''implémentation","Valider l''intention de l''utilisateur avant le développement"],"de":["Vage Konzepte in detaillierte Spezifikationen verfeinern","Durchführung umfassender Anforderungsanalysen","Erstellung implementierungsfertiger Designdokumente","Validierung der Benutzerabsicht vor der Entwicklung"],"pt":["Refinamento de conceitos vagos em especificações detalhadas","Realização de análise abrangente de requisitos","Criação de documentos de design prontos para implementação","Validação da intenção do usuário antes do desenvolvimento"],"ru":["Преобразование расплывчатых концепций в детальные спецификации","Проведение всестороннего анализа требований","Создание готовых к реализации проектных документов","Проверка намерений пользователя до разработки"],"ar":["تحويل المفاهيم الغامضة إلى مواصفات مفصلة","إجراء تحليل متطلبات شامل","إنشاء وثائق تصميم جاهزة للتنفيذ","التحقق من نية المستخدم قبل التطوير"]},"limitations":{"en":["Requires full design approval before implementation","Mandatory sequential questioning approach","No code generation until final design presentation"],"zh":["Requires full design approval before implementation","Mandatory sequential questioning approach","No code generation until final design presentation"],"ja":["Requires full design approval before implementation","Mandatory sequential questioning approach","No code generation until final design presentation"],"ko":["Requires full design approval before implementation","Mandatory sequential questioning approach","No code generation until final design presentation"],"es":["Requiere aprobación completa del diseño antes de la implementación","Enfoque de cuestionamiento secuencial obligatorio","No se genera código hasta la presentación final del diseño"],"fr":["Nécessite une approbation complète de la conception avant la mise en œuvre","Approche de questionnement séquentielle obligatoire","Aucune génération de code avant la présentation finale de la conception"],"de":["Erfordert vollständige Designgenehmigung vor der Implementierung","Verpflichtender sequenzieller Befragungsansatz","Keine Codegenerierung bis zur finalen Designpräsentation"],"pt":["Exige aprovação total do design antes da implementação","Abordagem de questionamento sequencial obrigatória","Nenhuma geração de código até a apresentação final do design"],"ru":["Требует полного утверждения дизайна перед внедрением","Обязательный последовательный подход к опросу","Отсутствие генерации кода до финальной презентации дизайна"],"ar":["يتطلب الموافقة الكاملة على التصميم قبل التنفيذ","نهج الاستجواب المتسلسل الإلزامي","لا يوجد توليد للكود حتى العرض النهائي للتصميم"]},"version":4},"contentHash":"7a238df1ebf0656c1da199aafafcc78c42f47bf4e56dd4e007a67afbb10af455","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":68}');
