INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/finishing-a-development-branch', 'finishing-a-development-branch', 'obra', 'superpowers', 'official', 'finishing-a-development-branch obra superpowers official The finishing-a-development-branch skill guides AI agents through completing development work by verifying test suites and presenting structured options for integration. It helps developers and DevOps engineers safely merge, create pull requests, or clean up branches after implementation is compl... Skill de IA que guía la finalización de trabajo en ramas de desarrollo. Verifica que los tests pasen, presenta opciones estructuradas para merge o PR, y ejecuta la limpieza automática del branch siguiendo principios de workflow definidos. Compétence IA qui guide la finalisation du travail sur les branches de développement. Vérifie la réussite des tests, présente des options structurées pour merge ou PR, et exécute le nettoyage automatique selon des principes de workflow définis. KI Skill der den Abschluss von Entwicklungsbranches leitet. Verifiziert bestandene Tests, bietet strukturierte Merge/PR Optionen und führt automatische Bereinigung nach definierten Workflow-Prinzipien durch. O Finishing-a-Development-Branch é uma habilidade que guia a conclusão do trabalho de desenvolvimento, verificando testes e apresentando opções de merge e limpeza Finishing-a-Development-Branch - это навык, который помогает завершить разработку, проверив тесты и выбрав опции слияния или очистки Finishing-a-Development-Branch هو مهارة تساعد على إكمال العمل التطويري، من خلال التحقق من الاختبارات وعرض الخيارات لدمج أو تنظيف how to use finishing-a-development-branch skill finishing-a-development-branch AI agent workflow npm test cargo test pytest go test verification git branch merge PR cleanup options finishing-a-development-branch setup guide development completion workflow automation what is finishing-a-development-branch finishing-a-development-branch vs manual git workflow install finishing-a-development-branch skill development branch test verification best practices Verifies test suite execution via npm test, cargo test, pytest, and go test commands Presents structured workflow options for branch integration (merge, PR, cleanup) Executes user-selected workflow choice automatically Handles development branch cleanup after completion Announces skill activation with "I''m using the finishing-a-development-branch skill to complete this work" Follows core principle: Verify tests → Present options → Execute choice → Clean up finishing-a-development-branch is an AI agent skill that manages the final stages of development work. It follows a core principle of verifying tests, presenting integration options (merge, PR, or cleanup), executing the chosen workflow, and cleaning up the branch to maintain repository hygiene.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/requesting-code-review', 'official', 'obra', 'superpowers', 'obra/superpowers', 'requesting-code-review', 71924, 5546, 68, '2026-03-06T03:26:30Z', '2026-03-06T03:32:16.897Z', '2da31af22a58938ab78f3ee6d5b4687fcca062b923b646459eb52ba72117ef97', '{"id":"obra/superpowers/requesting-code-review","name":"requesting-code-review","description":{"en":"The requesting-code-review skill automates the process of dispatching a code-reviewer subagent to verify work meets requirements. It is designed for developers and teams practicing subagent-driven development to ensure code quality before merging.","zh":"requesting-code-review是一个AI代理技能，用于在开发关键节点自动派遣代码审查子代理。它通过在git中获取BASE_SHA和HEAD_SHA来比较代码变更，确保工作符合要求并在合并前发现问题。","ja":"requesting-code-reviewは、開発の重要なポイントでコードレビューサブエージェントを自動的に派遣するAIエージェントスキルです。gitでBASE_SHAとHEAD_SHAを取得して変更を比較し、マージ前に問題を検出します。","ko":"requesting-code-review는 개발의 주요 지점에서 코드 리뷰 서브에이전트를 자동으로 파견하는 AI 에이전트 스킬입니다. git에서 BASE_SHA와 HEAD_SHA를 가져와 변경 사항을 비교하고, 병합 전에 문제를 발견합니다.","es":"La skill requesting-code-review automatiza revisiones de código mediante el subagente superpowers:code-reviewer. Está diseñada para verificar que el trabajo cumple los requisitos tras completar tareas, implementar features o antes de mergear a main, integrando comandos CLI con git SHAs.","fr":"La compétence requesting-code-review automatise les revues de code via le sous-agent superpowers:code-reviewer. Elle vérifie que le travail répond aux exigences après tâches, implémentation de fonctionnalités ou avant merge sur main, en intégrant des commandes CLI avec les SHAs git.","de":"Die Skill requesting-code-review automatisiert Code-Reviews über den Subagenten superpowers:code-reviewer. Sie überprüft, ob die Arbeit nach Tasks, Feature-Implementierung oder vor Merge auf main den Anforderungen entspricht und integriert CLI-Befehle mit git SHAs.","pt":"A skill requesting-code-review automatiza a garantia de qualidade do código ao despachar um subagente revisor. É projetada para validação obrigatória pós-tarefa, pós-feature e pré-merge para detectar issues cedo.","ru":"Навык requesting-code-review автоматизирует обеспечение качества кода, запуская субагента-рецензента. Предназначен для обязательной проверки после задач, функций и перед слиянием для раннего обнаружения проблем.","ar":"مهارة requesting-code-review تؤتمت ضمان جودة الكود عن طريق إرسال وكيل فرعي للمراجعة. مصممة للتحقق الإلزامي بعد المهام والميزات وقبل الدمج لاكتشاف المشكلات مبكرًا."},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"requesting-code-review","description":"Use when completing tasks, implementing major features, or before merging to verify work meets requirements","bodyPreview":"# Requesting Code Review\n\nDispatch superpowers:code-reviewer subagent to catch issues before they cascade.\n\n**Core principle:** Review early, review often.\n\n## When to Request Review\n\n**Mandatory:**\n- After each task in subagent-driven development\n- After completing major feature\n- Before merge to main\n\n**Optional but valuable:**\n- When stuck (fresh perspective)\n- Before refactoring (baseline check)\n- After fixing complex bug\n\n## How to Request\n\n**1. Get git SHAs:**\n```bash\nBASE_SHA=$(git rev-pa","body":"# Requesting Code Review\n\nDispatch superpowers:code-reviewer subagent to catch issues before they cascade.\n\n**Core principle:** Review early, review often.\n\n## When to Request Review\n\n**Mandatory:**\n- After each task in subagent-driven development\n- After completing major feature\n- Before merge to main\n\n**Optional but valuable:**\n- When stuck (fresh perspective)\n- Before refactoring (baseline check)\n- After fixing complex bug\n\n## How to Request\n\n**1. Get git SHAs:**\n```bash\nBASE_SHA=$(git rev-parse HEAD~1)  # or origin/main\nHEAD_SHA=$(git rev-parse HEAD)\n```\n\n**2. Dispatch code-reviewer subagent:**\n\nUse Task tool with superpowers:code-reviewer type, fill template at `code-reviewer.md`\n\n**Placeholders:**\n- `{WHAT_WAS_IMPLEMENTED}` - What you just built\n- `{PLAN_OR_REQUIREMENTS}` - What it should do\n- `{BASE_SHA}` - Starting commit\n- `{HEAD_SHA}` - Ending commit\n- `{DESCRIPTION}` - Brief summary\n\n**3. Act on feedback:**\n- Fix Critical issues immediately\n- Fix Important issues before proceeding\n- Note Minor issues for later\n- Push back if reviewer is wrong (with reasoning)\n\n## Example\n\n```\n[Just completed Task 2: Add verification function]\n\nYou: Let me request code review before proceeding.\n\nBASE_SHA=$(git log --oneline | grep \"Task 1\" | head -1 | awk ''{print $1}'')\nHEAD_SHA=$(git rev-parse HEAD)\n\n[Dispatch superpowers:code-reviewer subagent]\n  WHAT_WAS_IMPLEMENTED: Verification and repair functions for conversation index\n  PLAN_OR_REQUIREMENTS: Task 2 from docs/plans/deployment-plan.md\n  BASE_SHA: a7981ec\n  HEAD_SHA: 3df7661\n  DESCRIPTION: Added verifyIndex() and repairIndex() with 4 issue types\n\n[Subagent returns]:\n  Strengths: Clean architecture, real tests\n  Issues:\n    Important: Missing progress indicators\n    Minor: Magic number (100) for reporting interval\n  Assessment: Ready to proceed\n\nYou: [Fix progress indicators]\n[Continue to Task 3]\n```\n\n## Integration with Workflows\n\n**Subagent-Driven Development:**\n- Review after EACH task\n- Catch issues before they compound\n- Fix before moving to next task\n\n**Executing Plans:**\n- Review after each batch (3 tasks)\n- Get feedback, apply, continue\n\n**Ad-Hoc Development:**\n- Review before merge\n- Review when stuck\n\n## Red Flags\n\n**Never:**\n- Skip review because \"it''s simple\"\n- Ignore Critical issues\n- Proceed with unfixed Important issues\n- Argue with valid technical feedback\n\n**If reviewer wrong:**\n- Push back with technical reasoning\n- Show code/tests that prove it works\n- Request clarification\n\nSee template at: requesting-code-review/code-reviewer.md\n"},"category":"official","lastSynced":"2026-03-06T03:32:16.897Z","seo":{"title":{"en":"requesting-code-review: Automate Git-Based Code Reviews |...","zh":"请求代码审查AI代理：设置指南与最佳实践","ja":"コードレビュー依頼AIエージェント：開発効率化ガイド","ko":"코드 리뷰 요청 AI 에이전트: 설정 가이드 및 모범 사례","es":"requesting-code-review: Guía de mejores prácticas para re...","fr":"requesting-code-review: Guide de bonnes pratiques pour le...","de":"requesting-code-review: Best Practices für Code-Reviews m...","pt":"requesting-code-review: Guia de Melhores Práticas para Re...","ru":"requesting-code-review: Лучшие практики для проверки кода...","ar":"requesting-code-review: دليل أفضل الممارسات لمراجعة الكود..."},"description":{"en":"Automate mandatory code reviews using git SHAs. This AI Agent skill dispatches a ''superpowers:code-reviewer'' subagent to catch issues before merging to main....","zh":"学习如何配置requesting-code-review AI代理，在任务完成、主要功能实现或合并前自动触发代码审查。利用git SHA比较和superpowers:code-reviewer子代理提升代码质量。","ja":"タスク完了時、主要機能実装後、マージ前にコードレビューを自動化するrequesting-code-review AIエージェントの設定方法。git SHA比較とsuperpowers:code-reviewerサブエージェントで品質向上。","ko":"작업 완료, 주요 기능 구현 또는 병합 전에 코드 리뷰를 자동으로 트리거하는 requesting-code-review AI 에이전트 설정 방법. git SHA 비교와 superpowers:code-reviewer 서브에이전트로 코드 품질 향상.","es":"Automatiza revisiones de código con el agente AI superpowers:code-reviewer. Aprende cuándo solicitar revisión (tras tareas, antes de merge) y cómo usar git S...","fr":"Automatisez les revues de code avec l''agent IA superpowers:code-reviewer. Apprenez quand demander une revue (après tâches, avant merge) et comment utiliser l...","de":"Automatisieren Sie Code-Reviews mit dem KI-Agenten superpowers:code-reviewer. Erfahren Sie, wann Sie Reviews anfordern (nach Tasks, vor Merge) und wie Sie gi...","pt":"Automatize revisões de código com a skill requesting-code-review. Aprenda a usar o subagente superpowers:code-reviewer para validar tarefas, features e pré-m...","ru":"Автоматизируйте проверку кода с помощью навыка requesting-code-review. Узнайте, как использовать субагента superpowers:code-reviewer для проверки задач, функ...","ar":"أتمتة مراجعات الكود باستخدام مهارة requesting-code-review. تعلم كيفية استخدام الوكيل الفرعي superpowers:code-reviewer للتحقق من المهام والميزات وقبل الدمج. ي..."},"definition":{"en":"requesting-code-review is an AI Agent skill that automates code review by dispatching a ''superpowers:code-reviewer'' subagent. It is triggered after tasks, major features, or before merging to main, using git SHAs to identify changes for review.","zh":"requesting-code-review是一个AI代理技能，其核心原则是“早审查、常审查”。它用于在子代理驱动开发中每个任务完成后、完成主要功能后或合并到主分支前，自动派遣superpowers:code-reviewer子代理来验证工作是否符合要求。","ja":"requesting-code-reviewは、「早期レビュー、頻繁なレビュー」を核心原則とするAIエージェントスキルです。サブエージェント開発における各タスク後、主要機能完了後、mainブランチへのマージ前に、superpowers:code-reviewerサブエージェントを自動派遣し、作業が要件を満たすかを検証します。","ko":"requesting-code-review는 ''일찍 검토하고, 자주 검토하라''는 핵심 원칙을 가진 AI 에이전트 스킬입니다. 서브에이전트 주도 개발에서 각 작업 완료 후, 주요 기능 완료 후, 메인 브랜치로 병합 전에 superpowers:code-reviewer 서브에이전트를 자동으로 파견하여 작업이 요구사항을 충족하는지 확인합니다.","es":"Requesting-code-review es una skill de IA que despacha el subagente superpowers:code-reviewer para revisar código automáticamente. Se usa para verificar que el trabajo cumple requisitos tras completar tareas, features mayores o antes de merge, siguiendo el principio ''revisar pronto, revisar a menudo''.","fr":"Requesting-code-review est une compétence IA qui dispatch le sous-agent superpowers:code-reviewer pour réviser le code automatiquement. Elle vérifie que le travail répond aux exigences après tâches, fonctionnalités majeures ou avant merge, suivant le principe ''revoir tôt, revoir souvent''.","de":"Requesting-code-review ist eine KI-Skill, die den Subagenten superpowers:code-reviewer zur automatischen Code-Überprüfung einsetzt. Sie stellt sicher, dass die Arbeit nach Tasks, großen Features oder vor Merge den Anforderungen entspricht, nach dem Prinzip ''früh und oft reviewen''.","pt":"Requesting-code-review é uma skill de IA que aciona o subagente superpowers:code-reviewer para analisar automaticamente alterações de código. Ela é usada para verificar se o trabalho atende aos requisitos antes de conclusões de tarefas ou merge para a main.","ru":"Requesting-code-review — это навык ИИ, который запускает субагента superpowers:code-reviewer для автоматического анализа изменений кода. Он используется для проверки соответствия работы требованиям перед завершением задач или слиянием с основной веткой.","ar":"requesting-code-review هي مهارة ذكاء اصطناعي تستدعي الوكيل الفرعي superpowers:code-reviewer لتحليل تغييرات الكود تلقائيًا. تُستخدم للتحقق من استيفاء العمل للمتطلبات قبل انتهاء المهام أو الدمج مع الفرع الرئيسي."},"features":{"en":["Dispatches the ''superpowers:code-reviewer'' subagent for automated analysis","Triggers reviews based on git SHAs retrieved via `git rev-parse`","Enforces mandatory reviews after each subagent-driven development task","Requires review before merging to the main branch","Supports optional reviews for refactoring and complex bug fixes","Operates on the core principle of ''review early, review often''"],"zh":["在子代理驱动开发中每个任务完成后自动触发审查","完成主要功能后强制进行代码质量验证","在合并到主分支前进行最终检查以防止问题扩散","使用git rev-parse获取BASE_SHA和HEAD_SHA进行精确的代码差异比较","可选的有价值审查场景：卡住时、重构前、修复复杂bug后","集成superpowers:code-reviewer子代理进行专业问题捕捉"],"ja":["サブエージェント開発の各タスク完了後にレビューを自動トリガー","主要機能完了後のコード品質検証を必須化","mainブランチへのマージ前の最終チェックで問題の波及を防止","git rev-parseでBASE_SHAとHEAD_SHAを取得し、正確な差分比較を実現","オプションの有价值的レビュー：行き詰まった時、リファクタリング前、複雑なバグ修正後","superpowers:code-reviewerサブエージェント連携による専門的な問題検出"],"ko":["서브에이전트 주도 개발에서 각 작업 완료 후 자동 검토 트리거","주요 기능 완료 후 코드 품질 검증 의무화","메인 브랜치 병합 전 최종 점검으로 문제 전파 방지","git rev-parse로 BASE_SHA와 HEAD_SHA 획득하여 정확한 코드 차이 비교","선택적 가치 있는 검토 시나리오: 막힐 때, 리팩토링 전, 복잡한 버그 수정 후","superpowers:code-reviewer 서브에이전트 통합으로 전문적인 문제 포착"],"es":["Despacha el subagente superpowers:code-reviewer para detectar issues automáticamente","Revisiones obligatorias tras cada tarea en desarrollo con subagentes","Integración CLI con obtención de git SHAs via `git rev-parse`","Revisión previa a merge a main para prevenir problemas en producción","Uso opcional para stuck situations o antes de refactorizar","Alineado con el principio DevOps ''revisar pronto, revisar a menudo''"],"fr":["Dispatch le sous-agent superpowers:code-reviewer pour détecter les problèmes automatiquement","Revues obligatoires après chaque tâche en développement avec sous-agents","Intégration CLI avec obtention des SHAs git via `git rev-parse`","Revoir avant merge sur main pour prévenir les problèmes en production","Utilisation optionnelle pour situations bloquées ou avant refactoring","Aligné sur le principe DevOps ''revoir tôt, revoir souvent''"],"de":["Dispatch des Subagenten superpowers:code-reviewer zur automatischen Issue-Erkennung","Verpflichtende Reviews nach jedem Task in Subagenten-gestützter Entwicklung","CLI-Integration mit Abruf von git SHAs über `git rev-parse`","Überprüfung vor Merge auf main zur Vermeidung von Produktionsproblemen","Optionale Nutzung bei Blockaden oder vor Refactoring","Ausgerichtet auf das DevOps-Prinzip ''früh und oft reviewen''"],"pt":["Despacha o subagente superpowers:code-reviewer para análise automatizada","Validação obrigatória após cada tarefa no desenvolvimento orientado por subagentes","Revisão obrigatória após a conclusão de uma feature maior","Verificação pré-merge para o branch main","Uso opcional para obter uma nova perspectiva quando travado","Integração com Git para capturar SHAs (ex: git rev-parse)"],"ru":["Запускает субагента superpowers:code-reviewer для автоматического анализа","Обязательная проверка после каждой задачи в разработке на основе субагентов","Обязательный обзор после завершения крупной функции","Проверка перед слиянием с основной веткой","Опциональное использование для нового взгляда при затруднениях","Интеграция с Git для получения SHA (например, git rev-parse)"],"ar":["ترسل الوكيل الفرعي superpowers:code-reviewer للتحليل الآلي","تحقق إلزامي بعد كل مهمة في التطوير القائم على وكلاء فرعيين","مراجعة إلزامية بعد إكمال ميزة رئيسية","فحص قبل الدمج مع الفرع الرئيسي main","استخدام اختياري للحصول على منظور جديد عند التعثر","تكامل مع Git لاسترداد SHAs (مثل: git rev-parse)"]},"keywords":{"en":["how to use requesting-code-review","what is requesting-code-review","requesting-code-review git SHA","requesting-code-review vs manual code review","requesting-code-review setup guide","superpowers:code-reviewer subagent","automate code review AI agent","requesting-code-review install","subagent-driven development workflow","code review before merge main"],"zh":["requesting-code-review AI代理","代码审查自动化","git SHA代码比较","子代理驱动开发","合并前检查","superpowers code-reviewer","AI代理代码审查","开发工作流优化"],"ja":["requesting-code-review AIエージェント","コードレビュー自動化","git SHA コード比較","サブエージェント開発","マージ前チェック","superpowers code-reviewer","AIエージェント コードレビュー","開発ワークフロー最適化"],"ko":["requesting-code-review AI 에이전트","코드 리뷰 자동화","git SHA 코드 비교","서브에이전트 주도 개발","병합 전 점검","superpowers code-reviewer","AI 에이전트 코드 리뷰","개발 워크플로우 최적화"],"es":["automatizar revisiones de código IA","superpowers code reviewer subagent","cuándo solicitar code review","git SHA code review automation","code review antes de merge","mejores prácticas revisiones código","CLI integración code review","requesting code review skill","agentes AI para desarrolladores"],"fr":["automatiser revues de code IA","sous-agent superpowers code reviewer","quand demander revue code","automatisation review code git SHA","review code avant merge","bonnes pratiques revue code","intégration CLI revue code","compétence requesting code review","outils IA pour développeurs"],"de":["automatisierte Code-Reviews KI","superpowers code reviewer Subagent","wann Code-Review anfordern","git SHA Code-Review Automatisierung","Code-Review vor Merge","Best Practices Code-Reviews","CLI Integration Code-Review","requesting code review Skill","KI-Tools für Entwickler"],"pt":["requesting-code-review agente ia","automação revisão código","superpowers code reviewer","git sha code review","melhores práticas revisão código","validação pré-merge ia","subagente desenvolvimento","code review automatizado"],"ru":["requesting-code-review ИИ Агенты","автоматизация проверки кода","superpowers code reviewer","git sha проверка кода","лучшие практики code review","ИИ проверка перед слиянием","субагент разработка","автоматизированный code review"],"ar":["requesting-code-review أدوات الذكاء الاصطناعي","أتمتة مراجعة الكود","superpowers code reviewer","git sha مراجعة الكود","أفضل ممارسات مراجعة الكود","الذكاء الاصطناعي للتحقق قبل الدمج","وكيل فرعي للتطوير","مراجعة كود تلقائية"]}},"agentAnalysis":{"suitability":{"en":"Essential for development-focused AI Agents that implement features and require quality assurance before deployment.","zh":"对于专注于开发的AI代理来说至关重要，这些代理实现功能并在部署前需要质量保证。","ja":"開発に焦点を当てたAIエージェントにとって不可欠であり、機能を実装し、デプロイ前に品質保証を必要とします。","ko":"개발에 중점을 둔 AI 에이전트에게 필수적이며, 기능을 구현하고 배포 전에 품질 보증이 필요합니다.","es":"Esencial para Agentes de IA centrados en el desarrollo que implementan características y requieren garantía de calidad antes del despliegue.","fr":"Essentiel pour les Agents IA axés sur le développement qui implémentent des fonctionnalités et nécessitent une assurance qualité avant le déploiement.","de":"Unverzichtbar für entwicklungsorientierte KI-Agenten, die Funktionen implementieren und vor dem Einsatz eine Qualitätssicherung benötigen.","pt":"Essencial para Agentes de IA focados em desenvolvimento que implementam funcionalidades e requerem garantia de qualidade antes da implementação.","ru":"Необходим для AI Agent, ориентированных на разработку, которые реализуют функции и требуют проверки качества перед развертыванием.","ar":"أساسي لوكلاء الذكاء الاصطناعي المركزة على التطوير والتي تنفذ الميزات وتتطلب ضمان الجودة قبل النشر."},"recommendation":{"en":"Dispatches a specialized code-reviewer subagent to catch critical issues before they cascade, ensuring work meets requirements through systematic git SHA-based review cycles. This creates a robust quality gate for subagent-driven development workflows.","zh":"派遣专门的代码审查子代理，以在关键问题扩散之前捕获它们，通过基于git SHA的系统性审查周期确保工作符合要求。这为子代理驱动的开发工作流程创建了强大的质量门。","ja":"専門的なコードレビュー担当のサブエージェントを派遣し、重大な問題が連鎖する前に捕捉し、git SHAに基づく体系的なレビューサイクルを通じて作業が要件を満たしていることを確認します。これにより、サブエージェント駆動の開発ワークフローに対する堅牢な品質ゲートが形成されます。","ko":"전문화된 코드 리뷰어 서브 에이전트를 파견하여 중요한 문제가 확대되기 전에 포착하고, 체계적인 git SHA 기반 리뷰 주기를 통해 작업이 요구 사항을 충족하는지 확인합니다. 이는 서브 에이전트 주도 개발 워크플로우를 위한 강력한 품질 게이트를 생성합니다.","es":"Despacha un subagente especializado en revisión de código para detectar problemas críticos antes de que se propaguen, asegurando que el trabajo cumpla con los requisitos mediante ciclos sistemáticos de revisión basados en SHA de git. Esto crea una puerta de calidad robusta para flujos de trabajo de desarrollo impulsados por subagentes.","fr":"Dépatche un sous-agent spécialisé dans la revue de code pour détecter les problèmes critiques avant qu''ils ne se propagent, garantissant que le travail répond aux exigences grâce à des cycles systématiques de revue basés sur SHA git. Cela crée une barrière de qualité robuste pour les flux de travail de développement pilotés par des sous-agents.","de":"Sendet einen spezialisierten Code-Reviewer-Subagenten aus, um kritische Probleme zu erkennen, bevor sie eskalieren, und stellt sicher, dass die Arbeit die Anforderungen durch systematische, auf Git-SHA basierende Review-Zyklen erfüllt. Dies schafft ein robustes Qualitätsgate für subagentengesteuerte Entwicklungs-Workflows.","pt":"Despacha um subagente especializado em revisão de código para detetar problemas críticos antes que se propaguem, garantindo que o trabalho cumpre os requisitos através de ciclos sistemáticos de revisão baseados em git SHA. Isto cria um portão de qualidade robusto para fluxos de trabalho de desenvolvimento orientados por subagentes.","ru":"Отправляет специализированного сабагента для проверки кода, чтобы выявить критические проблемы до их эскалации, обеспечивая соответствие работы требованиям посредством систематических циклов проверки на основе git SHA. Это создает надежный контроль качества для рабочих процессов разработки, управляемых сабагентами.","ar":"يرسل وكيلًا فرعيًا متخصصًا لمراجعة التعليمات البرمجية للكشف عن المشكلات الحرجة قبل أن تتفاقم، مما يضمن استيفاء العمل للمتطلبات من خلال دورات مراجعة منهجية تعتمد على SHA في git. وهذا ينشئ بوابة جودة قوية لسير عمل التطوير التي تقودها الوكلاء الفرعيين."},"useCases":{"en":["Verifying task completion in subagent-driven development","Validating major feature implementation before merge","Establishing baseline checks before refactoring operations"],"zh":["在子代理驱动的开发中验证任务完成情况","在合并前验证主要功能实现","在重构操作之前建立基线检查"],"ja":["サブエージェント駆動開発におけるタスク完了の検証","マージ前の主要機能実装の検証","リファクタリング作業前のベースラインチェックの確立"],"ko":["서브 에이전트 주도 개발에서 작업 완료 검증","병합 전 주요 기능 구현 검증","리팩토링 작업 전 기준 검사 수립"],"es":["Verificación de la finalización de tareas en el desarrollo impulsado por subagentes","Validación de la implementación de características principales antes de la fusión","Establecimiento de comprobaciones de referencia antes de operaciones de refactorización"],"fr":["Vérification de l''achèvement des tâches dans le développement piloté par des sous-agents","Validation de l''implémentation des fonctionnalités majeures avant la fusion","Établissement de contrôles de base avant les opérations de refactorisation"],"de":["Überprüfung der Aufgabenabschlüsse in subagentengesteuerter Entwicklung","Validierung der Implementierung von Hauptfunktionen vor dem Merge","Einrichtung von Basisprüfungen vor Refactoring-Operationen"],"pt":["Verificação da conclusão de tarefas no desenvolvimento orientado por subagentes","Validação da implementação de funcionalidades principais antes do merge","Estabelecimento de verificações de base antes de operações de refatoração"],"ru":["Проверка завершения задач в разработке, управляемой сабагентами","Проверка реализации основных функций перед слиянием","Установка базовых проверок перед операциями рефакторинга"],"ar":["التحقق من إكمال المهمة في التطوير الذي تقوده الوكلاء الفرعيين","التحقق من صحة تنفيذ الميزات الرئيسية قبل الدمج","إنشاء فحوصات أساسية قبل عمليات إعادة الهيكلة"]},"limitations":{"en":["Requires git repository access","Depends on code-reviewer subagent availability","Needs proper SHA identification for diff analysis"],"zh":["需要git仓库访问权限","依赖于代码审查子代理的可用性","需要正确的SHA标识以进行差异分析"],"ja":["gitリポジトリへのアクセスが必要","コードレビュー担当サブエージェントの可用性に依存","差分分析に適切なSHA識別が必要"],"ko":["git 저장소 접근 권한 필요","코드 리뷰어 서브 에이전트 가용성에 의존","차이 분석을 위한 적절한 SHA 식별 필요"],"es":["Requiere acceso al repositorio git","Depende de la disponibilidad del subagente revisor de código","Necesita una identificación SHA adecuada para el análisis de diferencias"],"fr":["Nécessite un accès au dépôt git","Dépend de la disponibilité du sous-agent réviseur de code","Nécessite une identification SHA appropriée pour l''analyse des différences"],"de":["Erfordert Zugriff auf das Git-Repository","Hängt von der Verfügbarkeit des Code-Reviewer-Subagenten ab","Benötigt eine ordnungsgemäße SHA-Identifikation für die Diff-Analyse"],"pt":["Requer acesso ao repositório git","Depende da disponibilidade do subagente revisor de código","Necessita de identificação adequada do SHA para análise de diff"],"ru":["Требует доступ к репозиторию git","Зависит от доступности сабагента для проверки кода","Требует правильной идентификации SHA для анализа различий (diff)"],"ar":["يتطلب الوصول إلى مستودع git","يعتمد على توفر الوكيل الفرعي لمراجعة التعليمات البرمجية","يحتاج إلى تحديد SHA صحيح لتحليل الاختلافات (diff)"]},"version":4},"contentHash":"2da31af22a58938ab78f3ee6d5b4687fcca062b923b646459eb52ba72117ef97","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":68}');
DELETE FROM skills_fts WHERE id = 'obra/superpowers/requesting-code-review';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/requesting-code-review', 'requesting-code-review', 'obra', 'superpowers', 'official', 'requesting-code-review obra superpowers official The requesting-code-review skill automates the process of dispatching a code-reviewer subagent to verify work meets requirements. It is designed for developers and teams practicing subagent-driven development to ensure code quality before merging. requesting-code-review是一个AI代理技能，用于在开发关键节点自动派遣代码审查子代理。它通过在git中获取BASE_SHA和HEAD_SHA来比较代码变更，确保工作符合要求并在合并前发现问题。 requesting-code-reviewは、開発の重要なポイントでコードレビューサブエージェントを自動的に派遣するAIエージェントスキルです。gitでBASE_SHAとHEAD_SHAを取得して変更を比較し、マージ前に問題を検出します。 requesting-code-review는 개발의 주요 지점에서 코드 리뷰 서브에이전트를 자동으로 파견하는 AI 에이전트 스킬입니다. git에서 BASE_SHA와 HEAD_SHA를 가져와 변경 사항을 비교하고, 병합 전에 문제를 발견합니다. La skill requesting-code-review automatiza revisiones de código mediante el subagente superpowers:code-reviewer. Está diseñada para verificar que el trabajo cumple los requisitos tras completar tareas, implementar features o antes de mergear a main, integrando comandos CLI con git SHAs. La compétence requesting-code-review automatise les revues de code via le sous-agent superpowers:code-reviewer. Elle vérifie que le travail répond aux exigences après tâches, implémentation de fonctionnalités ou avant merge sur main, en intégrant des commandes CLI avec les SHAs git. Die Skill requesting-code-review automatisiert Code-Reviews über den Subagenten superpowers:code-reviewer. Sie überprüft, ob die Arbeit nach Tasks, Feature-Implementierung oder vor Merge auf main den Anforderungen entspricht und integriert CLI-Befehle mit git SHAs. A skill requesting-code-review automatiza a garantia de qualidade do código ao despachar um subagente revisor. É projetada para validação obrigatória pós-tarefa, pós-feature e pré-merge para detectar issues cedo. Навык requesting-code-review автоматизирует обеспечение качества кода, запуская субагента-рецензента. Предназначен для обязательной проверки после задач, функций и перед слиянием для раннего обнаружения проблем. مهارة requesting-code-review تؤتمت ضمان جودة الكود عن طريق إرسال وكيل فرعي للمراجعة. مصممة للتحقق الإلزامي بعد المهام والميزات وقبل الدمج لاكتشاف المشكلات مبكرًا. how to use requesting-code-review what is requesting-code-review requesting-code-review git SHA requesting-code-review vs manual code review requesting-code-review setup guide superpowers:code-reviewer subagent automate code review AI agent requesting-code-review install subagent-driven development workflow code review before merge main requesting-code-review AI代理 代码审查自动化 git SHA代码比较 子代理驱动开发 合并前检查 superpowers code-reviewer AI代理代码审查 开发工作流优化 Dispatches the ''superpowers:code-reviewer'' subagent for automated analysis Triggers reviews based on git SHAs retrieved via `git rev-parse` Enforces mandatory reviews after each subagent-driven development task Requires review before merging to the main branch Supports optional reviews for refactoring and complex bug fixes Operates on the core principle of ''review early, review often'' requesting-code-review is an AI Agent skill that automates code review by dispatching a ''superpowers:code-reviewer'' subagent. It is triggered after tasks, major features, or before merging to main, using git SHAs to identify changes for review.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/clickhouse-io', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'clickhouse-io', 61988, 7678, 68, '2026-03-06T03:39:20Z', '2026-03-06T03:48:30.421Z', 'bc0d9351ae909eaa725b57ee5c4928274ed94e0b55e0fef4076cbe2844ae8a7b', '{"id":"affaan-m/everything-claude-code/clickhouse-io","name":"clickhouse-io","description":{"en":"The clickhouse-io skill provides ClickHouse database patterns, query optimization, and data engineering best practices for high-performance analytical workloads, benefiting developers and data engineers.","zh":"ClickHouse数据库模式、查询优化和数据工程最佳实践，用于高性能分析工作负载","ja":"ClickHouseデータベースパターン、クエリ最適化、データエンジニアリングのベストプラクティス","ko":"ClickHouse 데이터베이스 패턴, 쿼리 최적화, 데이터 엔지니어링 최적화 방법","es":"ClickHouse es una base de datos de código abierto diseñada para cargas de trabajo analíticas de alto rendimiento. Ofrece patrones de diseño de esquemas de tabla, optimización de consultas y mejores prácticas para la ingeniería de datos.","fr":"ClickHouse est une base de données open source conçue pour les charges de travail analytiques à haute performance. Elle propose des modèles de conception de schémas de table, d''optimisation de requêtes et de meilleures pratiques pour l''ingénierie de données.","de":"ClickHouse ist eine Open-Source-Datenbank, die für hochleistungsfähige analytische Workloads konzipiert ist. Sie bietet Entwurfsmuster für Tabellenschemata, Abfrageoptimierung und Best Practices für Datenengineering.","pt":"Skill técnico para padrões analíticos no ClickHouse, otimizando esquemas MergeTree, consultas de agregação, junções e ingestão de dados em lote com Kafka para cargas de trabalho de alto desempenho.","ru":"Технический навык для аналитических шаблонов в ClickHouse, оптимизирующий схемы MergeTree, агрегационные запросы, соединения и пакетный прием данных с Kafka для высокопроизводительных рабочих нагрузок.","ar":"مهارة تقنية لأنماط التحليل في ClickHouse، تحسن أنماط MergeTree، واستعلامات التجميع، والوصلات واستيعاب البيانات المجمعة باستخدام Kafka لأحمال العمل عالية الأداء."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"clickhouse-io","description":"ClickHouse database patterns, query optimization, analytics, and data engineering best practices for high-performance analytical workloads.","bodyPreview":"# ClickHouse Analytics Patterns\n\nClickHouse-specific patterns for high-performance analytics and data engineering.\n\n## When to Activate\n\n- Designing ClickHouse table schemas (MergeTree engine selection)\n- Writing analytical queries (aggregations, window functions, joins)\n- Optimizing query performance (partition pruning, projections, materialized views)\n- Ingesting large volumes of data (batch inserts, Kafka integration)\n- Migrating from PostgreSQL/MySQL to ClickHouse for analytics\n- Implementin","body":"# ClickHouse Analytics Patterns\n\nClickHouse-specific patterns for high-performance analytics and data engineering.\n\n## When to Activate\n\n- Designing ClickHouse table schemas (MergeTree engine selection)\n- Writing analytical queries (aggregations, window functions, joins)\n- Optimizing query performance (partition pruning, projections, materialized views)\n- Ingesting large volumes of data (batch inserts, Kafka integration)\n- Migrating from PostgreSQL/MySQL to ClickHouse for analytics\n- Implementing real-time dashboards or time-series analytics\n\n## Overview\n\nClickHouse is a column-oriented database management system (DBMS) for online analytical processing (OLAP). It''s optimized for fast analytical queries on large datasets.\n\n**Key Features:**\n- Column-oriented storage\n- Data compression\n- Parallel query execution\n- Distributed queries\n- Real-time analytics\n\n## Table Design Patterns\n\n### MergeTree Engine (Most Common)\n\n```sql\nCREATE TABLE markets_analytics (\n    date Date,\n    market_id String,\n    market_name String,\n    volume UInt64,\n    trades UInt32,\n    unique_traders UInt32,\n    avg_trade_size Float64,\n    created_at DateTime\n) ENGINE = MergeTree()\nPARTITION BY toYYYYMM(date)\nORDER BY (date, market_id)\nSETTINGS index_granularity = 8192;\n```\n\n### ReplacingMergeTree (Deduplication)\n\n```sql\n-- For data that may have duplicates (e.g., from multiple sources)\nCREATE TABLE user_events (\n    event_id String,\n    user_id String,\n    event_type String,\n    timestamp DateTime,\n    properties String\n) ENGINE = ReplacingMergeTree()\nPARTITION BY toYYYYMM(timestamp)\nORDER BY (user_id, event_id, timestamp)\nPRIMARY KEY (user_id, event_id);\n```\n\n### AggregatingMergeTree (Pre-aggregation)\n\n```sql\n-- For maintaining aggregated metrics\nCREATE TABLE market_stats_hourly (\n    hour DateTime,\n    market_id String,\n    total_volume AggregateFunction(sum, UInt64),\n    total_trades AggregateFunction(count, UInt32),\n    unique_users AggregateFunction(uniq, String)\n) ENGINE = AggregatingMergeTree()\nPARTITION BY toYYYYMM(hour)\nORDER BY (hour, market_id);\n\n-- Query aggregated data\nSELECT\n    hour,\n    market_id,\n    sumMerge(total_volume) AS volume,\n    countMerge(total_trades) AS trades,\n    uniqMerge(unique_users) AS users\nFROM market_stats_hourly\nWHERE hour >= toStartOfHour(now() - INTERVAL 24 HOUR)\nGROUP BY hour, market_id\nORDER BY hour DESC;\n```\n\n## Query Optimization Patterns\n\n### Efficient Filtering\n\n```sql\n-- ✅ GOOD: Use indexed columns first\nSELECT *\nFROM markets_analytics\nWHERE date >= ''2025-01-01''\n  AND market_id = ''market-123''\n  AND volume > 1000\nORDER BY date DESC\nLIMIT 100;\n\n-- ❌ BAD: Filter on non-indexed columns first\nSELECT *\nFROM markets_analytics\nWHERE volume > 1000\n  AND market_name LIKE ''%election%''\n  AND date >= ''2025-01-01'';\n```\n\n### Aggregations\n\n```sql\n-- ✅ GOOD: Use ClickHouse-specific aggregation functions\nSELECT\n    toStartOfDay(created_at) AS day,\n    market_id,\n    sum(volume) AS total_volume,\n    count() AS total_trades,\n    uniq(trader_id) AS unique_traders,\n    avg(trade_size) AS avg_size\nFROM trades\nWHERE created_at >= today() - INTERVAL 7 DAY\nGROUP BY day, market_id\nORDER BY day DESC, total_volume DESC;\n\n-- ✅ Use quantile for percentiles (more efficient than percentile)\nSELECT\n    quantile(0.50)(trade_size) AS median,\n    quantile(0.95)(trade_size) AS p95,\n    quantile(0.99)(trade_size) AS p99\nFROM trades\nWHERE created_at >= now() - INTERVAL 1 HOUR;\n```\n\n### Window Functions\n\n```sql\n-- Calculate running totals\nSELECT\n    date,\n    market_id,\n    volume,\n    sum(volume) OVER (\n        PARTITION BY market_id\n        ORDER BY date\n        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n    ) AS cumulative_volume\nFROM markets_analytics\nWHERE date >= today() - INTERVAL 30 DAY\nORDER BY market_id, date;\n```\n\n## Data Insertion Patterns\n\n### Bulk Insert (Recommended)\n\n```typescript\nimport { ClickHouse } from ''clickhouse''\n\nconst clickhouse = new ClickHouse({\n  url: process.env.CLICKHOUSE_URL,\n  port: 8123,\n  basicAuth: {\n    username: process.env.CLICKHOUSE_USER,\n    password: process.env.CLICKHOUSE_PASSWORD\n  }\n})\n\n// ✅ Batch insert (efficient)\nasync function bulkInsertTrades(trades: Trade[]) {\n  const values = trades.map(trade => `(\n    ''${trade.id}'',\n    ''${trade.market_id}'',\n    ''${trade.user_id}'',\n    ${trade.amount},\n    ''${trade.timestamp.toISOString()}''\n  )`).join('','')\n\n  await clickhouse.query(`\n    INSERT INTO trades (id, market_id, user_id, amount, timestamp)\n    VALUES ${values}\n  `).toPromise()\n}\n\n// ❌ Individual inserts (slow)\nasync function insertTrade(trade: Trade) {\n  // Don''t do this in a loop!\n  await clickhouse.query(`\n    INSERT INTO trades VALUES (''${trade.id}'', ...)\n  `).toPromise()\n}\n```\n\n### Streaming Insert\n\n```typescript\n// For continuous data ingestion\nimport { createWriteStream } from ''fs''\nimport { pipeline } from ''stream/promises''\n\nasync function streamInserts() {\n  const stream = clickhouse.insert(''trades'').stream()\n\n  for await (const batch of dataSource) {\n    stream.write(batch)\n  }\n\n  await stream.end()\n}\n```\n\n## Materialized Views\n\n### Real-time Aggregations\n\n```sql\n-- Create materialized view for hourly stats\nCREATE MATERIALIZED VIEW market_stats_hourly_mv\nTO market_stats_hourly\nAS SELECT\n    toStartOfHour(timestamp) AS hour,\n    market_id,\n    sumState(amount) AS total_volume,\n    countState() AS total_trades,\n    uniqState(user_id) AS unique_users\nFROM trades\nGROUP BY hour, market_id;\n\n-- Query the materialized view\nSELECT\n    hour,\n    market_id,\n    sumMerge(total_volume) AS volume,\n    countMerge(total_trades) AS trades,\n    uniqMerge(unique_users) AS users\nFROM market_stats_hourly\nWHERE hour >= now() - INTERVAL 24 HOUR\nGROUP BY hour, market_id;\n```\n\n## Performance Monitoring\n\n### Query Performance\n\n```sql\n-- Check slow queries\nSELECT\n    query_id,\n    user,\n    query,\n    query_duration_ms,\n    read_rows,\n    read_bytes,\n    memory_usage\nFROM system.query_log\nWHERE type = ''QueryFinish''\n  AND query_duration_ms > 1000\n  AND event_time >= now() - INTERVAL 1 HOUR\nORDER BY query_duration_ms DESC\nLIMIT 10;\n```\n\n### Table Statistics\n\n```sql\n-- Check table sizes\nSELECT\n    database,\n    table,\n    formatReadableSize(sum(bytes)) AS size,\n    sum(rows) AS rows,\n    max(modification_time) AS latest_modification\nFROM system.parts\nWHERE active\nGROUP BY database, table\nORDER BY sum(bytes) DESC;\n```\n\n## Common Analytics Queries\n\n### Time Series Analysis\n\n```sql\n-- Daily active users\nSELECT\n    toDate(timestamp) AS date,\n    uniq(user_id) AS daily_active_users\nFROM events\nWHERE timestamp >= today() - INTERVAL 30 DAY\nGROUP BY date\nORDER BY date;\n\n-- Retention analysis\nSELECT\n    signup_date,\n    countIf(days_since_signup = 0) AS day_0,\n    countIf(days_since_signup = 1) AS day_1,\n    countIf(days_since_signup = 7) AS day_7,\n    countIf(days_since_signup = 30) AS day_30\nFROM (\n    SELECT\n        user_id,\n        min(toDate(timestamp)) AS signup_date,\n        toDate(timestamp) AS activity_date,\n        dateDiff(''day'', signup_date, activity_date) AS days_since_signup\n    FROM events\n    GROUP BY user_id, activity_date\n)\nGROUP BY signup_date\nORDER BY signup_date DESC;\n```\n\n### Funnel Analysis\n\n```sql\n-- Conversion funnel\nSELECT\n    countIf(step = ''viewed_market'') AS viewed,\n    countIf(step = ''clicked_trade'') AS clicked,\n    countIf(step = ''completed_trade'') AS completed,\n    round(clicked / viewed * 100, 2) AS view_to_click_rate,\n    round(completed / clicked * 100, 2) AS click_to_completion_rate\nFROM (\n    SELECT\n        user_id,\n        session_id,\n        event_type AS step\n    FROM events\n    WHERE event_date = today()\n)\nGROUP BY session_id;\n```\n\n### Cohort Analysis\n\n```sql\n-- User cohorts by signup month\nSELECT\n    toStartOfMonth(signup_date) AS cohort,\n    toStartOfMonth(activity_date) AS month,\n    dateDiff(''month'', cohort, month) AS months_since_signup,\n    count(DISTINCT user_id) AS active_users\nFROM (\n    SELECT\n        user_id,\n        min(toDate(timestamp)) OVER (PARTITION BY user_id) AS signup_date,\n        toDate(timestamp) AS activity_date\n    FROM events\n)\nGROUP BY cohort, month, months_since_signup\nORDER BY cohort, months_since_signup;\n```\n\n## Data Pipeline Patterns\n\n### ETL Pattern\n\n```typescript\n// Extract, Transform, Load\nasync function etlPipeline() {\n  // 1. Extract from source\n  const rawData = await extractFromPostgres()\n\n  // 2. Transform\n  const transformed = rawData.map(row => ({\n    date: new Date(row.created_at).toISOString().split(''T'')[0],\n    market_id: row.market_slug,\n    volume: parseFloat(row.total_volume),\n    trades: parseInt(row.trade_count)\n  }))\n\n  // 3. Load to ClickHouse\n  await bulkInsertToClickHouse(transformed)\n}\n\n// Run periodically\nsetInterval(etlPipeline, 60 * 60 * 1000)  // Every hour\n```\n\n### Change Data Capture (CDC)\n\n```typescript\n// Listen to PostgreSQL changes and sync to ClickHouse\nimport { Client } from ''pg''\n\nconst pgClient = new Client({ connectionString: process.env.DATABASE_URL })\n\npgClient.query(''LISTEN market_updates'')\n\npgClient.on(''notification'', async (msg) => {\n  const update = JSON.parse(msg.payload)\n\n  await clickhouse.insert(''market_updates'', [\n    {\n      market_id: update.id,\n      event_type: update.operation,  // INSERT, UPDATE, DELETE\n      timestamp: new Date(),\n      data: JSON.stringify(update.new_data)\n    }\n  ])\n})\n```\n\n## Best Practices\n\n### 1. Partitioning Strategy\n- Partition by time (usually month or day)\n- Avoid too many partitions (performance impact)\n- Use DATE type for partition key\n\n### 2. Ordering Key\n- Put most frequently filtered columns first\n- Consider cardinality (high cardinality first)\n- Order impacts compression\n\n### 3. Data Types\n- Use smallest appropriate type (UInt32 vs UInt64)\n- Use LowCardinality for repeated strings\n- Use Enum for categorical data\n\n### 4. Avoid\n- SELECT * (specify columns)\n- FINAL (merge data before query instead)\n- Too many JOINs (denormalize for analytics)\n- Small frequent inserts (batch instead)\n\n### 5. Monitoring\n- Track query performance\n- Monitor disk usage\n- Check merge operations\n- Review slow query log\n\n**Remember**: ClickHouse excels at analytical workloads. Design tables for your query patterns, batch inserts, and leverage materialized views for real-time aggregations.\n"},"category":"official","lastSynced":"2026-03-06T03:48:30.421Z","seo":{"title":{"en":"clickhouse-io: High-Performance Analytics Setup Guide | A...","zh":"ClickHouse 性能优化指南：提高分析工作负载","ja":"ClickHouse 最適化セットアップガイド：分析ワークロードのパフォーマンス向上","ko":"ClickHouse 성능 최적화 가이드: 분석 워크로드 최적화","es":"Guía de configuración de ClickHouse para cargas de trabaj...","fr":"Guide de configuration de ClickHouse pour les charges de ...","de":"Konfigurationsleitfaden für ClickHouse bei hochleistungsf...","pt":"ClickHouse-io: Guia de Otimização de Consultas e Padrões ...","ru":"ClickHouse-io: Руководство по оптимизации запросов и анал...","ar":"ClickHouse-io: دليل تحسين الاستعلامات وأنماط التحليل"},"description":{"en":"Unlock ClickHouse''s full potential with expert patterns and query optimization techniques. Get started with our AI agent skill today and boost your analytica...","zh":"了解ClickHouse数据库模式、查询优化和数据工程最佳实践，实现高性能分析工作负载","ja":"ClickHouseデータベースパターン、クエリ最適化、データエンジニアリングのベストプラクティスを学び、高パフォーマンスの分析ワークロードを実現","ko":"ClickHouse 데이터베이스 패턴, 쿼리 최적화, 데이터 엔지니어링 최적화 방법을 알아보세요","es":"Aprende a optimizar tus consultas y mejorar el rendimiento de tus cargas de trabajo analíticas con ClickHouse, la base de datos de código abierto para la ana...","fr":"Découvrez comment optimiser vos requêtes et améliorer les performances de vos charges de travail analytiques avec ClickHouse, la base de données open source ...","de":"Erfahren Sie, wie Sie Ihre Abfragen optimieren und die Leistung Ihrer analytischen Workloads mit ClickHouse, der Open-Source-Datenbank für die Analyse, verbe...","pt":"AI Agent ClickHouse-io para otimização de consultas, esquemas MergeTree, funções de janela e engenharia de dados analíticos. Aumente performance com Claude C...","ru":"ИИ агент ClickHouse-io для оптимизации запросов, схем MergeTree, оконных функций и аналитической инженерии данных. Повысьте производительность с Claude Code ...","ar":"أداة الذكاء الاصطناعي ClickHouse-io لتحسين الاستعلامات، وأنماط MergeTree، ودوال النوافذ وهندسة البيانات التحليلية. عزز الأداء باستخدام Claude Code و MCP."},"definition":{"en":"clickhouse-io is a skill that provides expert guidance on ClickHouse database patterns, query optimization, and data engineering for high-performance analytics and data engineering workloads.","zh":"ClickHouse是一种高性能的分析数据库，支持快速的数据查询和分析","ja":"ClickHouseは、高性能の分析データベースで、高速なデータクエリと分析をサポート","ko":"ClickHouse는 고성능 분석 데이터베이스로 빠른 데이터 쿼리와 분석을 지원","es":"ClickHouse es una base de datos de código abierto para la analítica que ofrece patrones de diseño y optimización de consultas para cargas de trabajo analíticas de alto rendimiento","fr":"ClickHouse est une base de données open source pour l''analyse qui propose des modèles de conception et d''optimisation de requêtes pour les charges de travail analytiques à haute performance","de":"ClickHouse ist eine Open-Source-Datenbank für die Analyse, die Entwurfsmuster und Abfrageoptimierung für hochleistungsfähige analytische Workloads bietet","pt":"ClickHouse-io é um AI Agent para desenvolvedores que trabalham com ClickHouse. Oferece melhores práticas em esquemas de tabela, otimização de consultas analíticas, funções de janela, migração de SGBDs relacionais e integração com Kafka para ingestão de dados.","ru":"ClickHouse-io — это ИИ агент для разработчиков, работающих с ClickHouse. Предоставляет лучшие практики по схемам таблиц, оптимизации аналитических запросов, оконным функциям, миграции с реляционных СУБД и интеграции с Kafka для приема данных.","ar":"ClickHouse-io هو أداة ذكاء اصطناعي للمطورين العاملين على ClickHouse. تقدم أفضل الممارسات لأنماط الجداول، وتحسين استعلامات التحليل، ودوال النوافذ، والهجرة من قواعد البيانات العلائقية والتكامل مع Kafka لاستيعاب البيانات."},"features":{"en":["Designs ClickHouse table schemas using MergeTree engine selection","Writes optimized analytical queries with aggregations, window functions, and joins","Optimizes query performance using partition pruning, projections, and materialized views","Ingests large volumes of data using batch inserts and Kafka integration","Migrates from PostgreSQL/MySQL to ClickHouse for analytics"],"zh":["ClickHouse表模式设计","MergeTree引擎选择","查询优化（聚合、窗口函数、连接）","数据工程最佳实践","批量插入和Kafka集成"],"ja":["ClickHouseテーブルスキーマ設計","MergeTreeエンジンの選択","クエリ最適化（集約、ウィンドウ関数、ジョイン）","データエンジニアリングのベストプラクティス","バッチ挿入とKafka統合"],"ko":["ClickHouse 테이블 스키마 설계","MergeTree 엔진 선택","쿼리 최적화（집계, 윈도우 함수, 조인）","데이터 엔지니어링 최적화 방법","배치 삽입과 Kafka 통합"],"es":["Diseño de esquemas de tabla con MergeTree","Optimización de consultas con agregaciones y funciones de ventana","Mejores prácticas para la ingeniería de datos y la analítica","Integración con Kafka para la ingesta de grandes volúmenes de datos","Migración desde PostgreSQL/MySQL a ClickHouse para la analítica"],"fr":["Conception de schémas de table avec MergeTree","Optimisation de requêtes avec agrégations et fonctions de fenêtrage","Meilleures pratiques pour l''ingénierie de données et l''analyse","Intégration avec Kafka pour l''ingestion de grands volumes de données","Migration de PostgreSQL/MySQL à ClickHouse pour l''analyse"],"de":["Entwurf von Tabellenschemata mit MergeTree","Abfrageoptimierung mit Aggregationen und Fensterfunktionen","Best Practices für Datenengineering und Analyse","Integration mit Kafka für die Aufnahme großer Datenmengen","Migration von PostgreSQL/MySQL zu ClickHouse für die Analyse"],"pt":["Otimização de esquemas de tabela com seleção de engines MergeTree","Otimização de performance de consultas com poda de partição e projeções","Implementação de funções de agregação e janela para consultas analíticas","Padrões de ingestão de dados em lote e integração com Kafka","Guias de migração de PostgreSQL/MySQL para cargas analíticas no ClickHouse","Criação de materialized views para pré-agregação de dados"],"ru":["Оптимизация схем таблиц с выбором движков MergeTree","Оптимизация производительности запросов с обрезкой разделов и проекциями","Реализация агрегационных и оконных функций для аналитических запросов","Шаблоны пакетного приема данных и интеграция с Kafka","Руководства по миграции с PostgreSQL/MySQL для аналитических нагрузок в ClickHouse","Создание материализованных представлений для предварительной агрегации данных"],"ar":["تحسين أنماط الجداول مع اختيار محركات MergeTree","تحسين أداء الاستعلامات مع تقليل الأقسام والإسقاطات","تنفيذ دوال التجميع والنوافذ لاستعلامات التحليل","أنماط استيعاب البيانات المجمعة والتكامل مع Kafka","أدلة الهجرة من PostgreSQL/MySQL لأحمال التحليل على ClickHouse","إنشاء وجهات مادية للتجميع المسبق للبيانات"]},"keywords":{"en":["how to use clickhouse-io","clickhouse-io vs PostgreSQL","clickhouse-io setup guide","what is clickhouse-io","clickhouse-io alternative to MySQL","clickhouse-io install on Ubuntu","clickhouse-io query optimization techniques","clickhouse-io data engineering best practices"],"zh":["ClickHouse","分析数据库","高性能查询","数据工程","MergeTree","Kafka集成","AIエージェント","ClickHouse优化"],"ja":["ClickHouse","分析データベース","高性能クエリ","データエンジニアリング","MergeTree","Kafka統合","AIエージェント","ClickHouse最適化"],"ko":["ClickHouse","분석 데이터베이스","고성능 쿼리","데이터 엔지니어링","MergeTree","Kafka 통합","AI 에이전트","ClickHouse 최적화"],"es":["ClickHouse","base de datos para la analítica","patrones de diseño de esquemas de tabla","optimización de consultas","ingeniería de datos","cargas de trabajo analíticas de alto rendimiento","Herramientas de AI para desarrolladores","Agentes de IA para la analítica"],"fr":["ClickHouse","base de données pour l''analyse","modèles de conception de schémas de table","optimisation de requêtes","ingénierie de données","charges de travail analytiques à haute performance","Outils d''IA pour les développeurs","Agents d''IA pour l''analyse"],"de":["ClickHouse","Datenbank für die Analyse","Entwurfsmuster für Tabellenschemata","Abfrageoptimierung","Datenengineering","hochleistungsfähige analytische Workloads","AI-Tools für Entwickler","KI-Agents für die Analyse"],"pt":["clickhouse otimização consultas","clickhouse mergeTree engine","clickhouse funções janela","migração postgresql para clickhouse","clickhouse kafka integração","clickhouse materialized views","claude code clickhouse","ai agent clickhouse developer"],"ru":["clickhouse оптимизация запросов","clickhouse движок mergeTree","clickhouse оконные функции","миграция postgresql в clickhouse","clickhouse интеграция с kafka","clickhouse материализованные представления","claude code clickhouse","ии агент clickhouse разработчик"],"ar":["clickhouse تحسين الاستعلامات","clickhouse محرك mergeTree","clickhouse دوال النوافذ","الهجرة من postgresql إلى clickhouse","clickhouse التكامل مع kafka","clickhouse وجهات مادية","claude code clickhouse","أداة الذكاء الاصطناعي clickhouse للمطورين"]}},"agentAnalysis":{"suitability":{"en":"Essential for Data Engineering Agents specializing in high-performance analytical database operations.","zh":"对于专注于高性能分析数据库操作的数据工程代理至关重要。","ja":"高性能分析データベース操作を専門とするデータエンジニアリングエージェントに不可欠です。","ko":"고성능 분석 데이터베이스 작업을 전문으로 하는 데이터 엔지니어링 에이전트에 필수적입니다.","es":"Esencial para agentes de ingeniería de datos especializados en operaciones de bases de datos analíticas de alto rendimiento.","fr":"Essentiel pour les agents d''ingénierie de données spécialisés dans les opérations de bases de données analytiques hautes performances.","de":"Essenziell für Data Engineering Agents, die sich auf Hochleistungsoperationen analytischer Datenbanken spezialisieren.","pt":"Essencial para Agentes de Engenharia de Dados especializados em operações de bancos de dados analíticos de alto desempenho.","ru":"Необходимо для агентов инженерии данных, специализирующихся на высокопроизводительных операциях с аналитическими базами данных.","ar":"ضروري لوكلاء هندسة البيانات المتخصصين في عمليات قواعد البيانات التحليلية عالية الأداء."},"recommendation":{"en":"Enables agents to design optimized MergeTree table schemas, implement query performance optimizations through partition pruning and projections, and manage large-scale data ingestion via batch inserts and Kafka integration. Provides specialized expertise for migrating analytical workloads from PostgreSQL/MySQL to ClickHouse.","zh":"使代理能够设计优化的MergeTree表结构，通过分区修剪和投影实现查询性能优化，并通过批量插入和Kafka集成管理大规模数据摄取。为将分析工作负载从PostgreSQL/MySQL迁移到ClickHouse提供专业技术支持。","ja":"エージェントが最適化されたMergeTreeテーブルスキーマを設計し、パーティションプルーニングとプロジェクションによるクエリパフォーマンス最適化を実装し、バッチ挿入とKafka統合による大規模データ取り込みを管理できるようにします。PostgreSQL/MySQLからの分析ワークロードのClickHouseへの移行に特化した専門知識を提供します。","ko":"에이전트가 최적화된 MergeTree 테이블 스키마를 설계하고, 파티션 프루닝 및 프로젝션을 통해 쿼리 성능 최적화를 구현하며, 배치 삽입 및 Kafka 통합을 통해 대규모 데이터 수집을 관리할 수 있도록 합니다. PostgreSQL/MySQL 분석 워크로드를 ClickHouse로 마이그레이션하기 위한 전문적인 전문 지식을 제공합니다.","es":"Permite a los agentes diseñar esquemas de tablas MergeTree optimizados, implementar optimizaciones de rendimiento de consultas mediante la poda de particiones y proyecciones, y gestionar la ingesta de datos a gran escala mediante inserciones por lotes e integración con Kafka. Proporciona experiencia especializada para migrar cargas de trabajo analíticas desde PostgreSQL/MySQL a ClickHouse.","fr":"Permet aux agents de concevoir des schémas de table MergeTree optimisés, de mettre en œuvre des optimisations de performance des requêtes via l''élagage de partitions et les projections, et de gérer l''ingestion de données à grande échelle via des insertions par lots et l''intégration Kafka. Fournit une expertise spécialisée pour migrer des charges de travail analytiques de PostgreSQL/MySQL vers ClickHouse.","de":"Ermöglicht es Agents, optimierte MergeTree-Tabellenschemata zu entwerfen, Leistungsoptimierungen für Abfragen durch Partition Pruning und Projections zu implementieren und die Datenerfassung in großem Maßstab über Batch-Inserts und Kafka-Integration zu verwalten. Bietet spezialisiertes Know-how für die Migration analytischer Workloads von PostgreSQL/MySQL zu ClickHouse.","pt":"Permite que os agentes projetem esquemas de tabelas MergeTree otimizados, implementem otimizações de desempenho de consulta por meio de partition pruning e projeções, e gerenciem a ingestão de dados em larga escala por meio de inserções em lote e integração com Kafka. Fornece expertise especializada para migrar cargas de trabalho analíticas do PostgreSQL/MySQL para o ClickHouse.","ru":"Позволяет агентам проектировать оптимизированные схемы таблиц MergeTree, реализовывать оптимизацию производительности запросов через partition pruning и проекции, а также управлять приемом данных в крупном масштабе через пакетные вставки и интеграцию с Kafka. Обеспечивает специальную экспертизу для переноса аналитических нагрузок из PostgreSQL/MySQL в ClickHouse.","ar":"يمكن الوكلاء من تصميم مخططات جداول MergeTree محسنة، وتنفيذ تحسينات أداء الاستعلام من خلال partition pruning والإسقاطات، وإدارة استيعاب البيانات على نطاق واسع عبر الإدراج الدفعي والتكامل مع Kafka. يوفر خبرة متخصصة لهجرة أحمال العمل التحليلية من PostgreSQL/MySQL إلى ClickHouse."},"useCases":{"en":["Optimizing analytical query performance with partition pruning","Designing MergeTree engine table schemas for time-series data","Implementing Kafka integration for high-volume data ingestion","Creating materialized views for pre-aggregated analytics","Migrating PostgreSQL/MySQL analytical workloads to ClickHouse"],"zh":["通过分区修剪优化分析查询性能","为时间序列数据设计MergeTree引擎表结构","实现Kafka集成以支持高容量数据摄取","创建物化视图以进行预聚合分析","将PostgreSQL/MySQL分析工作负载迁移到ClickHouse"],"ja":["パーティションプルーニングによる分析クエリパフォーマンスの最適化","時系列データのためのMergeTreeエンジンテーブルスキーマの設計","高容量データ取り込みのためのKafka統合の実装","事前集計分析のためのマテリアライズドビューの作成","PostgreSQL/MySQL分析ワークロードのClickHouseへの移行"],"ko":["파티션 프루닝을 통한 분석 쿼리 성능 최적화","시계열 데이터를 위한 MergeTree 엔진 테이블 스키마 설계","대용량 데이터 수집을 위한 Kafka 통합 구현","사전 집계 분석을 위한 구체화된 뷰 생성","PostgreSQL/MySQL 분석 워크로드를 ClickHouse로 마이그레이션"],"es":["Optimizar el rendimiento de consultas analíticas con la poda de particiones","Diseñar esquemas de tablas del motor MergeTree para datos de series temporales","Implementar la integración con Kafka para la ingesta de datos de alto volumen","Crear vistas materializadas para análisis preagregados","Migrar cargas de trabajo analíticas de PostgreSQL/MySQL a ClickHouse"],"fr":["Optimiser les performances des requêtes analytiques avec l''élagage de partitions","Concevoir des schémas de table du moteur MergeTree pour les données de séries chronologiques","Mettre en œuvre l''intégration Kafka pour l''ingestion de données à haut volume","Créer des vues matérialisées pour des analyses pré-agrégées","Migrer des charges de travail analytiques de PostgreSQL/MySQL vers ClickHouse"],"de":["Optimieren der Leistung analytischer Abfragen mit Partition Pruning","Entwerfen von MergeTree-Engine-Tabellenschemata für Zeitreihendaten","Implementieren der Kafka-Integration für die Hochvolumendatenerfassung","Erstellen von Materialized Views für voraggregierte Analysen","Migrieren analytischer Workloads von PostgreSQL/MySQL zu ClickHouse"],"pt":["Otimização do desempenho de consultas analíticas com partition pruning","Projetando esquemas de tabelas do mecanismo MergeTree para dados de séries temporais","Implementando integração com Kafka para ingestão de dados de alto volume","Criando visualizações materializadas para análises pré-agregadas","Migrando cargas de trabalho analíticas do PostgreSQL/MySQL para o ClickHouse"],"ru":["Оптимизация производительности аналитических запросов с помощью partition pruning","Проектирование схем таблиц движка MergeTree для данных временных рядов","Реализация интеграции с Kafka для приема данных большого объема","Создание материализованных представлений для предварительно агрегированной аналитики","Перенос аналитических нагрузок из PostgreSQL/MySQL в ClickHouse"],"ar":["تحسين أداء الاستعلام التحليلي مع partition pruning","تصميم مخططات جداول محرك MergeHouse للبيانات الزمنية","تنفيذ تكامل Kafka لاستيعاب البيانات عالية الحجم","إنشاء وجهات نظر مادية للتحليلات المجمعة مسبقًا","هجرة أحمال العمل التحليلية من PostgreSQL/MySQL إلى ClickHouse"]},"limitations":{"en":["Specialized for ClickHouse database only","Requires understanding of analytical query patterns","Optimized for batch processing rather than transactional workloads"],"zh":["仅专用于ClickHouse数据库","需要理解分析查询模式","针对批处理而非事务性工作负载进行了优化"],"ja":["ClickHouseデータベースに特化","分析クエリパターンの理解が必要","トランザクションワークロードではなくバッチ処理向けに最適化"],"ko":["ClickHouse 데이터베이스 전용으로 특화됨","분석 쿼리 패턴에 대한 이해가 필요함","트랜잭션 워크로드보다 배치 처리에 최적화됨"],"es":["Especializado únicamente para la base de datos ClickHouse","Requiere comprensión de los patrones de consultas analíticas","Optimizado para el procesamiento por lotes en lugar de cargas de trabajo transaccionales"],"fr":["Spécialisé uniquement pour la base de données ClickHouse","Nécessite une compréhension des modèles de requêtes analytiques","Optimisé pour le traitement par lots plutôt que pour les charges de travail transactionnelles"],"de":["Spezialisiert ausschließlich auf die ClickHouse-Datenbank","Erfordert ein Verständnis analytischer Abfragemuster","Optimiert für die Stapelverarbeitung und nicht für transaktionale Workloads"],"pt":["Especializado apenas para o banco de dados ClickHouse","Requer compreensão de padrões de consulta analítica","Otimizado para processamento em lote em vez de cargas de trabalho transacionais"],"ru":["Специализирован только для базы данных ClickHouse","Требует понимания шаблонов аналитических запросов","Оптимизирован для пакетной обработки, а не для транзакционных нагрузок"],"ar":["متخصص لقاعدة بيانات ClickHouse فقط","يتطلب فهم أنماط الاستعلام التحليلية","محسن للمعالجة الدفعية بدلاً من أحمال العمل المعاملية"]},"version":4},"contentHash":"bc0d9351ae909eaa725b57ee5c4928274ed94e0b55e0fef4076cbe2844ae8a7b","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":68}');
