INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/clickhouse-io', 'clickhouse-io', 'affaan-m', 'everything-claude-code', 'official', 'clickhouse-io affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The clickhouse-io skill provides ClickHouse database patterns, query optimization, and data engineering best practices for high-performance analytical workloads, benefiting developers and data engineers. ClickHouse数据库模式、查询优化和数据工程最佳实践，用于高性能分析工作负载 ClickHouseデータベースパターン、クエリ最適化、データエンジニアリングのベストプラクティス ClickHouse 데이터베이스 패턴, 쿼리 최적화, 데이터 엔지니어링 최적화 방법 ClickHouse es una base de datos de código abierto diseñada para cargas de trabajo analíticas de alto rendimiento. Ofrece patrones de diseño de esquemas de tabla, optimización de consultas y mejores prácticas para la ingeniería de datos. ClickHouse est une base de données open source conçue pour les charges de travail analytiques à haute performance. Elle propose des modèles de conception de schémas de table, d''optimisation de requêtes et de meilleures pratiques pour l''ingénierie de données. ClickHouse ist eine Open-Source-Datenbank, die für hochleistungsfähige analytische Workloads konzipiert ist. Sie bietet Entwurfsmuster für Tabellenschemata, Abfrageoptimierung und Best Practices für Datenengineering. Skill técnico para padrões analíticos no ClickHouse, otimizando esquemas MergeTree, consultas de agregação, junções e ingestão de dados em lote com Kafka para cargas de trabalho de alto desempenho. Технический навык для аналитических шаблонов в ClickHouse, оптимизирующий схемы MergeTree, агрегационные запросы, соединения и пакетный прием данных с Kafka для высокопроизводительных рабочих нагрузок. مهارة تقنية لأنماط التحليل في ClickHouse، تحسن أنماط MergeTree، واستعلامات التجميع، والوصلات واستيعاب البيانات المجمعة باستخدام Kafka لأحمال العمل عالية الأداء. how to use clickhouse-io clickhouse-io vs PostgreSQL clickhouse-io setup guide what is clickhouse-io clickhouse-io alternative to MySQL clickhouse-io install on Ubuntu clickhouse-io query optimization techniques clickhouse-io data engineering best practices ClickHouse 分析数据库 高性能查询 数据工程 MergeTree Kafka集成 AIエージェント ClickHouse优化 Designs ClickHouse table schemas using MergeTree engine selection Writes optimized analytical queries with aggregations, window functions, and joins Optimizes query performance using partition pruning, projections, and materialized views Ingests large volumes of data using batch inserts and Kafka integration Migrates from PostgreSQL/MySQL to ClickHouse for analytics clickhouse-io is a skill that provides expert guidance on ClickHouse database patterns, query optimization, and data engineering for high-performance analytics and data engineering workloads.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/iterative-retrieval', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'iterative-retrieval', 61988, 7678, 68, '2026-03-06T03:39:20Z', '2026-03-06T04:17:52.751Z', '5bf02488afe5504290a715d534b8dc41fa366997077715bd555f25c6e372f5bc', '{"id":"affaan-m/everything-claude-code/iterative-retrieval","name":"iterative-retrieval","description":{"en":"The iterative-retrieval skill is a pattern that solves the subagent context problem in multi-agent workflows. It allows AI agents like Claude to progressively retrieve and refine codebase context they cannot predict upfront, preventing failures and optimizing token usage.","zh":"Iterative-Retrieval是一种AI代理模式，专为解决多代理工作流中子代理无法预先确定所需上下文的“上下文问题”而设计。它通过逐步优化上下文检索，有效处理代码探索中的RAG-like检索管道，并优化token使用效率。","ja":"Iterative-Retrievalは、マルチエージェントワークフローにおいてサブエージェントが事前に必要なコンテキストを決定できない「コンテキスト問題」を解決するAIエージェントパターンです。段階的なコンテキスト検索の最適化により、コード探索におけるRAGライクな検索パイプラインを処理し、トークン使用効率を最適化します。","ko":"Iterative-Retrieval은 다중 에이전트 워크플로우에서 서브에이전트가 필요한 컨텍스트를 사전에 결정할 수 없는 ''컨텍스트 문제''를 해결하기 위한 AI 에이전트 패턴입니다. 점진적인 컨텍스트 검색 최적화를 통해 코드 탐색에서 RAG-like 검색 파이프라인을 처리하고 토큰 사용 효율을 최적화합니다.","es":"El patrón iterative-retrieval soluciona el ''problema de contexto'' en workflows multiagente, donde los subagentes no pueden predecir qué contexto necesitan. Permite un refinamiento progresivo de la recuperación de contexto, optimizando pipelines tipo RAG para exploración de código.","fr":"Le patron iterative-retrieval résout le ''problème de contexte'' dans les workflows multi-agents, où les sous-agents ne peuvent prédire le contexte nécessaire. Il permet un raffinement progressif de la récupération de contexte, optimisant les pipelines de type RAG pour l''exploration de code.","de":"Das iterative-retrieval Pattern löst das ''Kontextproblem'' in Multi-Agent-Workflows, bei dem Subagenten den benötigten Kontext nicht vorhersagen können. Es ermöglicht eine progressive Verfeinerung der Kontextabfrage und optimiert RAG-ähnliche Pipelines für Code-Exploration.","pt":"Padrão técnico para refinar progressivamente a recuperação de contexto em agentes de IA. Soluciona o problema de subagentes que não sabem qual contexto precisam antecipadamente, comum em fluxos com Claude Code e MCP.","ru":"Технический паттерн для постепенного уточнения извлечения контекста в ИИ агентах. Решает проблему суб-агентов, которые не знают, какой контекст им нужен заранее, часто встречается в workflows с Claude Code и MCP.","ar":"نمط تقني لتحسين استرجاع السياق تدريجيًا في أدوات الذكاء الاصطناعي. يحل مشكلة الأدوات الفرعية التي لا تعرف السياق الذي تحتاجه مقدمًا، شائع في سير العمل مع Claude Code و MCP."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"iterative-retrieval","description":"Pattern for progressively refining context retrieval to solve the subagent context problem","bodyPreview":"# Iterative Retrieval Pattern\n\nSolves the \"context problem\" in multi-agent workflows where subagents don''t know what context they need until they start working.\n\n## When to Activate\n\n- Spawning subagents that need codebase context they cannot predict upfront\n- Building multi-agent workflows where context is progressively refined\n- Encountering \"context too large\" or \"missing context\" failures in agent tasks\n- Designing RAG-like retrieval pipelines for code exploration\n- Optimizing token usage in","body":"# Iterative Retrieval Pattern\n\nSolves the \"context problem\" in multi-agent workflows where subagents don''t know what context they need until they start working.\n\n## When to Activate\n\n- Spawning subagents that need codebase context they cannot predict upfront\n- Building multi-agent workflows where context is progressively refined\n- Encountering \"context too large\" or \"missing context\" failures in agent tasks\n- Designing RAG-like retrieval pipelines for code exploration\n- Optimizing token usage in agent orchestration\n\n## The Problem\n\nSubagents are spawned with limited context. They don''t know:\n- Which files contain relevant code\n- What patterns exist in the codebase\n- What terminology the project uses\n\nStandard approaches fail:\n- **Send everything**: Exceeds context limits\n- **Send nothing**: Agent lacks critical information\n- **Guess what''s needed**: Often wrong\n\n## The Solution: Iterative Retrieval\n\nA 4-phase loop that progressively refines context:\n\n```\n┌─────────────────────────────────────────────┐\n│                                             │\n│   ┌──────────┐      ┌──────────┐            │\n│   │ DISPATCH │─────▶│ EVALUATE │            │\n│   └──────────┘      └──────────┘            │\n│        ▲                  │                 │\n│        │                  ▼                 │\n│   ┌──────────┐      ┌──────────┐            │\n│   │   LOOP   │◀─────│  REFINE  │            │\n│   └──────────┘      └──────────┘            │\n│                                             │\n│        Max 3 cycles, then proceed           │\n└─────────────────────────────────────────────┘\n```\n\n### Phase 1: DISPATCH\n\nInitial broad query to gather candidate files:\n\n```javascript\n// Start with high-level intent\nconst initialQuery = {\n  patterns: [''src/**/*.ts'', ''lib/**/*.ts''],\n  keywords: [''authentication'', ''user'', ''session''],\n  excludes: [''*.test.ts'', ''*.spec.ts'']\n};\n\n// Dispatch to retrieval agent\nconst candidates = await retrieveFiles(initialQuery);\n```\n\n### Phase 2: EVALUATE\n\nAssess retrieved content for relevance:\n\n```javascript\nfunction evaluateRelevance(files, task) {\n  return files.map(file => ({\n    path: file.path,\n    relevance: scoreRelevance(file.content, task),\n    reason: explainRelevance(file.content, task),\n    missingContext: identifyGaps(file.content, task)\n  }));\n}\n```\n\nScoring criteria:\n- **High (0.8-1.0)**: Directly implements target functionality\n- **Medium (0.5-0.7)**: Contains related patterns or types\n- **Low (0.2-0.4)**: Tangentially related\n- **None (0-0.2)**: Not relevant, exclude\n\n### Phase 3: REFINE\n\nUpdate search criteria based on evaluation:\n\n```javascript\nfunction refineQuery(evaluation, previousQuery) {\n  return {\n    // Add new patterns discovered in high-relevance files\n    patterns: [...previousQuery.patterns, ...extractPatterns(evaluation)],\n\n    // Add terminology found in codebase\n    keywords: [...previousQuery.keywords, ...extractKeywords(evaluation)],\n\n    // Exclude confirmed irrelevant paths\n    excludes: [...previousQuery.excludes, ...evaluation\n      .filter(e => e.relevance < 0.2)\n      .map(e => e.path)\n    ],\n\n    // Target specific gaps\n    focusAreas: evaluation\n      .flatMap(e => e.missingContext)\n      .filter(unique)\n  };\n}\n```\n\n### Phase 4: LOOP\n\nRepeat with refined criteria (max 3 cycles):\n\n```javascript\nasync function iterativeRetrieve(task, maxCycles = 3) {\n  let query = createInitialQuery(task);\n  let bestContext = [];\n\n  for (let cycle = 0; cycle < maxCycles; cycle++) {\n    const candidates = await retrieveFiles(query);\n    const evaluation = evaluateRelevance(candidates, task);\n\n    // Check if we have sufficient context\n    const highRelevance = evaluation.filter(e => e.relevance >= 0.7);\n    if (highRelevance.length >= 3 && !hasCriticalGaps(evaluation)) {\n      return highRelevance;\n    }\n\n    // Refine and continue\n    query = refineQuery(evaluation, query);\n    bestContext = mergeContext(bestContext, highRelevance);\n  }\n\n  return bestContext;\n}\n```\n\n## Practical Examples\n\n### Example 1: Bug Fix Context\n\n```\nTask: \"Fix the authentication token expiry bug\"\n\nCycle 1:\n  DISPATCH: Search for \"token\", \"auth\", \"expiry\" in src/**\n  EVALUATE: Found auth.ts (0.9), tokens.ts (0.8), user.ts (0.3)\n  REFINE: Add \"refresh\", \"jwt\" keywords; exclude user.ts\n\nCycle 2:\n  DISPATCH: Search refined terms\n  EVALUATE: Found session-manager.ts (0.95), jwt-utils.ts (0.85)\n  REFINE: Sufficient context (2 high-relevance files)\n\nResult: auth.ts, tokens.ts, session-manager.ts, jwt-utils.ts\n```\n\n### Example 2: Feature Implementation\n\n```\nTask: \"Add rate limiting to API endpoints\"\n\nCycle 1:\n  DISPATCH: Search \"rate\", \"limit\", \"api\" in routes/**\n  EVALUATE: No matches - codebase uses \"throttle\" terminology\n  REFINE: Add \"throttle\", \"middleware\" keywords\n\nCycle 2:\n  DISPATCH: Search refined terms\n  EVALUATE: Found throttle.ts (0.9), middleware/index.ts (0.7)\n  REFINE: Need router patterns\n\nCycle 3:\n  DISPATCH: Search \"router\", \"express\" patterns\n  EVALUATE: Found router-setup.ts (0.8)\n  REFINE: Sufficient context\n\nResult: throttle.ts, middleware/index.ts, router-setup.ts\n```\n\n## Integration with Agents\n\nUse in agent prompts:\n\n```markdown\nWhen retrieving context for this task:\n1. Start with broad keyword search\n2. Evaluate each file''s relevance (0-1 scale)\n3. Identify what context is still missing\n4. Refine search criteria and repeat (max 3 cycles)\n5. Return files with relevance >= 0.7\n```\n\n## Best Practices\n\n1. **Start broad, narrow progressively** - Don''t over-specify initial queries\n2. **Learn codebase terminology** - First cycle often reveals naming conventions\n3. **Track what''s missing** - Explicit gap identification drives refinement\n4. **Stop at \"good enough\"** - 3 high-relevance files beats 10 mediocre ones\n5. **Exclude confidently** - Low-relevance files won''t become relevant\n\n## Related\n\n- [The Longform Guide](https://x.com/affaanmustafa/status/2014040193557471352) - Subagent orchestration section\n- `continuous-learning` skill - For patterns that improve over time\n- Agent definitions in `~/.claude/agents/`\n"},"category":"official","lastSynced":"2026-03-06T04:17:52.751Z","seo":{"title":{"en":"Iterative-Retrieval: Solve Subagent Context Problems | AI...","zh":"Iterative-Retrieval 设置指南：解决AI代理上下文问题","ja":"Iterative-Retrieval セットアップガイド：AIエージェントのコンテキスト問題を解決","ko":"Iterative-Retrieval 설정 가이드: AI 에이전트 컨텍스트 문제 해결","es":"Patrón Iterative Retrieval: Guía de Implementación para A...","fr":"Patron Iterative Retrieval : Guide de Configuration pour ...","de":"Iterative Retrieval Pattern: Setup Guide für KI-Agenten","pt":"Iterative Retrieval Pattern: Guia de Configuração para Fl...","ru":"Паттерн Iterative Retrieval: Руководство по настройке для...","ar":"نمط الاسترجاع التكراري: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Struggling with ''context too large'' or ''missing context'' errors in your AI agents? Learn how the iterative-retrieval pattern for MCP and Claude dynamically r...","zh":"Iterative-Retrieval模式解决AI代理工作流中的“上下文问题”。当子代理无法预测所需代码库上下文时，逐步优化检索，避免“上下文过大”或“缺失上下文”错误，优化token使用。","ja":"Iterative-RetrievalパターンはAIエージェントワークフローの「コンテキスト問題」を解決。サブエージェントが事前予測できないコードベースコンテキストを段階的に最適化し、「コンテキスト過大」や「コンテキスト不足」エラーを回避、トークン使用を最適化。","ko":"Iterative-Retrieval 패턴은 AI 에이전트 워크플로우의 ''컨텍스트 문제''를 해결합니다. 서브에이전트가 예측할 수 없는 코드베이스 컨텍스트를 점진적으로 최적화하여 ''컨텍스트 너무 큼'' 또는 ''컨텍스트 누락'' 오류를 방지하고 토큰 사용을 최적화합니다.","es":"Implementa el patrón iterative-retrieval para resolver el problema de contexto en subagentes IA. Optimiza el uso de tokens y evita fallos de ''contexto demasi...","fr":"Implémentez le patron iterative-retrieval pour résoudre le problème de contexte dans les sous-agents IA. Optimisez l''usage des tokens et évitez les échecs ''c...","de":"Implementiere das iterative-retrieval Pattern zur Lösung des Kontextproblems in KI-Subagenten. Optimiere die Token-Nutzung und vermeide ''Kontext zu groß''-Feh...","pt":"Implemente o padrão iterative-retrieval para resolver problemas de contexto em subagentes de IA. Otimize o uso de tokens e evite falhas de ''contexto ausente''...","ru":"Реализуйте паттерн iterative-retrieval для решения проблем контекста в ИИ суб-агентах. Оптимизируйте использование токенов и избегайте сбоев ''отсутствует кон...","ar":"نفذ نمط iterative-retrieval لحل مشاكل السياق في أدوات الذكاء الاصطناعي الفرعية. حسّن استخدام الرموز المميزة وتجنب فشل ''السياق المفقود'' في سير العمل متعدد الع..."},"definition":{"en":"Iterative-retrieval is an AI agent pattern for progressively refining context retrieval to solve the subagent context problem. It is activated when spawning subagents that need unpredicted codebase context or when encountering context-related failures in agent tasks.","zh":"Iterative-Retrieval是一种AI代理技能模式，用于解决多代理工作流中的“上下文问题”。当子代理生成时需要代码库上下文但无法预先预测时，该模式通过逐步优化上下文检索，避免“上下文过大”或“缺失上下文”故障，并优化token使用。适用于构建渐进式精炼上下文的多代理工作流和RAG-like检索管道。","ja":"Iterative-Retrievalは、マルチエージェントワークフローにおける「コンテキスト問題」を解決するAIエージェントスキルパターンです。サブエージェントがコードベースコンテキストを必要とするが事前予測できない場合、段階的なコンテキスト検索の最適化により、「コンテキスト過大」や「コンテキスト不足」の失敗を回避し、トークン使用を最適化します。漸進的にコンテキストを洗練させるマルチエージェントワークフローやRAGライクな検索パイプラインの構築に適しています。","ko":"Iterative-Retrieval은 다중 에이전트 워크플로우에서 ''컨텍스트 문제''를 해결하는 AI 에이전트 스킬 패턴입니다. 서브에이전트가 코드베이스 컨텍스트가 필요하지만 사전에 예측할 수 없는 경우 점진적인 컨텍스트 검색 최적화를 통해 ''컨텍스트 너무 큼'' 또는 ''컨텍스트 누락'' 오류를 방지하고 토큰 사용을 최적화합니다. 점진적으로 컨텍스트를 정제하는 다중 에이전트 워크플로우 및 RAG-like 검색 파이프라인 구축에 적합합니다.","es":"El patrón iterative-retrieval es una técnica para flujos de trabajo de agentes IA que aborda el problema de contexto de los subagentes. Permite una recuperación de contexto progresivamente refinada, evitando fallos por contexto insuficiente o excesivo, optimizando así el uso de tokens.","fr":"Le patron iterative-retrieval est une technique pour workflows d''outils IA qui adresse le problème de contexte des sous-agents. Il permet une récupération de contexte progressivement raffinée, évitant les échecs dus à un contexte insuffisant ou excessif, optimisant ainsi l''usage des tokens.","de":"Das iterative-retrieval Pattern ist eine Technik für KI-Agenten-Workflows, die das Kontextproblem von Subagenten adressiert. Es ermöglicht eine progressively verfeinerte Kontextabfrage, vermeidet Fehler durch unzureichenden oder übermäßigen Kontext und optimiert so die Token-Nutzung.","pt":"Iterative Retrieval é um padrão para fluxos de trabalho multiagente que refina progressivamente a recuperação de contexto. Ele resolve o problema em que subagentes não podem prever qual contexto de codebase precisarão até iniciar sua tarefa.","ru":"Iterative Retrieval — это паттерн для мульти-агентных workflows, который постепенно уточняет извлечение контекста. Он решает проблему, когда суб-агенты не могут предсказать, какой контекст codebase им понадобится до начала задачи.","ar":"Iterative Retrieval هو نمط لسير العمل متعدد العوامل يقوم بتحسين استرجاع السياق تدريجيًا. يحل المشكلة حيث لا يمكن للأدوات الفرعية التنبؤ بالسياق الذي ستحتاجه من قاعدة التعليمات البرمجية حتى تبدأ مهمتها."},"features":{"en":["Solves the subagent context problem in multi-agent workflows","Progressively refines context retrieval for agents like Claude","Addresses ''context too large'' and ''missing context'' failures","Optimizes token usage in AI agent tasks","Designed for RAG-like retrieval pipelines for code exploration","Activated when spawning subagents needing unpredictable codebase context"],"zh":["解决子代理无法预测代码库上下文的“上下文问题”","构建渐进式精炼上下文的多代理工作流","处理“上下文过大”或“缺失上下文”代理任务故障","为代码探索设计RAG-like检索管道","优化AI代理任务中的token使用"],"ja":["サブエージェントがコードベースコンテキストを予測できない「コンテキスト問題」の解決","コンテキストを段階的に洗練するマルチエージェントワークフローの構築","「コンテキスト過大」や「コンテキスト不足」のエージェントタスク失敗への対応","コード探索のためのRAGライクな検索パイプラインの設計","AIエージェントタスクにおけるトークン使用の最適化"],"ko":["서브에이전트가 코드베이스 컨텍스트를 예측할 수 없는 ''컨텍스트 문제'' 해결","컨텍스트를 점진적으로 정제하는 다중 에이전트 워크플로우 구축","''컨텍스트 너무 큼'' 또는 ''컨텍스트 누락'' 에이전트 작업 실패 처리","코드 탐색을 위한 RAG-like 검색 파이프라인 설계","AI 에이전트 작업에서 토큰 사용 최적화"],"es":["Resuelve el ''problema de contexto'' para subagentes que no pueden predecir sus necesidades de contexto","Optimiza el uso de tokens en workflows multiagente evitando recuperación excesiva inicial","Previene fallos de ''contexto demasiado grande'' o ''contexto faltante'' en tareas de agentes","Diseña pipelines de recuperación tipo RAG para exploración de códigobase","Integración con herramientas de desarrollador MCP y modelos Claude Code"],"fr":["Résout le ''problème de contexte'' pour les sous-agents ne pouvant prédire leurs besoins contextuels","Optimise l''usage des tokens dans les workflows multi-agents en évitant la récupération excessive initiale","Prévient les échecs ''contexte trop large'' ou ''contexte manquant'' dans les tâches d''agents","Conçoit des pipelines de récupération de type RAG pour l''exploration de codebase","Intégration avec les outils développeur MCP et modèles Claude Code"],"de":["Löst das ''Kontextproblem'' für Subagenten, die ihren Kontextbedarf nicht vorhersagen können","Optimiert die Token-Nutzung in Multi-Agent-Workflows durch Vermeidung anfänglich übermäßiger Abfragen","Verhindert ''Kontext zu groß''- oder ''Fehlender Kontext''-Fehler in Agentenaufgaben","Entwirft RAG-ähnliche Abfrage-Pipelines für Codebase-Exploration","Integration mit MCP-Entwicklertools und Claude Code-Modellen"],"pt":["Resolve falhas de ''contexto muito grande'' em tarefas de agente","Otimiza o uso de tokens em pipelines de recuperação tipo RAG","Projetado para exploração de código com subagentes","Integra com ferramentas MCP e Claude para desenvolvimento","Ativa quando subagentes não podem prever contexto antecipadamente"],"ru":["Решает сбои ''контекст слишком большой'' в задачах агента","Оптимизирует использование токенов в RAG-like retrieval pipelines","Предназначен для исследования кода с суб-агентами","Интегрируется с инструментами MCP и Claude для разработки","Активируется, когда суб-агенты не могут предсказать контекст заранее"],"ar":["يحل فشل ''السياق كبير جدًا'' في مهام الأداة","يحسن استخدام الرموز المميزة في خطوط أنابيب الاسترجاع الشبيهة بـ RAG","مصمم لاستكشاف التعليمات البرمجية مع الأدوات الفرعية","يتكامل مع أدوات MCP و Claude للتطوير","ينشط عندما لا يمكن للأدوات الفرعية التنبؤ بالسياق مقدمًا"]},"keywords":{"en":["what is iterative-retrieval","how to use iterative-retrieval pattern","solve subagent context problem","iterative-retrieval vs traditional RAG","iterative-retrieval for MCP","iterative-retrieval setup guide","Claude code context optimization","multi-agent workflow context handling","iterative-retrieval install","AI agent token usage optimization"],"zh":["iterative-retrieval AI代理","多代理工作流上下文问题","子代理代码库上下文","RAG-like检索管道","Claude代码优化","MCP token使用","AI代理渐进式检索","上下文过大错误解决"],"ja":["iterative-retrieval AIエージェント","マルチエージェントワークフロー コンテキスト問題","サブエージェント コードベースコンテキスト","RAGライク検索パイプライン","Claudeコード最適化","MCP トークン使用","AIエージェント 段階的検索","コンテキスト過大エラー解決"],"ko":["iterative-retrieval AI 에이전트","다중 에이전트 워크플로우 컨텍스트 문제","서브에이전트 코드베이스 컨텍스트","RAG-like 검색 파이프라인","Claude 코드 최적화","MCP 토큰 사용","AI 에이전트 점진적 검색","컨텍스트 너무 큼 오류 해결"],"es":["patrón iterative retrieval","subagentes contexto problema","multiagente workflows","RAG pipelines código","optimizar uso tokens Claude","MCP developer tools","evitar contexto demasiado grande","recuperación contexto progresiva"],"fr":["patron iterative retrieval","sous-agents problème contexte","workflows multi-agents","pipelines RAG code","optimiser usage tokens Claude","outils développeur MCP","éviter contexte trop large","récupération contexte progressive"],"de":["iterative retrieval pattern","subagenten kontext problem","multi-agent workflows","RAG pipelines code","token nutzung optimieren claude","MCP developer tools","kontext zu groß vermeiden","progressive kontext retrieval"],"pt":["iterative retrieval pattern","subagentes contexto problema","claude code MCP","fluxo trabalho multiagente IA","RAG retrieval codebase","otimizar uso tokens AI agents","configurar iterative retrieval","ferramentas desenvolvedor anthropic claude"],"ru":["iterative retrieval pattern","проблема контекста суб-агентов","claude code MCP","мульти-агентный workflow ИИ","RAG retrieval codebase","оптимизация использования токенов ИИ агенты","настройка iterative retrieval","инструменты разработчика anthropic claude"],"ar":["نمط الاسترجاع التكراري","مشكلة سياق الأدوات الفرعية","claude code MCP","سير عمل متعدد العوامل للذكاء الاصطناعي","استرجاع RAG لقاعدة التعليمات البرمجية","تحسين استخدام الرموز المميزة لأدوات الذكاء الاصطناعي","إعداد iterative retrieval","أدوات المطور anthropic claude"]}},"agentAnalysis":{"suitability":{"en":"Essential for Multi-Agent Architectures tackling complex codebase exploration and RAG workflows.","zh":"对于处理复杂代码库探索和RAG工作流程的多智能体架构至关重要。","ja":"複雑なコードベースの探索とRAGワークフローに取り組むマルチエージェントアーキテクチャに不可欠です。","ko":"복잡한 코드베이스 탐색 및 RAG 워크플로우를 다루는 멀티 에이전트 아키텍처에 필수적입니다.","es":"Esencial para arquitecturas multiagente que abordan la exploración compleja de bases de código y flujos de trabajo de RAG.","fr":"Essentiel pour les architectures multi-agents abordant l''exploration complexe de bases de code et les flux de travail RAG.","de":"Wesentlich für Multi-Agenten-Architekturen, die die Erkundung komplexer Codebasen und RAG-Workflows bewältigen.","pt":"Essencial para Arquiteturas Multi-Agente que lidam com exploração complexa de codebase e workflows de RAG.","ru":"Необходим для Мульти-Агентных Архитектур, решающих задачи сложного исследования кодовой базы и рабочих процессов RAG.","ar":"أساسي لبنيات Multi-Agent التي تتناول استكشاف codebase المعقدة وتدفقات عمل RAG."},"recommendation":{"en":"Enables progressive refinement of context retrieval for subagents that cannot predict their required context upfront. Directly addresses ''context too large'' and ''missing context'' failures in multi-agent workflows by implementing a dynamic retrieval pipeline.","zh":"使无法预先预测所需上下文的子智能体能够逐步优化上下文检索。通过实现动态检索管道，直接解决多智能体工作流程中的''上下文过大''和''上下文缺失''故障。","ja":"必要なコンテキストを事前に予測できないサブエージェントのコンテキスト検索を段階的に洗練させることを可能にします。動的検索パイプラインを実装することで、マルチエージェントワークフローにおける「コンテキスト过大」および「コンテキスト欠落」の失敗に直接対処します。","ko":"필요한 컨텍스트를 사전에 예측할 수 없는 하위 에이전트가 컨텍스트 검색을 점진적으로 개선할 수 있게 합니다. 동적 검색 파이프라인을 구현하여 멀티 에이전트 워크플로우에서 ''컨텍스트 너무 큼'' 및 ''컨텍스트 누락'' 오류를 직접 해결합니다.","es":"Permite el refinamiento progresivo de la recuperación de contexto para subagentes que no pueden predecir su contexto requerido de antemano. Aborda directamente los fallos de ''contexto demasiado grande'' y ''contexto faltante'' en flujos de trabajo multiagente mediante la implementación de una canalización de recuperación dinámica.","fr":"Permet un raffinement progressif de la récupération du contexte pour les sous-agents qui ne peuvent pas prédire leur contexte requis à l''avance. Traite directement les échecs ''contexte trop grand'' et ''contexte manquant'' dans les flux de travail multi-agents en mettant en œuvre un pipeline de récupération dynamique.","de":"Ermöglicht die progressive Verfeinerung der Kontextabrufung für Subagenten, die ihren benötigten Kontext nicht im Voraus vorhersagen können. Adressiert direkt die Fehler ''Kontext zu groß'' und ''fehlender Kontext'' in Multi-Agenten-Workflows durch die Implementierung einer dynamischen Abrufpipeline.","pt":"Permite o refinamento progressivo da recuperação de contexto para subagentes que não podem prever seu contexto necessário antecipadamente. Aborda diretamente as falhas de ''contexto muito grande'' e ''contexto ausente'' em workflows multi-agente, implementando um pipeline de recuperação dinâmico.","ru":"Позволяет осуществлять прогрессивное уточнение извлечения контекста для суб-агентов, которые не могут заранее предсказать свой требуемый контекст. Напрямую решает проблемы ''слишком большой контекст'' и ''отсутствующий контекст'' в мульти-агентных рабочих процессах путем реализации динамического конвейера извлечения.","ar":"يُمكّن من التنقيح التدريجي لاسترداد السياق للوكلاء الفرعيين الذين لا يمكنهم التنبؤ بسياقهم المطلوب مسبقًا. يعالج مباشرة فشل ''السياق كبير جدًا'' و''السياق المفقود'' في تدفقات العمل متعددة الوكلاء من خلال تنفيذ خط أنابيب ديناميكي للاسترداد."},"useCases":{"en":["Spawning subagents for codebase analysis","Building multi-agent workflows with progressive context refinement","Optimizing token usage in RAG-like retrieval pipelines","Solving the subagent context problem in complex tasks"],"zh":["生成用于代码库分析的子智能体","构建具有渐进式上下文优化功能的多智能体工作流程","在类似RAG的检索管道中优化token使用","解决复杂任务中的子智能体上下文问题"],"ja":["コードベース分析のためのサブエージェントの生成","段階的なコンテキスト洗練を備えたマルチエージェントワークフローの構築","RAGのような検索パイプラインにおけるtoken使用の最適化","複雑なタスクにおけるサブエージェントのコンテキスト問題の解決"],"ko":["코드베이스 분석을 위한 하위 에이전트 생성","점진적인 컨텍스트 개선을 통한 멀티 에이전트 워크플로우 구축","RAG 유사 검색 파이프라인에서 token 사용 최적화","복잡한 작업에서 하위 에이전트 컨텍스트 문제 해결"],"es":["Generación de subagentes para el análisis de bases de código","Construcción de flujos de trabajo multiagente con refinamiento progresivo del contexto","Optimización del uso de tokens en canalizaciones de recuperación similares a RAG","Resolución del problema de contexto del subagente en tareas complejas"],"fr":["Lancement de sous-agents pour l''analyse de bases de code","Construction de flux de travail multi-agents avec raffinement progressif du contexte","Optimisation de l''utilisation des tokens dans les pipelines de récupération de type RAG","Résolution du problème de contexte des sous-agents dans les tâches complexes"],"de":["Erzeugung von Subagenten für die Codebasis-Analyse","Aufbau von Multi-Agenten-Workflows mit progressiver Kontextverfeinerung","Optimierung der Token-Nutzung in RAG-ähnlichen Abrufpipelines","Lösung des Subagenten-Kontextproblems bei komplexen Aufgaben"],"pt":["Criação de subagentes para análise de codebase","Construção de workflows multi-agente com refinamento progressivo de contexto","Otimização do uso de tokens em pipelines de recuperação do tipo RAG","Resolução do problema de contexto do subagente em tarefas complexas"],"ru":["Запуск суб-агентов для анализа кодовой базы","Построение мульти-агентных рабочих процессов с прогрессивным уточнением контекста","Оптимизация использования токенов в конвейерах извлечения, подобных RAG","Решение проблемы контекста суб-агента в сложных задачах"],"ar":["إنشاء وكلاء فرعيين لتحليل codebase","بناء تدفقات عمل متعددة الوكلاء مع تنقيح تدريجي للسياق","تحسين استخدام الرموز المميزة في خطوط أنابيب الاسترداد الشبيهة بـ RAG","حل مشكلة سياق الوكيل الفرعي في المهام المعقدة"]},"limitations":{"en":["Requires integration into multi-agent architectures","Designed specifically for code exploration contexts","Needs a retrieval mechanism for initial context gathering"],"zh":["需要集成到多智能体架构中","专为代码探索上下文设计","需要初始上下文收集的检索机制"],"ja":["マルチエージェントアーキテクチャへの統合が必要","コード探索コンテキスト専用に設計","初期コンテキスト収集のための検索メカニズムが必要"],"ko":["멀티 에이전트 아키텍처로의 통합 필요","코드 탐색 컨텍스트에 특화되어 설계됨","초기 컨텍스트 수집을 위한 검색 메커니즘 필요"],"es":["Requiere integración en arquitecturas multiagente","Diseñado específicamente para contextos de exploración de código","Necesita un mecanismo de recuperación para la recopilación inicial de contexto"],"fr":["Nécessite une intégration dans des architectures multi-agents","Conçu spécifiquement pour les contextes d''exploration de code","Nécessite un mécanisme de récupération pour la collecte initiale du contexte"],"de":["Erfordert Integration in Multi-Agenten-Architekturen","Speziell für Code-Explorationskontexte entwickelt","Benötigt einen Abrufmechanismus für die anfängliche Kontexterfassung"],"pt":["Requer integração em arquiteturas multi-agente","Projetado especificamente para contextos de exploração de código","Necessita de um mecanismo de recuperação para coleta inicial de contexto"],"ru":["Требует интеграции в мульти-агентные архитектуры","Специально разработан для контекстов исследования кода","Требует механизма извлечения для первоначального сбора контекста"],"ar":["يتطلب التكامل في بنيات متعددة الوكلاء","مصمم خصيصًا لسياقات استكشاف التعليمات البرمجية","يحتاج إلى آلية استرداد لجمع السياق الأولي"]},"version":4},"contentHash":"5bf02488afe5504290a715d534b8dc41fa366997077715bd555f25c6e372f5bc","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":68}');
