INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/iterative-retrieval', 'iterative-retrieval', 'affaan-m', 'everything-claude-code', 'official', 'iterative-retrieval affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The iterative-retrieval skill is a pattern that solves the subagent context problem in multi-agent workflows. It allows AI agents like Claude to progressively retrieve and refine codebase context they cannot predict upfront, preventing failures and optimizing token usage. Iterative-Retrieval是一种AI代理模式，专为解决多代理工作流中子代理无法预先确定所需上下文的“上下文问题”而设计。它通过逐步优化上下文检索，有效处理代码探索中的RAG-like检索管道，并优化token使用效率。 Iterative-Retrievalは、マルチエージェントワークフローにおいてサブエージェントが事前に必要なコンテキストを決定できない「コンテキスト問題」を解決するAIエージェントパターンです。段階的なコンテキスト検索の最適化により、コード探索におけるRAGライクな検索パイプラインを処理し、トークン使用効率を最適化します。 Iterative-Retrieval은 다중 에이전트 워크플로우에서 서브에이전트가 필요한 컨텍스트를 사전에 결정할 수 없는 ''컨텍스트 문제''를 해결하기 위한 AI 에이전트 패턴입니다. 점진적인 컨텍스트 검색 최적화를 통해 코드 탐색에서 RAG-like 검색 파이프라인을 처리하고 토큰 사용 효율을 최적화합니다. El patrón iterative-retrieval soluciona el ''problema de contexto'' en workflows multiagente, donde los subagentes no pueden predecir qué contexto necesitan. Permite un refinamiento progresivo de la recuperación de contexto, optimizando pipelines tipo RAG para exploración de código. Le patron iterative-retrieval résout le ''problème de contexte'' dans les workflows multi-agents, où les sous-agents ne peuvent prédire le contexte nécessaire. Il permet un raffinement progressif de la récupération de contexte, optimisant les pipelines de type RAG pour l''exploration de code. Das iterative-retrieval Pattern löst das ''Kontextproblem'' in Multi-Agent-Workflows, bei dem Subagenten den benötigten Kontext nicht vorhersagen können. Es ermöglicht eine progressive Verfeinerung der Kontextabfrage und optimiert RAG-ähnliche Pipelines für Code-Exploration. Padrão técnico para refinar progressivamente a recuperação de contexto em agentes de IA. Soluciona o problema de subagentes que não sabem qual contexto precisam antecipadamente, comum em fluxos com Claude Code e MCP. Технический паттерн для постепенного уточнения извлечения контекста в ИИ агентах. Решает проблему суб-агентов, которые не знают, какой контекст им нужен заранее, часто встречается в workflows с Claude Code и MCP. نمط تقني لتحسين استرجاع السياق تدريجيًا في أدوات الذكاء الاصطناعي. يحل مشكلة الأدوات الفرعية التي لا تعرف السياق الذي تحتاجه مقدمًا، شائع في سير العمل مع Claude Code و MCP. what is iterative-retrieval how to use iterative-retrieval pattern solve subagent context problem iterative-retrieval vs traditional RAG iterative-retrieval for MCP iterative-retrieval setup guide Claude code context optimization multi-agent workflow context handling iterative-retrieval install AI agent token usage optimization iterative-retrieval AI代理 多代理工作流上下文问题 子代理代码库上下文 RAG-like检索管道 Claude代码优化 MCP token使用 AI代理渐进式检索 上下文过大错误解决 Solves the subagent context problem in multi-agent workflows Progressively refines context retrieval for agents like Claude Addresses ''context too large'' and ''missing context'' failures Optimizes token usage in AI agent tasks Designed for RAG-like retrieval pipelines for code exploration Activated when spawning subagents needing unpredictable codebase context Iterative-retrieval is an AI agent pattern for progressively refining context retrieval to solve the subagent context problem. It is activated when spawning subagents that need unpredicted codebase context or when encountering context-related failures in agent tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/java-coding-standards', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'java-coding-standards', 61988, 7678, 68, '2026-03-06T03:39:20Z', '2026-03-06T04:18:50.642Z', '253c3ef143330a2901c2b75fd8def3a3f9ec66e6cb1f8fd1e323b803004dd22b', '{"id":"affaan-m/everything-claude-code/java-coding-standards","name":"java-coding-standards","description":{"en":"The java-coding-standards skill provides guidelines for writing clean, readable Java code in Spring Boot services, benefiting developers and teams working with Java 17+.","zh":"Java 编码标准为 Spring Boot 服务提供了一套可读性和可维护性的代码标准，涵盖命名、不可变性、Optional 使用、流、异常、泛型和项目布局等方面","ja":"Java コーディングスタンダードは、Spring Boot サービスに読みやすく保守性の高いコード標準を提供し、命名、不変性、Optional の使用、ストリーム、例外、ジェネリクス、プロジェクトレイアウトなどをカバーする","ko":"Java 코딩 표준은 Spring Boot 서비스에 읽기 쉽고 유지보수가 가능한 코드 표준을 제공하며, 이름 지정, 불변성, Optional 사용, 스트림, 예외, 제네릭스, 프로젝트 레이아웃 등을 다룹니다","es":"Este AI Agent aplica estándares de codificación Java 17+ para servicios Spring Boot, incluyendo convenciones de naming, uso de Optional, streams, manejo de excepciones y estructuración de proyectos con principios de inmutabilidad y claridad.","fr":"Cet Agent IA applique des standards de codage Java 17+ pour les services Spring Boot, incluant les conventions de naming, l''usage d''Optional, les streams, la gestion d''exceptions et la structuration de projets avec principes d''immutabilité et clarté.","de":"Dieser KI-Agent wendet Java 17+ Coding Standards für Spring Boot Services an, inklusive Naming-Konventionen, Optional-Verwendung, Streams, Exception Handling und Projektstrukturierung mit Immutability- und Klarheitsprinzipien.","pt":"Um AI Agent especializado em aplicar padrões de codificação Java modernos (17+) em projetos Spring Boot. Foca em naming consistente, imutabilidade, uso correto de Optional, streams API, tratamento de exceções e estruturação de projetos para melhor legibilidade e manutenibilidade.","ru":"ИИ агент для применения современных стандартов Java (17+) в проектах Spring Boot. Специализируется на соглашениях именования, иммутабельности, правильном использовании Optional, streams API, обработке исключений и структуре проектов для улучшения читаемости кода.","ar":"أداة ذكاء اصطناعي متخصصة في تطبيق معايير كتابة كود جافا الحديثة (17+) في مشاريع Spring Boot. تركز على التسمية المتسقة، الثبات، الاستخدام الصحيح لـ Optional، واجهة streams، معالجة الاستثناءات وهيكلة المشروع لتحسين قابلية القراءة والصيانة."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"java-coding-standards","description":"Java coding standards for Spring Boot services: naming, immutability, Optional usage, streams, exceptions, generics, and project layout.","bodyPreview":"# Java Coding Standards\n\nStandards for readable, maintainable Java (17+) code in Spring Boot services.\n\n## When to Activate\n\n- Writing or reviewing Java code in Spring Boot projects\n- Enforcing naming, immutability, or exception handling conventions\n- Working with records, sealed classes, or pattern matching (Java 17+)\n- Reviewing use of Optional, streams, or generics\n- Structuring packages and project layout\n\n## Core Principles\n\n- Prefer clarity over cleverness\n- Immutable by default; minimize","body":"# Java Coding Standards\n\nStandards for readable, maintainable Java (17+) code in Spring Boot services.\n\n## When to Activate\n\n- Writing or reviewing Java code in Spring Boot projects\n- Enforcing naming, immutability, or exception handling conventions\n- Working with records, sealed classes, or pattern matching (Java 17+)\n- Reviewing use of Optional, streams, or generics\n- Structuring packages and project layout\n\n## Core Principles\n\n- Prefer clarity over cleverness\n- Immutable by default; minimize shared mutable state\n- Fail fast with meaningful exceptions\n- Consistent naming and package structure\n\n## Naming\n\n```java\n// ✅ Classes/Records: PascalCase\npublic class MarketService {}\npublic record Money(BigDecimal amount, Currency currency) {}\n\n// ✅ Methods/fields: camelCase\nprivate final MarketRepository marketRepository;\npublic Market findBySlug(String slug) {}\n\n// ✅ Constants: UPPER_SNAKE_CASE\nprivate static final int MAX_PAGE_SIZE = 100;\n```\n\n## Immutability\n\n```java\n// ✅ Favor records and final fields\npublic record MarketDto(Long id, String name, MarketStatus status) {}\n\npublic class Market {\n  private final Long id;\n  private final String name;\n  // getters only, no setters\n}\n```\n\n## Optional Usage\n\n```java\n// ✅ Return Optional from find* methods\nOptional<Market> market = marketRepository.findBySlug(slug);\n\n// ✅ Map/flatMap instead of get()\nreturn market\n    .map(MarketResponse::from)\n    .orElseThrow(() -> new EntityNotFoundException(\"Market not found\"));\n```\n\n## Streams Best Practices\n\n```java\n// ✅ Use streams for transformations, keep pipelines short\nList<String> names = markets.stream()\n    .map(Market::name)\n    .filter(Objects::nonNull)\n    .toList();\n\n// ❌ Avoid complex nested streams; prefer loops for clarity\n```\n\n## Exceptions\n\n- Use unchecked exceptions for domain errors; wrap technical exceptions with context\n- Create domain-specific exceptions (e.g., `MarketNotFoundException`)\n- Avoid broad `catch (Exception ex)` unless rethrowing/logging centrally\n\n```java\nthrow new MarketNotFoundException(slug);\n```\n\n## Generics and Type Safety\n\n- Avoid raw types; declare generic parameters\n- Prefer bounded generics for reusable utilities\n\n```java\npublic <T extends Identifiable> Map<Long, T> indexById(Collection<T> items) { ... }\n```\n\n## Project Structure (Maven/Gradle)\n\n```\nsrc/main/java/com/example/app/\n  config/\n  controller/\n  service/\n  repository/\n  domain/\n  dto/\n  util/\nsrc/main/resources/\n  application.yml\nsrc/test/java/... (mirrors main)\n```\n\n## Formatting and Style\n\n- Use 2 or 4 spaces consistently (project standard)\n- One public top-level type per file\n- Keep methods short and focused; extract helpers\n- Order members: constants, fields, constructors, public methods, protected, private\n\n## Code Smells to Avoid\n\n- Long parameter lists → use DTO/builders\n- Deep nesting → early returns\n- Magic numbers → named constants\n- Static mutable state → prefer dependency injection\n- Silent catch blocks → log and act or rethrow\n\n## Logging\n\n```java\nprivate static final Logger log = LoggerFactory.getLogger(MarketService.class);\nlog.info(\"fetch_market slug={}\", slug);\nlog.error(\"failed_fetch_market slug={}\", slug, ex);\n```\n\n## Null Handling\n\n- Accept `@Nullable` only when unavoidable; otherwise use `@NonNull`\n- Use Bean Validation (`@NotNull`, `@NotBlank`) on inputs\n\n## Testing Expectations\n\n- JUnit 5 + AssertJ for fluent assertions\n- Mockito for mocking; avoid partial mocks where possible\n- Favor deterministic tests; no hidden sleeps\n\n**Remember**: Keep code intentional, typed, and observable. Optimize for maintainability over micro-optimizations unless proven necessary.\n"},"category":"official","lastSynced":"2026-03-06T04:18:50.642Z","seo":{"title":{"en":"java-coding-standards: Spring Boot Best Practices | AI Ag...","zh":"Java 编码标准配置指南","ja":"Java コーディングスタンダードのベストプラクティス","ko":"Java 코딩 표준 설정 가이드","es":"Guía de Estándares Java Spring Boot con Claude AI","fr":"Guide des Standards Java Spring Boot avec Claude AI","de":"Java Spring Boot Coding Standards Leitfaden mit Claude AI","pt":"Padrões de Codificação Java para Spring Boot: Guia de Mel...","ru":"Стандарты кодирования Java для Spring Boot: руководство п...","ar":"معايير كتابة كود جافا لـ Spring Boot: دليل