INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/java-coding-standards', 'java-coding-standards', 'affaan-m', 'everything-claude-code', 'official', 'java-coding-standards affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The java-coding-standards skill provides guidelines for writing clean, readable Java code in Spring Boot services, benefiting developers and teams working with Java 17+. Java 编码标准为 Spring Boot 服务提供了一套可读性和可维护性的代码标准，涵盖命名、不可变性、Optional 使用、流、异常、泛型和项目布局等方面 Java コーディングスタンダードは、Spring Boot サービスに読みやすく保守性の高いコード標準を提供し、命名、不変性、Optional の使用、ストリーム、例外、ジェネリクス、プロジェクトレイアウトなどをカバーする Java 코딩 표준은 Spring Boot 서비스에 읽기 쉽고 유지보수가 가능한 코드 표준을 제공하며, 이름 지정, 불변성, Optional 사용, 스트림, 예외, 제네릭스, 프로젝트 레이아웃 등을 다룹니다 Este AI Agent aplica estándares de codificación Java 17+ para servicios Spring Boot, incluyendo convenciones de naming, uso de Optional, streams, manejo de excepciones y estructuración de proyectos con principios de inmutabilidad y claridad. Cet Agent IA applique des standards de codage Java 17+ pour les services Spring Boot, incluant les conventions de naming, l''usage d''Optional, les streams, la gestion d''exceptions et la structuration de projets avec principes d''immutabilité et clarté. Dieser KI-Agent wendet Java 17+ Coding Standards für Spring Boot Services an, inklusive Naming-Konventionen, Optional-Verwendung, Streams, Exception Handling und Projektstrukturierung mit Immutability- und Klarheitsprinzipien. Um AI Agent especializado em aplicar padrões de codificação Java modernos (17+) em projetos Spring Boot. Foca em naming consistente, imutabilidade, uso correto de Optional, streams API, tratamento de exceções e estruturação de projetos para melhor legibilidade e manutenibilidade. ИИ агент для применения современных стандартов Java (17+) в проектах Spring Boot. Специализируется на соглашениях именования, иммутабельности, правильном использовании Optional, streams API, обработке исключений и структуре проектов для улучшения читаемости кода. أداة ذكاء اصطناعي متخصصة في تطبيق معايير كتابة كود جافا الحديثة (17+) في مشاريع Spring Boot. تركز على التسمية المتسقة، الثبات، الاستخدام الصحيح لـ Optional، واجهة streams، معالجة الاستثناءات وهيكلة المشروع لتحسين قابلية القراءة والصيانة. java-coding-standards setup guide spring boot best practices java 17+ coding standards how to use java-coding-standards java-coding-standards vs checkstyle java-coding-standards install java coding standards for beginners spring boot service naming conventions java immutability best practices Java 编码标准 Spring Boot 服务 可读性 可维护性 命名约定 不可变性 Optional 使用 流处理 异常处理 泛型使用 Enforces naming conventions for Spring Boot services Promotes immutability by default and minimizes mutable state Provides guidance on using Optional, streams, and generics effectively Supports structuring packages and project layout for Java 17+ projects Helps with exception handling and review of records, sealed classes, and pattern matching java-coding-standards is a set of guidelines for writing readable, maintainable Java code in Spring Boot services, focusing on naming, immutability, and exception handling.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/jpa-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'jpa-patterns', 61988, 7678, 68, '2026-03-06T03:39:20Z', '2026-03-06T04:19:52.827Z', '5302c813a58deb5420e10c6dec4c5f0d036c278f2c494c8243a23326a994063e', '{"id":"affaan-m/everything-claude-code/jpa-patterns","name":"jpa-patterns","description":{"en":"jpa-patterns provides JPA/Hibernate patterns for entity design, relationships, and performance tuning in Spring Boot, benefiting developers and data architects.","zh":"一款专注于 JPA/Hibernate 开发模式的 AI 代理工具，提供实体设计、关系映射、查询优化、事务管理、审计和性能调优的专业指导。帮助开发者在 Spring Boot 中构建高效的数据访问层。","ja":"JPA/Hibernate 開発パターンに特化したAIエージェントツールです。エンティティ設計、リレーションシップマッピング、クエリ最適化、トランザクション管理、監査、パフォーマンスチューニングに関する専門的なガイダンスを提供し、Spring Boot で効率的なデータアクセス層を構築することを支援します。","ko":"JPA/Hibernate 개발 패턴에 특화된 AI 에이전트 도구입니다. 엔티티 설계, 관계 매핑, 쿼리 최적화, 트랜잭션 관리, 감사, 성능 튜닝에 대한 전문적인 지침을 제공하여 Spring Boot에서 효율적인 데이터 액세스 계층을 구축하는 데 도움을 줍니다.","es":"Esta Herramienta de IA proporciona patrones avanzados de JPA/Hibernate para Spring Boot, incluyendo diseño de entidades, optimización de consultas, relaciones y configuración de pooling con HikariCP.","fr":"Cet Outil IA fournit des modèles JPA/Hibernate avancés pour Spring Boot, incluant la conception d''entités, l''optimisation des requêtes, les relations et la configuration du pooling avec HikariCP.","de":"Dieses KI-Tool bietet fortgeschrittene JPA/Hibernate-Patterns für Spring Boot, inklusive Entity-Design, Query-Optimierung, Beziehungen und Pooling-Konfiguration mit HikariCP.","pt":"Padrões JPA/Hibernate para design de entidades, relações e otimização de consultas em Spring Boot.","ru":"Шаблоны JPA/Hibernate для проектирования сущностей, отношений и оптимизации запросов в Spring Boot.","ar":"أنماط JPA/Hibernate لتصميم الكيانات والعلاقات وتحسين الاستفسارات في Spring Boot."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"jpa-patterns","description":"JPA/Hibernate patterns for entity design, relationships, query optimization, transactions, auditing, indexing, pagination, and pooling in Spring Boot.","bodyPreview":"# JPA/Hibernate Patterns\n\nUse for data modeling, repositories, and performance tuning in Spring Boot.\n\n## When to Activate\n\n- Designing JPA entities and table mappings\n- Defining relationships (@OneToMany, @ManyToOne, @ManyToMany)\n- Optimizing queries (N+1 prevention, fetch strategies, projections)\n- Configuring transactions, auditing, or soft deletes\n- Setting up pagination, sorting, or custom repository methods\n- Tuning connection pooling (HikariCP) or second-level caching\n\n## Entity Design\n\n`","body":"# JPA/Hibernate Patterns\n\nUse for data modeling, repositories, and performance tuning in Spring Boot.\n\n## When to Activate\n\n- Designing JPA entities and table mappings\n- Defining relationships (@OneToMany, @ManyToOne, @ManyToMany)\n- Optimizing queries (N+1 prevention, fetch strategies, projections)\n- Configuring transactions, auditing, or soft deletes\n- Setting up pagination, sorting, or custom repository methods\n- Tuning connection pooling (HikariCP) or second-level caching\n\n## Entity Design\n\n```java\n@Entity\n@Table(name = \"markets\", indexes = {\n  @Index(name = \"idx_markets_slug\", columnList = \"slug\", unique = true)\n})\n@EntityListeners(AuditingEntityListener.class)\npublic class MarketEntity {\n  @Id @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  @Column(nullable = false, length = 200)\n  private String name;\n\n  @Column(nullable = false, unique = true, length = 120)\n  private String slug;\n\n  @Enumerated(EnumType.STRING)\n  private MarketStatus status = MarketStatus.ACTIVE;\n\n  @CreatedDate private Instant createdAt;\n  @LastModifiedDate private Instant updatedAt;\n}\n```\n\nEnable auditing:\n```java\n@Configuration\n@EnableJpaAuditing\nclass JpaConfig {}\n```\n\n## Relationships and N+1 Prevention\n\n```java\n@OneToMany(mappedBy = \"market\", cascade = CascadeType.ALL, orphanRemoval = true)\nprivate List<PositionEntity> positions = new ArrayList<>();\n```\n\n- Default to lazy loading; use `JOIN FETCH` in queries when needed\n- Avoid `EAGER` on collections; use DTO projections for read paths\n\n```java\n@Query(\"select m from MarketEntity m left join fetch m.positions where m.id = :id\")\nOptional<MarketEntity> findWithPositions(@Param(\"id\") Long id);\n```\n\n## Repository Patterns\n\n```java\npublic interface MarketRepository extends JpaRepository<MarketEntity, Long> {\n  Optional<MarketEntity> findBySlug(String slug);\n\n  @Query(\"select m from MarketEntity m where m.status = :status\")\n  Page<MarketEntity> findByStatus(@Param(\"status\") MarketStatus status, Pageable pageable);\n}\n```\n\n- Use projections for lightweight queries:\n```java\npublic interface MarketSummary {\n  Long getId();\n  String getName();\n  MarketStatus getStatus();\n}\nPage<MarketSummary> findAllBy(Pageable pageable);\n```\n\n## Transactions\n\n- Annotate service methods with `@Transactional`\n- Use `@Transactional(readOnly = true)` for read paths to optimize\n- Choose propagation carefully; avoid long-running transactions\n\n```java\n@Transactional\npublic Market updateStatus(Long id, MarketStatus status) {\n  MarketEntity entity = repo.findById(id)\n      .orElseThrow(() -> new EntityNotFoundException(\"Market\"));\n  entity.setStatus(status);\n  return Market.from(entity);\n}\n```\n\n## Pagination\n\n```java\nPageRequest page = PageRequest.of(pageNumber, pageSize, Sort.by(\"createdAt\").descending());\nPage<MarketEntity> markets = repo.findByStatus(MarketStatus.ACTIVE, page);\n```\n\nFor cursor-like pagination, include `id > :lastId` in JPQL with ordering.\n\n## Indexing and Performance\n\n- Add indexes for common filters (`status`, `slug`, foreign keys)\n- Use composite indexes matching query patterns (`status, created_at`)\n- Avoid `select *`; project only needed columns\n- Batch writes with `saveAll` and `hibernate.jdbc.batch_size`\n\n## Connection Pooling (HikariCP)\n\nRecommended properties:\n```\nspring.datasource.hikari.maximum-pool-size=20\nspring.datasource.hikari.minimum-idle=5\nspring.datasource.hikari.connection-timeout=30000\nspring.datasource.hikari.validation-timeout=5000\n```\n\nFor PostgreSQL LOB handling, add:\n```\nspring.jpa.properties.hibernate.jdbc.lob.non_contextual_creation=true\n```\n\n## Caching\n\n- 1st-level cache is per EntityManager; avoid keeping entities across transactions\n- For read-heavy entities, consider second-level cache cautiously; validate eviction strategy\n\n## Migrations\n\n- Use Flyway or Liquibase; never rely on Hibernate auto DDL in production\n- Keep migrations idempotent and additive; avoid dropping columns without plan\n\n## Testing Data Access\n\n- Prefer `@DataJpaTest` with Testcontainers to mirror production\n- Assert SQL efficiency using logs: set `logging.level.org.hibernate.SQL=DEBUG` and `logging.level.org.hibernate.orm.jdbc.bind=TRACE` for parameter values\n\n**Remember**: Keep entities lean, queries intentional, and transactions short. Prevent N+1 with fetch strategies and projections, and index for your read/write paths.\n"},"category":"official","lastSynced":"2026-03-06T04:19:52.827Z","seo":{"title":{"en":"jpa-patterns: Spring Boot Data Modeling Setup Guide | AI ...","zh":"JPA/Hibernate 模式最佳实践 - Spring Boot 实体设计与查询优化","ja":"JPA/Hibernate パターン完全ガイド - Spring Boot でのエンティティ設計とクエリ最適化","ko":"JPA/Hibernate 패턴 완벽 가이드 - Spring Boot 엔티티 설계 및 쿼리 최적화","es":"Patrones JPA/Hibernate: Guía de Configuración para Spring...","fr":"Modèles JPA/Hibernate : Guide de Configuration pour Sprin...","de":"JPA/Hibernate Patterns: Setup-Leitfaden für Spring Boot","pt":"Guia de Configuração de Padrões JPA/Hibernate para Spring...","ru":"Настройка шаблонов JPA/Hibernate для Spring Boot: ИИ Агенты","ar":"دليل إعداد أنماط JPA/Hibernate للربط مع Spring Boot"},"description":{"en":"Unlock efficient data management with jpa-patterns. Learn how to optimize entity design, relationships, and queries in Spring Boot. Get started now!","zh":"AI 代理工具，提供 JPA/Hibernate 实体关系设计、N+1 查询预防、事务配置、分页优化和 HikariCP 连接池调优的最佳实践模式。提升 Spring Boot 数据层性能。","ja":"AIエージェントツールが提供する、JPA/Hibernate のエンティティ関係設計、N+1クエリ防止、トランザクション設定、ページネーション最適化、HikariCP 接続プールチューニングのベストプラクティスパターン。Spring Boot データ層のパフォーマンス向上。","ko":"AI 에이전트 도구가 제공하는 JPA/Hibernate 엔티티 관계 설계, N+1 쿼리 방지, 트랜잭션 설정, 페이징 최적화, HikariCP 연결 풀 튜닝을 위한 베스트 프랙티스 패턴. Spring Boot 데이터 계층 성능 향상.","es":"Optimiza Spring Boot con Herramientas de IA para patrones JPA: diseño de entidades, relaciones @OneToMany, prevención N+1, paginación, HikariCP y transacciones.","fr":"Optimisez Spring Boot avec des Outils IA pour modèles JPA : conception d''entités, relations @OneToMany, prévention N+1, pagination, HikariCP et transactions.","de":"Optimieren Sie Spring Boot mit KI-Tools für JPA-Patterns: Entity-Design, @OneToMany-Beziehungen, N+1-Prävention, Paginierung, HikariCP und Transaktionen.","pt":"Aprenda a otimizar o desempenho do seu aplicativo com padrões JPA/Hibernate para Spring Boot, incluindo design de entidades e relações","ru":"Узнайте, как оптимизировать производительность вашего приложения с помощью шаблонов JPA/Hibernate для Spring Boot, включая проектирование сущностей и отношений","ar":"تعلم كيفية تحسين أداء تطبيقك باستخدام أنماط JPA/Hibernate للربط مع Spring Boot، بما في ذلك تصميم الكيانات والعلاقات"},"definition":{"en":"jpa-patterns is a set of guidelines for designing JPA entities, relationships, and optimizing queries in Spring Boot applications.","zh":"jpa-patterns 是一款 AI 代理工具，专为 Spring Boot 开发者提供 JPA 和 Hibernate 的数据建模与性能优化模式。它涵盖实体关系配置、查询获取策略、事务管理、软删除实现、分页处理及连接池调优等核心数据层开发场景。","ja":"jpa-patterns は、Spring Boot 開発者向けに JPA と Hibernate のデータモデリングとパフォーマンス最適化パターンを提供するAIエージェントツールです。エンティティ関係設定、クエリフェッチ戦略、トランザクション管理、ソフトデリート実装、ページネーション処理、接続プールチューニングなどのコアデータ層開発シナリオをカバーします。","ko":"jpa-patterns는 Spring Boot 개발자를 위해 JPA 및 Hibernate의 데이터 모델링 및 성능 최적화 패턴을 제공하는 AI 에이전트 도구입니다. 엔티티 관계 설정, 쿼리 페치 전략, 트랜잭션 관리, 소프트 삭제 구현, 페이징 처리 및 연결 풀 튜닝과 같은 핵심 데이터 계층 개발 시나리오를 다룹니다.","es":"jpa-patterns es una Herramienta de IA especializada en patrones de JPA/Hibernate para Spring Boot. Proporciona guías técnicas para diseño de entidades, relaciones, optimización de consultas, paginación y configuración de transacciones.","fr":"jpa-patterns est un Outil IA spécialisé dans les modèles JPA/Hibernate pour Spring Boot. Il fournit des guides techniques pour la conception d''entités, les relations, l''optimisation des requêtes, la pagination et la configuration des transactions.","de":"jpa-patterns ist ein KI-Tool, das sich auf JPA/Hibernate-Patterns für Spring Boot spezialisiert. Es bietet technische Leitfäden für Entity-Design, Beziehungen, Query-Optimierung, Paginierung und Transaktionskonfiguration.","pt":"Padrões JPA/Hibernate são estruturas de design para entidades e relações em bancos de dados","ru":"Шаблоны JPA/Hibernate - это структуры проектирования для сущностей и отношений в базах данных","ar":"أنماط JPA/Hibernate هي هياكل تصميم للكيانات والعلاقات في قواعد البيانات"},"features":{"en":["Optimizes queries using N+1 prevention, fetch strategies, and projections","Configures transactions, auditing, and soft deletes","Supports pagination, sorting, and custom repository methods","Tunes connection pooling with HikariCP","Implements second-level caching for improved performance","Defines relationships using @OneToMany, @ManyToOne, and @ManyToMany annotations"],"zh":["实体关系映射指导 (@OneToMany, @ManyToOne, @ManyToMany)","N+1 查询问题预防与获取策略优化","Spring Data JPA 事务与审计配置","软删除 (Soft Deletes) 实现模式","分页 (Pagination) 与排序性能优化","HikariCP 连接池配置与调优"],"ja":["エンティティ関係マッピングガイダンス (@OneToMany, @ManyToOne, @ManyToMany)","N+1クエリ問題防止とフェッチ戦略最適化","Spring Data JPA トランザクションと監査設定","ソフトデリート (Soft Deletes) 実装パターン","ページネーション (Pagination) とソートのパフォーマンス最適化","HikariCP 接続プール設定とチューニング"],"ko":["엔티티 관계 매핑 가이드 (@OneToMany, @ManyToOne, @ManyToMany)","N+1 쿼리 문제 방지 및 페치 전략 최적화","Spring Data JPA 트랜잭션 및 감사 설정","소프트 삭제 (Soft Deletes) 구현 패턴","페이징 (Pagination) 및 정렬 성능 최적화","HikariCP 연결 풀 설정 및 튜닝"],"es":["Diseño de entidades JPA y mapeo de tablas","Definición de relaciones (@OneToMany, @ManyToOne, @ManyToMany)","Optimización de consultas con prevención N+1 y estrategias de fetch","Configuración de transacciones y auditoría","Implementación de paginación y métodos de repositorio personalizados","Ajuste de connection pooling con HikariCP y caché de segundo nivel"],"fr":["Conception d''entités JPA et mapping de tables","Définition des relations (@OneToMany, @ManyToOne, @ManyToMany)","Optimisation des requêtes avec prévention N+1 et stratégies de fetch","Configuration des transactions et audit","Implémentation de pagination et méthodes de repository personnalisées","Réglage du connection pooling avec HikariCP et cache de second niveau"],"de":["JPA-Entity-Design und Tabellen-Mapping","Definition von Beziehungen (@OneToMany, @ManyToOne, @ManyToMany)","Query-Optimierung mit N+1-Prävention und Fetch-Strategien","Transaktionskonfiguration und Auditing","Implementierung von Paginierung und benutzerdefinierten Repository-Methoden","Optimierung von Connection Pooling mit HikariCP und Second-Level-Cache"],"pt":["Design de entidades e mapeamento de tabelas","Definição de relações (@OneToMany, @ManyToOne, @ManyToMany)","Otimização de consultas (prevenção de N+1, estratégias de busca, projeções)","Configuração de transações, auditoria e exclusão suave","Configuração de paginação, ordenação e métodos personalizados de repositório"],"ru":["Проектирование сущностей и отображение таблиц","Определение отношений (@OneToMany, @ManyToOne, @ManyToMany)","Оптимизация запросов (предотвращение N+1, стратегии выборки, проекции)","Настройка транзакций, аудита и мягкого удаления","Настройка постраничного вывода, сортировки и пользовательских методов репозитория"],"ar":["تصميم الكيانات و映射 الجداول","تعريف العلاقات (@OneToMany, @ManyToOne, @ManyToMany)","تحسين الاستفسارات (منع N+1, استراتيجيات البحث, المشاريع)","تكوين المعاملات, التدقيق, والحذف اللطيف","تكوين Trangination, الترتيب, والأوامر المخصصة للمخزن"]},"keywords":{"en":["how to use jpa-patterns in Spring Boot","jpa-patterns vs Hibernate","jpa-patterns setup guide","what is jpa-patterns","jpa-patterns alternative to Spring Data JPA","jpa-patterns install and configuration","jpa-patterns best practices for entity design","jpa-patterns performance optimization techniques","jpa-patterns and Spring Boot data modeling"],"zh":["JPA 模式","Hibernate 性能优化","Spring Boot 实体设计","N+1 查询解决","Spring Data JPA 分页","HikariCP 配置","JPA 审计配置","AI 代理开发工具"],"ja":["JPA パターン","Hibernate パフォーマンス最適化","Spring Boot エンティティ設計","N+1クエリ対策","Spring Data JPA ページネーション","HikariCP 設定","JPA 監査設定","AIエージェント 開発ツール"],"ko":["JPA 패턴","Hibernate 성능 최적화","Spring Boot 엔티티 설계","N+1 쿼리 해결","Spring Data JPA 페이징","HikariCP 설정","JPA 감사 설정","AI 에이전트 개발 도구"],"es":["patrones jpa hibernate spring boot","relaciones @OneToMany @ManyToOne","prevención n+1 jpa","optimización consultas jpa","paginación spring data jpa","hikaricp configuración spring boot","auditoría entidades jpa","transacciones spring boot","herramientas ia desarrollo java","mcp claude code"],"fr":["modèles jpa hibernate spring boot","relations @OneToMany @ManyToOne","prévention n+1 jpa","optimisation requêtes jpa","pagination spring data jpa","configuration hikaricp spring boot","audit entités jpa","transactions spring boot","outils ia développement java","mcp claude code"],"de":["jpa hibernate patterns spring boot","@OneToMany @ManyToOne beziehungen","n+1 prävention jpa","query optimierung jpa","paginierung spring data jpa","hikaricp konfiguration spring boot","auditing entity jpa","transaktionen spring boot","ki tools java entwicklung","mcp claude code"],"pt":["jpa patterns","hibernate spring boot","otimização de consultas","design de entidades","relações em jpa","transações em jpa","auditoria em jpa","paginação em jpa"],"ru":["шаблоны jpa","hibernate spring boot","оптимизация запросов","проектирование сущностей","отношения в jpa","транзакции в jpa","аудит в jpa","постраничный вывод в jpa"],"ar":["نماط jpa","hibernate spring boot","تحسين الاستفسارات","تصميم الكيانات","العلاقات في jpa","المعاملات في jpa","التدقيق في jpa","ترانجينेशन في jpa"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Backend Engineering Agents specializing in Spring Boot data layer optimization and complex entity modeling.","zh":"非常适合专注于 Spring Boot 数据层优化和复杂实体建模的后端工程智能体。","ja":"Spring Bootのデータ層最適化と複雑なエンティティモデリングを専門とするバックエンドエンジニアリングエージェントに最適です。","ko":"Spring Boot 데이터 계층 최적화 및 복잡한 엔티티 모델링을 전문으로 하는 백엔드 엔지니어링 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Ingeniería de Backend especializados en optimización de la capa de datos de Spring Boot y modelado de entidades complejas.","fr":"Parfait pour les Agents d''Ingénierie Backend spécialisés dans l''optimisation de la couche de données Spring Boot et la modélisation d''entités complexes.","de":"Perfekt für Backend Engineering Agents, die sich auf die Optimierung der Spring Boot-Datenschicht und die Modellierung komplexer Entitäten spezialisieren.","pt":"Perfeito para Agentes de Engenharia de Backend especializados em otimização da camada de dados Spring Boot e modelagem de entidades complexas.","ru":"Идеально подходит для агентов бэкенд-инжиниринга, специализирующихся на оптимизации уровня данных Spring Boot и сложном моделировании сущностей.","ar":"مثالي لوكلات هندسة الباك إند المتخصصة في تحسين طبقة البيانات في Spring Boot ونمذجة الكيانات المعقدة."},"recommendation":{"en":"Enables agents to architect efficient JPA/Hibernate entity designs, optimize queries to prevent N+1 issues, and configure advanced persistence features like auditing, soft deletes, and HikariCP connection pooling. Provides comprehensive patterns for relationship mapping, transaction management, and performance tuning in Spring Data repositories.","zh":"使智能体能够构建高效的 JPA/Hibernate 实体设计，优化查询以防止 N+1 问题，并配置审计、软删除和 HikariCP 连接池等高级持久化功能。为 Spring Data repositories 中的关系映射、事务管理和性能调优提供全面的模式。","ja":"エージェントが効率的なJPA/Hibernateエンティティ設計を構築し、N+1問題を防ぐためのクエリを最適化し、監査、ソフトデリート、HikariCPコネクションプーリングなどの高度な永続性機能を設定できるようにします。Spring Dataリポジトリにおけるリレーションシップマッピング、トランザクション管理、パフォーマンスチューニングのための包括的なパターンを提供します。","ko":"에이전트가 효율적인 JPA/Hibernate 엔티티 설계를 구성하고, N+1 문제를 방지하기 위해 쿼리를 최적화하며, 감사(Auditing), 소프트 삭제(Soft Delete) 및 HikariCP 연결 풀링과 같은 고급 지속성 기능을 구성할 수 있게 합니다. Spring Data 리포지토리에서 관계 매핑, 트랜잭션 관리 및 성능 튜닝을 위한 포괄적인 패턴을 제공합니다.","es":"Permite a los agentes diseñar arquitecturas eficientes de entidades JPA/Hibernate, optimizar consultas para prevenir problemas N+1 y configurar funciones avanzadas de persistencia como auditoría, eliminaciones suaves y agrupación de conexiones HikariCP. Proporciona patrones completos para el mapeo de relaciones, la gestión de transacciones y la optimización del rendimiento en los repositorios de Spring Data.","fr":"Permet aux agents de concevoir des architectures efficaces d''entités JPA/Hibernate, d''optimiser les requêtes pour éviter les problèmes N+1 et de configurer des fonctionnalités avancées de persistance comme l''audit, les suppressions logiques et le pool de connexions HikariCP. Fournit des modèles complets pour le mappage des relations, la gestion des transactions et l''optimisation des performances dans les référentiels Spring Data.","de":"Ermöglicht Agents, effiziente JPA/Hibernate-Entitätsdesigns zu entwerfen, Abfragen zur Vermeidung von N+1-Problemen zu optimieren und erweiterte Persistenzfunktionen wie Auditing, Soft Deletes und HikariCP Connection Pooling zu konfigurieren. Bietet umfassende Muster für Beziehungsmapping, Transaktionsverwaltung und Leistungsoptimierung in Spring Data Repositories.","pt":"Permite que os agentes arquitetem designs eficientes de entidades JPA/Hibernate, otimizem consultas para prevenir problemas N+1 e configurem recursos avançados de persistência como auditoria, soft deletes e pool de conexões HikariCP. Fornece padrões abrangentes para mapeamento de relacionamentos, gerenciamento de transações e ajuste de desempenho em repositórios Spring Data.","ru":"Позволяет агентам проектировать эффективные модели сущностей JPA/Hibernate, оптимизировать запросы для предотвращения проблем N+1 и настраивать расширенные функции persistence, такие как аудит, мягкое удаление (soft deletes) и пул соединений HikariCP. Предоставляет комплексные шаблоны для сопоставления отношений, управления транзакциями и настройки производительности в репозиториях Spring Data.","ar":"يمكن الوكلات من تصميم هياكل كيانات JPA/Hibernate فعالة، وتحسين الاستعلامات لمنع مشاكل N+1، وتهيئة ميزات الإستدامة المتقدمة مثل التدقيق والحذف الناعم وتجميع اتصالات HikariCP. يوفر أنماطًا شاملة لتعيين العلاقات وإدارة المعاملات وضبط الأداء في مستودعات Spring Data."},"useCases":{"en":["Optimizing query performance with fetch strategies and projections","Implementing auditing and soft delete patterns","Configuring connection pooling and second-level caching","Designing complex entity relationships (@OneToMany, @ManyToMany)","Setting up pagination and custom repository methods"],"zh":["使用获取策略和投影优化查询性能","实现审计和软删除模式","配置连接池和二级缓存","设计复杂的实体关系（@OneToMany, @ManyToMany）","设置分页和自定义存储库方法"],"ja":["フェッチ戦略とプロジェクションを使用したクエリパフォーマンスの最適化","監査とソフトデリートパターンの実装","コネクションプーリングとセカンドレベルキャッシュの設定","複雑なエンティティ関係の設計 (@OneToMany, @ManyToMany)","ページネーションとカスタムリポジトリメソッドの設定"],"ko":["페치 전략(Fetch Strategies)과 프로젝션(Projections)을 사용한 쿼리 성능 최적화","감사(Auditing) 및 소프트 삭제(Soft Delete) 패턴 구현","연결 풀링(Connection Pooling)과 2차 캐싱(Second-Level Caching) 구성","복잡한 엔티티 관계 설계 (@OneToMany, @ManyToMany)","페이징(Pagination) 및 사용자 정의 리포지토리 메서드 설정"],"es":["Optimización del rendimiento de consultas con estrategias de fetch y proyecciones","Implementación de patrones de auditoría y eliminación suave","Configuración de agrupación de conexiones y caché de segundo nivel","Diseño de relaciones de entidades complejas (@OneToMany, @ManyToMany)","Configuración de paginación y métodos de repositorio personalizados"],"fr":["Optimisation des performances des requêtes avec les stratégies de fetch et les projections","Mise en œuvre des modèles d''audit et de suppression logique","Configuration du pool de connexions et du cache de second niveau","Conception de relations d''entités complexes (@OneToMany, @ManyToMany)","Mise en place de la pagination et des méthodes de référentiel personnalisées"],"de":["Optimieren der Abfrageleistung mit Fetch-Strategien und Projections","Implementieren von Auditing- und Soft-Delete-Mustern","Konfigurieren von Connection Pooling und Second-Level-Caching","Entwerfen komplexer Entitätsbeziehungen (@OneToMany, @ManyToMany)","Einrichten von Paginierung und benutzerdefinierten Repository-Methoden"],"pt":["Otimização de desempenho de consulta com estratégias de fetch e projeções","Implementação de padrões de auditoria e soft delete","Configuração de connection pooling e cache de segundo nível","Projetando relacionamentos complexos de entidades (@OneToMany, @ManyToMany)","Configurando paginação e métodos de repositório personalizados"],"ru":["Оптимизация производительности запросов с помощью стратегий выборки (fetch strategies) и проекций","Реализация шаблонов аудита и мягкого удаления (soft delete)","Настройка пула соединений (connection pooling) и кеширования второго уровня","Проектирование сложных связей сущностей (@OneToMany, @ManyToMany)","Настройка пагинации и пользовательских методов репозитория"],"ar":["تحسين أداء الاستعلام باستخدام استراتيجيات جلب البيانات والإسقاطات","تنفيذ أنماط التدقيق والحذف الناعم","تهيئة تجميع الاتصالات والتخزين المؤقت من المستوى الثاني","تصميم علاقات الكيانات المعقدة (@OneToMany, @ManyToMany)","إعداد التقسيم إلى صفحات وطرق المستودعات المخصصة"]},"limitations":{"en":["Spring Boot specific implementation required","Requires existing JPA/Hibernate infrastructure","Database-specific tuning may be needed"],"zh":["需要特定于 Spring Boot 的实现","需要现有的 JPA/Hibernate 基础设施","可能需要进行数据库特定的调优"],"ja":["Spring Boot固有の実装が必要","既存のJPA/Hibernateインフラストラクチャが必要","データベース固有のチューニングが必要な場合がある"],"ko":["Spring Boot 특정 구현이 필요함","기존 JPA/Hibernate 인프라가 필요함","데이터베이스별 튜닝이 필요할 수 있음"],"es":["Requiere implementación específica de Spring Boot","Requiere infraestructura existente de JPA/Hibernate","Puede ser necesario ajustes específicos de la base de datos"],"fr":["Nécessite une implémentation spécifique à Spring Boot","Nécessite une infrastructure JPA/Hibernate existante","Un réglage spécifique à la base de données peut être nécessaire"],"de":["Spring Boot-spezifische Implementierung erforderlich","Bestehende JPA/Hibernate-Infrastruktur erforderlich","Datenbankspezifisches Tuning kann erforderlich sein"],"pt":["Requer implementação específica do Spring Boot","Requer infraestrutura JPA/Hibernate existente","Pode ser necessário ajuste específico do banco de dados"],"ru":["Требуется специфичная реализация для Spring Boot","Требуется существующая инфраструктура JPA/Hibernate","Может потребоваться специфичная для базы данных настройка"],"ar":["يتطلب تنفيذًا مخصصًا لـ Spring Boot","يتطلب بنية تحتية حالية لـ JPA/Hibernate","قد يلزم إجراء ضبط خاص بقاعدة البيانات"]},"version":4},"contentHash":"5302c813a58deb5420e10c6dec4c5f0d036c278f2c494c8243a23326a994063e","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":68}');
