INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/jpa-patterns', 'jpa-patterns', 'affaan-m', 'everything-claude-code', 'official', 'jpa-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity jpa-patterns provides JPA/Hibernate patterns for entity design, relationships, and performance tuning in Spring Boot, benefiting developers and data architects. 一款专注于 JPA/Hibernate 开发模式的 AI 代理工具，提供实体设计、关系映射、查询优化、事务管理、审计和性能调优的专业指导。帮助开发者在 Spring Boot 中构建高效的数据访问层。 JPA/Hibernate 開発パターンに特化したAIエージェントツールです。エンティティ設計、リレーションシップマッピング、クエリ最適化、トランザクション管理、監査、パフォーマンスチューニングに関する専門的なガイダンスを提供し、Spring Boot で効率的なデータアクセス層を構築することを支援します。 JPA/Hibernate 개발 패턴에 특화된 AI 에이전트 도구입니다. 엔티티 설계, 관계 매핑, 쿼리 최적화, 트랜잭션 관리, 감사, 성능 튜닝에 대한 전문적인 지침을 제공하여 Spring Boot에서 효율적인 데이터 액세스 계층을 구축하는 데 도움을 줍니다. Esta Herramienta de IA proporciona patrones avanzados de JPA/Hibernate para Spring Boot, incluyendo diseño de entidades, optimización de consultas, relaciones y configuración de pooling con HikariCP. Cet Outil IA fournit des modèles JPA/Hibernate avancés pour Spring Boot, incluant la conception d''entités, l''optimisation des requêtes, les relations et la configuration du pooling avec HikariCP. Dieses KI-Tool bietet fortgeschrittene JPA/Hibernate-Patterns für Spring Boot, inklusive Entity-Design, Query-Optimierung, Beziehungen und Pooling-Konfiguration mit HikariCP. Padrões JPA/Hibernate para design de entidades, relações e otimização de consultas em Spring Boot. Шаблоны JPA/Hibernate для проектирования сущностей, отношений и оптимизации запросов в Spring Boot. أنماط JPA/Hibernate لتصميم الكيانات والعلاقات وتحسين الاستفسارات في Spring Boot. how to use jpa-patterns in Spring Boot jpa-patterns vs Hibernate jpa-patterns setup guide what is jpa-patterns jpa-patterns alternative to Spring Data JPA jpa-patterns install and configuration jpa-patterns best practices for entity design jpa-patterns performance optimization techniques jpa-patterns and Spring Boot data modeling JPA 模式 Hibernate 性能优化 Spring Boot 实体设计 N+1 查询解决 Spring Data JPA 分页 HikariCP 配置 JPA 审计配置 AI 代理开发工具 Optimizes queries using N+1 prevention, fetch strategies, and projections Configures transactions, auditing, and soft deletes Supports pagination, sorting, and custom repository methods Tunes connection pooling with HikariCP Implements second-level caching for improved performance Defines relationships using @OneToMany, @ManyToOne, and @ManyToMany annotations jpa-patterns is a set of guidelines for designing JPA entities, relationships, and optimizing queries in Spring Boot applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/swiftui-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'swiftui-patterns', 61988, 7678, 68, '2026-03-06T03:39:20Z', '2026-03-06T04:43:11.708Z', 'c27f90145101dd77d64e9f9b70297c4167af26abb8a924f2a91326289bc3ec2c', '{"id":"affaan-m/everything-claude-code/swiftui-patterns","name":"swiftui-patterns","description":{"en":"The swiftui-patterns skill provides modern SwiftUI architecture patterns for building declarative and performant user interfaces on Apple platforms, benefiting iOS and macOS developers.","zh":"SwiftUI Patterns提供现代的iOS/macOS UI架构模式，包括状态管理、视图组合和性能优化","ja":"SwiftUIパターンは、現代のiOS/macOS UIアーキテクチャパターンを提供し、状態管理、ビューコンポジション、パフォーマンス最適化などを含む","ko":"SwiftUI Patterns은 현대적인 iOS/macOS UI 아키텍처 패턴을 제공하며, 상태 관리, 뷰 구성 및 성능 최적화를 포함","es":"Patrones de arquitectura SwiftUI para interfaces de usuario declarativas y performantes, incluyendo gestión de estado y optimización de rendimiento.","fr":"Modèles de conception SwiftUI pour des interfaces utilisateur déclaratives et performantes, comprenant la gestion d''état et l''optimisation des performances.","de":"SwiftUI-Architekturmuster für effiziente und performante Benutzeroberflächen, einschließlich Zustandsverwaltung und Leistungsoptimierung.","pt":"Padrões SwiftUI para construir interfaces do usuário declarativas e performáticas, incluindo gerenciamento de estado e otimização de desempenho","ru":"Шаблоны SwiftUI для создания быстрого и эффективного интерфейса пользователя, включая управление состоянием и оптимизацию производительности","ar":"أنماط SwiftUI لإنشاء واجهات مستخدم إعلانية وأداء عالية، بما في ذلك إدارة الحالة وتحسين الأداء"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"swiftui-patterns","description":"SwiftUI architecture patterns, state management with @Observable, view composition, navigation, performance optimization, and modern iOS/macOS UI best practices.","bodyPreview":"# SwiftUI Patterns\n\nModern SwiftUI patterns for building declarative, performant user interfaces on Apple platforms. Covers the Observation framework, view composition, type-safe navigation, and performance optimization.\n\n## When to Activate\n\n- Building SwiftUI views and managing state (`@State`, `@Observable`, `@Binding`)\n- Designing navigation flows with `NavigationStack`\n- Structuring view models and data flow\n- Optimizing rendering performance for lists and complex layouts\n- Working with env","body":"# SwiftUI Patterns\n\nModern SwiftUI patterns for building declarative, performant user interfaces on Apple platforms. Covers the Observation framework, view composition, type-safe navigation, and performance optimization.\n\n## When to Activate\n\n- Building SwiftUI views and managing state (`@State`, `@Observable`, `@Binding`)\n- Designing navigation flows with `NavigationStack`\n- Structuring view models and data flow\n- Optimizing rendering performance for lists and complex layouts\n- Working with environment values and dependency injection in SwiftUI\n\n## State Management\n\n### Property Wrapper Selection\n\nChoose the simplest wrapper that fits:\n\n| Wrapper | Use Case |\n|---------|----------|\n| `@State` | View-local value types (toggles, form fields, sheet presentation) |\n| `@Binding` | Two-way reference to parent''s `@State` |\n| `@Observable` class + `@State` | Owned model with multiple properties |\n| `@Observable` class (no wrapper) | Read-only reference passed from parent |\n| `@Bindable` | Two-way binding to an `@Observable` property |\n| `@Environment` | Shared dependencies injected via `.environment()` |\n\n### @Observable ViewModel\n\nUse `@Observable` (not `ObservableObject`) — it tracks property-level changes so SwiftUI only re-renders views that read the changed property:\n\n```swift\n@Observable\nfinal class ItemListViewModel {\n    private(set) var items: [Item] = []\n    private(set) var isLoading = false\n    var searchText = \"\"\n\n    private let repository: any ItemRepository\n\n    init(repository: any ItemRepository = DefaultItemRepository()) {\n        self.repository = repository\n    }\n\n    func load() async {\n        isLoading = true\n        defer { isLoading = false }\n        items = (try? await repository.fetchAll()) ?? []\n    }\n}\n```\n\n### View Consuming the ViewModel\n\n```swift\nstruct ItemListView: View {\n    @State private var viewModel: ItemListViewModel\n\n    init(viewModel: ItemListViewModel = ItemListViewModel()) {\n        _viewModel = State(initialValue: viewModel)\n    }\n\n    var body: some View {\n        List(viewModel.items) { item in\n            ItemRow(item: item)\n        }\n        .searchable(text: $viewModel.searchText)\n        .overlay { if viewModel.isLoading { ProgressView() } }\n        .task { await viewModel.load() }\n    }\n}\n```\n\n### Environment Injection\n\nReplace `@EnvironmentObject` with `@Environment`:\n\n```swift\n// Inject\nContentView()\n    .environment(authManager)\n\n// Consume\nstruct ProfileView: View {\n    @Environment(AuthManager.self) private var auth\n\n    var body: some View {\n        Text(auth.currentUser?.name ?? \"Guest\")\n    }\n}\n```\n\n## View Composition\n\n### Extract Subviews to Limit Invalidation\n\nBreak views into small, focused structs. When state changes, only the subview reading that state re-renders:\n\n```swift\nstruct OrderView: View {\n    @State private var viewModel = OrderViewModel()\n\n    var body: some View {\n        VStack {\n            OrderHeader(title: viewModel.title)\n            OrderItemList(items: viewModel.items)\n            OrderTotal(total: viewModel.total)\n        }\n    }\n}\n```\n\n### ViewModifier for Reusable Styling\n\n```swift\nstruct CardModifier: ViewModifier {\n    func body(content: Content) -> some View {\n        content\n            .padding()\n            .background(.regularMaterial)\n            .clipShape(RoundedRectangle(cornerRadius: 12))\n    }\n}\n\nextension View {\n    func cardStyle() -> some View {\n        modifier(CardModifier())\n    }\n}\n```\n\n## Navigation\n\n### Type-Safe NavigationStack\n\nUse `NavigationStack` with `NavigationPath` for programmatic, type-safe routing:\n\n```swift\n@Observable\nfinal class Router {\n    var path = NavigationPath()\n\n    func navigate(to destination: Destination) {\n        path.append(destination)\n    }\n\n    func popToRoot() {\n        path = NavigationPath()\n    }\n}\n\nenum Destination: Hashable {\n    case detail(Item.ID)\n    case settings\n    case profile(User.ID)\n}\n\nstruct RootView: View {\n    @State private var router = Router()\n\n    var body: some View {\n        NavigationStack(path: $router.path) {\n            HomeView()\n                .navigationDestination(for: Destination.self) { dest in\n                    switch dest {\n                    case .detail(let id): ItemDetailView(itemID: id)\n                    case .settings: SettingsView()\n                    case .profile(let id): ProfileView(userID: id)\n                    }\n                }\n        }\n        .environment(router)\n    }\n}\n```\n\n## Performance\n\n### Use Lazy Containers for Large Collections\n\n`LazyVStack` and `LazyHStack` create views only when visible:\n\n```swift\nScrollView {\n    LazyVStack(spacing: 8) {\n        ForEach(items) { item in\n            ItemRow(item: item)\n        }\n    }\n}\n```\n\n### Stable Identifiers\n\nAlways use stable, unique IDs in `ForEach` — avoid using array indices:\n\n```swift\n// Use Identifiable conformance or explicit id\nForEach(items, id: \\.stableID) { item in\n    ItemRow(item: item)\n}\n```\n\n### Avoid Expensive Work in body\n\n- Never perform I/O, network calls, or heavy computation inside `body`\n- Use `.task {}` for async work — it cancels automatically when the view disappears\n- Use `.sensoryFeedback()` and `.geometryGroup()` sparingly in scroll views\n- Minimize `.shadow()`, `.blur()`, and `.mask()` in lists — they trigger offscreen rendering\n\n### Equatable Conformance\n\nFor views with expensive bodies, conform to `Equatable` to skip unnecessary re-renders:\n\n```swift\nstruct ExpensiveChartView: View, Equatable {\n    let dataPoints: [DataPoint] // DataPoint must conform to Equatable\n\n    static func == (lhs: Self, rhs: Self) -> Bool {\n        lhs.dataPoints == rhs.dataPoints\n    }\n\n    var body: some View {\n        // Complex chart rendering\n    }\n}\n```\n\n## Previews\n\nUse `#Preview` macro with inline mock data for fast iteration:\n\n```swift\n#Preview(\"Empty state\") {\n    ItemListView(viewModel: ItemListViewModel(repository: EmptyMockRepository()))\n}\n\n#Preview(\"Loaded\") {\n    ItemListView(viewModel: ItemListViewModel(repository: PopulatedMockRepository()))\n}\n```\n\n## Anti-Patterns to Avoid\n\n- Using `ObservableObject` / `@Published` / `@StateObject` / `@EnvironmentObject` in new code — migrate to `@Observable`\n- Putting async work directly in `body` or `init` — use `.task {}` or explicit load methods\n- Creating view models as `@State` inside child views that don''t own the data — pass from parent instead\n- Using `AnyView` type erasure — prefer `@ViewBuilder` or `Group` for conditional views\n- Ignoring `Sendable` requirements when passing data to/from actors\n\n## References\n\nSee skill: `swift-actor-persistence` for actor-based persistence patterns.\nSee skill: `swift-protocol-di-testing` for protocol-based DI and testing with Swift Testing.\n"},"category":"official","lastSynced":"2026-03-06T04:43:11.708Z","seo":{"title":{"en":"swiftui-patterns: Mastering Modern iOS/macOS UI Best Prac...","zh":"SwiftUI Patterns Setup Guide - AIエージェント集成","ja":"SwiftUI パターン ベストプラクティス - AIエージェントとの連携","ko":"SwiftUI Patterns 설정 가이드 - AI 에이전트와의 통합","es":"Guía de patrones SwiftUI para interfaces de usuario decla...","fr":"Meilleures pratiques de conception SwiftUI pour les inter...","de":"SwiftUI-Muster-Setup für effiziente Benutzeroberflächen","pt":"Guia de Configuração de Padrões SwiftUI para Desenvolvedores","ru":"Настройка шаблонов SwiftUI: лучшие практики для ИИ Агентов","ar":"دليل إعداد أنماط SwiftUI لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient SwiftUI development with expert patterns for state management, view composition, and performance optimization - get started now!","zh":"学习使用SwiftUI Patterns构建高性能的Apple平台UI，包括@Observable、视图组合和导航","ja":"SwiftUIパターンを使用して、高パフォーマンスのAppleプラットフォームUIを構築する方法を学ぶ","ko":"SwiftUI Patterns을 사용하여 고성능의 Apple 플랫폼 UI를 구축하는 방법을 배우세요","es":"Aprende patrones de arquitectura SwiftUI, gestión de estado con @Observable y optimización de rendimiento para interfaces de usuario en Apple","fr":"Découvrez les modèles de conception SwiftUI, la gestion d''état avec @Observable et l''optimisation des performances pour les interfaces utilisateur sur Apple","de":"Erkunden Sie SwiftUI-Architekturmuster, Zustandsverwaltung mit @Observable und Leistungsoptimierung für Benutzeroberflächen auf Apple-Plattformen","pt":"Aprenda a criar interfaces do usuário declarativas e performáticas com padrões SwiftUI, incluindo gerenciamento de estado com @Observable e otimização de des...","ru":"Изучите современные шаблоны SwiftUI для создания быстрого и эффективного интерфейса пользователя, включая управление состоянием с @Observable и оптимизацию п...","ar":"تعلم كيفية إنشاء واجهات مستخدم إعلانية وأداء عالية باستخدام أنماط SwiftUI، بما في ذلك إدارة الحالة مع @Observable وتحسين الأداء"},"definition":{"en":"swiftui-patterns is a set of modern SwiftUI architecture patterns for building efficient and scalable user interfaces on Apple platforms.","zh":"SwiftUI Patterns是用于构建Apple平台UI的现代架构模式","ja":"SwiftUIパターンは、AppleプラットフォームのUIを構築するための現代のアーキテクチャパターン","ko":"SwiftUI Patterns은 Apple 플랫폼의 UI를 구축하기 위한 현대적인 아키텍처 패턴","es":"SwiftUI-Patrones son modelos de arquitectura para interfaces de usuario en Apple, que utilizan @Observable para la gestión de estado","fr":"Les modèles de conception SwiftUI sont des modèles d''architecture pour les interfaces utilisateur sur Apple, utilisant @Observable pour la gestion d''état","de":"SwiftUI-Muster sind Architekturmuster für Benutzeroberflächen auf Apple-Plattformen, die @Observable für die Zustandsverwaltung verwenden","pt":"Padrões SwiftUI são práticas de arquitetura para criar interfaces do usuário declarativas e performáticas em plataformas Apple","ru":"Шаблоны SwiftUI - это архитектурные паттерны для создания быстрого и эффективного интерфейса пользователя на платформах Apple","ar":"أنماط SwiftUI هي ممارسات هندسية لإنشاء واجهات مستخدم إعلانية وأداء عالية على منصات Apple"},"features":{"en":["Utilizes @Observable for state management","Supports view composition for declarative UI design","Enables type-safe navigation with NavigationStack","Optimizes rendering performance for lists and complex layouts","Works with environment variables for flexible data flow"],"zh":["使用@Observable进行状态管理","视图组合和导航","性能优化和渲染","支持NavigationStack","现代iOS/macOS UI最佳实践"],"ja":["状態管理のための@Observableの使用","ビューコンポジションとナビゲーション","パフォーマンス最適化とレンダリング","NavigationStackのサポート","現代のiOS/macOS UIのベストプラクティス"],"ko":["상태 관리를 위한 @Observable 사용","뷰 구성 및导航","성능 최적화 및 렌더링","NavigationStack 지원","현대적인 iOS/macOS UI 최적實踐"],"es":["Patrones de arquitectura SwiftUI para interfaces de usuario declarativas","Gestión de estado con @Observable y @Binding","Composición de vistas y navegación con NavigationStack","Optimización de rendimiento para listas y diseños complejos","Integración con el entorno de trabajo de SwiftUI"],"fr":["Modèles de conception SwiftUI pour les interfaces utilisateur déclaratives","Gestion d''état avec @Observable et @Binding","Composition de vues et navigation avec NavigationStack","Optimisation des performances pour les listes et les conceptions complexes","Intégration avec l''environnement de travail de SwiftUI"],"de":["SwiftUI-Architekturmuster für effiziente Benutzeroberflächen","Zustandsverwaltung mit @Observable und @Binding","Ansichtszusammensetzung und Navigation mit NavigationStack","Leistungsoptimierung für Listen und komplexe Layouts","Integration mit der Arbeitsumgebung von SwiftUI"],"pt":["Gerenciamento de estado com @Observable","Composição de views","Navegação com NavigationStack","Otimização de desempenho para listas e layouts complexos","Trabalho com env"],"ru":["Управление состоянием с @Observable","Композиция представлений","Навигация с NavigationStack","Оптимизация производительности для списков и сложных макетов","Работа с env"],"ar":["إدارة الحالة مع @Observable","تركيب العروض","التنقل مع NavigationStack","تحسين الأداء للقوائم والتصاميم المعقدة","العمل مع env"]},"keywords":{"en":["how to use swiftui-patterns","swiftui-patterns best practices","swiftui-patterns alternative","swiftui-patterns vs competitor","swiftui-patterns install","swiftui-patterns setup guide","what is swiftui-patterns","swiftui-patterns tutorial","swiftui-patterns performance optimization"],"zh":["SwiftUI Patterns","AIエージェント","状态管理","视图组合","导航","性能优化","Apple平台UI","iOS开发","macOS开发"],"ja":["SwiftUIパターン","AIエージェント","状態管理","ビューコンポジション","ナビゲーション","パフォーマンス最適化","AppleプラットフォームUI","iOS開発","macOS開発"],"ko":["SwiftUI Patterns","AI 에이전트","상태 관리","뷰 구성","导航","성능 최적화","Apple 플랫폼 UI","iOS 개발","macOS 개발"],"es":["patrones swiftui","arquitectura swiftui","gestión de estado en swiftui","optimización de rendimiento en swiftui","navegación en swiftui","diseño de interfaces de usuario en apple","herramientas de desarrollo de swiftui","Agente de inteligencia artificial para desarrolladores"],"fr":["modèles de conception swiftui","architecture swiftui","gestion d''état dans swiftui","optimisation des performances dans swiftui","navigation dans swiftui","conception d''interfaces utilisateur sur apple","outils de développement de swiftui","Outil d''intelligence artificielle pour les développeurs"],"de":["swiftui-muster","swiftui-architektur","zustandsverwaltung in swiftui","leistungsoptimierung in swiftui","navigation in swiftui","benutzeroberflächen-design auf apple-plattformen","entwicklungstools für swiftui","Künstliche Intelligenz-Tool für Entwickler"],"pt":["padrões SwiftUI","gerenciamento de estado","composição de views","navegação","otimização de desempenho","desenvolvimento iOS","desenvolvimento macOS","ferramentas de desenvolvimento","AI Agents","ИИ Агенты"],"ru":["шаблоны SwiftUI","управление состоянием","композиция представлений","навигация","оптимизация производительности","разработка iOS","разработка macOS","инструменты разработки","ИИ Агенты","AI Agents"],"ar":["أنماط SwiftUI","إدارة الحالة","تركيب العروض","التنقل","تحسين الأداء","تطوير iOS","تطوير macOS","أدوات التطوير","أدوات الذكاء الاصطناعي","AI Agents"]}},"agentAnalysis":{"suitability":{"en":"Perfect for iOS/macOS Development Agents needing advanced SwiftUI architecture patterns and state management capabilities.","zh":"非常适合需要高级SwiftUI架构模式和状态管理功能的iOS/macOS开发代理。","ja":"iOS/macOS開発エージェントが高度なSwiftUIアーキテクチャパターンと状態管理機能を必要とする場合に最適です。","ko":"고급 SwiftUI 아키텍처 패턴과 상태 관리 기능이 필요한 iOS/macOS 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo para iOS/macOS que necesitan patrones avanzados de arquitectura SwiftUI y capacidades de gestión de estado.","fr":"Idéal pour les agents de développement iOS/macOS nécessitant des modèles d''architecture SwiftUI avancés et des capacités de gestion d''état.","de":"Ideal für iOS/macOS-Entwicklungsagenten, die fortgeschrittene SwiftUI-Architekturmuster und State-Management-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento do iOS/macOS que necessitam de padrões de arquitetura avançados do SwiftUI e capacidades de gerenciamento de estado.","ru":"Идеально подходит для агентов разработки iOS/macOS, которым необходимы продвинутые шаблоны архитектуры SwiftUI и возможности управления состоянием.","ar":"مثالي لعمليات تطوير iOS/macOS التي تحتاج إلى أنماط معمارية متقدمة من SwiftUI وقدرات إدارة الحالة."},"recommendation":{"en":"Empowers agents to design declarative, performant user interfaces on Apple platforms using the Observation framework, view composition, type-safe navigation, and performance optimization techniques with @Observable, @State, and @Binding.","zh":"赋予代理设计声明式的、在Apple平台上具有高性能的用户界面，使用Observation框架、视图组合、类型安全导航和@Observable、@State、@Binding的性能优化技术。","ja":"エージェントがAppleプラットフォーム上で宣言的で高性能なユーザーインターフェイスを設計できるようにすることで、Observationフレームワーク、ビューの組み合わせ、型安全なナビゲーション、および@Observable、@State、@Bindingのパフォーマンス最適化技術を使用します。","ko":"에이전트가 Apple 플랫폼에서 선언적이고 고성능의 사용자 인터페이스를 설계할 수 있도록하여 Observation 프레임워크, 뷰 구성, 타입 안전한 내비게이션 및 @Observable, @State, @Binding의 성능 최적화 기술을 사용합니다.","es":"Permite a los agentes diseñar interfaces de usuario declarativas y de alto rendimiento en las plataformas de Apple utilizando el framework Observation, la composición de vistas, la navegación type-safe y técnicas de optimización del rendimiento con @Observable, @State y @Binding.","fr":"Permet aux agents de concevoir des interfaces utilisateur déclaratives et performantes sur les plateformes Apple en utilisant le framework Observation, la composition de vues, la navigation type-safe et les techniques d''optimisation des performances avec @Observable, @State et @Binding.","de":"Ermöglicht Agenten das Entwerfen deklarativer, leistungsstarker Benutzeroberflächen auf Apple-Plattformen unter Verwendung des Observation-Frameworks, View Composition, Type-Safe Navigation und Leistungsoptimierungstechniken mit @Observable, @State und @Binding.","pt":"Habilita os agentes a projetar interfaces de usuário declarativas e de alto desempenho nas plataformas Apple usando o framework Observation, composição de exibição, navegação segura de tipo e técnicas de otimização de desempenho com @Observable, @State e @Binding.","ru":"Наделяет агентов возможностью проектировать декларативные и высокопроизводительные пользовательские интерфейсы на платформах Apple с помощью фреймворка Observation, композиции представлений, типобезопасной навигации и методов оптимизации производительности с @Observable, @State и @Binding.","ar":"تمكن الوكلاء من تصميم واجهات مستخدم اعلانية وذات أداء عالي على منصات شركة Apple باستخدام إطار المراقبة وتركيبة العرض والملاحة الآمنة من النوع وتقنيات تحسين الأداء مع @Observable و @State و @Binding."},"useCases":{"en":["Building and managing complex SwiftUI views with @State and @Observable","Designing and optimizing navigation flows with NavigationStack","Structuring view models and data flow for improved performance","Optimizing rendering performance for lists and complex layouts"],"zh":["使用@State和@Observable构建和管理复杂的SwiftUI视图","使用NavigationStack设计和优化导航流程","为提高性能而结构化视图模型和数据流","优化列表和复杂布局的渲染性能"],"ja":["@Stateと@Observableを使用して複雑なSwiftUIビューを構築して管理する","NavigationStackを使用してナビゲーションフローを設計して最適化する","パフォーマンスを向上させるためにビューモデルとデータフローを構造化する","リストと複雑なレイアウトのレンダリングパフォーマンスを最適化する"],"ko":["@State와 @Observable을 사용하여 복잡한 SwiftUI 뷰를 구축하고 관리하는 것","NavigationStack를 사용하여 내비게이션 흐름을 설계하고 최적화하는 것","성능을 향상시키기 위해 뷰 모델과 데이터 흐름을 구조화하는 것","리스트와 복잡한 레이아웃의 렌더링 성능을 최적화하는 것"],"es":["Construcción y gestión de vistas SwiftUI complejas con @State y @Observable","Diseño y optimización de flujos de navegación con NavigationStack","Estructuración de modelos de vista y flujo de datos para mejorar el rendimiento","Optimización del rendimiento de renderizado para listas y diseños complejos"],"fr":["Construction et gestion de vues SwiftUI complexes avec @State et @Observable","Conception et optimisation des flux de navigation avec NavigationStack","Structuration des modèles de vue et du flux de données pour améliorer les performances","Optimisation des performances de rendu pour les listes et les mises en page complexes"],"de":["Erstellen und Verwalten komplexer SwiftUI-Views mit @State und @Observable","Entwerfen und Optimieren von Navigationsabläufen mit NavigationStack","Strukturierung von View Models und Datenfluss für verbesserte Leistung","Optimieren der Rendering-Leistung für Listen und komplexe Layouts"],"pt":["Construir e gerenciar vistas complexas do SwiftUI com @State e @Observable","Projetar e otimizar fluxos de navegação com NavigationStack","Estruturar modelos de vista e fluxo de dados para melhorar o desempenho","Otimizar o desempenho de renderização para listas e layouts complexos"],"ru":["Создание и управление сложными представлениями SwiftUI с @State и @Observable","Проектирование и оптимизация потоков навигации с NavigationStack","Структуризация моделей представления и потока данных для улучшения производительности","Оптимизация производительности рендеринга для списков и сложных компоновок"],"ar":["بناء وإدارة معرضات معقدة من SwiftUI مع @State و @Observable","تصميم وتحسين تدفقات الملاحة مع NavigationStack","هيكلة نماذج العرض وتدفق البيانات لتحسين الأداء","تحسين أداء العرض للقوائم والتنسيقات المعقدة"]},"limitations":{"en":["Requires knowledge of Swift programming language","Limited to Apple platforms (iOS, macOS)"],"zh":["需要Swift编程语言的知识","仅限于Apple平台（iOS，macOS）"],"ja":["Swiftプログラミング言語の知識が必要","Appleプラットフォーム（iOS、macOS）のみ"],"ko":["Swift 프로그래밍 언어에 대한 지식이 필요함","Apple 플랫폼（iOS, macOS）에만 제한됨"],"es":["Requiere conocimientos del lenguaje de programación Swift","Limitado a las plataformas de Apple (iOS, macOS)"],"fr":["Nécessite une connaissance du langage de programmation Swift","Limité aux plateformes Apple (iOS, macOS)"],"de":["Erfordert Kenntnisse der Programmiersprache Swift","Beschränkt auf Apple-Plattformen (iOS, macOS)"],"pt":["Exige conhecimento da linguagem de programação Swift","Limitado às plataformas Apple (iOS, macOS)"],"ru":["Требует знания языка программирования Swift","Ограничен платформами Apple (iOS, macOS)"],"ar":["يتطلب معرفة لغة برمجة Swift","محدود بمنصات شركة Apple (iOS, macOS)"]},"version":4},"contentHash":"c27f90145101dd77d64e9f9b70297c4167af26abb8a924f2a91326289bc3ec2c","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":68}');
