INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/swiftui-patterns', 'swiftui-patterns', 'affaan-m', 'everything-claude-code', 'official', 'swiftui-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The swiftui-patterns skill provides modern SwiftUI architecture patterns for building declarative and performant user interfaces on Apple platforms, benefiting iOS and macOS developers. SwiftUI Patterns提供现代的iOS/macOS UI架构模式，包括状态管理、视图组合和性能优化 SwiftUIパターンは、現代のiOS/macOS UIアーキテクチャパターンを提供し、状態管理、ビューコンポジション、パフォーマンス最適化などを含む SwiftUI Patterns은 현대적인 iOS/macOS UI 아키텍처 패턴을 제공하며, 상태 관리, 뷰 구성 및 성능 최적화를 포함 Patrones de arquitectura SwiftUI para interfaces de usuario declarativas y performantes, incluyendo gestión de estado y optimización de rendimiento. Modèles de conception SwiftUI pour des interfaces utilisateur déclaratives et performantes, comprenant la gestion d''état et l''optimisation des performances. SwiftUI-Architekturmuster für effiziente und performante Benutzeroberflächen, einschließlich Zustandsverwaltung und Leistungsoptimierung. Padrões SwiftUI para construir interfaces do usuário declarativas e performáticas, incluindo gerenciamento de estado e otimização de desempenho Шаблоны SwiftUI для создания быстрого и эффективного интерфейса пользователя, включая управление состоянием и оптимизацию производительности أنماط SwiftUI لإنشاء واجهات مستخدم إعلانية وأداء عالية، بما في ذلك إدارة الحالة وتحسين الأداء how to use swiftui-patterns swiftui-patterns best practices swiftui-patterns alternative swiftui-patterns vs competitor swiftui-patterns install swiftui-patterns setup guide what is swiftui-patterns swiftui-patterns tutorial swiftui-patterns performance optimization SwiftUI Patterns AIエージェント 状态管理 视图组合 导航 性能优化 Apple平台UI iOS开发 macOS开发 Utilizes @Observable for state management Supports view composition for declarative UI design Enables type-safe navigation with NavigationStack Optimizes rendering performance for lists and complex layouts Works with environment variables for flexible data flow swiftui-patterns is a set of modern SwiftUI architecture patterns for building efficient and scalable user interfaces on Apple platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/skills/agents-sdk', 'official', 'cloudflare', 'skills', 'cloudflare/skills', 'agents-sdk', 535, 66, 68, '2026-03-06T05:33:24Z', '2026-03-06T05:51:38.651Z', '007d6ccf85808a6c779f5b058b1be970d77785000071cb27a55a5f580fbc845b', '{"id":"cloudflare/skills/agents-sdk","name":"agents-sdk","description":{"en":"The agents-sdk enables developers to build AI agents on Cloudflare Workers, supporting state management, callable RPC, and Workflows integration. Ideal for creating real-time applications and scheduled tasks.","zh":"Cloudflare Agents SDK允许开发人员构建AI代理，实现状态管理、可调用RPC和工作流集成","ja":"Cloudflare Agents SDKは、開発者がAIエージェントを構築し、状態管理、callable RPC、ワークフロー統合を実現できるようにする","ko":"Cloudflare Agents SDK는 개발자가 AI 에이전트를 구축하고 상태 관리, callable RPC, 워크플로 통합을 구현할 수 있도록 해줍니다","es":"El agents-sdk permite a los desarrolladores crear agentes de inteligencia artificial en Cloudflare Workers. Incluye características como gestión de estado, flujos de trabajo y aplicaciones de WebSocket","fr":"L''agents-sdk permet aux développeurs de créer des agents d''intelligence artificielle sur Cloudflare Workers. Il comprend des fonctionnalités telles que la gestion d''état, les flux de travail et les applications WebSocket","de":"Das agents-sdk ermöglicht es Entwicklern, künstliche Intelligenz-Agenten auf Cloudflare Workers zu erstellen. Es umfasst Funktionen wie Zustandsverwaltung, Workflows und WebSocket-Anwendungen","pt":"O Agents SDK permite criar agentes de inteligência artificial com Cloudflare Workers, incluindo gerenciamento de estado e integração com Workflows.","ru":"Agents SDK позволяет создавать ИИ агентов с Cloudflare Workers, включая управление состоянием и интеграцию с Workflows.","ar":"يسمح Agents SDK بإنشاء أداة إدارة ذكية مع Cloudflare Workers، بما في ذلك إدارة الحالة ودمجها مع Workflows"},"owner":"cloudflare","repo":"skills","repoPath":"cloudflare/skills","stars":535,"forks":66,"updatedAt":"2026-03-06T05:33:24Z","topics":["agents","cloudflare","skills","workers"],"skillMd":{"name":"agents-sdk","description":"Build AI agents on Cloudflare Workers using the Agents SDK. Load when creating stateful agents, durable workflows, real-time WebSocket apps, scheduled tasks, MCP servers, or chat applications. Covers Agent class, state management, callable RPC, Workflows integration, and React hooks. Biases towards retrieval from Cloudflare docs over pre-trained knowledge.","bodyPreview":"# Cloudflare Agents SDK\n\nYour knowledge of the Agents SDK may be outdated. **Prefer retrieval over pre-training** for any Agents SDK task.\n\n## Retrieval Sources\n\nFetch current docs from `https://github.com/cloudflare/agents/tree/main/docs` before implementing.\n\n| Topic | Doc | Use for |\n|-------|-----|---------|\n| Getting started | `docs/getting-started.md` | First agent, project setup |\n| State | `docs/state.md` | `setState`, `validateStateChange`, persistence |\n| Routing | `docs/routing.md` |","body":"# Cloudflare Agents SDK\n\nYour knowledge of the Agents SDK may be outdated. **Prefer retrieval over pre-training** for any Agents SDK task.\n\n## Retrieval Sources\n\nFetch current docs from `https://github.com/cloudflare/agents/tree/main/docs` before implementing.\n\n| Topic | Doc | Use for |\n|-------|-----|---------|\n| Getting started | `docs/getting-started.md` | First agent, project setup |\n| State | `docs/state.md` | `setState`, `validateStateChange`, persistence |\n| Routing | `docs/routing.md` | URL patterns, `routeAgentRequest`, `basePath` |\n| Callable methods | `docs/callable-methods.md` | `@callable`, RPC, streaming, timeouts |\n| Scheduling | `docs/scheduling.md` | `schedule()`, `scheduleEvery()`, cron |\n| Workflows | `docs/workflows.md` | `AgentWorkflow`, durable multi-step tasks |\n| HTTP/WebSockets | `docs/http-websockets.md` | Lifecycle hooks, hibernation |\n| Email | `docs/email.md` | Email routing, secure reply resolver |\n| MCP client | `docs/mcp-client.md` | Connecting to MCP servers |\n| MCP server | `docs/mcp-servers.md` | Building MCP servers with `McpAgent` |\n| Client SDK | `docs/client-sdk.md` | `useAgent`, `useAgentChat`, React hooks |\n| Human-in-the-loop | `docs/human-in-the-loop.md` | Approval flows, pausing workflows |\n| Resumable streaming | `docs/resumable-streaming.md` | Stream recovery on disconnect |\n\nCloudflare docs: https://developers.cloudflare.com/agents/\n\n## Capabilities\n\nThe Agents SDK provides:\n\n- **Persistent state** - SQLite-backed, auto-synced to clients\n- **Callable RPC** - `@callable()` methods invoked over WebSocket\n- **Scheduling** - One-time, recurring (`scheduleEvery`), and cron tasks\n- **Workflows** - Durable multi-step background processing via `AgentWorkflow`\n- **MCP integration** - Connect to MCP servers or build your own with `McpAgent`\n- **Email handling** - Receive and reply to emails with secure routing\n- **Streaming chat** - `AIChatAgent` with resumable streams\n- **React hooks** - `useAgent`, `useAgentChat` for client apps\n\n## FIRST: Verify Installation\n\n```bash\nnpm ls agents  # Should show agents package\n```\n\nIf not installed:\n```bash\nnpm install agents\n```\n\n## Wrangler Configuration\n\n```jsonc\n{\n  \"durable_objects\": {\n    \"bindings\": [{ \"name\": \"MyAgent\", \"class_name\": \"MyAgent\" }]\n  },\n  \"migrations\": [{ \"tag\": \"v1\", \"new_sqlite_classes\": [\"MyAgent\"] }]\n}\n```\n\n## Agent Class\n\n```typescript\nimport { Agent, routeAgentRequest, callable } from \"agents\";\n\ntype State = { count: number };\n\nexport class Counter extends Agent<Env, State> {\n  initialState = { count: 0 };\n\n  // Validation hook - runs before state persists (sync, throwing rejects the update)\n  validateStateChange(nextState: State, source: Connection | \"server\") {\n    if (nextState.count < 0) throw new Error(\"Count cannot be negative\");\n  }\n\n  // Notification hook - runs after state persists (async, non-blocking)\n  onStateUpdate(state: State, source: Connection | \"server\") {\n    console.log(\"State updated:\", state);\n  }\n\n  @callable()\n  increment() {\n    this.setState({ count: this.state.count + 1 });\n    return this.state.count;\n  }\n}\n\nexport default {\n  fetch: (req, env) => routeAgentRequest(req, env) ?? new Response(\"Not found\", { status: 404 })\n};\n```\n\n## Routing\n\nRequests route to `/agents/{agent-name}/{instance-name}`:\n\n| Class | URL |\n|-------|-----|\n| `Counter` | `/agents/counter/user-123` |\n| `ChatRoom` | `/agents/chat-room/lobby` |\n\nClient: `useAgent({ agent: \"Counter\", name: \"user-123\" })`\n\n## Core APIs\n\n| Task | API |\n|------|-----|\n| Read state | `this.state.count` |\n| Write state | `this.setState({ count: 1 })` |\n| SQL query | `` this.sql`SELECT * FROM users WHERE id = ${id}` `` |\n| Schedule (delay) | `await this.schedule(60, \"task\", payload)` |\n| Schedule (cron) | `await this.schedule(\"0 * * * *\", \"task\", payload)` |\n| Schedule (interval) | `await this.scheduleEvery(30, \"poll\")` |\n| RPC method | `@callable() myMethod() { ... }` |\n| Streaming RPC | `@callable({ streaming: true }) stream(res) { ... }` |\n| Start workflow | `await this.runWorkflow(\"ProcessingWorkflow\", params)` |\n\n## React Client\n\n```tsx\nimport { useAgent } from \"agents/react\";\n\nfunction App() {\n  const [state, setLocalState] = useState({ count: 0 });\n\n  const agent = useAgent({\n    agent: \"Counter\",\n    name: \"my-instance\",\n    onStateUpdate: (newState) => setLocalState(newState),\n    onIdentity: (name, agentType) => console.log(`Connected to ${name}`)\n  });\n\n  return (\n    <button onClick={() => agent.setState({ count: state.count + 1 })}>\n      Count: {state.count}\n    </button>\n  );\n}\n```\n\n## References\n\n- **[references/workflows.md](references/workflows.md)** - Durable Workflows integration\n- **[references/callable.md](references/callable.md)** - RPC methods, streaming, timeouts\n- **[references/state-scheduling.md](references/state-scheduling.md)** - State persistence, scheduling\n- **[references/streaming-chat.md](references/streaming-chat.md)** - AIChatAgent, resumable streams\n- **[references/mcp.md](references/mcp.md)** - MCP server integration\n- **[references/email.md](references/email.md)** - Email routing and handling\n- **[references/codemode.md](references/codemode.md)** - Code Mode (experimental)\n"},"category":"official","lastSynced":"2026-03-06T05:51:38.651Z","seo":{"title":{"en":"agents-sdk: Setup Guide for AI Agents | Cloudflare Workers","zh":"AIエージェント开发指南：Cloudflare Agents SDK Setup Guide","ja":"AIエージェントの構築：Cloudflare Agents SDK ベストプラクティス","ko":"AI 에이전트 설정 가이드: Cloudflare Agents SDK","es":"Guía de configuración de agents-sdk para desarrolladores","fr":"Guide de démarrage rapide pour agents-sdk","de":"Einrichtungsleitfaden für agents-sdk-Entwickler","pt":"Guia de Configuração do Agents SDK para Ferramentas de In...","ru":"ИИ Агенты: Руководство по Настройке Agents SDK","ar":"دليل إعداد أداة Agents SDK للأدوات الذكية"},"description":{"en":"Unlock the full potential of Cloudflare Workers with the agents-sdk. Learn how to build stateful agents, durable workflows, and real-time WebSocket apps. Get...","zh":"使用Cloudflare Agents SDK构建AI代理，实现状态管理、可调用RPC和工作流集成","ja":"Cloudflare Agents SDKを使用してAIエージェントを構築し、状態管理、callable RPC、ワークフロー統合を実現","ko":"Cloudflare Agents SDK를 사용하여 AI 에이전트를 구축하고 상태 관리, callable RPC, 워크플로 통합을 구현","es":"Aprende a crear agentes de inteligencia artificial con agents-sdk en Cloudflare Workers. Descubre cómo configurar flujos de trabajo en tiempo real y aplicaci...","fr":"Découvrez comment créer des agents d''intelligence artificielle avec agents-sdk sur Cloudflare Workers. Configurez des flux de travail en temps réel et des ap...","de":"Erfahren Sie, wie Sie künstliche Intelligenz-Agenten mit agents-sdk auf Cloudflare Workers erstellen. Konfigurieren Sie Echtzeit-Workflows und WebSocket-Anwe...","pt":"Aprenda a criar agentes de inteligência artificial com o Agents SDK na Cloudflare Workers. Descubra como integrar o Agent class, gerenciamento de estado e mu...","ru":"Создайте ИИ агентов с помощью Agents SDK на Cloudflare Workers. Узнайте, как интегрировать класс Agent, управление состоянием и многое другое.","ar":"ابني أداة إدارة ذكية باستخدام Agents SDK على Cloudflare Workers. اكتشف كيفية دمج فئة Agent وإدارة الحالة وغيرها"},"definition":{"en":"agents-sdk is a software development kit for building AI agents on Cloudflare Workers, providing features like state management, routing, and React hooks.","zh":"Cloudflare Agents SDK是一种用于构建AI代理的软件开发工具包","ja":"Cloudflare Agents SDKは、AIエージェントを構築するためのソフトウェア開発キット","ko":"Cloudflare Agents SDK는 AI 에이전트를 구축하기 위한 소프트웨어 개발 키트","es":"El agents-sdk es un kit de desarrollo de software que permite a los desarrolladores crear agentes de inteligencia artificial en Cloudflare Workers","fr":"L''agents-sdk est un kit de développement logiciel qui permet aux développeurs de créer des agents d''intelligence artificielle sur Cloudflare Workers","de":"Das agents-sdk ist ein Software-Development-Kit, das es Entwicklern ermöglicht, künstliche Intelligenz-Agenten auf Cloudflare Workers zu erstellen","pt":"O Agents SDK é uma ferramenta para criar agentes de inteligência artificial com Cloudflare Workers.","ru":"Agents SDK - это инструмент для создания ИИ агентов с Cloudflare Workers.","ar":"Agents SDK هو أداة لإنشاء أداة إدارة ذكية مع Cloudflare Workers"},"features":{"en":["Loading Agent class for stateful agents and durable workflows","Supports callable RPC for real-time communication","Integrates with Workflows for automated task management","Utilizes React hooks for building dynamic user interfaces","Enables retrieval of current documentation from Cloudflare GitHub repository","Provides state management capabilities with setState and validateStateChange"],"zh":["状态管理：setState、validateStateChange和持久性","可调用RPC：实现远程过程调用","工作流集成：与Cloudflare工作流无缝集成","React Hooks：使用React Hooks构建AI代理","Cloudflare Workers：在Cloudflare Workers上运行AI代理"],"ja":["状態管理：setState、validateStateChange、永続性","callable RPC：リモートプロセス呼び出しを実現","ワークフロー統合：Cloudflareワークフローとのシームレスな統合","React Hooks：React Hooksを使用してAIエージェントを構築","Cloudflare Workers：Cloudflare Workers上でAIエージェントを実行"],"ko":["상태 관리：setState, validateStateChange, 지속성","callable RPC：원격 프로세스 호출을 구현","워크플로 통합：Cloudflare 워크플로와의无缝 통합","React Hooks：React Hooks를 사용하여 AI 에이전트를 구축","Cloudflare Workers：Cloudflare Workers에서 AI 에이전트를 실행"],"es":["Gestión de estado con setState y validateStateChange","Flujos de trabajo en tiempo real con Workflows","Aplicaciones de WebSocket con callable RPC","Integración con React hooks","Compatibilidad con Cloudflare Workers","Documentación actualizada en GitHub"],"fr":["Gestion d''état avec setState et validateStateChange","Flux de travail en temps réel avec Workflows","Applications WebSocket avec callable RPC","Intégration avec React hooks","Compatibilité avec Cloudflare Workers","Documentation mise à jour sur GitHub"],"de":["Zustandsverwaltung mit setState und validateStateChange","Echtzeit-Workflows mit Workflows","WebSocket-Anwendungen mit callable RPC","Integration mit React-Hooks","Kompatibilität mit Cloudflare Workers","Aktualisierte Dokumentation auf GitHub"],"pt":["Criação de agentes de inteligência artificial com Cloudflare Workers","Integração com o Agent class","Gerenciamento de estado com setState e validateStateChange","Suporte a Workflows e React hooks","Capacidade de criar aplicativos WebSocket em tempo real"],"ru":["Создание ИИ агентов с Cloudflare Workers","Интеграция с классом Agent","Управление состоянием с setState и validateStateChange","Поддержка Workflows и React hooks","Возможность создания приложений WebSocket в реальном времени"],"ar":["إنشاء أداة إدارة ذكية مع Cloudflare Workers","دمج فئة Agent","إدارة الحالة مع setState و validateStateChange","دعم Workflows و React hooks","قدرة على إنشاء تطبيقات WebSocket في الوقت الفعلي"]},"keywords":{"en":["how to use agents-sdk","what is agents-sdk","agents-sdk alternative","agents-sdk vs serverless","agents-sdk install","agents-sdk setup guide","Cloudflare Workers tutorial","building AI agents with agents-sdk","stateful agents with agents-sdk"],"zh":["AI代理","Cloudflare Agents SDK","状态管理","可调用RPC","工作流集成","React Hooks","Cloudflare Workers","AI开发","云计算"],"ja":["AIエージェント","Cloudflare Agents SDK","状態管理","callable RPC","ワークフロー統合","React Hooks","Cloudflare Workers","AI開発","クラウドコンピューティング"],"ko":["AI 에이전트","Cloudflare Agents SDK","상태 관리","callable RPC","워크플로 통합","React Hooks","Cloudflare Workers","AI 개발","클라우드 컴퓨팅"],"es":["agents-sdk","Cloudflare Workers","inteligencia artificial","desarrollo de software","gestión de estado","flujos de trabajo en tiempo real","aplicaciones de WebSocket","React hooks","callable RPC"],"fr":["agents-sdk","Cloudflare Workers","intelligence artificielle","développement logiciel","gestion d''état","flux de travail en temps réel","applications WebSocket","React hooks","callable RPC"],"de":["agents-sdk","Cloudflare Workers","künstliche Intelligenz","Software-Entwicklung","Zustandsverwaltung","Echtzeit-Workflows","WebSocket-Anwendungen","React-Hooks","callable RPC"],"pt":["Agents SDK","Cloudflare Workers","Inteligência Artificial","Gerenciamento de Estado","Workflows","React hooks","WebSocket em tempo real","Desenvolvimento de Aplicativos","Ferramentas de Desenvolvimento"],"ru":["Agents SDK","Cloudflare Workers","ИИ Агенты","Управление Состоянием","Workflows","React hooks","WebSocket в реальном времени","Разработка Приложений","Инструменты Разработки"],"ar":["Agents SDK","Cloudflare Workers","أدوات الذكية","إدارة الحالة","Workflows","React hooks","WebSocket في الوقت الفعلي","تطوير التطبيقات","أدوات التطوير"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Cloudflare Workers Agents needing to build stateful, real-time applications with durable workflows.","zh":"非常适合需要构建有状态、实时应用程序以及持久工作流的 Cloudflare Workers Agents。","ja":"Cloudflare Workers エージェントが状態を保持したリアルタイムアプリケーションと耐久性のあるワークフローを構築する必要がある場合に最適です。","ko":"클라우드플레어 워커 에이전트가 상태를 유지하는 실시간 애플리케이션과 지속적인 워크플로를 구축해야 하는 경우에 적합합니다.","es":"Perfecto para agentes de Cloudflare Workers que necesitan crear aplicaciones en tiempo real con flujos de trabajo duraderos.","fr":"Parfait pour les agents Cloudflare Workers qui ont besoin de créer des applications en temps réel avec des flux de travail durables.","de":"Perfekt für Cloudflare Workers Agents, die stateful-Echtzeit-Anwendungen mit dauerhaften Workflows erstellen müssen.","pt":"Perfeito para Agentes Cloudflare Workers que precisam criar aplicações em tempo real e stateful com fluxos de trabalho duráveis.","ru":"Идеально подходит для агентов Cloudflare Workers, которым необходимо создавать приложения в режиме реального времени и stateful с устойчивыми рабочими процессами.","ar":"مثالي للوكلاء Cloudflare Workers الذين يحتاجون إلى بناء تطبيقات في الوقت الحقيقي و stateful مع سير عمل متين."},"recommendation":{"en":"Enables agents to create stateful applications on Cloudflare Workers with built-in state management, durable workflows, and real-time WebSocket support. Integrates directly with Cloudflare''s ecosystem for callable RPC, scheduled tasks, and React hooks.","zh":"使得代理能够在 Cloudflare Workers 上创建有状态的应用程序，并带有内置的状态管理、持久的工作流和实时 WebSocket 支持。直接与 Cloudflare 的生态系统集成，用于可调用 RPC、定时任务和 React hooks。","ja":"エージェントが Cloudflare Workers 上に状態を保持したアプリケーションを構築できるようにし、内蔵の状態管理、耐久性のあるワークフロー、およびリアルタイムの WebSocket サポートを提供します。Cloudflare のエコシステムと直接統合して、callable RPC、スケジュールされたタスク、および React フックスを使用します。","ko":"에이전트가 클라우드플레어 워커에서 상태를 유지하는 애플리케이션을 구축할 수 있도록 하며, 내장 상태 관리, 지속적인 워크플로, 실시간 WebSocket 지원을 제공합니다. 호출 가능한 RPC, 예약된 작업 및 React 훅과 함께 클라우드플레어의 생태계와 직접 통합됩니다.","es":"Permite a los agentes crear aplicaciones stateful en Cloudflare Workers con administración de estado integrada, flujos de trabajo duraderos y soporte de WebSocket en tiempo real. Se integra directamente con el ecosistema de Cloudflare para RPC callable, tareas programadas y ganchos de React.","fr":"Permet aux agents de créer des applications stateful sur Cloudflare Workers avec une gestion d''état intégrée, des flux de travail durables et un support WebSocket en temps réel. S''intègre directement à l''écosystème de Cloudflare pour RPC appelable, tâches planifiées et crochets de React.","de":"Ermöglicht es Agents, stateful-Anwendungen auf Cloudflare Workers mit integrierter Statusverwaltung, dauerhaften Workflows und Echtzeit-WebSocket-Unterstützung zu erstellen. Integriert sich direkt in das Cloudflare-Ökosystem für aufrufbare RPC, geplante Aufgaben und React-Hooks.","pt":"Permite que os agentes criem aplicações stateful no Cloudflare Workers com gerenciamento de estado incorporado, fluxos de trabalho duráveis e suporte a WebSocket em tempo real. Integra-se diretamente com o ecossistema da Cloudflare para RPC chamável, tarefas agendadas e ganchos React.","ru":"Позволяет агентам создавать приложения stateful на Cloudflare Workers с встроенным управлением состоянием, устойчивыми рабочими процессами и поддержкой WebSocket в режиме реального времени. Интегрируется напрямую с экосистемой Cloudflare для вызываемого RPC, запланированных задач и крючков React.","ar":"يمكن للوكلاء من إنشاء تطبيقات stateful على Cloudflare Workers مع إدارة الحالة المدمجة و سير عمل متين ودعم WebSocket في الوقت الحقيقي. يتكامل مباشرة مع نظام البيئة Cloudflare ل RPC يمكن الاستدعاء والمهام المجدولة وأكواز React."},"useCases":{"en":["Building stateful agents with persistent storage","Creating durable workflows for long-running operations","Developing real-time WebSocket applications","Implementing scheduled tasks and cron jobs","Setting up MCP servers for tool integration"],"zh":["构建具有持久存储的有状态代理","为长时间运行的操作创建持久的工作流","开发实时 WebSocket 应用程序","实现定时任务和 cron 作业","为工具集成设置 MCP 服务器"],"ja":["永続的なストレージを備えた状態を保持したエージェントの構築","長時間実行される操作のための耐久性のあるワークフローの作成","リアルタイムの WebSocket アプリケーションの開発","スケジュールされたタスクと cron ジョブの実装","ツール統合のための MCP サーバーの設定"],"ko":["지속적인 저장소가 있는 상태를 유지하는 에이전트 구축","장기간 실행되는 작업을 위한 지속적인 워크플로 생성","실시간 WebSocket 애플리케이션 개발","예약된 작업 및 cron 작업 구현","도구 통합을 위한 MCP 서버 설정"],"es":["Creación de agentes stateful con almacenamiento persistente","Creación de flujos de trabajo duraderos para operaciones de larga duración","Desarrollo de aplicaciones WebSocket en tiempo real","Implementación de tareas programadas y trabajos cron","Configuración de servidores MCP para la integración de herramientas"],"fr":["Création d''agents stateful avec stockage persistant","Création de flux de travail durables pour les opérations à long terme","Développement d''applications WebSocket en temps réel","Mise en œuvre de tâches planifiées et de travaux cron","Configuration de serveurs MCP pour l''intégration d''outils"],"de":["Erstellung von stateful-Agents mit persistentem Speicher","Erstellung von dauerhaften Workflows für Langzeitoperationen","Entwicklung von Echtzeit-WebSocket-Anwendungen","Implementierung von geplanten Aufgaben und Cron-Jobs","Einrichtung von MCP-Servern für die Integration von Tools"],"pt":["Construir agentes stateful com armazenamento persistente","Criar fluxos de trabalho duráveis para operações de longa duração","Desenvolver aplicações WebSocket em tempo real","Implementar tarefas agendadas e trabalhos cron","Configurar servidores MCP para integração de ferramentas"],"ru":["Создание агентов stateful с постоянным хранилищем","Создание устойчивых рабочих процессов для долгосрочных операций","Разработка приложений WebSocket в режиме реального времени","Реализация запланированных задач и работ cron","Настройка серверов MCP для интеграции инструментов"],"ar":["بناء وكلاء stateful مع تخزين متين","إنشاء سير عمل متين لعمليات طويلة الأمد","تطوير تطبيقات WebSocket في الوقت الحقيقي","تنفيذ المهام المجدولة ووظائف cron","تكوين خوادم MCP لتكامل الأدوات"]},"limitations":{"en":["Requires Cloudflare Workers environment","Depends on Cloudflare-specific APIs and infrastructure","Documentation must be retrieved from GitHub repository rather than pre-trained knowledge"],"zh":["需要 Cloudflare Workers 环境","依赖于 Cloudflare 特有的 API 和基础设施","文档必须从 GitHub 存储库中检索，而不是预先训练的知识"],"ja":["Cloudflare Workers 環境が必要","Cloudflare 固有の API とインフラストラクチャに依存する","ドキュメントは事前に学習した知識ではなく、GitHub リポジトリから取得する必要がある"],"ko":["클라우드플레어 워커 환경이 필요합니다.","클라우드플레어 전용 API 및 인프라에 의존합니다.","문서를 사전 학습된 지식이 아닌 GitHub 저장소에서 가져와야 합니다."],"es":["Requiere entorno de Cloudflare Workers","Depende de APIs e infraestructura específicas de Cloudflare","La documentación debe recuperarse desde el repositorio de GitHub en lugar de conocimientos preentrenados"],"fr":["Nécessite un environnement Cloudflare Workers","Dépend des API et de l''infrastructure spécifiques de Cloudflare","La documentation doit être récupérée depuis le référentiel GitHub plutôt que des connaissances préentraînées"],"de":["Benötigt Cloudflare Workers-Umgebung","Hängt von Cloudflare-spezifischen APIs und Infrastruktur ab","Die Dokumentation muss aus dem GitHub-Repository abgerufen werden, anstatt vorab trainierte Kenntnisse"],"pt":["Requer ambiente Cloudflare Workers","Depende de APIs e infraestrutura específicas da Cloudflare","A documentação deve ser recuperada do repositório GitHub em vez do conhecimento pré-treinado"],"ru":["Требуется окружение Cloudflare Workers","Зависит от специфических API и инфраструктуры Cloudflare","Документация должна быть получена из репозитория GitHub вместо предварительно обученных знаний"],"ar":["يتطلب بيئة Cloudflare Workers","يعتمد على واجهات برمجة التطبيقات والبنية التحتية الخاصة بـ Cloudflare","يجب استرجاع الوثائق من مستودع GitHub بدلاً من المعرفة المدربة مسبقاً"]},"version":4},"contentHash":"007d6ccf85808a6c779f5b058b1be970d77785000071cb27a55a5f580fbc845b","repoEtag":"W/\"295e4fcdb92b56b41ac51b00a34c693d22b101994424f954c0d419002c1abf71\"","qualityScore":68}');
