INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudflare/skills/agents-sdk', 'agents-sdk', 'cloudflare', 'skills', 'official', 'agents-sdk cloudflare skills official agents cloudflare skills workers The agents-sdk enables developers to build AI agents on Cloudflare Workers, supporting state management, callable RPC, and Workflows integration. Ideal for creating real-time applications and scheduled tasks. Cloudflare Agents SDK允许开发人员构建AI代理，实现状态管理、可调用RPC和工作流集成 Cloudflare Agents SDKは、開発者がAIエージェントを構築し、状態管理、callable RPC、ワークフロー統合を実現できるようにする Cloudflare Agents SDK는 개발자가 AI 에이전트를 구축하고 상태 관리, callable RPC, 워크플로 통합을 구현할 수 있도록 해줍니다 El agents-sdk permite a los desarrolladores crear agentes de inteligencia artificial en Cloudflare Workers. Incluye características como gestión de estado, flujos de trabajo y aplicaciones de WebSocket L''agents-sdk permet aux développeurs de créer des agents d''intelligence artificielle sur Cloudflare Workers. Il comprend des fonctionnalités telles que la gestion d''état, les flux de travail et les applications WebSocket Das agents-sdk ermöglicht es Entwicklern, künstliche Intelligenz-Agenten auf Cloudflare Workers zu erstellen. Es umfasst Funktionen wie Zustandsverwaltung, Workflows und WebSocket-Anwendungen O Agents SDK permite criar agentes de inteligência artificial com Cloudflare Workers, incluindo gerenciamento de estado e integração com Workflows. Agents SDK позволяет создавать ИИ агентов с Cloudflare Workers, включая управление состоянием и интеграцию с Workflows. يسمح Agents SDK بإنشاء أداة إدارة ذكية مع Cloudflare Workers، بما في ذلك إدارة الحالة ودمجها مع Workflows how to use agents-sdk what is agents-sdk agents-sdk alternative agents-sdk vs serverless agents-sdk install agents-sdk setup guide Cloudflare Workers tutorial building AI agents with agents-sdk stateful agents with agents-sdk AI代理 Cloudflare Agents SDK 状态管理 可调用RPC 工作流集成 React Hooks Cloudflare Workers AI开发 云计算 Loading Agent class for stateful agents and durable workflows Supports callable RPC for real-time communication Integrates with Workflows for automated task management Utilizes React hooks for building dynamic user interfaces Enables retrieval of current documentation from Cloudflare GitHub repository Provides state management capabilities with setState and validateStateChange agents-sdk is a software development kit for building AI agents on Cloudflare Workers, providing features like state management, routing, and React hooks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('langgenius/dify/frontend-code-review', 'official', 'langgenius', 'dify', 'langgenius/dify', 'frontend-code-review', 131375, 20455, 68, '2026-03-06T06:00:48Z', '2026-03-06T06:05:47.292Z', 'f4fefe4db6804043a36626f5f6028192f038bacd0c881f0fe6887cc4dd5f43b0', '{"id":"langgenius/dify/frontend-code-review","name":"frontend-code-review","description":{"en":"The frontend-code-review AI agent skill automatically analyzes JavaScript and TypeScript files against a predefined checklist. It supports both pre-commit reviews of staged changes and targeted file reviews, helping developers and AI agents maintain code quality.","es":"La revisión de código frontend es una herramienta de revisión de código basada en AI que soporta la revisión de archivos .tsx, .ts y .js. Permite la revisión de cambios pendientes y la revisión de archivos específicos","fr":"La revue de code frontend est un outil de revue de code basé sur l''IA qui prend en charge la revue de fichiers .tsx, .ts et .js. Il permet la revue de modifications en attente et la revue de fichiers spécifiques","de":"Die Frontend-Code-Überprüfung ist ein Code-Review-Tool basierend auf KI, das die Überprüfung von Dateien .tsx, .ts und .js unterstützt. Es ermöglicht die Überprüfung von ausstehenden Änderungen und die Überprüfung bestimmter Dateien"},"owner":"langgenius","repo":"dify","repoPath":"langgenius/dify","stars":131375,"forks":20455,"updatedAt":"2026-03-06T06:00:48Z","topics":["agent","agentic-ai","agentic-framework","agentic-workflow","ai","automation","gemini","genai","gpt","gpt-4","llm","low-code","mcp","nextjs","no-code","openai","orchestration","python","rag","workflow"],"skillMd":{"name":"frontend-code-review","description":"Trigger when the user requests a review of frontend files (e.g., `.tsx`, `.ts`, `.js`). Support both pending-change reviews and focused file reviews while applying the checklist rules.","bodyPreview":"# Frontend Code Review\n\n## Intent\nUse this skill whenever the user asks to review frontend code (especially `.tsx`, `.ts`, or `.js` files). Support two review modes:\n\n1. **Pending-change review** – inspect staged/working-tree files slated for commit and flag checklist violations before submission.\n2. **File-targeted review** – review the specific file(s) the user names and report the relevant checklist findings.\n\nStick to the checklist below for every applicable file and mode.\n\n## Checklist\nSee","body":"# Frontend Code Review\n\n## Intent\nUse this skill whenever the user asks to review frontend code (especially `.tsx`, `.ts`, or `.js` files). Support two review modes:\n\n1. **Pending-change review** – inspect staged/working-tree files slated for commit and flag checklist violations before submission.\n2. **File-targeted review** – review the specific file(s) the user names and report the relevant checklist findings.\n\nStick to the checklist below for every applicable file and mode.\n\n## Checklist\nSee [references/code-quality.md](references/code-quality.md), [references/performance.md](references/performance.md), [references/business-logic.md](references/business-logic.md) for the living checklist split by category—treat it as the canonical set of rules to follow.\n\nFlag each rule violation with urgency metadata so future reviewers can prioritize fixes.\n\n## Review Process\n1. Open the relevant component/module. Gather lines that relate to class names, React Flow hooks, prop memoization, and styling.\n2. For each rule in the review point, note where the code deviates and capture a representative snippet.\n3. Compose the review section per the template below. Group violations first by **Urgent** flag, then by category order (Code Quality, Performance, Business Logic).\n\n## Required output\nWhen invoked, the response must exactly follow one of the two templates:\n\n### Template A (any findings)\n```\n# Code review\nFound <N> urgent issues need to be fixed:\n\n## 1 <brief description of bug>\nFilePath: <path> line <line>\n<relevant code snippet or pointer>\n\n\n### Suggested fix\n<brief description of suggested fix>\n\n---\n... (repeat for each urgent issue) ...\n\nFound <M> suggestions for improvement:\n\n## 1 <brief description of suggestion>\nFilePath: <path> line <line>\n<relevant code snippet or pointer>\n\n\n### Suggested fix\n<brief description of suggested fix>\n\n---\n\n... (repeat for each suggestion) ...\n```\n\nIf there are no urgent issues, omit that section. If there are no suggestions, omit that section.\n\nIf the issue number is more than 10, summarize as \"10+ urgent issues\" or \"10+ suggestions\" and just output the first 10 issues.\n\nDon''t compress the blank lines between sections; keep them as-is for readability.\n\nIf you use Template A (i.e., there are issues to fix) and at least one issue requires code changes, append a brief follow-up question after the structured output asking whether the user wants you to apply the suggested fix(es). For example: \"Would you like me to use the Suggested fix section to address these issues?\"\n\n### Template B (no issues)\n```\n## Code review\nNo issues found.\n```\n\n"},"category":"official","lastSynced":"2026-03-06T06:05:47.292Z","seo":{"title":{"en":"Frontend-Code-Review: Automated Checklist Enforcement for...","es":"Guía de configuración de revisión de código frontend","fr":"Guide de configuration de la revue de code frontend","de":"Einrichtungsleitfaden für Frontend-Code-Review"},"description":{"en":"Automate your frontend code reviews for .tsx, .ts, and .js files. This AI agent skill flags violations pre-commit or reviews specific files against a defined...","es":"Automatice la revisión de código frontend con nuestra herramienta de revisión de código basada en AI. Soporta revisiones de cambios pendientes y revisiones d...","fr":"Automatisez la revue de code frontend avec notre outil de revue de code basé sur l''IA. Prend en charge les revues de modifications en attente et les revues d...","de":"Automatisieren Sie die Überprüfung von Frontend-Code mit unserem Code-Review-Tool basierend auf KI. Unterstützt Überprüfungen von ausstehenden Änderungen und..."},"definition":{"en":"frontend-code-review is an AI agent skill that programmatically reviews frontend source code files (.tsx, .ts, .js). It applies a specific checklist to either pending changes in a git working tree or to user-specified files, flagging violations automatically.","es":"La revisión de código frontend es una herramienta de revisión de código que utiliza la inteligencia artificial para revisar y validar el código frontend","fr":"La revue de code frontend est un outil de revue de code qui utilise l''intelligence artificielle pour réviser et valider le code frontend","de":"Die Frontend-Code-Überprüfung ist ein Code-Review-Tool, das die künstliche Intelligenz verwendet, um den Frontend-Code zu überprüfen und zu validieren"},"features":{"en":["Reviews .tsx, .ts, and .js file formats against a predefined checklist","Supports pending-change review mode for staged or working-tree files pre-commit","Executes file-targeted reviews for specific, user-named files","Flags checklist violations programmatically for automated workflows","Integrates with agentic frameworks via MCP for AI-driven code analysis"],"es":["Soporte para la revisión de archivos .tsx, .ts y .js","Revisión de cambios pendientes y revisión de archivos específicos","Aplicación de reglas de verificación para garantizar la calidad del código","Integración con frameworks de frontend como Next.js","Compatibilidad con la automatización de flujos de trabajo con herramientas como Agentic Workflow"],"fr":["Prise en charge de la revue de fichiers .tsx, .ts et .js","Revue de modifications en attente et revue de fichiers spécifiques","Application de règles de vérification pour garantir la qualité du code","Intégration avec des frameworks de frontend tels que Next.js","Compatibilité avec l''automatisation de flux de travail avec des outils tels que Agentic Workflow"],"de":["Unterstützung für die Überprüfung von Dateien .tsx, .ts und .js","Überprüfung von ausstehenden Änderungen und Überprüfung bestimmter Dateien","Anwendung von Prüfregeln, um die Qualität des Codes sicherzustellen","Integration mit Frontend-Frameworks wie Next.js","Kompatibilität mit der Automatisierung von Workflows mit Tools wie Agentic Workflow"]},"keywords":{"en":["how to use frontend-code-review agent","what is frontend-code-review mcp","frontend-code-review vs manual code review","frontend-code-review alternative","install frontend-code-review skill","frontend-code-review setup guide for nextjs","automated typescript code review","ai agent for javascript linting"],"es":["revisión de código frontend","herramientas de revisión de código","automatización de flujos de trabajo","Agentic Workflow","Next.js","inteligencia artificial en el desarrollo de software","mejores prácticas de codificación","revisión de código basada en AI"],"fr":["revue de code frontend","outils de revue de code","automatisation de flux de travail","Agentic Workflow","Next.js","intelligence artificielle dans le développement de logiciels","meilleures pratiques de codage","revue de code basée sur l''IA"],"de":["Frontend-Code-Überprüfung","Code-Review-Tools","Automatisierung von Workflows","Agentic Workflow","Next.js","künstliche Intelligenz in der Softwareentwicklung","beste Praktiken für die Codierung","Code-Review basierend auf KI"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents specializing in TypeScript and React-based frontend development.","zh":"非常适合专注于 TypeScript 和 React 前端开发的代码审查智能体。","ja":"TypeScriptとReactベースのフロントエンド開発に特化したコードレビューエージェントに最適です。","ko":"TypeScript 및 React 기반 프론트엔드 개발에 특화된 코드 리뷰 에이전트에 이상적입니다.","es":"Ideal para agentes de revisión de código especializados en desarrollo frontend basado en TypeScript y React.","fr":"Idéal pour les agents de revue de code spécialisés dans le développement frontend basé sur TypeScript et React.","de":"Ideal für Code-Review-Agenten, die auf TypeScript- und React-basierte Frontend-Entwicklung spezialisiert sind.","pt":"Ideal para Agentes de Revisão de Código especializados em TypeScript e desenvolvimento de frontend baseado em React.","ru":"Идеально подходит для агентов проверки кода, специализирующихся на TypeScript и разработке frontend на основе React.","ar":"مثالي لعميل مراجعة الشفرة المتخصص في TypeScript وتطوير الواجهة الأمامية المستندة إلى React."},"recommendation":{"en":"Enables automated detection of frontend code quality issues across .tsx, .ts, and .js files using a comprehensive checklist. Supports both pre-commit validation of staged changes and targeted file analysis for immediate feedback.","zh":"支持使用综合性检查清单，自动检测 .tsx、.ts 和 .js 文件中的前端代码质量问题。既支持对暂存的更改进行预提交验证，也支持对特定文件进行分析以提供即时反馈。","ja":"包括的なチェックリストを使用して、.tsx、.ts、.jsファイル全体でフロントエンドコードの品質問題を自動検出できます。ステージングされた変更のコミット前検証と、即時のフィードバックのための特定ファイル分析の両方をサポートします。","ko":"포괄적인 체크리스트를 사용하여 .tsx, .ts 및 .js 파일 전반에 걸친 프론트엔드 코드 품질 문제를 자동으로 감지할 수 있게 합니다. 스테이징된 변경 사항에 대한 커밋 전 검증과 즉각적인 피드백을 위한 특정 파일 분석을 모두 지원합니다.","es":"Permite la detección automatizada de problemas de calidad del código frontend en archivos .tsx, .ts y .js utilizando una lista de verificación exhaustiva. Admite tanto la validación pre-commit de cambios preparados como el análisis de archivos específicos para obtener retroalimentación inmediata.","fr":"Permet la détection automatisée des problèmes de qualité du code frontend dans les fichiers .tsx, .ts et .js en utilisant une liste de contrôle complète. Prend en charge la validation pré-commit des modifications préparées et l''analyse ciblée de fichiers pour un retour immédiat.","de":"Ermöglicht die automatisierte Erkennung von Frontend-Codequalitätsproblemen in .tsx-, .ts- und .js-Dateien mithilfe einer umfassenden Checkliste. Unterstützt sowohl die Pre-Commit-Validierung von vorgemerkten Änderungen als auch die gezielte Dateianalyse für sofortiges Feedback.","pt":"Permite a detecção automatizada de problemas de qualidade de código frontend em arquivos .tsx, .ts e .js usando uma lista de verificação abrangente. Suporta tanto a validação pré-commit das alterações em estágio quanto a análise de arquivos direcionada para feedback imediato.","ru":"Позволяет автоматически обнаруживать проблемы качества frontend-кода в файлах .tsx, .ts и .js с помощью всестороннего чек-листа. Поддерживает как предкоммитную валидацию изменений, находящихся в стадии, так и целевую анализ файлов для немедленного обратной связи.","ar":"يسمح بالكشف التلقائي عن مشاكل جودة الشفرة الأمامية في الملفات .tsx و .ts و .js باستخدام قائمة مراجعة شاملة. يدعم التحقق من التغييرات في مرحلة ما قبل الالتزام وتحليل الملفات المستهدفة لتعليقات فورية."},"useCases":{"en":["Validating staged changes before commit","Reviewing specific frontend files for quality violations","Enforcing TypeScript and React best practices","Identifying accessibility and performance issues in UI components"],"zh":["在提交前验证暂存的更改","审查特定的前端文件以发现质量违规","强制执行 TypeScript 和 React 最佳实践","识别 UI 组件中的可访问性和性能问题"],"ja":["コミット前のステージングされた変更の検証","品質違反のための特定のフロントエンドファイルのレビュー","TypeScriptとReactのベストプラクティスの実施","UIコンポーネントのアクセシビリティとパフォーマンス問題の特定"],"ko":["커밋 전 스테이징된 변경 사항 검증","품질 위반에 대한 특정 프론트엔드 파일 검토","TypeScript 및 React 모범 사례 적용","UI 컴포넌트의 접근성 및 성능 문제 식별"],"es":["Validación de cambios preparados antes del commit","Revisión de archivos frontend específicos en busca de violaciones de calidad","Aplicación de las mejores prácticas de TypeScript y React","Identificación de problemas de accesibilidad y rendimiento en componentes de UI"],"fr":["Validation des modifications préparées avant le commit","Examen de fichiers frontend spécifiques pour les violations de qualité","Application des meilleures pratiques TypeScript et React","Identification des problèmes d''accessibilité et de performance dans les composants d''interface utilisateur"],"de":["Validierung vorgemerkter Änderungen vor dem Commit","Überprüfung spezifischer Frontend-Dateien auf Qualitätsverstöße","Durchsetzung von TypeScript- und React-Best Practices","Identifizierung von Barrierefreiheits- und Leistungsproblemen in UI-Komponenten"],"pt":["Validar alterações em estágio antes do commit","Revisar arquivos frontend específicos para violações de qualidade","Impor as melhores práticas de TypeScript e React","Identificar problemas de acessibilidade e desempenho em componentes de UI"],"ru":["Проверка изменений на стадии до коммита","Просмотр конкретных frontend-файлов для нарушений качества","Принуждение к соблюдению лучших практик TypeScript и React","Определение проблем доступности и производительности в компонентах UI"],"ar":["التحقق من التغييرات في مرحلة ما قبل الالتزام","مراجعة ملفات الواجهة الأمامية المحددة للانتهاكات الجودة","فرض أفضل الممارسات لـ TypeScript و React","تحديد مشاكل إمكانية الوصول والأداء في مكونات الواجهة"]},"limitations":{"en":["Limited to frontend file types (.tsx, .ts, .js)","Requires access to git staging area for pending-change reviews","Checklist-based analysis may miss project-specific patterns"],"zh":["仅限于前端文件类型（.tsx、.ts、.js）","对待审查的更改需要访问 git 暂存区","基于检查清单的分析可能会遗漏项目特定的模式"],"ja":["フロントエンドファイルタイプ（.tsx、.ts、.js）に限定","保留中の変更のレビューにはgitステージング領域へのアクセスが必要","チェックリストベースの分析はプロジェクト固有のパターンを見落とす可能性があります"],"ko":["프론트엔드 파일 유형(.tsx, .ts, .js)으로 제한됨","보류 중인 변경 사항 검토를 위해 git 스테이징 영역에 대한 액세스 필요","체크리스트 기반 분석은 프로젝트별 패턴을 놓칠 수 있음"],"es":["Limitado a tipos de archivos frontend (.tsx, .ts, .js)","Requiere acceso al área de staging de git para revisiones de cambios pendientes","El análisis basado en listas de verificación puede pasar por alto patrones específicos del proyecto"],"fr":["Limité aux types de fichiers frontend (.tsx, .ts, .js)","Nécessite un accès à la zone de staging git pour l''examen des modifications en attente","L''analyse basée sur une liste de contrôle peut manquer des modèles spécifiques au projet"],"de":["Beschränkt auf Frontend-Dateitypen (.tsx, .ts, .js)","Erfordert Zugriff auf den Git-Staging-Bereich für Überprüfungen ausstehender Änderungen","Die checklistenbasierte Analyse kann projektspezifische Muster übersehen"],"pt":["Limitado a tipos de arquivos frontend (.tsx, .ts, .js)","Exige acesso à área de estágio do git para revisões de alterações pendentes","Análise baseada em lista de verificação pode perder padrões específicos do projeto"],"ru":["Ограничен типами frontend-файлов (.tsx, .ts, .js)","Требует доступа к области стадии git для обзоров изменений в ожидании","Анализ на основе чек-листа может пропустить проектно-специфические шаблоны"],"ar":["محدود بنوعيات الملفات الأمامية (.tsx و .ts و .js)","يتطلب الوصول إلى منطقة المرحلة الخاصة بـ git لمراجعة التغييرات المعلقة","يمكن أن تفوت التحليل القائم على قائمة المراجعة أنماطًا محددة للمشروع"]},"version":4},"contentHash":"f4fefe4db6804043a36626f5f6028192f038bacd0c881f0fe6887cc4dd5f43b0","repoEtag":"W/\"8b79270de464b84537dd173d2e750efb4b05e743496516f4c20a14f45fafde09\"","qualityScore":68}');
