INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('langgenius/dify/frontend-code-review', 'frontend-code-review', 'langgenius', 'dify', 'official', 'frontend-code-review langgenius dify official agent agentic-ai agentic-framework agentic-workflow ai automation gemini genai gpt gpt-4 llm low-code mcp nextjs no-code openai orchestration python rag workflow The frontend-code-review AI agent skill automatically analyzes JavaScript and TypeScript files against a predefined checklist. It supports both pre-commit reviews of staged changes and targeted file reviews, helping developers and AI agents maintain code quality. La revisión de código frontend es una herramienta de revisión de código basada en AI que soporta la revisión de archivos .tsx, .ts y .js. Permite la revisión de cambios pendientes y la revisión de archivos específicos La revue de code frontend est un outil de revue de code basé sur l''IA qui prend en charge la revue de fichiers .tsx, .ts et .js. Il permet la revue de modifications en attente et la revue de fichiers spécifiques Die Frontend-Code-Überprüfung ist ein Code-Review-Tool basierend auf KI, das die Überprüfung von Dateien .tsx, .ts und .js unterstützt. Es ermöglicht die Überprüfung von ausstehenden Änderungen und die Überprüfung bestimmter Dateien how to use frontend-code-review agent what is frontend-code-review mcp frontend-code-review vs manual code review frontend-code-review alternative install frontend-code-review skill frontend-code-review setup guide for nextjs automated typescript code review ai agent for javascript linting Reviews .tsx, .ts, and .js file formats against a predefined checklist Supports pending-change review mode for staged or working-tree files pre-commit Executes file-targeted reviews for specific, user-named files Flags checklist violations programmatically for automated workflows Integrates with agentic frameworks via MCP for AI-driven code analysis frontend-code-review is an AI agent skill that programmatically reviews frontend source code files (.tsx, .ts, .js). It applies a specific checklist to either pending changes in a git working tree or to user-specified files, flagging violations automatically.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vercel/next.js/update-docs', 'official', 'vercel', 'next.js', 'vercel/next.js', 'update-docs', 138169, 30553, 68, '2026-03-06T05:45:21Z', '2026-03-06T06:09:15.662Z', '0f46c6e76a222cfa4008d16cdb1dfa37c413901db2b304a49cce829ef4c7ad71', '{"id":"vercel/next.js/update-docs","name":"update-docs","description":{"en":"The update-docs skill helps maintainers review PRs for documentation completeness, providing a guided workflow for updating Next.js documentation based on code changes.","zh":"update-docs 技能为 Next.js 文档更新提供了指导，确保代码变更与文档同步","ja":"update-docs スキルは Next.js ドキュメントの更新をサポートし、コード変更を反映","ko":"update-docs 기능은 Next.js 문서의 업데이트를 지원하여 코드 변경 사항을 반영","es":"La habilidad ''update-docs'' proporciona un flujo de trabajo guiado para actualizar la documentación de Next.js en función de los cambios de código","fr":"La compétence ''update-docs'' fournit un flux de travail guidé pour mettre à jour la documentation Next.js en fonction des modifications de code","de":"Die Fähigkeit ''update-docs'' bietet einen geleiteten Workflow zur Aktualisierung der Next.js-Dokumentation auf der Grundlage von Codeänderungen","pt":"O update-docs é uma ferramenta que ajuda a manter a documentação Next.js atualizada com base em alterações de código. Ele fornece um fluxo de trabalho guiado para revisar e atualizar a documentação.","ru":"ИИ Агент update-docs - это инструмент, который помогает поддерживать документацию Next.js в актуальном состоянии на основе изменений кода. Он предоставляет руководимый рабочий процесс для проверки и обновления документации.","ar":"أداة الذكاء الاصطناعي update-docs هي أداة تساعد في الحفاظ على وثائق Next.js محدثة بناءً على تغييرات في الكود. توفر عملية عمل موجهة لمراجعة وتحديث الوثائق."},"owner":"vercel","repo":"next.js","repoPath":"vercel/next.js","stars":138169,"forks":30553,"updatedAt":"2026-03-06T05:45:21Z","topics":["blog","browser","compiler","components","hybrid","nextjs","node","react","server-rendering","ssg","static","static-site-generator","universal","vercel"],"skillMd":{"name":"update-docs","description":"This skill should be used when the user asks to update documentation for my changes, check docs for this PR, what docs need updating, sync docs with code, scaffold docs for this feature, document this feature, review docs completeness, add docs for this change, what documentation is affected, docs impact, or mentions docs/, docs/01-app, docs/02-pages, MDX, documentation update, API reference, .mdx files. Provides guided workflow for updating Next.js documentation based on code changes.","bodyPreview":"# Next.js Documentation Updater\n\nGuides you through updating Next.js documentation based on code changes on the active branch. Designed for maintainers reviewing PRs for documentation completeness.\n\n## Quick Start\n\n1. **Analyze changes**: Run `git diff canary...HEAD --stat` to see what files changed\n2. **Identify affected docs**: Map changed source files to documentation paths\n3. **Review each doc**: Walk through updates with user confirmation\n4. **Validate**: Run `pnpm lint` to check formatting","body":"# Next.js Documentation Updater\n\nGuides you through updating Next.js documentation based on code changes on the active branch. Designed for maintainers reviewing PRs for documentation completeness.\n\n## Quick Start\n\n1. **Analyze changes**: Run `git diff canary...HEAD --stat` to see what files changed\n2. **Identify affected docs**: Map changed source files to documentation paths\n3. **Review each doc**: Walk through updates with user confirmation\n4. **Validate**: Run `pnpm lint` to check formatting\n5. **Commit**: Stage documentation changes\n\n## Workflow: Analyze Code Changes\n\n### Step 1: Get the diff\n\n```bash\n# See all changed files on this branch\ngit diff canary...HEAD --stat\n\n# See changes in specific areas\ngit diff canary...HEAD -- packages/next/src/\n```\n\n### Step 2: Identify documentation-relevant changes\n\nLook for changes in these areas:\n\n| Source Path                            | Likely Doc Impact           |\n| -------------------------------------- | --------------------------- |\n| `packages/next/src/client/components/` | Component API reference     |\n| `packages/next/src/server/`            | Function API reference      |\n| `packages/next/src/shared/lib/`        | Varies by export            |\n| `packages/next/src/build/`             | Configuration or build docs |\n| `packages/next/src/lib/`               | Various features            |\n\n### Step 3: Map to documentation files\n\nUse the code-to-docs mapping in `references/CODE-TO-DOCS-MAPPING.md` to find corresponding documentation files.\n\nExample mappings:\n\n- `src/client/components/image.tsx` → `docs/01-app/03-api-reference/02-components/image.mdx`\n- `src/server/config-shared.ts` → `docs/01-app/03-api-reference/05-config/`\n\n## Workflow: Update Existing Documentation\n\n### Step 1: Read the current documentation\n\nBefore making changes, read the existing doc to understand:\n\n- Current structure and sections\n- Frontmatter fields in use\n- Whether it uses `<AppOnly>` / `<PagesOnly>` for router-specific content\n\n### Step 2: Identify what needs updating\n\nCommon updates include:\n\n- **New props/options**: Add to the props table and create a section explaining usage\n- **Changed behavior**: Update descriptions and examples\n- **Deprecated features**: Add deprecation notices and migration guidance\n- **New examples**: Add code blocks following conventions\n\n### Step 3: Apply updates with confirmation\n\nFor each change:\n\n1. Show the user what you plan to change\n2. Wait for confirmation before editing\n3. Apply the edit\n4. Move to the next change\n\n### Step 4: Check for shared content\n\nIf the doc uses the `source` field pattern (common for Pages Router docs), the source file is the one to edit. Example:\n\n```yaml\n# docs/02-pages/... file with shared content\n---\nsource: app/building-your-application/optimizing/images\n---\n```\n\nEdit the App Router source, not the Pages Router file.\n\n### Step 5: Validate changes\n\n```bash\npnpm lint          # Check formatting\npnpm prettier-fix  # Auto-fix formatting issues\n```\n\n## Workflow: Scaffold New Feature Documentation\n\nUse this when adding documentation for entirely new features.\n\n### Step 1: Determine the doc type\n\n| Feature Type        | Doc Location                                        | Template         |\n| ------------------- | --------------------------------------------------- | ---------------- |\n| New component       | `docs/01-app/03-api-reference/02-components/`       | API Reference    |\n| New function        | `docs/01-app/03-api-reference/04-functions/`        | API Reference    |\n| New config option   | `docs/01-app/03-api-reference/05-config/`           | Config Reference |\n| New concept/guide   | `docs/01-app/02-guides/`                            | Guide            |\n| New file convention | `docs/01-app/03-api-reference/03-file-conventions/` | File Convention  |\n\n### Step 2: Create the file with proper naming\n\n- Use kebab-case: `my-new-feature.mdx`\n- Add numeric prefix if ordering matters: `05-my-new-feature.mdx`\n- Place in the correct directory based on feature type\n\n### Step 3: Use the appropriate template\n\n**API Reference Template:**\n\n```mdx\n---\ntitle: Feature Name\ndescription: Brief description of what this feature does.\n---\n\n{/* The content of this doc is shared between the app and pages router. You can use the `<PagesOnly>Content</PagesOnly>` component to add content that is specific to the Pages Router. Any shared content should not be wrapped in a component. */}\n\nBrief introduction to the feature.\n\n## Reference\n\n### Props\n\n<div style={{ overflowX: ''auto'', width: ''100%'' }}>\n\n| Prop                    | Example            | Type   | Status   |\n| ----------------------- | ------------------ | ------ | -------- |\n| [`propName`](#propname) | `propName=\"value\"` | String | Required |\n\n</div>\n\n#### `propName`\n\nDescription of the prop.\n\n\\`\\`\\`tsx filename=\"app/example.tsx\" switcher\n// TypeScript example\n\\`\\`\\`\n\n\\`\\`\\`jsx filename=\"app/example.js\" switcher\n// JavaScript example\n\\`\\`\\`\n```\n\n**Guide Template:**\n\n```mdx\n---\ntitle: How to do X in Next.js\nnav_title: X\ndescription: Learn how to implement X in your Next.js application.\n---\n\nIntroduction explaining why this guide is useful.\n\n## Prerequisites\n\nWhat the reader needs to know before starting.\n\n## Step 1: First Step\n\nExplanation and code example.\n\n\\`\\`\\`tsx filename=\"app/example.tsx\" switcher\n// Code example\n\\`\\`\\`\n\n## Step 2: Second Step\n\nContinue with more steps...\n\n## Next Steps\n\nRelated topics to explore.\n```\n\n### Step 4: Add related links\n\nUpdate frontmatter with related documentation:\n\n```yaml\nrelated:\n  title: Next Steps\n  description: Learn more about related features.\n  links:\n    - app/api-reference/functions/related-function\n    - app/guides/related-guide\n```\n\n## Documentation Conventions\n\nSee `references/DOC-CONVENTIONS.md` for complete formatting rules.\n\n### Quick Reference\n\n**Frontmatter (required):**\n\n```yaml\n---\ntitle: Page Title (2-3 words)\ndescription: One or two sentences describing the page.\n---\n```\n\n**Code blocks:**\n\n```\n\\`\\`\\`tsx filename=\"app/page.tsx\" switcher\n// TypeScript first\n\\`\\`\\`\n\n\\`\\`\\`jsx filename=\"app/page.js\" switcher\n// JavaScript second\n\\`\\`\\`\n```\n\n**Router-specific content:**\n\n```mdx\n<AppOnly>Content only for App Router docs.</AppOnly>\n\n<PagesOnly>Content only for Pages Router docs.</PagesOnly>\n```\n\n**Notes:**\n\n```mdx\n> **Good to know**: Single line note.\n\n> **Good to know**:\n>\n> - Multi-line note point 1\n> - Multi-line note point 2\n```\n\n## Validation Checklist\n\nBefore committing documentation changes:\n\n- [ ] Frontmatter has `title` and `description`\n- [ ] Code blocks have `filename` attribute\n- [ ] TypeScript examples use `switcher` with JS variant\n- [ ] Props tables are properly formatted\n- [ ] Related links point to valid paths\n- [ ] `pnpm lint` passes\n- [ ] Changes render correctly (if preview available)\n\n## References\n\n- `references/DOC-CONVENTIONS.md` - Complete frontmatter and formatting rules\n- `references/CODE-TO-DOCS-MAPPING.md` - Source code to documentation mapping\n"},"category":"official","lastSynced":"2026-03-06T06:09:15.662Z","seo":{"title":{"en":"update-docs: Next.js Documentation Update Guide | AI Agen...","zh":"Next.js 文档更新器: 更新文档的最佳实践","ja":"Next.js ドキュメント更新ツール: 更新方法のガイド","ko":"Next.js 문서 업데이터: 문서 업데이트를 위한 가이드","es":"Guía de actualización de documentación para Next.js","fr":"Mise à jour de la documentation Next.js : Guide étape par...","de":"Next.js-Dokumentations-Update: Schritt-für-Schritt-Anleitung","pt":"Guia de Configuração do update-docs: Atualize Documentaçã...","ru":"Настройка ИИ Агента update-docs: Руководство по обновлени...","ar":"إعداد أداة الذكاء الاصطناعي update-docs: دليل تحديث وثائق..."},"description":{"en":"Streamline your Next.js documentation updates with the update-docs skill, guiding you through code changes and doc validation - get started now!","zh":"使用 update-docs 技能更新 Next.js 文档，确保代码变更与文档同步","ja":"update-docs スキルを使用して Next.js ドキュメントを更新し、コード変更を反映","ko":"update-docs 기능을 사용하여 Next.js 문서를 업데이트 하여 코드 변경 사항을 반영","es":"Actualiza la documentación de Next.js automáticamente con nuestra herramienta de AI. Aprende a sincronizar docs con código y a revisar la completitud de la d...","fr":"Mettez à jour la documentation Next.js automatiquement avec notre outil d''IA. Découvrez comment synchroniser les docs avec le code et vérifier l''exhaustivité...","de":"Aktualisieren Sie die Next.js-Dokumentation automatisch mit unserem AI-Tool. Erfahren Sie, wie Sie Docs mit Code synchronisieren und die Vollständigkeit der ...","pt":"Aprenda a usar o update-docs para atualizar documentação Next.js com base em alterações de código. Siga nosso guia passo a passo.","ru":"Узнайте, как использовать ИИ Агент update-docs для обновления документации Next.js на основе изменений кода. Следуйте нашему пошаговому руководству.","ar":"تعلم كيفية استخدام أداة الذكاء الاصطناعي update-docs لتحديث وثائق Next.js بناءً على تغييرات في الكود. اتبع دليلنا خطوة بخطوة."},"definition":{"en":"update-docs is a skill that guides users through updating Next.js documentation based on code changes, ensuring documentation completeness and accuracy.","zh":"update-docs 是一个用于更新 Next.js 文档的技能，确保代码变更与文档同步","ja":"update-docs は Next.js ドキュメントを更新するためのスキルで、コード変更を反映","ko":"update-docs 는 Next.js 문서를 업데이트하는 기능으로 코드 변경 사항을 반영","es":"La habilidad ''update-docs'' es una herramienta de AI que ayuda a actualizar la documentación de Next.js en función de los cambios de código","fr":"La compétence ''update-docs'' est un outil d''IA qui aide à mettre à jour la documentation Next.js en fonction des modifications de code","de":"Die Fähigkeit ''update-docs'' ist ein AI-Tool, das hilft, die Next.js-Dokumentation auf der Grundlage von Codeänderungen zu aktualisieren","pt":"O update-docs é uma ferramenta de atualização de documentação que ajuda a manter a documentação Next.js sincronizada com o código.","ru":"ИИ Агент update-docs - это инструмент обновления документации, который помогает поддерживать документацию Next.js в синхронизации с кодом.","ar":"أداة الذكاء الاصطناعي update-docs هي أداة تحديث وثائق تساعد في الحفاظ على وثائق Next.js متزامنة مع الكود."},"features":{"en":["Analyzes code changes using `git diff` to identify affected documentation","Maps changed source files to documentation paths for efficient review","Walks through updates with user confirmation for accuracy","Validates documentation formatting using `pnpm lint`","Supports Next.js and MDX file formats for comprehensive documentation"],"zh":["支持 Next.js 代码变更分析","能够识别受影响的文档路径","提供文档更新的指导","支持 pnpm lint 格式检查","集成 MDX 和 API 参考文档"],"ja":["Next.js コード変更分析をサポート","影響を受けるドキュメントパスを識別","ドキュメント更新のガイドを提供","pnpm lint フォーマットチェックをサポート","MDX と API リファレンスドキュメントを統合"],"ko":["Next.js 코드 변경 분석 지원","영향받는 문서 경로 식별","문서 업데이트를 위한 가이드 제공","pnpm lint 형식 확인 지원","MDX 및 API 참조 문서 통합"],"es":["Análisis de cambios de código con `git diff`","Identificación de documentos afectados por los cambios de código","Revisión de la completitud de la documentación con confirmación del usuario","Validación de la documentación con `pnpm lint`","Sincronización de documentos con código","Generación de documentos para nuevas características"],"fr":["Analyse des modifications de code avec `git diff`","Identification des documents affectés par les modifications de code","Vérification de l''exhaustivité de la documentation avec confirmation de l''utilisateur","Validation de la documentation avec `pnpm lint`","Synchronisation des documents avec le code","Génération de documents pour les nouvelles fonctionnalités"],"de":["Analyse von Codeänderungen mit `git diff`","Identifizierung von Dokumenten, die von Codeänderungen betroffen sind","Überprüfung der Vollständigkeit der Dokumentation mit Benutzerbestätigung","Validierung der Dokumentation mit `pnpm lint`","Synchronisierung von Dokumenten mit Code","Erstellung von Dokumenten für neue Funktionen"],"pt":["Análise de alterações de código com `git diff`","Identificação de documentos afetados","Revisão de documentos com confirmação do usuário","Validação de formatação com `pnpm lint`"],"ru":["Анализ изменений кода с помощью `git diff`","Определение документов, на которые влияют изменения","Проверка документов с подтверждением пользователя","Проверка форматирования с помощью `pnpm lint`"],"ar":["تحليل التغييرات في الكود باستخدام `git diff`","تحديد الوثائق المتأثرة","مراجعة الوثائق مع تأكيد المستخدم","التحقق من تنسيق باستخدام `pnpm lint`"]},"keywords":{"en":["how to use update-docs","update-docs setup guide","Next.js documentation update","update-docs alternative","update-docs vs documentation generators","update-docs install","MDX file documentation","git diff documentation","pnpm lint documentation"],"zh":["Next.js 文档更新","AIエージェント","代码变更分析","文档同步","MDX 文档","API 参考文档","pnpm lint","React 文档更新"],"ja":["Next.js ドキュメント更新","AIエージェント","コード変更分析","ドキュメント同期","MDX ドキュメント","API リファレンスドキュメント","pnpm lint","React ドキュメント更新"],"ko":["Next.js 문서 업데이트","AI 에이전트","코드 변경 분석","문서 동기화","MDX 문서","API 참조 문서","pnpm lint","React 문서 업데이트"],"es":["actualización de documentación Next.js","herramientas de AI para documentación","sincronización de docs con código","revisión de documentación","validación de documentación","Next.js","React","Node.js","Vercel"],"fr":["mise à jour de la documentation Next.js","outils d''IA pour la documentation","synchronisation des docs avec le code","vérification de la documentation","validation de la documentation","Next.js","React","Node.js","Vercel"],"de":["Aktualisierung der Next.js-Dokumentation","AI-Tools für Dokumentation","Synchronisierung von Dokumenten mit Code","Überprüfung der Dokumentation","Validierung der Dokumentation","Next.js","React","Node.js","Vercel"],"pt":["update-docs","Next.js","documentação","atualização de documentação","git diff","pnpm lint","React","Node.js"],"ru":["ИИ Агент update-docs","Next.js","документация","обновление документации","git diff","pnpm lint","React","Node.js"],"ar":["أداة الذكاء الاصطناعي update-docs","Next.js","وثائق","تحديث وثائق","git diff","pnpm lint","React","Node.js"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Next.js Development Agents needing automated documentation updates based on code changes.","zh":"适用于需要根据代码更改自动更新文档的 Next.js 开发代理。","ja":"Next.js 開発エージェントがコードの変更に基づいて自動的にドキュメントを更新する必要がある場合に最適です。","ko":"코드 변경에 따라 문서를 자동으로 업데이트해야 하는 Next.js 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de Next.js que necesitan actualizaciones de documentación automatizadas basadas en cambios de código.","fr":"Parfait pour les agents de développement Next.js ayant besoin de mises à jour de documentation automatisées basées sur les modifications de code.","de":"Perfekt für Next.js-Entwicklungsagenten, die automatisierte Dokumentationsaktualisierungen auf Basis von Codeänderungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento do Next.js que precisam de atualizações automatizadas de documentação com base em alterações de código.","ru":"Идеально для агентов разработки Next.js, которым необходимы автоматические обновления документации на основе изменений кода.","ar":"مثالي لعميل تطور Next.js الذين يحتاجون إلى تحديثات وثائقية آلية بناءً على تغييرات في الشفرة."},"recommendation":{"en":"Empowers agents to synchronize documentation with code changes using git diff, map source files to documentation paths, and validate updates with pnpm lint, ensuring documentation completeness and accuracy for Next.js projects with MDX and API reference documentation.","zh":"赋予代理人使用 git diff 同步代码更改与文档，映射源文件到文档路径，并使用 pnpm lint 验证更新，从而确保 Next.js 项目（包括 MDX 和 API 参考文档）文档的完整性和准确性。","ja":"git diff を使用してコードの変更とドキュメントを同期させ、ソース ファイルをドキュメント パスにマッピングし、pnpm lint を使用して更新を検証することで、Next.js プロジェクト（MDX と API リファレンス ドキュメントを含む）のドキュメントの完全性と正確性を確保します。","ko":"git diff를 사용하여 코드 변경과 문서를 동기화하고, 소스 파일을 문서 경로에 매핑하며, pnpm lint를 사용하여 업데이트를 검증하여 Next.js 프로젝트(MDX 및 API 참조 문서 포함)의 문서 완결성과 정확성을 보장합니다.","es":"Habilita a los agentes a sincronizar la documentación con los cambios de código utilizando git diff, asignar archivos de origen a rutas de documentación y validar las actualizaciones con pnpm lint, garantizando la completitud y precisión de la documentación para proyectos Next.js con documentación de referencia de MDX y API.","fr":"Permet aux agents de synchroniser la documentation avec les modifications de code à l''aide de git diff, de mapper les fichiers sources vers les chemins de documentation et de valider les mises à jour avec pnpm lint, garantissant ainsi l''exhaustivité et l''exactitude de la documentation pour les projets Next.js avec une documentation de référence MDX et API.","de":"Ermöglicht es Agenten, die Dokumentation mit Codeänderungen mithilfe von git diff zu synchronisieren, Quelldateien zu Dokumentationspfaden zuzuordnen und Aktualisierungen mit pnpm lint zu validieren, um so die Vollständigkeit und Genauigkeit der Dokumentation für Next.js-Projekte mit MDX- und API-Referenzdokumentation sicherzustellen.","pt":"Habilita os agentes a sincronizar a documentação com as alterações de código usando git diff, mapear arquivos de origem para caminhos de documentação e validar atualizações com pnpm lint, garantindo a completude e precisão da documentação para projetos Next.js com MDX e documentação de referência da API.","ru":"Наделяет агентов возможностью синхронизировать документацию с изменениями кода с помощью git diff, сопоставлять исходные файлы с путями документации и проверять обновления с помощью pnpm lint, обеспечивая полноту и точность документации для проектов Next.js с MDX и справочной документацией API.","ar":"يمنح الوكيل khảية مزامنة الوثائق مع تغييرات الشفرة باستخدام git diff، وربط الملفات المصدر بمسارات الوثائق، والتحقق من التحديثات باستخدام pnpm lint، وضمان اكتمال و دقة الوثائق لمشاريع Next.js مع MDX ووثائق مرجعية API."},"useCases":{"en":["Updating Next.js documentation for new feature releases","Validating documentation completeness for pull requests","Scaffolding documentation for new features with MDX files"],"zh":["为新功能版本更新 Next.js 文档","验证拉取请求的文档完整性","使用 MDX 文件为新功能搭建文档"],"ja":["新機能リリースのための Next.js ドキュメントの更新","プルリクエストのドキュメントの完全性の検証","MDX ファイルを使用した新機能のドキュメントの作成"],"ko":["새 기능 릴리스를 위한 Next.js 문서 업데이트","풀 리퀘스트의 문서 완결성 검증","MDX 파일을 사용한 새로운 기능의 문서 스캐폴딩"],"es":["Actualización de la documentación de Next.js para nuevas versiones de características","Validación de la completitud de la documentación para solicitudes de extracción","Creación de documentación para nuevas características con archivos MDX"],"fr":["Mise à jour de la documentation Next.js pour les nouvelles versions de fonctionnalités","Validation de l''exhaustivité de la documentation pour les demandes d''extraction","Création de documentation pour les nouvelles fonctionnalités avec des fichiers MDX"],"de":["Aktualisierung der Next.js-Dokumentation für neue Funktionsversionen","Validierung der Vollständigkeit der Dokumentation für Pull-Requests","Erstellung von Dokumentation für neue Funktionen mit MDX-Dateien"],"pt":["Atualizar a documentação do Next.js para lançamentos de novos recursos","Validar a completude da documentação para solicitações de pull","Criar estrutura para documentação de novos recursos com arquivos MDX"],"ru":["Обновление документации Next.js для выпусков новых функций","Проверка полноты документации для запросов на включение","Создание базовой структуры для документации новых функций с помощью файлов MDX"],"ar":["تحديث وثائق Next.js لإصدارات الميزات الجديدة","التحقق من اكتمال الوثائق لطلبات السحب","إنشاء هيكل للوثائق لميزات جديدة مع ملفات MDX"]},"limitations":{"en":["Requires git repository access","Next.js project setup","pnpm installation"],"zh":["需要 git 仓库访问权限","需要 Next.js 项目设置","需要 pnpm 安装"],"ja":["git リポジトリへのアクセスが必要","Next.js プロジェクトの設定が必要","pnpm のインストールが必要"],"ko":["git 저장소 접근 권한 필요","Next.js 프로젝트 설정 필요","pnpm 설치 필요"],"es":["Requiere acceso al repositorio git","Configuración del proyecto Next.js","Instalación de pnpm"],"fr":["Nécessite un accès au référentiel git","Configuration du projet Next.js","Installation de pnpm"],"de":["Erfordert Zugriff auf das Git-Repository","Einrichtung des Next.js-Projekts","Installation von pnpm"],"pt":["Exige acesso ao repositório git","Configuração do projeto Next.js","Instalação do pnpm"],"ru":["Требует доступа к репозиторию git","Настройка проекта Next.js","Установка pnpm"],"ar":["يتطلب الوصول إلى مستودع git","إعداد مشروع Next.js","تثبيت pnpm"]},"version":4},"contentHash":"0f46c6e76a222cfa4008d16cdb1dfa37c413901db2b304a49cce829ef4c7ad71","repoEtag":"W/\"ba864559e2a3775d981dccc9d6d5207db6d88a2194976253738543b2146b85ec\"","qualityScore":68}');
