INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vercel/next.js/update-docs', 'update-docs', 'vercel', 'next.js', 'official', 'update-docs vercel next.js official blog browser compiler components hybrid nextjs node react server-rendering ssg static static-site-generator universal vercel The update-docs skill helps maintainers review PRs for documentation completeness, providing a guided workflow for updating Next.js documentation based on code changes. update-docs 技能为 Next.js 文档更新提供了指导，确保代码变更与文档同步 update-docs スキルは Next.js ドキュメントの更新をサポートし、コード変更を反映 update-docs 기능은 Next.js 문서의 업데이트를 지원하여 코드 변경 사항을 반영 La habilidad ''update-docs'' proporciona un flujo de trabajo guiado para actualizar la documentación de Next.js en función de los cambios de código La compétence ''update-docs'' fournit un flux de travail guidé pour mettre à jour la documentation Next.js en fonction des modifications de code Die Fähigkeit ''update-docs'' bietet einen geleiteten Workflow zur Aktualisierung der Next.js-Dokumentation auf der Grundlage von Codeänderungen O update-docs é uma ferramenta que ajuda a manter a documentação Next.js atualizada com base em alterações de código. Ele fornece um fluxo de trabalho guiado para revisar e atualizar a documentação. ИИ Агент update-docs - это инструмент, который помогает поддерживать документацию Next.js в актуальном состоянии на основе изменений кода. Он предоставляет руководимый рабочий процесс для проверки и обновления документации. أداة الذكاء الاصطناعي update-docs هي أداة تساعد في الحفاظ على وثائق Next.js محدثة بناءً على تغييرات في الكود. توفر عملية عمل موجهة لمراجعة وتحديث الوثائق. how to use update-docs update-docs setup guide Next.js documentation update update-docs alternative update-docs vs documentation generators update-docs install MDX file documentation git diff documentation pnpm lint documentation Next.js 文档更新 AIエージェント 代码变更分析 文档同步 MDX 文档 API 参考文档 pnpm lint React 文档更新 Analyzes code changes using `git diff` to identify affected documentation Maps changed source files to documentation paths for efficient review Walks through updates with user confirmation for accuracy Validates documentation formatting using `pnpm lint` Supports Next.js and MDX file formats for comprehensive documentation update-docs is a skill that guides users through updating Next.js documentation based on code changes, ensuring documentation completeness and accuracy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gustavscirulis/snapgrid/monetization', 'community', 'gustavscirulis', 'snapgrid', 'gustavscirulis/snapgrid', 'monetization', 106, 6, 67, '2026-03-01T17:46:42Z', '2026-03-06T06:31:15.110Z', '9a06c187d206c2564108bb1ce09b7030962abd312b249e048d707bb1f37c9c65', '{"id":"gustavscirulis/snapgrid/monetization","name":"monetization","description":{"en":"The monetization skill provides end-to-end guidance for Apple platform apps, helping developers determine pricing and choose between freemium, subscription, or one-time purchase models.","zh":"monetization是指应用程序通过各种方式实现盈利的过程，包括订阅、一次性购买和免费增值模式","ja":"monetizationは、アプリケーションがさまざまな方法で収益を上げるプロセスです。サブスクリプション、ワンタイムパーチェージ、フリーミアムモデルなどが含まれます","ko":"monetization은 애플리케이션이 다양한 방식으로 수익을 창출하는 과정으로, 구독, 일회성 구매, 무료增值 모델 등이 포함됩니다","es":"La monetización es un proceso crucial para los desarrolladores de aplicaciones. Nuestra guía ofrece orientación sobre cómo elegir el modelo de monetización adecuado y cómo implementarlo de manera efectiva.","fr":"La monétisation est un processus crucial pour les développeurs d''applications. Notre guide offre des conseils sur la façon de choisir le modèle de monétisation approprié et de le mettre en œuvre de manière efficace.","de":"Die Monetarisierung ist ein entscheidender Prozess für Anwendungsentwickler. Unser Leitfaden bietet Anleitung dazu, wie man das richtige Monetarisierungsmodell auswählt und es effektiv implementiert.","pt":"O SnapGrid oferece um guia de monetização completo para desenvolvedores, incluindo estratégias de preços e modelos de receita.","ru":"SnapGrid предлагает полное руководство по монетизации для разработчиков, включая стратегии ценообразования и модели дохода для ИИ Агентов.","ar":"يقدم SnapGrid دليل تمويز كامل للمطورين، بما في ذلك استراتيجيات التسعير ونماذج الإيرادات"},"seo":{"title":{"en":"Monetization: End-to-end Guidance for Apple Platform Apps...","zh":"AIエージェント_monetization_setup_guide","ja":"AIエージェント_moneitzation_best_practices","ko":"monetization_setup_가이드_for_developers","es":"Guía de Monetización para Desarrolladores de Aplicaciones","fr":"Guide de Monétisation pour les Développeurs d''Applications","de":"Monetarisierungs-Setup Guide für Entwickler","pt":"Guia de Configuração de Monetização para Desenvolvedores","ru":"Руководство по настройке монетизации для разработчиков ИИ...","ar":"دليل إعداد التمويز لل مطورين"},"description":{"en":"Discover how to monetize your Apple platform app with expert guidance on pricing, freemium models, and more - get started now!","zh":"了解如何使用AIエージェント实现应用monetization，包括定价策略和免费试用计划","ja":"AIエージェントを使用してアプリのmonetizationを実装する方法を学ぶ、価格設定と無料トライアルについて","ko":"monetization을 위한 AI 에이전트 가이드, 가격 정책 및 무료 체험 계획 포함","es":"Aprende a monetizar tus aplicaciones con nuestra guía de mejores prácticas para desarrolladores de Apple","fr":"Découvrez comment monétiser vos applications avec notre guide de bonnes pratiques pour les développeurs Apple","de":"Erfahren Sie, wie Sie Ihre Anwendungen monetarisieren können, mit unserem Leitfaden für Entwickler von Apple-Anwendungen","pt":"Aprenda a monetizar seu aplicativo com o guia de monetização do SnapGrid, incluindo estratégias de preços e modelos de receita.","ru":"Узнайте, как монетизировать свое приложение с помощью руководства по монетизации SnapGrid, включая стратегии ценообразования и модели дохода для ИИ Агентов.","ar":"تعلم كيفية تحقيق الإيرادات من تطبيقك باستخدام دليل التمويز من SnapGrid، بما في ذلك استراتيجيات التسعير ونماذج الإيرادات"},"definition":{"en":"Monetization is the process of generating revenue from an app, including strategies for pricing, free trials, and subscription models.","zh":"monetization是应用程序盈利的过程，涉及价格策略、免费试用和应用类型规划","ja":"monetizationは、アプリケーションの収益化プロセスであり、価格戦略、無料トライアル、及びアプリケーションの種類計画を含みます","ko":"monetization은 애플리케이션의 수익 창출 과정으로, 가격 전략, 무료 체험, 애플리케이션 유형 계획 등을 포함합니다","es":"La monetización se refiere al proceso de generar ingresos a partir de una aplicación o servicio","fr":"La monétisation fait référence au processus de génération de revenus à partir d''une application ou d''un service","de":"Die Monetarisierung bezeichnet den Prozess der Generierung von Einnahmen aus einer Anwendung oder einem Dienst","pt":"Monetização é o processo de gerar receita a partir de um aplicativo ou serviço.","ru":"Монетизация - это процесс генерации дохода от приложения или услуги для ИИ Агентов.","ar":"التمويز هو عملية توليد الإيرادات من تطبيق أو خدمة"},"features":{"en":["Provides guidance on choosing between freemium, subscription, or one-time purchase models","Offers pricing tier recommendations for Apple platform apps","Helps plan monetization for specific app types, such as kids or therapy apps","Assists with free trial strategy and implementation","Supports end-to-end monetization guidance, from initial consideration to pricing page structure"],"zh":["应用monetization策略指导","价格策略和层级推荐","免费试用计划指导","特定应用类型monetization规划","订阅、一次性购买和免费增值模式支持"],"ja":["アプリのmonetization戦略ガイド","価格戦略と階層構造の提案","無料トライアルプランのガイド","特定のアプリケーションタイプのmonetization計画","サブスクリプション、ワンタイムパーチェージ、フリーミアムモデルのサポート"],"ko":["monetization 전략 가이드","가격 전략 및 티어 추천","무료 체험 계획 가이드","특정 애플리케이션 유형의 monetization 계획","구독, 일회성 구매, 무료增值 모델 지원"],"es":["Orientación sobre la elección del modelo de monetización adecuado","Implementación de estrategias de precios y planes de tarifa","Planificación de la monetización para aplicaciones específicas","Análisis de la efectividad de las estrategias de monetización","Integración con herramientas de análisis y seguimiento"],"fr":["Conseils sur le choix du modèle de monétisation approprié","Mise en œuvre de stratégies de tarification et de plans de tarification","Planification de la monétisation pour des applications spécifiques","Analyse de l''efficacité des stratégies de monétisation","Intégration avec des outils d''analyse et de suivi"],"de":["Anleitung zur Auswahl des richtigen Monetarisierungsmodells","Implementierung von Preisstrategien und Tarife","Planung der Monetarisierung für spezifische Anwendungen","Analyse der Effektivität von Monetarisierungsstrategien","Integration mit Analyse- und Überwachungstools"],"pt":["Estratégias de preços personalizadas","Modelos de receita flexíveis","Análise de componentes e padrões de UI","Suporte a modelos de negócios diferentes","Integração com plataformas de pagamento","Otimização de conversão de clientes"],"ru":["Индивидуальные стратегии ценообразования","Гибкие модели дохода","Анализ компонентов и паттернов UI","Поддержка различных моделей бизнеса","Интеграция с платформами платежей","Оптимизация конверсии клиентов для ИИ Агентов"],"ar":["استراتيجيات التسعير المخصصة","نماذج الإيرادات المرنة","تحليل المكونات وأنماط واجهة المستخدم","دعم نماذج الأعمال المختلفة","التكامل مع منصات الدفع","تحسين تحويل العملاء"]},"keywords":{"en":["how to monetize an app","monetization strategy for Apple platform","freemium vs subscription models","app pricing guidance","monetization setup guide","what is monetization in app development","monetization alternatives for Apple apps","monetization vs in-app purchases"],"zh":["AIエージェント_monetization","应用monetization策略","价格策略和层级","免费试用计划","特定应用类型monetization","订阅模式","一次性购买","免费增值模式"],"ja":["AIエージェント_moneitzation","アプリのmonetization戦略","価格戦略と階層構造","無料トライアルプラン","特定のアプリケーションタイプのmonetization","サブスクリプションモデル","ワンタイムパーチェージ","フリーミアムモデル"],"ko":["monetization_setup","monetization_전략","가격_전략","무료_체험_계획","특정_애플리케이션_유형_monetization","구독_모델","일회성_구매","무료增值_모델"],"es":["monetización de aplicaciones","modelos de monetización","estrategias de precios","planes de tarifa","análisis de efectividad","herramientas de análisis","desarrollo de aplicaciones","Apple Developer","iOS monetización"],"fr":["monétisation d''applications","modèles de monétisation","stratégies de tarification","plans de tarification","analyse de l''efficacité","outils d''analyse","développement d''applications","Apple Developer","iOS monétisation"],"de":["Monetarisierung von Anwendungen","Monetarisierungsmodelle","Preisstrategien","Tarife","Effektivitätsanalyse","Analyse-Tools","Anwendungsentwicklung","Apple Developer","iOS-Monetarisierung"],"pt":["monetização de aplicativos","estratégias de preços","modelos de receita","análise de UI","desenvolvimento de aplicativos","plataformas de pagamento","otimização de conversão","SnapGrid","guia de monetização"],"ru":["монетизация приложений","стратегии ценообразования","модели дохода","анализ UI","разработка приложений","платформы платежей","оптимизация конверсии","SnapGrid","руководство по монетизации","ИИ Агенты"],"ar":["تمويز التطبيقات","استراتيجيات التسعير","نماذج الإيرادات","تحليل واجهة المستخدم","تطوير التطبيقات","منصات الدفع","تحسين تحويل العملاء","SnapGrid","دليل التمويز","أدوات الذكاء الاصطناعي"]}},"owner":"gustavscirulis","repo":"snapgrid","repoPath":"gustavscirulis/snapgrid","stars":106,"forks":6,"updatedAt":"2026-03-01T17:46:42Z","topics":[],"category":"community","skillMd":{"name":"monetization","description":"Monetization strategy for iOS/macOS apps. Covers readiness assessment, pricing model selection, tier structuring, free trial strategy, and implementation guidance. Use when deciding what to charge, how to price, or planning monetization end-to-end.","bodyPreview":"# Monetization Strategy\n\nEnd-to-end monetization guidance for Apple platform apps — from \"should I charge?\" to \"here''s your pricing page structure.\"\n\n## When This Skill Activates\n\nUse this skill when the user:\n- Asks \"should I monetize my app?\" or \"is my app ready to charge?\"\n- Wants help choosing between freemium, subscription, or one-time purchase\n- Needs pricing tier recommendations\n- Asks about free trial strategy\n- Wants to plan monetization for a specific app type (kids, therapy, productiv","body":"# Monetization Strategy\n\nEnd-to-end monetization guidance for Apple platform apps — from \"should I charge?\" to \"here''s your pricing page structure.\"\n\n## When This Skill Activates\n\nUse this skill when the user:\n- Asks \"should I monetize my app?\" or \"is my app ready to charge?\"\n- Wants help choosing between freemium, subscription, or one-time purchase\n- Needs pricing tier recommendations\n- Asks about free trial strategy\n- Wants to plan monetization for a specific app type (kids, therapy, productivity, etc.)\n- Mentions \"pricing\", \"revenue model\", or \"how to make money from my app\"\n- Wants to understand Apple''s commission structure\n\n## Process\n\n### Phase 1: Readiness Assessment\n\nBefore recommending a pricing model, evaluate whether the app is ready to monetize. Ask these questions via AskUserQuestion:\n\n**1. App Stage**\n- Pre-launch (idea/prototype)\n- Beta / TestFlight\n- Live with users (< 1K)\n- Live with traction (1K+ users)\n\n**2. Value Proposition**\n- What problem does your app solve?\n- Who is the target user?\n- What alternatives exist (including doing nothing)?\n\n**3. Current State**\n- Do you have active users?\n- What''s your retention like? (Day 1, Day 7, Day 30)\n- Are users asking for features / willing to pay?\n\n#### Readiness Scorecard\n\nEvaluate against these criteria:\n\n| Signal | Ready | Not Ready |\n|--------|-------|-----------|\n| Core value | Clear, differentiated | Still finding product-market fit |\n| User retention | D7 > 20% | D7 < 10% |\n| User feedback | \"I''d pay for this\" | Silence or complaints |\n| Feature depth | Enough for free + paid split | Everything feels essential |\n| Competition | You offer something unique | Commodity feature set |\n| Polish | Professional quality | Rough edges everywhere |\n\n**Recommendation thresholds:**\n- 5-6 Ready signals → Monetize now\n- 3-4 Ready signals → Soft-launch pricing (low price, gather data)\n- 0-2 Ready signals → Focus on product first, monetize later\n\n### Phase 2: Pricing Model Selection\n\nBased on app type and user behavior, recommend the right model.\n\n#### Decision Framework\n\n```\nIs the app used daily/weekly?\n├── YES → Does it provide ongoing value?\n│   ├── YES → SUBSCRIPTION\n│   └── NO → ONE-TIME PURCHASE (with optional tip jar)\n└── NO → Is it a utility/tool?\n    ├── YES → ONE-TIME PURCHASE or FREEMIUM\n    └── NO → Is it content-based?\n        ├── YES → SUBSCRIPTION or CONSUMABLE IAP\n        └── NO → FREEMIUM with premium unlock\n```\n\n#### Model Comparison\n\nRead **pricing-models.md** for detailed comparison of each model:\n- Subscriptions (auto-renewable)\n- One-time purchase (paid upfront or freemium unlock)\n- Consumable IAP (credits, tokens)\n- Non-consumable IAP (feature unlock)\n- Tip jar / patronage\n- Ad-supported with premium upgrade\n\n#### App-Type Recommendations\n\nRead **app-type-guides.md** for specific guidance by app category:\n- Productivity / task management\n- Health / therapy / wellness\n- Kids / education\n- Creative tools\n- Social / community\n- Developer tools\n- Finance / budgeting\n\n### Phase 3: Tier Structure\n\nOnce a model is selected, design the tier structure.\n\n#### Subscription Tiers (if applicable)\n\n**Two-tier structure** (recommended for most indie apps):\n```\nFREE                    PRO ($X.99/mo or $XX.99/yr)\n─────────────────────   ─────────────────────────────\nCore functionality      Everything in Free\nLimited usage/storage   Unlimited usage\nBasic features          Advanced features\n                        Priority support (optional)\n                        Early access to new features\n```\n\n**Three-tier structure** (for apps with clear user segments):\n```\nFREE          PLUS ($X.99/mo)     PRO ($XX.99/mo)\n────────────  ──────────────────  ──────────────────\nBasic use     Power user          Professional/team\nAds/limits    No ads, more quota  Unlimited + extras\n```\n\n#### Pricing Psychology\n\n- **Anchor pricing**: Show yearly first to make monthly look expensive\n- **Price ending**: Use .99 for < $10, round numbers for premium ($19, $29)\n- **Yearly discount**: 15-40% off monthly equivalent (sweet spot: ~30%)\n- **Decoy effect**: Three tiers where middle looks like best value\n- **Regional pricing**: Use App Store price tiers for automatic localization\n\n#### Free vs. Paid Feature Split\n\nThe hardest decision. Follow these principles:\n\n**Free tier should:**\n- Demonstrate the core value proposition\n- Be genuinely useful (not a crippled demo)\n- Create natural upgrade moments (\"you''ve hit the limit\")\n- Let users invest time/data before hitting the paywall\n\n**Paid tier should:**\n- Unlock power/convenience, not basic functionality\n- Feel like \"more of what you love\" not \"removing annoyances\"\n- Include at least one \"hero feature\" worth paying for alone\n\n**❌ Bad splits:**\n- Free: Can view data → Paid: Can edit data (feels hostile)\n- Free: 3-day trial → Paid: Everything (no ongoing free value)\n- Free: Everything → Paid: Remove ads (weak value prop)\n\n**✅ Good splits:**\n- Free: 5 projects → Paid: Unlimited projects + templates\n- Free: Basic tracking → Paid: Insights, trends, export\n- Free: Single device → Paid: Sync across devices + widgets\n\n### Phase 4: Free Trial Strategy\n\n#### Trial Types\n\n| Type | Best For | Apple Support |\n|------|----------|---------------|\n| Introductory offer (free) | Subscriptions | Built-in via App Store |\n| Introductory offer (discounted) | High-value subscriptions | Built-in via App Store |\n| Feature-limited free tier | Freemium apps | N/A (your logic) |\n| Time-limited full access | Productivity apps | Built-in via App Store |\n\n#### Trial Duration Recommendations\n\n| App Type | Trial Length | Reason |\n|----------|-------------|--------|\n| Daily-use productivity | 7 days | Quick to see value |\n| Health/fitness tracking | 14 days | Need time to build habit |\n| Creative tools | 7 days | One project cycle |\n| Business/professional | 14-30 days | Need to integrate into workflow |\n| Education/learning | 7 days | One learning cycle |\n\n#### Trial Conversion Tactics\n\n1. **Onboard to premium features** during trial (not free features)\n2. **Show \"trial ending\" reminder** 2-3 days before expiration\n3. **Highlight value received** (\"You tracked 47 workouts this month\")\n4. **Offer annual option** at trial end (bigger commitment but better price)\n5. **Win-back offer** if they don''t convert (promotional offer after 30 days)\n\n### Phase 5: Implementation Guidance\n\nAfter strategy is set, guide implementation.\n\n#### Apple Commission Structure\n\n| Scenario | Apple''s Cut | You Keep |\n|----------|-------------|----------|\n| Standard (Year 1) | 30% | 70% |\n| After Year 1 of subscription | 15% | 85% |\n| Small Business Program (< $1M/yr) | 15% | 85% |\n| Small Business + Year 2 subscription | 15% | 85% |\n\n**Important:** Revenue calculations should always account for Apple''s cut. A $9.99/mo subscription with Small Business Program = ~$8.49/mo to you.\n\n#### StoreKit 2 Implementation\n\nFor code generation, refer users to the **paywall-generator** skill:\n```\nUse the paywall-generator skill to create:\n- StoreKit 2 subscription management\n- Paywall UI (SwiftUI)\n- Receipt validation\n- Subscription status tracking\n```\n\n#### Paywall UI Patterns (HIG-Compliant)\n\n**Do:**\n- Show feature comparison (free vs. paid)\n- Display price per period clearly\n- Highlight savings on annual plan\n- Include \"Restore Purchases\" button\n- Show terms of service and privacy policy links\n- Use system subscription views where available (iOS 18.4+)\n\n**Don''t:**\n- Block the app immediately on launch\n- Use dark patterns (hidden close button, confusing language)\n- Make it hard to dismiss the paywall\n- Misrepresent subscription terms\n- Auto-select the most expensive option\n\n#### App Store Review Guidelines (Monetization)\n\nKey rules to follow:\n- **3.1.1**: In-app purchase required for digital content/features\n- **3.1.2**: Subscriptions must provide ongoing value\n- **3.1.3**: \"Reader\" apps can link to web for account management\n- **3.2.2**: Unacceptable business models (bait-and-switch, etc.)\n- **5.6**: Developer Code of Conduct (no manipulative tactics)\n\n## Output Format\n\nPresent monetization strategy as:\n\n```markdown\n# Monetization Strategy: [App Name]\n\n## Readiness Assessment\n**Score**: X/6 — [Ready to monetize / Soft-launch / Focus on product]\n\n| Signal | Status | Notes |\n|--------|--------|-------|\n| Core value | ✅/❌ | ... |\n| Retention | ✅/❌ | ... |\n| User demand | ✅/❌ | ... |\n| Feature depth | ✅/❌ | ... |\n| Differentiation | ✅/❌ | ... |\n| Polish | ✅/❌ | ... |\n\n## Recommended Model\n**[Model Name]** — [One-line rationale]\n\n## Tier Structure\n\n| Feature | Free | Pro ($X.99/mo) |\n|---------|------|-----------------|\n| ... | ✅ | ✅ |\n| ... | Limited | Unlimited |\n| ... | ❌ | ✅ |\n\n**Annual pricing**: $XX.99/yr (XX% savings)\n\n## Free Trial\n**Type**: [Introductory offer / Feature-limited / etc.]\n**Duration**: [X days]\n**Conversion tactics**: [Bullet list]\n\n## Revenue Projections (Conservative)\n\n| Metric | Estimate |\n|--------|----------|\n| Monthly price | $X.99 |\n| Annual price | $XX.99 |\n| Conversion rate (free→paid) | X-X% |\n| Revenue per 1K MAU | $XXX-$XXX/mo |\n\n## Implementation Checklist\n- [ ] Configure products in App Store Connect\n- [ ] Implement StoreKit 2 (use paywall-generator skill)\n- [ ] Design paywall UI\n- [ ] Set up introductory offers\n- [ ] Add analytics for conversion tracking\n- [ ] Test with StoreKit Configuration file\n- [ ] Submit for review\n\n## Next Steps\n1. [First action item]\n2. [Second action item]\n3. [Third action item]\n```\n\n## References\n\n- **pricing-models.md** — Detailed comparison of all pricing models\n- **app-type-guides.md** — Category-specific monetization recommendations\n- **paywall-generator** skill — For StoreKit 2 code generation\n- **app-store** skill — For App Store description optimization\n- Apple App Store Review Guidelines §3 (Business)\n- Apple StoreKit 2 documentation\n"},"lastSynced":"2026-03-06T06:31:15.110Z","agentAnalysis":{"suitability":{"en":"Perfect for Business Strategy Agents needing end-to-end monetization guidance for Apple platform apps","zh":"非常适合需要为Apple平台应用提供端到端变现指导的商业策略代理","ja":"Appleプラットフォームアプリのエンドツーエンドの収益化ガイダンスが必要なビジネス戦略エージェントに最適","ko":"Apple 플랫폼 애플리케이션을 위한 종단 간 수익화 가이드가 필요한 비즈니스 전략 에이전트에게 완벽함","es":"Perfecto para Agentes de Estrategia Comercial que necesitan orientación de monetización de extremo a extremo para aplicaciones de la plataforma Apple","fr":"Parfait pour les Agents de Stratégie Commerciale ayant besoin de conseils de monétisation de bout en bout pour les applications de la plateforme Apple","de":"Perfekt für Geschäftsstrategie-Agenten, die eine umfassende Monetarisierungsberatung für Apple-Plattform-Apps benötigen","pt":"Perfeito para Agentes de Estratégia de Negócios que precisam de orientação de monetização de ponta a ponta para aplicativos de plataforma Apple","ru":"Идеально подходит для агентов по бизнес-стратегии, которым необходима комплексная поддержка монетизации для приложений платформы Apple","ar":"مثالي للوكلاء الاستراتيجيين التجاريين الذين يحتاجون إلى إرشادات شاملة لتحقيق الإيرادات لتطبيقات منصة Apple"},"recommendation":{"en":"Empowers agents to determine optimal pricing models, including freemium, subscription, and one-time purchase strategies, and provides pricing tier recommendations using Apple platform guidelines and protocols","zh":"赋予代理人确定最佳定价模式的能力，包括免费增值、订阅和一次性购买策略，并使用Apple平台指南和协议提供定价层级推荐","ja":"エージェントが最適な価格設定モデルを決定する機能を提供します。フリーミアム、サブスクリプション、一時的な購入戦略を含み、Appleプラットフォームのガイドラインとプロトコルを使用した価格階層の推奨","ko":"에이전트가 최적의 定价 모델을 결정할 수 있는 기능을 제공합니다. 무료增强, 구독, 1회 구매 전략을 포함하며, Apple 플랫폼 지침 및 프로토콜을 사용한 가격 계층 추천","es":"Permite a los agentes determinar modelos de precios óptimos, incluidas estrategias de freemium, suscripción y compra única, y proporciona recomendaciones de nivel de precios utilizando las directrices y protocolos de la plataforma Apple","fr":"Permet aux agents de déterminer des modèles de tarification optimaux, notamment des stratégies de freemium, d''abonnement et d''achat unique, et fournit des recommandations de niveau de tarification en utilisant les lignes directrices et les protocoles de la plateforme Apple","de":"Ermöglicht es Agenten, optimale Preismodelle zu bestimmen, einschließlich Freemium-, Abonnements- und Einmalzahlungsstrategien, und bietet Preisstaffel-Empfehlungen unter Verwendung der Richtlinien und Protokolle der Apple-Plattform","pt":"Habilita os agentes a determinar modelos de preços ótimos, incluindo estratégias de freemium, assinatura e compra única, e fornece recomendações de níveis de preços usando diretrizes e protocolos da plataforma Apple","ru":"Позволяет агентам определять оптимальные модели ценообразования, включая стратегии freemium, подписки и единовременной покупки, и предоставляет рекомендации по уровням ценообразования с использованием руководств и протоколов платформы Apple","ar":"تمكن الوكلاء من تحديد نماذج أسعار مثالية، بما في ذلك استراتيجيات Freemium و الاشتراك و الشراء لمرة واحدة، و يوفر توصيات لمراتب الأسعار باستخدام إرشادات و بروتوكولات منصة Apple"},"useCases":{"en":["Developing monetization strategies for kids, therapy, or productivity apps","Choosing between freemium, subscription, or one-time purchase models for an app","Planning free trial strategies for Apple platform apps","Creating pricing page structures for apps"],"zh":["为儿童、治疗或生产力应用开发变现策略","在应用中选择免费增值、订阅或一次性购买模型","为Apple平台应用规划免费试用策略","为应用创建价格页面结构"],"ja":["子供、セラピー、または生産性アプリの収益化戦略を開発する","アプリでフリーミアム、サブスクリプション、または一時的な購入モデルを選択する","Appleプラットフォームアプリの無料試用戦略を計画する","アプリの価格ページ構造を作成する"],"ko":["어린이, 치료 또는 생산성 애플리케이션을 위한 수익화 전략 개발","애플리케이션에서 무료增强, 구독 또는 1회 구매 모델 선택","Apple 플랫폼 애플리케이션을 위한 무료 시도 전략 수립","애플리케이션을 위한 가격 페이지 구조 생성"],"es":["Desarrollar estrategias de monetización para aplicaciones de niños, terapia o productividad","Elegir entre modelos de freemium, suscripción o compra única para una aplicación","Planificar estrategias de prueba gratuita para aplicaciones de la plataforma Apple","Crear estructuras de páginas de precios para aplicaciones"],"fr":["Développer des stratégies de monétisation pour les applications pour enfants, la thérapie ou la productivité","Choisir entre des modèles de freemium, d''abonnement ou d''achat unique pour une application","Planifier des stratégies d''essai gratuit pour les applications de la plateforme Apple","Créer des structures de pages de tarification pour les applications"],"de":["Entwickeln von Monetarisierungsstrategien für Kinder-, Therapie- oder Produktivitäts-Apps","Wählen zwischen Freemium-, Abonnements- oder Einmalzahlungsmodellen für eine App","Planen von Teststrategien für Apple-Plattform-Apps","Erstellen von Preis-Seiten-Strukturen für Apps"],"pt":["Desenvolver estratégias de monetização para aplicativos de crianças, terapia ou produtividade","Escolher entre modelos de freemium, assinatura ou compra única para um aplicativo","Planejar estratégias de teste gratuito para aplicativos de plataforma Apple","Criar estruturas de páginas de preços para aplicativos"],"ru":["Разрабатывать стратегии монетизации для детских, терапевтических или производственных приложений","Выбирать между моделями freemium, подписки или единовременной покупки для приложения","Планировать стратегии бесплатного тестирования для приложений платформы Apple","Создавать структуры страниц цен для приложений"],"ar":["تطوير استراتيجيات لتحقيق الإيرادات لتطبيقات الأطفال أو العلاج أو الإنتاجية","اختيار بين نماذج Freemium أو الاشتراك أو الشراء لمرة واحدة لتطبيق","تخطيط استراتيجيات الاختبار المجاني لتطبيقات منصة Apple","إنشاء هياكل صفحات الأسعار لتطبيقات"]},"limitations":{"en":["Limited to Apple platform apps","Requires knowledge of app development and monetization principles"],"zh":["仅限于Apple平台应用","需要应用开发和变现原则的知识"],"ja":["Appleプラットフォームアプリに限定される","アプリ開発と収益化の原則に関する知識が必要"],"ko":["Apple 플랫폼 애플리케이션에만 제한됨","애플리케이션 개발 및 수익화 원칙에 대한 지식이 필요"],"es":["Limitado a aplicaciones de la plataforma Apple","Requiere conocimiento de los principios de desarrollo y monetización de aplicaciones"],"fr":["Limité aux applications de la plateforme Apple","Nécessite une connaissance des principes de développement et de monétisation d''applications"],"de":["Begrenzt auf Apple-Plattform-Apps","Benötigt Kenntnisse der App-Entwicklungs- und Monetarisierungsprinzipien"],"pt":["Limitado a aplicativos de plataforma Apple","Exige conhecimento de desenvolvimento de aplicativos e princípios de monetização"],"ru":["Ограничен приложениями платформы Apple","Требует знания разработки приложений и принципов монетизации"],"ar":["محدد بتطبيقات منصة Apple","يتطلب معرفة بتطوير التطبيقات و مبدأ تحقيق الإيرادات"]},"version":4},"contentHash":"9a06c187d206c2564108bb1ce09b7030962abd312b249e048d707bb1f37c9c65","qualityScore":67}');
